INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In barium swallow studies:', 'Patients should not be NPO', 'High fiber diet is encouraged a day to study', 'Good for studying condition of ascending colon', 'Good for diagnosing achalasia', 'D', 'Barium swallow (esophagography) visualises the esophagus and is the classic study for achalasia, showing the dilated esophagus with distal ''bird-beak'' narrowing (Brunner & Suddarth''s Med-Surg). Patients are kept NPO before the study, so ''not NPO'' is wrong, and it studies the upper GI tract, not the ascending colon.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Esophageal varices are caused by:', 'Inflammation of the esophagus', 'Peptic ulcers', 'Hepatic hypertension', 'Hemorrhoids', 'C', 'Esophageal varices are dilated submucosal veins resulting from portal (hepatic) hypertension, most often due to cirrhosis (Brunner & Suddarth''s Med-Surg). The option ''hepatic hypertension'' best represents portal hypertension; inflammation, peptic ulcers and hemorrhoids do not cause esophageal varices.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following is the correct order of abdominal assessment:', 'Inspection, percussion, auscultation, palpation.', 'Inspection, auscultation, percussion, palpation.', 'Inspection, palpation, percussion, auscultation.', 'Inspection, auscultation, palpation, percussion.', 'B', 'Abdominal assessment follows inspection, auscultation, percussion, then palpation; auscultation precedes percussion/palpation so bowel sounds are not altered by manipulation (Kozier & Erb''s Fundamentals of Nursing).', 'BScN', 'Paper I', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following gastrointestinal disorder is managed best by downscaling gluten containing meals:', 'Irritable bowel syndrome', 'Diverticulum', 'Celiac disease', 'Esophageal varices.', 'C', 'Celiac disease is an immune reaction to gluten and is managed by a lifelong gluten-free diet (Brunner & Suddarth''s Med-Surg). IBS, diverticulum and esophageal varices are not gluten-driven.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Nursing intervention should be a priority in one of the following patients:', 'Patient with appendicitis with pain rating of 10/10.', 'Patient with appendicitis with sudden relief of pain.', 'Patient with peptic ulcers who need omeprazole', 'Patient with jaundice that need evaluation of liver function', 'B', 'Sudden relief of pain in appendicitis suggests perforation/rupture, a surgical emergency requiring priority intervention (Brunner & Suddarth''s Med-Surg). Severe steady pain, routine omeprazole, and elective liver-function evaluation are lower priority than a possible rupture.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The scientific study of the aging process is referred to as:', 'Ageism', 'Geriatrics', 'Gerontic', 'Gerontology', 'D', 'Gerontology is the scientific study of the aging process and older adults; geriatrics is the clinical/medical care of the elderly, and ageism is prejudice against them (Brunner & Suddarth''s Med-Surg, gerontologic nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Drug dosages must be reduced in the elderly because:', 'Cardiac output is significantly reduced', 'The mucosal cells in the gastrointestinal tract are reduced', 'Drug biotransformation takes longer in an older person', 'There is a high likelihood of manifestation of toxic effects of drugs', 'D', 'Age-related decline in hepatic metabolism and renal clearance leads to drug accumulation and a high likelihood of toxicity, so doses are reduced (Brunner & Suddarth''s Med-Surg; Kenya EML pharmacology principles). This is the overarching reason encompassing slower biotransformation.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Nursing measures to deal with sensory changes in the aged include', 'Increasing lighting in the room', 'Speaking in low tones', 'Providing single and adequate calories', 'Suggesting appetite stimulants before meals', 'A', 'Aging causes visual decline; increasing (glare-free) lighting compensates for sensory changes and improves safety (Brunner & Suddarth''s Med-Surg, gerontologic nursing). Speaking in low tones worsens presbycusis; the other options address nutrition, not sensory changes.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Bone changes associated with aging frequently result from loss of:', 'Calcium', 'Magnesium', 'Vitamin A', 'Vitamin C', 'A', 'Age-related bone changes (osteoporosis/osteopenia) result from loss of bone calcium and mass (Brunner & Suddarth''s Med-Surg). Magnesium and vitamins A/C are not the primary lost element in aging bone.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('All of the following statements concerning genitourinary system changes in the older adult are true except:', 'The glomerular filtration rate decreases', 'Acid-base balance is restored more slowly', 'Bladder capacity increases with advanced age', 'Urinary frequency, urgency, and incontinence are common.', 'C', 'This is the ''except'' (false) statement: with aging, bladder capacity DECREASES, contributing to frequency, urgency and incontinence, while GFR falls and acid-base correction is slower (Brunner & Suddarth''s Med-Surg).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the following is true about loss of muscle mass in the elderly:', 'It also known as osteopenia', 'It is solely caused by disused', 'Exercise has no impact on the process', 'It is referred to as sarcopenia.', 'D', 'Age-related loss of muscle mass and strength is termed sarcopenia; osteopenia refers to low bone mass, and exercise/resistance training does slow the process (Brunner & Suddarth''s Med-Surg).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('An example of exocrine glands are the:', 'Adrenals.', 'Ovaries.', 'Parathyroids.', 'Sweat glands.', 'D', 'Exocrine glands secrete through ducts onto a surface; sweat glands are exocrine. Adrenals, ovaries and parathyroids are endocrine (ductless, secrete hormones into blood) (Anatomy & Physiology / Brunner & Suddarth).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse knows that the anterior pituitary gland is responsible for secreting all of the following except the:', 'Adrenocorticotropic hormone (ACTH).', 'Antidiuretic hormone (ADH).', 'Follicle-stimulating hormone (FSH).', 'Thyroid-stimulating hormone (TSH).', 'B', 'This is the ''except'': ADH (and oxytocin) are secreted by the posterior pituitary. The anterior pituitary secretes ACTH, FSH and TSH (Anatomy & Physiology / Brunner & Suddarth).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The major structure balancing the rapid action of the nervous system with slower hormonal action is the:', 'Hypothalamus.', 'Pineal gland.', 'Hypophysis.', 'Thyroid gland.', 'A', 'The hypothalamus links the rapid nervous system with the slower endocrine system by controlling the pituitary, balancing neural and hormonal regulation (Anatomy & Physiology / Brunner & Suddarth).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Diabetes insipidus is a disorder related to a deficiency of:', 'Growth hormone.', 'Prolactin.', 'Oxytocin.', 'Vasopressin.', 'D', 'Diabetes insipidus results from deficiency of antidiuretic hormone (vasopressin), causing polyuria and polydipsia (Brunner & Suddarth''s Med-Surg).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When thyroid hormone is administered for prolonged hypothyroidism, the nurse knows to monitor the patient for:', 'Angina.', 'Depression.', 'Mental confusion.', 'Hypoglycemia.', 'A', 'Thyroid hormone replacement increases myocardial oxygen demand; in prolonged hypothyroidism, especially with underlying CAD, it can precipitate angina, so the nurse monitors for it (Brunner & Suddarth''s Med-Surg).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The preferred medication for treating hypothyroidism is:', 'Lithium.', 'Proprandol.', 'Propylthiouracil.', 'Synthroid.', 'D', 'Synthroid (levothyroxine/T4) is the drug of choice for hypothyroidism replacement (Brunner & Suddarth''s Med-Surg; Kenya EML). Propylthiouracil and propranolol treat hyperthyroidism, and lithium is unrelated.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A clinical manifestation not usually associated with hyperthyroidism is:', 'A pulse rate slower than 90 bpm.', 'An elevated systolic blood pressure.', 'Muscular fatigability.', 'Weight loss.', 'A', 'Hyperthyroidism produces tachycardia, elevated systolic BP, weight loss and fatigability; a pulse slower than 90 bpm is NOT associated (it would suggest hypothyroidism) (Brunner & Suddarth''s Med-Surg).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Patients with hyperthyroidism are characteristically:', 'Apathetic and anorexic.', 'Calm.', 'Emotionally stable.', 'Sensitive to heat.', 'D', 'Hyperthyroid patients have increased metabolism causing heat intolerance, nervousness and irritability; they are not calm, apathetic or emotionally stable (Brunner & Suddarth''s Med-Surg).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Iodine or iodide compounds are used for hyperthyroidism because they do all of the following except:', 'Decrease the basal metabolic rate.', 'Increase the vascularity of the gland.', 'Lessen the release of thyroid hormones.', 'Reduce the size of the gland.', 'B', 'This is the ''except'': iodine/iodide compounds DECREASE the size and vascularity of the thyroid gland and reduce hormone release and BMR, which is why they are given preoperatively (Brunner & Suddarth''s Med-Surg).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The objectives of pharmacotherapy for hyperthyroidism include:', 'Destroying overreactive thyroid cells.', 'Preventing thyroid hormonal synthesis.', 'Increasing the amount of thyroid tissue.', 'All of the above.', 'B', 'The objective of antithyroid pharmacotherapy (e.g., propylthiouracil, methimazole) is to inhibit thyroid hormone synthesis (Brunner & Suddarth''s Med-Surg). Destroying cells is radioiodine (not pharmacotherapy proper), and increasing thyroid tissue is opposite to the goal, so ''all of the above'' is wrong.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Signs of thyroid storm include all of the following except:', 'Bradycardia.', 'Delirium or somnolence.', 'Dyspnea and chest pain.', 'Hyperpyrexia.', 'A', 'This is the ''except'': thyroid storm causes tachycardia, hyperpyrexia, delirium/somnolence and cardiorespiratory distress; bradycardia is not a feature (Brunner & Suddarth''s Med-Surg).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Medical management for thyroid crisis includes:', 'Intravenous dextrose fluids.', 'Hypothermia measures.', 'Oxygen therapy.', 'All of the above.', 'D', 'Management of thyroid crisis includes IV dextrose/fluids for hypermetabolic demand, hypothermia (cooling) measures for hyperpyrexia, and oxygen therapy for increased metabolic demand (Brunner & Suddarth''s Med-Surg).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Pharmacotherapy for thyroid storm would not include the administration of:', 'Acetaminophen.', 'Iodine.', 'Propylthiouracil.', 'Synthetic levothyroxine.', 'D', 'Thyroid storm is treated with PTU, iodine and acetaminophen (for fever); administering synthetic levothyroxine (more thyroid hormone) would worsen the crisis and is therefore not included (Brunner & Suddarth''s Med-Surg).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The most common type of goiter is etiologically related to a deficiency of:', 'Thyrotropin.', 'Iodine.', 'Thyroxine.', 'Calcitonin.', 'B', 'Simple (endemic) goiter, the most common type, is caused by iodine deficiency (Brunner & Suddarth''s Med-Surg; addressed in Kenya via salt iodization). This is the basis of nutritional iodine supplementation.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse knows that the most common and least aggressive type of cancer is:', 'Anaplastic.', 'Follicular adenocarcinoma.', 'Medullary.', 'Papillary adenocarcinoma.', 'D', 'Papillary adenocarcinoma is the most common and least aggressive (best-prognosis) thyroid cancer; anaplastic is the most aggressive (Brunner & Suddarth''s Med-Surg).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A diagnosis of hyperparathyroidism can be established by all of the following signs except:', 'A negative reading on a Sulkowitch test.', 'A serum calcium level of 12 mg/dL.', 'An elevated level of parathyroid hormone.', 'Bone demineralization seen on an x-ray film.', 'A', 'This is the ''except'': hyperparathyroidism causes hypercalcemia, so the Sulkowitch (urine calcium) test would be POSITIVE, not negative; elevated serum calcium, elevated PTH and bone demineralization all support the diagnosis (Brunner & Suddarth''s Med-Surg).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A recommended breakfast for a hyperparathyroid patient would be:', 'Cereal with milk and bananas.', 'Fried eggs and bacon.', 'Orange juice and toast.', 'Pork sausage and cranberry juice', 'B', 'Hyperparathyroidism causes hypercalcemia, so a low-calcium breakfast is preferred; eggs and bacon avoid the high calcium of milk/cereal (Brunner & Suddarth''s Med-Surg nutrition guidance). Cereal with milk is high in calcium and thus inappropriate.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the most important and frequently occurring complications of hyperparathyroidism is:', 'Kidney stones.', 'Pancreatitis.', 'Pathologic fractures.', 'Peptic ulcer.', 'A', 'Chronic hypercalcemia and hypercalciuria in hyperparathyroidism commonly cause renal calculi (nephrolithiasis) (Brunner & Suddarth''s Med-Surg). Pathologic fractures occur but renal stones are the most frequent complication.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The pathophysiology of hypoparathyroidism is associated with all of the following except:', 'A decrease in serum calcium.', 'An elevation of blood phosphate.', 'An increase in the renal excretion of phosphate.', 'A lowered renal excretion of calcium.', 'C', 'This is the ''except'': in hypoparathyroidism low PTH DECREASES renal phosphate excretion, causing hyperphosphatemia along with hypocalcemia and reduced renal calcium excretion (Brunner & Suddarth''s Med-Surg).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The goal of medical management for hypoparathyroidism is to:', 'Achieve a serum calcium level of 9 to 10 mg/dL.', 'Eliminate clinical symptoms.', 'Reverse the symptoms of hypocalcemia.', 'Accomplish all of the above.', 'D', 'Medical management of hypoparathyroidism aims to restore serum calcium to 9–10 mg/dL, reverse hypocalcemia and eliminate clinical symptoms (Brunner & Suddarth''s Med-Surg), so all listed goals apply.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Nursing management for a hypoparathyroid patient would not include:', 'Maintaining a quiet, subdued environment.', 'Making certain that calcium gluconate is kept at the bedside.', 'Observing the patient for signs of tetany.', 'Supplementing the diet with milk and milk products.', 'D', 'This is the ''would not include'': milk products are high in phosphorus, which is already elevated in hypoparathyroidism, so a high-calcium/low-phosphorus diet is advised, not milk supplementation. Seizure precautions, bedside calcium gluconate and tetany monitoring are appropriate (Brunner & Suddarth''s Med-Surg).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A pheochromocytoma is an adrenal medulla tumor that causes arterial hypertension by increasing the level of circulating:', 'Catecholamines.', 'Enzymes.', 'Hormones.', 'Glucocorticoids.', 'A', 'Pheochromocytoma is an adrenal medulla tumor that secretes excess catecholamines (epinephrine and norepinephrine), causing paroxysmal or sustained hypertension (Brunner & Suddarth''s Medical-Surgical Nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A positive test for overactivity of the adrenal medulla is an epinephrine value of:', '50 pg/mL.', '100 pg/mL.', '100 to 300 pg/mL.', '450 pg/mL.', 'D', 'Normal plasma epinephrine is under ~100 pg/mL; values above ~400 pg/mL indicate adrenal medulla overactivity (pheochromocytoma). 450 pg/mL is clearly elevated and positive (Brunner & Suddarth''s Medical-Surgical Nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Laboratory findings suggestive of Addison''s disease include all of the following except:', 'A relative lymphocytosis.', 'Hyperkalemia and hyponatremia.', 'Hypertension.', 'Hypoglycemia.', 'C', 'Addison''s disease (adrenal insufficiency) causes HYPOtension, not hypertension, due to aldosterone/cortisol deficiency. Expected findings are hyperkalemia, hyponatremia, hypoglycemia and relative lymphocytosis; hypertension is the exception (Brunner & Suddarth''s Medical-Surgical Nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A positive diagnosis of Cushing''s syndrome is associated with:', 'The disappearance of lymphoid tissue.', 'A reduction in circulating eosinophils.', 'An elevated cortisol levels.', 'All of the above.', 'D', 'Cushing''s syndrome (excess cortisol) produces elevated cortisol levels, involution/disappearance of lymphoid tissue, and eosinopenia (reduced circulating eosinophils); all listed features apply (Brunner & Suddarth''s Medical-Surgical Nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Clinical manifestations of Cushing''s syndrome may be modified with a diet that is:', 'High in protein.', 'Low in carbohydrates.', 'Low in sodium.', 'All of the above.', 'D', 'Cushing''s manifestations are eased by a diet high in protein (counter catabolism), low in carbohydrates (counter hyperglycemia) and low in sodium (counter fluid retention/hypertension); all three apply (Brunner & Suddarth''s Medical-Surgical Nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A patient with aldosteronism would be expected to exhibit all of the following symptoms except:', 'Alkalosis.', 'Hypokalemia.', 'Hyponatremia.', 'An increased pH.', 'C', 'Primary aldosteronism (excess aldosterone) causes sodium retention (HYPERnatremia), potassium loss (hypokalemia), and metabolic alkalosis with raised pH. Hyponatremia is the exception (Brunner & Suddarth''s Medical-Surgical Nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse needs to be aware that large-dose corticosteroid therapy is most effective when administered:', 'At 8:00 AM.', 'At 8:00 PM.', 'Between 4:00 AM and 5:00 AM.', 'Between 4:00 PM and 6:00 PM.', 'A', 'Corticosteroids are best given in the early morning (around 8:00 AM) to mimic the body''s natural diurnal cortisol peak and minimise HPA-axis suppression (Brunner & Suddarth''s Medical-Surgical Nursing; Kenya EML principles).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Nursing assessment for a patient who is receiving corticosteroid therapy includes observation for the unacceptable side effect of:', 'Glaucoma.', 'Facial mooning.', 'Potassium loss.', 'Weight gain', 'A', 'Facial mooning, potassium loss and weight gain are expected/anticipated corticosteroid effects; glaucoma (raised intraocular pressure with possible vision loss) is a serious, unacceptable adverse effect requiring monitoring (Brunner & Suddarth''s Medical-Surgical Nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Traumatic injury of the following section of spine causes acute respiratory failure:', 'L1-L2', 'L3-L4', 'C5-C6', 'C7-C8', 'C', 'The phrenic nerve (diaphragm) arises from C3-C5; high cervical injury at C5-C6 impairs diaphragmatic/respiratory function causing acute respiratory failure, whereas lumbar (L1-L4) injuries spare respiration (Brunner & Suddarth''s Medical-Surgical Nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Barium swallow is used in diagnosis of the following:', 'Jejunal atresia', 'Stomach Cardia', 'Upper GIT', 'Rectal and Sigmoid tumors', 'C', 'A barium swallow outlines the upper gastrointestinal tract (pharynx, esophagus, stomach). Lower/rectosigmoid lesions require a barium enema, not a swallow (Brunner & Suddarth''s Medical-Surgical Nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Chronic respiratory failure manifest with:', 'p.H. =7.36, High PaCO2>50, and PaO2 <50 mmHg', 'p.H. =7.56, High PaCO2>50, and PaO2 <50 mmHg', 'p.H.7.37, High PaCO2<50, and PaO2 <50 mmHg', 'PaO2 <50 mmHg, PaCO2 >50 mmHg, and pH =7.35', 'D', 'Chronic respiratory failure shows hypoxemia (PaO2 <50) and hypercapnia (PaCO2 >50) with a near-normal/compensated pH (~7.35) due to renal bicarbonate retention, unlike the acute uncompensated acidosis in the other options (Brunner & Suddarth''s Medical-Surgical Nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Non atopic asthma is best described as:', 'Start in adulthood.', 'Associated with allergies.', 'Patient with eczema is likely not to have it.', 'Also known as intrinsic asthma.', 'D', 'Non-atopic asthma is not associated with allergy/IgE and is termed intrinsic asthma; it typically starts in adulthood but the defining description is intrinsic (non-allergic) asthma (Brunner & Suddarth''s Medical-Surgical Nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Failure of bone marrow results in:', 'Pernicious anemia.', 'Aplastic anemia with fever.', 'Aplastic anemia without fever.', 'Iron deficiency anemia.', 'B', 'Bone marrow failure causes aplastic anemia; because all cell lines fail (including neutrophils), leukopenia predisposes to infection and fever, distinguishing it from the febrile-free option (Brunner & Suddarth''s Medical-Surgical Nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Hyperplasia of gingiva is likely to be indicator of:', 'Ludwig angina', 'Vincent angina', 'Heart failure', 'Phenytoin therapy', 'D', 'Gingival hyperplasia is a classic adverse effect of phenytoin (anticonvulsant) therapy (Brunner & Suddarth''s Medical-Surgical Nursing; Kenya EML).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The bacteria known to cause dental caries is:', 'Streptococcus aureas', 'Streptococcus mutans', 'Group A beta hemolytic streptococcus', 'Sedenomonous aeruginosa', 'B', 'Streptococcus mutans is the principal bacterium responsible for dental caries through acid production from fermentable carbohydrates (Brunner & Suddarth''s Medical-Surgical Nursing; standard microbiology).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Contralateral shift of trachea in patient with chest complains is likely to be due to:', 'Pneumonia', 'Emphysema', 'Flail chest', 'Tension pneumothorax', 'D', 'Tension pneumothorax builds intrapleural pressure that pushes mediastinal structures and the trachea to the opposite (contralateral) side; it is a life-threatening emergency (Brunner & Suddarth''s Medical-Surgical Nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Biot''s respirations are associated with:', 'Lesions on Pons.', 'Diabetic ketoacidosis.', 'Asthmatic attack.', 'Pneumonia.', 'A', 'Biot''s (ataxic) respirations, an irregular pattern of breaths with apnea, are associated with damage to the pons/medulla (Brunner & Suddarth''s Medical-Surgical Nursing). Kussmaul breathing, not Biot''s, is seen in diabetic ketoacidosis.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('______is the deadliest form of gangrene:', 'Wet gangrene', 'Dry gangrene', 'Gas gangrene', 'Meleney''s gangrene', 'C', 'Gas gangrene (clostridial myonecrosis, usually Clostridium perfringens) is the deadliest, most rapidly fatal form of gangrene due to toxin production and systemic toxicity (Brunner & Suddarth''s Medical-Surgical Nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following is associated with thoracic aortic aneurysm only:', 'Marfan syndrome', 'Hypertension', 'Atherosclerosis', 'Smoking', 'A', 'Marfan syndrome (connective-tissue defect) is specifically linked to thoracic aortic aneurysm/dissection, whereas hypertension, atherosclerosis and smoking are shared risk factors for abdominal aneurysms too (Brunner & Suddarth''s Medical-Surgical Nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A burn obtained as a result of a lightning strike is:', 'Heat burn', 'Thermal burn', 'Radiation burn', 'Electrical burn', 'D', 'A lightning strike delivers a high-voltage electrical current, producing an electrical burn (Brunner & Suddarth''s Medical-Surgical Nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In nursing assessment subjective data is data that the:', 'Patient can report on their own', 'Nurse can assess on their own', 'Nurse and doctor can confirm', 'Patient can report and the nurse can confirm', 'A', 'Subjective data is information reported by the patient (symptoms, feelings) that cannot be directly observed, whereas objective data is measurable/observable by the nurse (Kozier & Erb''s Fundamentals of Nursing).', 'BScN', 'Paper I', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the following procedures involves a segment of the leg being used to provide an alternative pathway for blood flow past a point of obstruction between the aorta and coronary artery:', 'Angioplasty', 'Coronary angiography', 'Heart transplant', 'Coronary bypass', 'D', 'Coronary artery bypass graft (CABG) uses a vessel such as the saphenous vein from the leg to bypass an obstruction and restore blood flow to the coronary artery (Brunner & Suddarth''s Medical-Surgical Nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the following procedures involves using a small plastic balloon to open a narrowed artery:', 'Heart transplant', 'Coronary bypass', 'Angioplasty', 'Coronary angiography', 'C', 'Percutaneous transluminal (balloon) angioplasty uses a small inflatable balloon to open a narrowed artery (Brunner & Suddarth''s Medical-Surgical Nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The most common symptom of myocardial infarction is:', 'Palpitations', 'Edema', 'Dyspnea', 'Chest pain', 'D', 'Chest pain (crushing, substernal, possibly radiating) is the most common presenting symptom of myocardial infarction (Brunner & Suddarth''s Medical-Surgical Nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Dyspnea, fatigue, increased pulmonary artery pressure and decreased cardiac output are indicative of:', 'Right valve failure', 'Paracentisis', 'Myocardial infarction', 'Left sided heart failure', 'D', 'Dyspnea, fatigue, raised pulmonary artery pressure and reduced cardiac output reflect left-sided heart failure, where the failing left ventricle causes pulmonary congestion and low output (Brunner & Suddarth''s Medical-Surgical Nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The primary reason for administration of morphine in a patient with myocardial infarction is to relieve:', 'Edema', 'Palpitations', 'Chest pain', 'Dyspnea', 'C', 'In myocardial infarction, morphine is given primarily to relieve severe ischemic chest pain (and also reduces anxiety and cardiac workload/preload) (Brunner & Suddarth''s Medical-Surgical Nursing; Kenya EML).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the following conditions results in coronary artery disease:', 'Renal failure', 'Diabetes mellitus', 'Myocardial infarction', 'Atherosclerosis', 'D', 'Atherosclerosis (plaque buildup narrowing coronary arteries) is the underlying pathological process that directly results in coronary artery disease (Brunner & Suddarth''s Medical-Surgical Nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Nursing diagnoses mostly differ from medical diagnoses in that they are:', 'Primarily concerned with human response, while medical diagnoses are primarily concerned with pathology', 'Dependent upon medical diagnoses for the direction of appropriate interventions', 'Primarily concerned with caring, while medical diagnoses are primarily concerned with curing', 'Primarily concerned with psychosocial parameters, while medical diagnoses are primarily concerned with physiologic parameters.', 'A', 'A nursing diagnosis addresses the patient''s human responses to actual/potential health problems, whereas a medical diagnosis identifies the disease/pathology (Kozier & Erb''s Fundamentals of Nursing).', 'BScN', 'Paper I', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In the management of myocardial infarction, atherectomy is:', 'Removal of atherosclerotic plaque', 'Use of new implants', 'Ballooning of narrowed artery', 'Putting a stent to prevent collapse of artery)', 'A', 'Atherectomy is a catheter-based procedure that cuts away/removes atherosclerotic plaque from the coronary artery wall, distinct from angioplasty (ballooning) or stenting (Brunner & Suddarth''s Medical-Surgical Nursing, cardiovascular interventions).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nursing diagnosis for a patient with angina pectoris is infective tissue perfusion. The plan of care includes the patient outcome criterion of:', 'Experiencing no dyspnea on exertion', 'Reduce ischemia by increasing O2 to tissues', 'Agreeing to discontinue smoking', 'Ambulating 50 feet without experiencing dyspnea', 'D', 'An outcome criterion must be patient-centred, measurable and observable. ''Ambulating 50 feet without dyspnea'' is a specific, measurable patient outcome; the others are goals/interventions rather than measurable outcome criteria (Kozier & Erb''s Fundamentals of Nursing, nursing process).', 'BScN', 'Paper I', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which diagnostic test will be used to test for claudication in peripheral artery disease?', 'Doppler ultrasound', 'Treadmill', 'Arteriogram', 'Ankle brachial index', 'D', 'The ankle-brachial index (ABI) is the primary, first-line diagnostic test for peripheral artery disease/claudication, quantifying arterial insufficiency of the lower limbs (Brunner & Suddarth''s, peripheral vascular assessment).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following cardiovascular condition is more prevalent among females than males:', 'Hypertension', 'Varicose veins', 'Coronary artery disease', 'Myocardial infarction', 'B', 'Varicose veins are more prevalent in females (pregnancy, hormonal influence), whereas coronary artery disease and myocardial infarction are more common in males (Brunner & Suddarth''s, venous disorders).', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which action occurs primarily during the evaluation phase of the nursing process:', 'Decision making and judgment', 'Data collection', 'Reassessment and audit', 'Priority setting and expected outcomes.', 'C', 'The evaluation phase of the nursing process involves reassessing the patient and auditing whether outcomes were met. Data collection is assessment; priority setting/expected outcomes are planning; decision making is diagnosis (Kozier & Erb''s Fundamentals of Nursing).', 'BScN', 'Paper I', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Cognitive skills, key in implementation of nursing process, refers to:', 'A blend of intellectual and ''hand'' on skills', '''Hands on'' skills such as manipulating equipment', 'Problem solving, decision making, critical thinking and curative thinking', 'All activities, verbal and nonverbal, that people use when communicating directly with one another', 'C', 'Cognitive (intellectual) skills in the nursing process refer to problem solving, decision making and critical thinking. Option B describes psychomotor skills and D describes interpersonal skills (Kozier & Erb''s Fundamentals of Nursing, implementation).', 'BScN', 'Paper I', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Hematocrit of 60% is likely to be an indicator of:', 'Leukemia', 'Idiopathic Thrombocytopenia.', 'Non-Hodgkin Lymphoma', 'Polycythemia vera', 'D', 'A markedly elevated hematocrit (60%) indicates an increased red cell mass, characteristic of polycythemia vera. Leukemia, ITP and lymphoma do not raise the hematocrit (Brunner & Suddarth''s, hematologic disorders).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Vitamin B12 anemia is characterized by:', 'Microcytosis of RBC', 'Normal hematocrit', 'Hypochromic RBC', 'Macrocytosis of RBC', 'D', 'Vitamin B12 deficiency causes megaloblastic (macrocytic) anemia characterized by large red cells (macrocytosis) with high MCV, not microcytosis or hypochromia (Brunner & Suddarth''s, anemias).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One following oxygen delivery system has constant FiO2:', 'Nasal Prongs', 'Venturi Mask', 'Non-rebreather mask', 'Partial rebreather mask', 'B', 'The Venturi mask is a high-flow device that delivers a precise, constant FiO2 regardless of the patient''s breathing pattern; nasal prongs and rebreather masks deliver variable FiO2 (Brunner & Suddarth''s, oxygen therapy).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Patient manifesting with "hot potato voice" is likely to be suffering from:', 'Vincent angina', 'Periodontitis', 'Asthma', 'Ludwig Angina', 'D', 'A muffled ''hot potato voice'' results from the pharyngeal/submandibular swelling of Ludwig''s angina (and severe peritonsillar/deep neck infection); it is not a feature of asthma or periodontitis (Brunner & Suddarth''s, upper airway infections).', 'BScN', 'Paper I', 'Infection Prevention & Control', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nursing action needed for claustrophobic patient before MRI is:', 'Explain the procedure to the patient.', 'Assume patient''s concerns', 'Give paralytic drugs to the patient.', 'Tell the patient to man up.', 'A', 'For a claustrophobic patient facing MRI, the nurse should first explain the procedure to reduce anxiety and gain cooperation; assuming concerns or dismissive/inappropriate responses are non-therapeutic (Kozier & Erb''s Fundamentals of Nursing, therapeutic communication).', 'BScN', 'Paper I', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The best imaging study for patient with basilar artery aneurysm is:', 'Magnetic resonance imaging', 'X-Ray', 'Coronary angiography', 'Radioisotope imaging', 'A', 'MRI (with MR angiography) is the preferred non-invasive imaging for cerebral/basilar artery aneurysms; plain X-ray and coronary angiography are unsuitable for intracranial vessels (Brunner & Suddarth''s, neurologic diagnostics).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Mild intermittent asthma is best managed by:', 'Long-acting beta-adrenergic agonist (LABA)', 'Short acting beta-adrenergic agonist (SABA)', 'Long-acting muscarinic antagonist (LAMA)', 'Inhaled corticosteroids (ICS)', 'B', 'Mild intermittent asthma is managed with a short-acting beta-agonist (SABA) as reliever therapy; ICS and LABA/LAMA are for persistent asthma (GINA/WHO guidance as adopted in Kenya, Brunner & Suddarth''s).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('X-ray film of a patient shows expanded airways. This likely to be indicative of:', 'Emphysema', 'Bronchiectasis', 'Tension pneumothorax', 'Diffused pneumonia', 'A', 'Emphysema causes hyperinflation with expanded/enlarged airspaces and flattened diaphragm on chest X-ray; tension pneumothorax shows lung collapse, not expanded airways (Brunner & Suddarth''s, COPD).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Hemoptysis is defined as:', 'Blood in sputum cough.', 'Blood in GIT', 'Bad breath', 'Dry cough', 'A', 'Hemoptysis is the coughing up of blood or blood-stained sputum from the respiratory tract; blood in the GIT is hematemesis/melena (Brunner & Suddarth''s, respiratory assessment).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the following is an Intracardiac shunt', 'Ductus arteriosus', 'Ductus venosus', 'Foramen ovale', 'Ostia of aorta', 'C', 'The foramen ovale is an intracardiac shunt between the right and left atria in fetal circulation; the ductus arteriosus and ductus venosus are extracardiac shunts (Guyton/standard physiology; fetal circulation).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The immediate drainage of left intercostal veins is____________', 'Internal thoracic vein', 'Azygous vein', 'Hemiazagous vein', 'Inferior venacava', 'C', 'The left (lower) posterior intercostal veins drain immediately into the hemiazygos vein, which then crosses to the azygos vein; the right side drains to the azygos (standard anatomy, venous drainage of the thorax).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The cerebral vessels, CSF, and the cranial nerves are found within____________space.', 'Subdural', 'Epidural', 'Subarachnoid', 'Beneath Pia matter', 'C', 'The subarachnoid space contains cerebrospinal fluid (CSF), the cerebral vessels and the cranial nerves as they traverse it; the subdural and epidural spaces are potential spaces (standard neuroanatomy).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the following will reduce pulse of pressure of an individual:', 'Reduced osmolality', 'Dehydration', 'Highly hydration status', 'Low temperatures', 'B', 'Pulse pressure is stroke volume dependent; dehydration/hypovolemia reduces stroke volume and thus narrows the pulse pressure. Overhydration would widen it (Guyton physiology; Brunner & Suddarth''s, fluid balance).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Sensory neurons enter the spinal cord via:', 'Lateral horn', 'Anterior horn', 'Central canal', 'Posterior horn', 'D', 'Sensory (afferent) neurons enter the spinal cord via the dorsal (posterior) root and synapse in the posterior/dorsal horn; motor neurons exit via the anterior horn (standard neuroanatomy).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following conductive system of the heart fire action potential at higher frequency than the rest:', 'Sino Atrio Node', 'Atrioventricular Node', 'Bundle of His', 'Purkinje fibers', 'A', 'The sinoatrial (SA) node has the fastest intrinsic firing rate (~60-100/min) and thus acts as the natural pacemaker; the AV node, Bundle of His and Purkinje fibers fire at progressively lower rates (Guyton physiology; cardiac conduction).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The anterior 2/3 of tongue is innervated by cranial nerve:', '1', '3', '5', '7', 'D', 'General sensation of the anterior two-thirds of the tongue is via the lingual (V3) nerve, but taste is carried by the chorda tympani of the facial nerve (cranial nerve VII); among the options 7 (facial) is correct for taste innervation (standard neuroanatomy).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Spinal cord terminates at:', 'T12-L1', 'T11-T12', 'L1-L2', 'L4-L5', 'C', 'In adults the spinal cord terminates as the conus medullaris at the L1-L2 vertebral level; below this is the cauda equina (standard neuroanatomy).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Phrenic nerve is formed by following spinal cord plexus:', 'Cervical plexus', 'Lumber plexus', 'Thoracic nerves', 'Sacral plexus', 'A', 'The phrenic nerve arises from the cervical plexus (C3, C4, C5) and supplies the diaphragm (standard anatomy, cervical plexus).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the following is true about renal system:', 'Renal artery carries purified blood.', 'Renal vein carries oxygenated blood.', 'Renal vein carries blood with metabolic wastes.', 'It participates in erythropoiesis', 'D', 'The kidney produces erythropoietin and thus participates in erythropoiesis. The renal artery carries oxygenated (not purified) blood and the renal vein carries deoxygenated, filtered blood, making the other options false (Guyton physiology; renal function).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the following wave represent atrial depolarization:', 'P', 'Q', 'R', 'T', 'A', 'The P wave of the ECG represents atrial depolarization; the QRS represents ventricular depolarization and the T wave ventricular repolarization (Brunner & Suddarth''s, ECG interpretation).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The occipital lobe of brain:', 'Concerned with olfaction', 'Concerned with sense of test', 'Control osmolality', 'Concerned with vision.', 'D', 'The occipital lobe contains the primary visual cortex and is concerned with vision; olfaction and taste are processed elsewhere (standard neuroanatomy).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of following is a nerve formed by brachial plexus:', 'Radial nerve', 'Tibial nerve', 'Sciatic nerve', 'Pudendal nerve', 'A', 'The radial nerve is a branch of the brachial plexus supplying the upper limb; the tibial, sciatic and pudendal nerves arise from the lumbosacral plexus (standard anatomy, brachial plexus).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The fibers that pass through the internal capsule form:', 'Pyramidal tracts', 'Extrapyramidal tract', 'Rubrospinal tract', 'Cranial nerves', 'A', 'The corticospinal (pyramidal) tract fibers descend through the posterior limb of the internal capsule; the extrapyramidal and rubrospinal tracts take other routes (standard neuroanatomy, motor pathways).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following cranial nerve innervates the lateral rectus muscle of the eye:', '1', '3', '5', '6', 'D', 'The abducens nerve (cranial nerve VI) innervates the lateral rectus muscle, which abducts the eye (standard neuroanatomy, cranial nerves).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Collection of cell bodies in the central nervous system forms:', 'White matter', 'Grey matter', 'Commissures', 'Ganglion', 'B', 'Per standard neuroanatomy (Kozier & Erb''s / Brunner & Suddarth), collections of neuronal cell bodies within the CNS form grey matter, whereas myelinated axons form white matter and a cluster of cell bodies OUTSIDE the CNS is a ganglion.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Gonadal arteries branch from:', 'Internal iliac artery', 'External iliac artery', 'Abdominal aorta', 'Subclavian artery', 'C', 'Per standard anatomy (Gray''s/anatomy texts used in Kenyan training), the gonadal (testicular/ovarian) arteries arise directly from the abdominal aorta below the renal arteries, not from the iliac or subclavian vessels.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Foamy and greasy stool is a likely indicator of:', 'Secretory Diarrhea', 'Celiac disease', 'Upper GI bleeding', 'Steatorrhea', 'D', 'Per Brunner & Suddarth, foamy, greasy, bulky, foul-smelling stool that reflects fat malabsorption is by definition steatorrhea; celiac disease can cause it but the descriptive finding itself IS steatorrhea.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Esophageal varices are caused by:', 'GERD', 'Peptic ulcers', 'Cirrhosis', 'Hemorrhoids', 'C', 'Per Brunner & Suddarth, oesophageal varices result from portal hypertension, most commonly caused by hepatic cirrhosis, which raises portal venous pressure and dilates the oesophageal collateral veins.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following gastrointestinal disorder is managed best by downscaling wheat product in diet', 'Irritable bowel syndrome', 'Diverticulum', 'Celiac disease', 'Esophageal varices.', 'C', 'Per Brunner & Suddarth, celiac disease is gluten-sensitive enteropathy; management centres on a gluten-free diet, i.e. eliminating wheat, barley and rye products.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the following disorder is caused by increased tone of lower esophageal sphincter:', 'GERD', 'Achalasia', 'Hiatal hernia', 'Dumping syndrome', 'B', 'Per Brunner & Suddarth, achalasia is characterised by increased tone / failure of relaxation of the lower oesophageal sphincter, whereas GERD and hiatal hernia involve a weak/incompetent LES.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Oliguria in renal function means:', 'Urine output of < 250 mL /24 hours', 'Urine output of <1000 mL /24 hours', 'Urine output of < 2500 mL /24 hours', 'Urine output of < 500 mL /24 hours', 'D', 'Per Brunner & Suddarth and standard renal physiology, oliguria is defined as urine output less than 500 mL in 24 hours (or <0.5 mL/kg/hr); <100 mL/24 hr is anuria.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Normal Glomerular Filtration Rate (GFR) is_________ mL /min/m2  and above.', '30', '40', '50', '60', 'D', 'Per KDIGO/standard renal references used in Kenyan practice, a normal GFR is ≥60 mL/min/1.73 m2 (typically 90–120); values below 60 sustained ≥3 months indicate chronic kidney disease.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Urine specific gravity of 1.100 is indicative of:', 'Normal hydration', 'Fluid overload', 'Dehydration', 'None of the above', 'C', 'Per Brunner & Suddarth, a high urine specific gravity indicates concentrated urine seen in dehydration/fluid volume deficit (normal range ~1.005–1.030); a very high value reflects reduced water intake and haemoconcentration.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the following is inappropriate health education to a discharge patient with chronic kidney disease.', 'Use NSAID to manage mild pain.', 'Reduce red meat intake and increase carbohydrates', 'Reduce dietary intake of salt intake.', 'Reduce dietary intake of potassium.', 'A', 'Per Kenya MOH renal/CKD guidance and Brunner & Suddarth, NSAIDs are nephrotoxic and contraindicated in CKD, so advising their use is INAPPROPRIATE education; salt, potassium and protein restriction are appropriate.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Management of moderately elevated K+ in a patient with acute kidney injury involve the following:', 'Administration of KCl by slow infusion', 'Administration of spironolactone to aid elimination.', 'Administration of insulin to aid in redistribution', 'None of the above', 'C', 'Per Brunner & Suddarth and MOH emergency guidance, IV insulin (with dextrose) shifts potassium intracellularly to lower serum K+; giving KCl would worsen it and spironolactone (K-sparing) is contraindicated in hyperkalaemia/AKI.', 'BScN', 'Paper I', 'Nursing Management & Leadership', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Nephrotic syndrome is manifested by one of the following:', 'Proteinuria, Hypoalbuminemia, Edema, Hyperlipidemia.', 'Hyperkalemia, Hyperalbuminemia, Edema, Hypertension', 'Proteinuria, Hypoalbuminemia, Edema, Hypokalemia', 'Proteinuria, Hyperalbuminemia, Edema, Hyperlipidemia.', 'A', 'Per Brunner & Suddarth, the classic tetrad of nephrotic syndrome is massive proteinuria, hypoalbuminaemia, oedema and hyperlipidaemia.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the following is likely to cause urolithiasis', 'Hypertension', 'Diabetes insipidus', 'Hyperparathyroidism', 'Compulsive water intake', 'C', 'Per Brunner & Suddarth, hyperparathyroidism raises serum calcium and urinary calcium excretion, predisposing to calcium-containing renal stones (urolithiasis); compulsive water intake is protective.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The most common kidney stones are:', 'Calcium Phosphate salts.', 'Uric acid and Struvite', 'Calcium Oxalate', 'Amino acid Cystine', 'C', 'Per Brunner & Suddarth, calcium oxalate stones are the most common type of kidney stone (about 75–80% of cases).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Lesion of cranial nerve VII causes one of the following:', 'Ebbs palsy', 'Inability to raise neck', 'Bell''s Palsy', 'Anosmia', 'C', 'Per standard neuroanatomy (Brunner & Suddarth), the facial nerve (CN VII) supplies the muscles of facial expression; its lesion causes Bell''s palsy (unilateral facial droop). Anosmia is CN I; CN VII does not affect neck raising.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which one of the following combinations of antiparkinsonian drugs is an appropriate treatment plan?', 'Amantadine, carbidopa, and entacapone.', 'Levodopa, carbidopa, and entacapone.', 'Pramipexole, carbidopa, and entacapone.', 'Ropinirole, carbidopa, and selegiline.', 'B', 'Per Kenya EML/pharmacology texts, the standard Parkinson''s regimen combines levodopa (dopamine precursor) with carbidopa (peripheral decarboxylase inhibitor) and entacapone (COMT inhibitor); the other options pair carbidopa with drugs (amantadine, dopamine agonists) that are not levodopa and so gain no benefit from carbidopa.', 'BScN', 'Paper I', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Carbidopa used as antiparkinsonian drug is a:', 'Dopamine receptor agonist', 'Decarboxylase inhibitor', 'Catechol-o-methyl transferase inhibitor', 'Monoamine oxidase B inhibitor', 'B', 'Per standard pharmacology, carbidopa is a peripheral dopa-decarboxylase inhibitor that prevents peripheral conversion of levodopa, increasing CNS availability and reducing peripheral side effects.', 'BScN', 'Paper I', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The part of brain affected in parkinsonian disease is the:', 'Limbic system', 'Occipital lobe', 'Pyramidal tracts', 'Basal ganglia', 'D', 'Per Brunner & Suddarth, Parkinson''s disease results from degeneration of dopaminergic neurons in the substantia nigra of the basal ganglia, impairing control of voluntary movement.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the following is a rapidly progressing, ascending inflammatory demyelinating polyneuropathy of the peripheral sensory and motor nerves and nerve roots disease.', 'Myasthenia Gravis', 'Guillain-Barre Syndrome', 'Multiple Myeloma', 'Alzheimer''s disease', 'B', 'Per Brunner & Suddarth, Guillain-Barre syndrome is an acute, rapidly progressive ascending inflammatory demyelinating polyneuropathy affecting peripheral sensory and motor nerves and nerve roots.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following is a cutoff for diagnosis of increased intracranial pressure (ICP):', 'ICP of 5 mmHg', 'ICP of 10 mmHg', 'ICP of 15 mmHg', 'ICP of 20 mmHg', 'D', 'Per Brunner & Suddarth and standard neuro-critical care, normal ICP is 5–15 mmHg; a sustained ICP above 20 mmHg is the threshold defining raised intracranial pressure requiring treatment.
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When caring for a 3-day-old neonate who is receiving phototherapy to treat jaundice, the nurse in charge would expect to do which of the following?', 'Turn the neonate every 6 hours', 'Encourage the mother to discontinue breastfeeding', 'Notify the physician if the skin becomes bronze', 'Check the vital signs every 2 to 4 hours', 'D', 'During phototherapy the neonate can become hyperthermic/dehydrated, so vital signs are monitored every 2-4 hours; breastfeeding is continued and bronze skin (bronze-baby syndrome) is documented, not primarily reported. Per Basic Paediatric Protocols (Kenya) neonatal jaundice management.', 'BScN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is caring for a primigravida at about 2 months and 1-week gestation. After explaining self-care measures for common discomforts of pregnancy, the nurse determines that the client understands the instructions when she says:', '“Nausea and vomiting can be reduced if I eat a few crackers before rising”', '“If I start to leak colostrum, I should cleanse my nipples with soap and water.”', '“If I have a vaginal discharge, I should wear nylon underwear.”', '“Leg cramps can be alleviated if I put an ice pack on the area.”', 'A', 'Eating dry crackers before rising is the correct self-care for morning nausea. Nipples should be washed with water only (soap dries them), cotton (not nylon) underwear is advised, and leg cramps are relieved by dorsiflexion/warmth, not ice. Per Myles Textbook for Midwives (minor disorders of pregnancy).', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse plans to instruct the postpartum client about methods to prevent breast engorgement. Which of the following measures would the nurse include in the teaching plan?', 'Feeding the neonate a maximum of 5 minutes per side on the first day', 'Wearing a supportive brassiere with nipple shields', 'Breastfeeding the neonate at frequent intervals', 'Decreasing fluid intake for the first 24 to 48 hours', 'C', 'Frequent breastfeeding empties the breasts and prevents engorgement; time-limited feeds, restricting fluids, and nipple shields do not prevent engorgement. Per Myles Textbook for Midwives / MOH breastfeeding guidelines.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When the nurse on duty accidentally bumps the bassinet, the neonate throws out its arms, hands open, and begins to cry. The nurse interprets this reaction as indicative of which of the following reflexes?', 'Startle reflex', 'Babinski reflex', 'Grasping reflex', 'Tonic neck reflex', 'A', 'Sudden jarring causing symmetrical arm abduction with open hands followed by crying is the Moro (startle) reflex. Babinski is toe fanning to sole stroking, grasp is finger curling, and tonic neck is the fencing posture. Per Kozier & Erb / Basic Paediatric Protocols (newborn assessment).', 'BScN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following would the nurse most likely expect to find when assessing a pregnant client with abruption placenta?', 'Excessive vaginal bleeding', 'Rigid, board-like abdomen', 'Tetanic uterine contractions', 'Premature rupture of membranes', 'B', 'Abruptio placentae classically causes a rigid, board-like, tender abdomen from concealed retroplacental bleeding; vaginal bleeding may be minimal/concealed. Excessive painless bleeding suggests previa. Per Myles Textbook for Midwives / MOH obstetric guidelines.', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse in charge is caring for a patient who is in the first stage of labor. What is the shortest but most difficult part of this stage?', 'Active phase', 'Complete phase', 'Latent phase', 'Transitional phase', 'D', 'The transitional phase (8-10 cm) is the shortest but most intense and difficult part of the first stage of labor. Per Myles Textbook for Midwives (stages of labor).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is developing a teaching plan for a patient who is 8 weeks pregnant. The nurse should tell the patient that she can expect to feel the fetus move at which time?', 'Between 10 and 12 weeks’ gestation', 'Between 16 and 20 weeks’ gestation', 'Between 21 and 23 weeks’ gestation', 'Between 24 and 26 weeks’ gestation', 'B', 'Quickening (first felt fetal movement) typically occurs at 16-20 weeks in a primigravida. Per Myles Textbook for Midwives (presumptive signs of pregnancy).', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Normal lochial findings in the first 24 hours post-delivery include:', 'Bright red blood', 'Large clots or tissue fragments', 'A foul odor', 'The complete absence of lochia', 'A', 'Lochia rubra (bright red blood) is normal in the first 1-3 days postpartum. Large clots/tissue, foul odor, and absence of lochia are abnormal. Per Myles Textbook for Midwives (puerperium).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse in-charge is reviewing a patient’s prenatal history. Which finding indicates a genetic risk factor?', 'The patient is 25 years old', 'The patient has a child with cystic fibrosis', 'The patient was exposed to rubella at 36 weeks’ gestation', 'The patient has a history of preterm labor at 32 weeks’ gestation', 'B', 'Cystic fibrosis is an autosomal recessive inherited disorder, so a previously affected child is a genetic risk factor. Rubella exposure is teratogenic (not genetic) and preterm labor is obstetric history. Per Myles / genetics in midwifery.', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is caring for a client in labor. The external fetal monitor shows a pattern of variable decelerations in fetal heart rate. What should the nurse do first?', 'Change the client’s position', 'Prepare for an emergency cesarean section', 'Check for placenta previa', 'Administer oxygen', 'A', 'Variable decelerations indicate cord compression; the first intrauterine resuscitation step is repositioning the mother to relieve pressure, then oxygen. Cesarean is a later step if the pattern persists. Per WHO/MOH intrapartum guidelines and Myles.', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When administering magnesium sulfate to a client with preeclampsia, the nurse understands that this drug is given to:', 'Prevent seizures', 'Reduce blood pressure', 'Slow the process of labor', 'Increase diuresis', 'A', 'Magnesium sulfate is given in pre-eclampsia/eclampsia as an anticonvulsant to prevent and control seizures, not primarily to lower blood pressure. Per MOH/WHO eclampsia guidelines and Kenya EML.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is teaching care of the newborn to a childbirth preparation class and describes the need for administering antibiotic ointment into the eyes of the newborn. An expectant father asks, “What type of disease causes infections in babies that can be prevented by using this ointment?” Which response by the nurse is accurate?', 'Herpes', 'Trichomonas', 'Gonorrhea', 'Syphilis', 'C', 'Neonatal eye prophylaxis (tetracycline/erythromycin ointment) prevents ophthalmia neonatorum caused by maternal Neisseria gonorrhoeae (and chlamydia). Per MOH newborn care guidelines / Basic Paediatric Protocols.', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is counseling a couple who has sought information about conceiving. The couple asks the nurse to explain when ovulation usually occurs. Which statement by the nurse is correct?', 'Two weeks before menstruation', 'Immediately after menstruation', 'Immediately before menstruation', 'Three weeks before menstruation', 'A', 'Ovulation occurs about 14 days before the next menstrual period (mid-cycle in a 28-day cycle), driven by the fixed luteal phase length. Per Myles Textbook for Midwives (menstrual cycle physiology).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following urinary symptoms does the pregnant woman most frequently experience during the first trimester?', 'Dysuria', 'Frequency', 'Incontinence', 'Burning', 'B', 'First-trimester uterine enlargement presses on the bladder causing urinary frequency; dysuria and burning suggest infection, not normal pregnancy. Per Myles Textbook for Midwives (minor disorders).', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In which of the following areas would the nurse expect to observe chloasma?', 'Breast, areola, and nipples', 'Chest, neck, arms, and legs', 'Abdomen, breast, and thighs', 'Cheeks, forehead, and nose', 'D', 'Chloasma (melasma, the “mask of pregnancy”) is hyperpigmentation over the cheeks, forehead, and nose. Per Myles Textbook for Midwives (skin changes in pregnancy).', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Cervical softening and uterine souffle are classified as which of the following?', 'Diagnostic signs', 'Presumptive signs', 'Probable signs', 'Positive signs', 'C', 'Cervical softening (Goodell sign) and uterine souffle are objective changes detected by the examiner but not conclusive of pregnancy, so they are probable signs. Per Myles Textbook for Midwives (signs of pregnancy).', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following would the nurse identify as a presumptive sign of pregnancy?', 'Hegar sign', 'Nausea and vomiting', 'Skin pigmentation changes', 'Positive serum pregnancy test', 'B', 'Presumptive signs are subjective symptoms reported by the woman, such as nausea and vomiting. Hegar sign and pigmentation are probable, and a positive serum test/fetal detection is positive/probable. Per Myles Textbook for Midwives.', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following would be a disadvantage of breastfeeding?', 'Involution occurs more rapidly', 'The incidence of allergies increases due to maternal antibodies', 'The father may resent the infant’s demands on the mother’s body', 'There is a greater chance for error during preparation', 'C', 'A recognized disadvantage of breastfeeding is that the father may feel excluded or resent the infant''s demands on the mother. Faster involution and antibody transfer are advantages, and preparation error applies to formula. Per Myles Textbook for Midwives (breastfeeding).', 'BScN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following would cause a false-positive result on a pregnancy test?', 'The test was performed less than 10 days after an abortion', 'The test was performed too early or too late in the pregnancy', 'The urine sample was stored too long at room temperature', 'A spontaneous abortion or a missed abortion is impending', 'A', 'hCG remains detectable for up to ~10 days after abortion/delivery, giving a false-positive pregnancy test. Prolonged storage or wrong timing typically cause false negatives, and impending abortion is not a false positive. Per standard laboratory/midwifery references.', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following danger signs should be reported promptly during the antepartum period?', 'Constipation', 'Breast tenderness', 'Nasal stuffiness', 'Leaking amniotic fluid', 'D', 'Per Kenya MOH/WHO focused ANC danger signs, leaking amniotic fluid (PROM) risks infection and preterm labour and must be reported; constipation, breast tenderness and nasal stuffiness are normal pregnancy discomforts.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following characteristics of contractions would the nurse expect to find in a client experiencing true labor?', 'Occurring at irregular intervals', 'Starting mainly in the abdomen', 'Gradually increasing intervals', 'Increasing intensity with walking', 'D', 'Myles Textbook for Midwives: true labour contractions are regular, begin in the back radiating to the abdomen, come at shortening intervals and intensify with activity/walking, unlike false labour which eases with walking.', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('During which of the following stages of labor would the nurse assess “crowning”?', 'First stage', 'Second stage', 'Third stage', 'Fourth stage', 'B', 'Crowning (the fetal head remaining visible at the vulva between contractions) occurs in the second stage of labour, the stage of expulsion (Myles Textbook for Midwives).', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following nursing interventions would the nurse perform during the third stage of labor?', 'Obtain a urine specimen and other laboratory tests', 'Assess uterine contractions every 30 minutes', 'Coach for effective client pushing', 'Promote parent-newborn interaction', 'D', 'The third stage runs from birth of the baby to delivery of the placenta; while awaiting placental separation the nurse promotes early parent-newborn bonding/interaction. Pushing coaching is second stage (Myles Textbook for Midwives).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following actions demonstrates the nurse’s understanding of the newborn’s thermoregulatory ability?', 'Placing the newborn under a radiant warmer', 'Suctioning with a bulb syringe', 'Obtaining an Apgar score', 'Inspecting the newborn’s umbilical cord', 'A', 'Newborns lose heat rapidly and have limited thermoregulation; placing under a radiant warmer (or skin-to-skin) prevents cold stress (Kenya Basic Paediatric Protocols / newborn care). The other actions relate to airway, scoring and cord, not thermoregulation.', 'BScN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Immediately before expulsion, which of the following cardinal movements occur?', 'Descent', 'Flexion', 'Extension', 'External rotation', 'C', 'In the cardinal movements of labour, extension of the fetal head occurs as it distends the vulva and is born immediately before expulsion; external rotation (restitution) follows after the head is delivered (Myles Textbook for Midwives).', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When assessing the newborn’s heart rate, which of the following ranges would be considered normal if the newborn were sleeping?', '80 beats per minute', '100 beats per minute', '120 beats per minute', '140 beats per minute', 'B', 'Normal newborn heart rate is 120-160 bpm awake but may drop to about 100 bpm during sleep, which remains within normal limits (Kenya Basic Paediatric Protocols; newborn assessment).', 'BScN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is true regarding the fontanels of the newborn?', 'The anterior is triangular shaped; the posterior is diamond-shaped', 'The posterior closes at 18 months; the anterior closes at 8 to 12 weeks', 'The anterior is large in size when compared to the posterior fontanel', 'The anterior is bulging; the posterior appears sunken', 'C', 'The anterior fontanel is diamond-shaped and larger, closing at 12-18 months; the posterior is triangular, smaller, closing by ~8-12 weeks. Option C is correct; option A reverses the shapes (Myles/newborn assessment).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following describes the Babinski reflex?', 'The newborn’s toes will hyperextend and fan apart from the dorsiflexion of the big toe when one side of the foot is stroked upward from the ball of the heel and across the ball of the foot.', 'The newborn abducts and flexes all extremities and may begin to cry when exposed to sudden movement or loud noise', 'The newborn turns the head in the direction of the stimulus, opens the mouth, and begins to suck when the cheek, lip, or corner of the mouth is touched', 'The newborn will attempt to crawl forward with both arms and legs when he is placed on his abdomen on a flat surface', 'A', 'Babinski reflex: stroking the sole causes dorsiflexion of the big toe with fanning of the toes. Option B describes Moro, C describes rooting, D describes the crawl reflex (newborn reflex assessment).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following statements best describes hyperemesis gravidarum?', 'Severe anemia leading to an electrolyte, metabolic, and nutritional imbalances in the absence of other medical problems', 'Severe nausea and vomiting leading to an electrolyte, metabolic, and nutritional imbalances in the absence of other medical problems', 'Loss of appetite and continuous vomiting that commonly results in dehydration and ultimately decreasing maternal nutrients', 'Severe nausea and diarrhea that can cause gastrointestinal irritation and possibly internal bleeding.', 'B', 'Hyperemesis gravidarum is severe, persistent nausea and vomiting in pregnancy causing dehydration, electrolyte, metabolic and nutritional imbalance without other medical cause (Myles Textbook for Midwives).', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In which of the following types of spontaneous abortions would the nurse assess dark brown vaginal discharge and a negative pregnancy test?', 'Threatened', 'Imminent', 'Missed', 'Incomplete', 'C', 'In a missed abortion the fetus dies but is retained; the woman has a dark brown discharge and, as hormone levels fall, the pregnancy test becomes negative. Threatened abortion still has a positive test (Myles Textbook for Midwives).', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is described as premature separation of a normally implanted placenta during the second half of pregnancy, usually with severe hemorrhage?', 'Placenta previa', 'Ectopic pregnancy', 'Incompetent cervix', 'Abruptio placenta', 'D', 'Abruptio placentae is premature separation of a normally implanted placenta after 20 weeks, usually with severe haemorrhage. Placenta previa is abnormal low implantation, not premature separation (Myles Textbook for Midwives).', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following best describes preterm labor?', 'Labor that begins after 20 weeks gestation and before 37 weeks gestation', 'Labor that begins after 15 weeks gestation and before 37 weeks gestation', 'Labor that begins after 24 weeks gestation and before 28 weeks gestation', 'Labor that begins after 28 weeks gestation and before 40 weeks gestation', 'A', 'Preterm labour is defined as labour occurring after 20 (viability threshold) and before 37 completed weeks of gestation (WHO/Myles Textbook for Midwives).', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following factors is the underlying cause of dystocia?', 'Nutritional', 'Mechanical', 'Environmental', 'Medical', 'B', 'Dystocia (difficult labour) arises from mechanical problems in the powers, passage or passenger (uterine dysfunction, cephalopelvic disproportion, malposition). The underlying cause is mechanical (Myles Textbook for Midwives).', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When uterine rupture occurs, which of the following would be the priority?', 'Limiting hypovolemic shock', 'Obtaining blood specimens', 'Instituting complete bed rest', 'Inserting a urinary catheter', 'A', 'Uterine rupture causes catastrophic haemorrhage; the priority is limiting/managing hypovolaemic shock (fluid resuscitation, restore circulating volume) alongside preparation for surgery (Myles Textbook for Midwives; ABC priority).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is the nurse’s initial action when umbilical cord prolapse occurs?', 'Begin monitoring maternal vital signs and FHR', 'Place the client in a knee-chest position in bed', 'Notify the physician and prepare the client for delivery', 'Apply a sterile warm saline dressing to the exposed cord', 'B', 'The immediate/first action in cord prolapse is to relieve pressure on the cord by positioning the mother knee-chest (or Trendelenburg) to prevent fetal hypoxia, before notifying and preparing for delivery (Myles Textbook for Midwives).', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following amounts of blood loss following birth marks the criterion for describing postpartum hemorrhage?', 'More than 200 ml', 'More than 300 ml', 'More than 400 ml', 'More than 500 ml', 'D', 'Postpartum haemorrhage is classically defined as blood loss exceeding 500 ml after vaginal birth (Kenya MOH maternal guidelines / WHO; Myles Textbook for Midwives).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following best reflects the frequency of reported postpartum “blues”?', 'Between 10% and 40% of all new mothers report some form of postpartum blues', 'Between 30% and 50% of all new mothers report some form of postpartum blues', 'Between 50% and 80% of all new mothers report some form of postpartum blues', 'Between 25% and 70% of all new mothers report some form of postpartum blues', 'C', 'Postpartum (baby) blues are very common, affecting roughly 50-80% of new mothers, a transient self-limiting mood disturbance in the first postnatal days (Myles Textbook for Midwives; maternal mental health).', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('For the client who is using oral contraceptives, the nurse informs the client about the need to take the pill at the same time each day to accomplish which of the following?', 'Decrease the incidence of nausea', 'Maintain hormonal levels', 'Reduce side effects', 'Prevent drug interactions', 'B', 'Taking oral contraceptives at the same time daily keeps steady hormone (estrogen/progestin) blood levels, ensuring reliable ovulation suppression and contraceptive efficacy (Kenya National Family Planning Guidelines).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When teaching a client about contraception. Which of the following would the nurse include as the most effective method for preventing sexually transmitted infections?', 'Spermicides', 'Diaphragm', 'Condoms', 'Vasectomy', 'C', 'Condoms (barrier method) are the most effective contraceptive method for preventing STIs by preventing exchange of body fluids; spermicides, diaphragm and vasectomy do not protect against STIs (Kenya National Family Planning Guidelines).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('For which of the following clients would the nurse expect that an intrauterine device would not be recommended?', 'Woman over age 35', 'Nulliparous woman', 'Promiscuous young adult', 'Postpartum client', 'C', 'An IUD is not recommended for women at high risk of STIs (multiple partners) because of the increased risk of pelvic inflammatory disease with ascending infection (Kenya National Family Planning Guidelines / WHO MEC).', 'BScN', 'Paper I', 'Infection Prevention & Control', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client tells the nurse that her last menstrual period started on January 14 and ended on January 20. Using Nagele’s rule, the nurse determines her EDD to be which of the following?', 'September 27', 'October 21', 'November 7', 'December 27', 'B', 'Naegele''s rule uses the first day of LMP (Jan 14): + 7 days = Jan 21, - 3 months = Oct 21. EDD is October 21 (Myles Textbook for Midwives).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse assesses the postpartum vaginal discharge (lochia) on four clients. Which of the following assessments would warrant notification of the physician?', 'A dark red discharge on a 2-day postpartum client', 'A pink to brownish discharge on a client who is 5 days postpartum', 'Almost colorless to creamy discharge on a client 2 weeks after delivery', 'A bright red discharge 5 days after delivery', 'D', 'By day 5 lochia should be serosa (pink/brown). Bright red (rubra) lochia at 5 days suggests fresh bleeding/possible haemorrhage and warrants physician notification; the other findings follow the normal lochia progression (Myles Textbook for Midwives).', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nutritional supplement given to a woman during the preconception care to prevent neural tube defect is:', 'Iron', 'Zinc', 'Folate', 'Calcium', 'C', 'Per Kenya National MNH/preconception guidelines and WHO, folic acid (folate) supplementation before and in early pregnancy prevents neural tube defects; iron/zinc/calcium do not.', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The hormone responsible for the regeneration and proliferation of the endothelium during each menstrual cycle, after menstruation has taken place is:', 'Progesterone', 'Estrogen', 'Estradiol', 'Inhibin', 'B', 'Per Myles Textbook for Midwives, estrogen from the developing follicles drives regeneration and proliferation of the endometrium during the proliferative phase after menstruation; progesterone dominates the secretory phase.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Pica is usually a sign of -------in pregnancy:', 'Anemia', 'Heart disease', 'Diabetes mellitus', 'Syphilitic infection', 'A', 'Per Myles Textbook for Midwives, pica (craving non-food substances) in pregnancy is commonly associated with iron-deficiency anaemia.', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('While evaluating urine output for a mother in shock, the midwife is concerned if the urine output is:', '< 30ml/h', '> 30ml/h', '< 150 ml/h', '> 150ml/h', 'A', 'Per Kenya MNH guidelines and Myles, urine output below 30 ml/hour indicates inadequate renal perfusion and is a concerning sign of shock/hypovolaemia.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following sign may help a midwife diagnose shoulder dystocia in labour ward?', 'The fetal head remains slightly stuck in the vagina', 'The anterior shoulder is delivered but the posterior one is stuck', 'The chin retracts and depresses the perineum', 'Traction of the head delivers the shoulder', 'C', 'Per Myles Textbook for Midwives, shoulder dystocia is recognised by the ''turtle sign''—the head delivers then retracts against the perineum (chin retracts/depresses perineum) because the anterior shoulder is impacted behind the symphysis.', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The first maneuver a nurse would choose in the management of shoulder dystocia is:', 'Zavanelli', 'Woodscrew', 'Rubin', 'McRoberts', 'D', 'Per Kenya MNH guidelines and Myles, the McRoberts manoeuvre (hyperflexion of maternal thighs) is the first-line intervention for shoulder dystocia due to its simplicity and effectiveness; Zavanelli is a last resort.', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Pressure exerted on amniotic fluid during uterine contractions is:', 'Fore water pressure', 'Hind water pressure', 'Fetal axis pressure', 'General fluid pressure', 'D', 'Per Myles Textbook for Midwives, when membranes are intact the pressure of a contraction is applied to the fluid and equally distributed throughout—this is general fluid pressure.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Immediately after the placenta is delivered, the nurse must do the following:', 'Inspect the placenta for completeness including the membranes', 'Place the placenta in a kidney dish for disposal', 'Massage the uterus and expel clots', 'Carefully examine it in the kidney dish and measure blood loss', 'A', 'Per Kenya MNH guidelines and Myles, after delivery of the placenta the midwife inspects it for completeness of cotyledons and membranes to exclude retained products, a cause of PPH.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When the fontanelles are bulging, this implies that there is :', 'A fracture of the skull', 'Increased intracranial  pressure', 'Dehydration', 'Excessive molding', 'B', 'Per Basic Paediatric Protocols (Kenya), a bulging/tense anterior fontanelle indicates raised intracranial pressure (e.g. meningitis, hydrocephalus); a sunken fontanelle indicates dehydration.', 'BScN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The reflex that is elicited when the corner of the baby’s mouth is stroked and the baby turns its head and opens its mouth is:', 'Moro reflex', 'Rooting reflex', 'Sucking reflex', 'Turning reflex', 'B', 'Per Myles/Kozier, stroking the corner of the newborn''s mouth causing the head to turn and mouth to open is the rooting reflex, which aids location of the nipple.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the following is a danger sign during pueperium:', 'Watery vaginal discharge', 'Whitish with some mucus', 'Reddish with some pieces of tissue', 'Serous with some brown tinged mucus', 'C', 'Per Myles, offensive/heavy lochia with clots or tissue during puerperium suggests retained products or infection and is a danger sign; the normal progression is rubra to serosa to alba.', 'BScN', 'Paper I', 'Infection Prevention & Control', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The risks associated with prematurity include:', 'Asphyxia, hypothermia, cerebral haemorrhage', 'Infections, jaundice, genito-urinary malformations', 'Infections, asphyxia, malformation of the gut', 'Duodenal atresia, hypothermia, cerebral haemorrhage', 'A', 'Per Basic Paediatric Protocols (Kenya), preterm infants are prone to asphyxia, hypothermia (poor thermoregulation) and intraventricular/cerebral haemorrhage; malformations and atresias are not consequences of prematurity itself.', 'BScN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The three bones that form the vault of the fetal head are:', 'Parietal, frontal, temporal', 'Frontal, lambdoidal, coronal', 'Temporal, parietal, coronal', 'Sinciput, parietal, lambdoidal', 'A', 'Per Myles Textbook for Midwives, the vault of the fetal skull is formed by the frontal, parietal (two), temporal and occipital bones; of the listed sets only ''parietal, frontal, temporal'' are true vault bones (the others list sutures).', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The diameter of the normal pelvic cavity is:', '13 cm', '12 cm', '11 cm', '10 cm', 'B', 'Per Myles Textbook for Midwives, the cavity of the true pelvis is roughly circular with diameters averaging about 12 cm; the anteroposterior and transverse diameters of the cavity are approximately 12 cm.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The four sutures of obstetric importance are:', 'Saggital, frontal, coronal, occipital', 'Coronal, temporal, saggital, frontal', 'Saggital, lambdoidal, coronal, frontal', 'Frontal, coronal, occipital, temporal', 'C', 'Per Myles Textbook for Midwives, the sutures of obstetric importance on the fetal skull are the sagittal, frontal, coronal and lambdoidal sutures.', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('During vacuum extraction procedure, the centre of the vacuum cup should be placed over which of the flexion point on the fetal head?', 'Along the sagittal suture 3 cm posterior to the anterior fontanelle', 'Over the occiput eminence', 'Along the sagittal suture 3 cm anterior to the posterior fontanelle', 'Over the posterior fontanelle', 'C', 'Per Myles/WHO obstetric vacuum guidance, the cup is centred over the flexion point on the sagittal suture about 3 cm anterior to the posterior fontanelle (about 6 cm from the anterior fontanelle) to promote flexion.', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Pathological jaundice as a result of increased haemolysis involves all the following except:', 'G6PD deficiency', 'ABO incompatibility', 'Gilbert’s syndrome', 'Bacterial septicaemia', 'C', 'Per Basic Paediatric Protocols/standard texts, Gilbert''s syndrome causes unconjugated hyperbilirubinaemia from reduced conjugation (UGT enzyme), not increased haemolysis; G6PD deficiency, ABO incompatibility and septicaemia all cause haemolytic jaundice.', 'BScN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following nursing diagnosis will be of priority for a neonate undergoing phototherapy:', 'Deficient fluid volume', 'Imbalanced nutrition less than body requirements', 'Ineffective thermoregulation', 'Impaired skin integrity', 'A', 'Per Basic Paediatric Protocols and nursing care standards, phototherapy increases insensible water loss and stool water, so deficient fluid volume (risk of dehydration) is the priority; skin integrity and thermoregulation are managed but fluid loss is the leading concern.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which one of the following will be a priority nursing intervention for a neonate with Hemorrhagic disease of the newborn?', 'Administer vitamin K', 'Inform the physician', 'Preserve soiled line for estimation of blood loss', 'Observe signs of shock', 'A', 'Per Basic Paediatric Protocols (Kenya), haemorrhagic disease of the newborn results from vitamin K deficiency, so administering vitamin K is the priority intervention that treats the cause.', 'BScN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The most common cause of opthalmia neonatorum is:', 'C.trachomatis', 'N.gonorrhea', 'H.simplex', 'T.pallidum', 'B', 'Per Kenya STI/newborn guidelines, Neisseria gonorrhoeae is the classic most common cause of severe ophthalmia neonatorum (purulent conjunctivitis) presenting within the first days of life; it is the reason for routine eye prophylaxis.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Sodium bicarbonate is indicated in babies with asphyxia neonatorum to:', 'Prevent metabolic acidosis', 'Reverse effects of narcotics', 'Treat hypoglycaemia', 'Treat arrhythmias', 'A', 'Per neonatal resuscitation/standard texts, sodium bicarbonate is used to correct/prevent metabolic acidosis in asphyxiated newborns; naloxone reverses narcotics, not bicarbonate.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The most appropriate treatment for hyperbilirubinemia (11.2mg/dl) in a 3 weeks old breastfeeding infant with normal growth and development is:', 'Phototherapy', 'Exchange transfusion', 'Phenobarbitone', 'Protopophyrins', 'A', 'Per Basic Paediatric Protocols (Kenya), a bilirubin of 11.2 mg/dl in a thriving 3-week breastfed infant is managed with phototherapy if treatment is required; exchange transfusion is reserved for much higher levels/haemolysis.', 'BScN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('You are called to the delivery suite for a 39-week baby about to be born through thick meconium. One of following is your first step of management:', 'Intubate the baby and suction in case there is meconium below the cords', 'Dry the baby down, remove the wet wraps and give suction only if required', 'Visualize the cords with laryngoscope and only intubate if you see meconium below the cords', 'Give immediate deep oral suction', 'B', 'Per current Kenya/WHO neonatal resuscitation guidance, routine intubation and suctioning of vigorous meconium-stained babies is no longer recommended; the first step is to dry, remove wet wraps and provide initial care, suctioning only if the airway is obstructed.', 'BScN', 'Paper I', 'Nursing Management & Leadership', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The drug of choice for treatment of apnoeic attacks in new-borns is:', 'Caffeine citrate', 'Phenobarbitone', 'Theophylline', 'Diazepam', 'A', 'Per Kenya EML/Basic Paediatric Protocols, caffeine citrate is the drug of choice for apnoea of prematurity, being safer and more effective than theophylline.', 'BScN', 'Paper I', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which one of the following will be a priority nursing diagnosis for a postdate baby?', 'Risk for aspiration related to delayed swallowing reflex and meconium aspiration', 'Risk for hypoglycaemia related to decreased glycogen stores', 'Risk for infection related to prolonged exposure to the uterine environment', 'Ineffective breastfeeding related to decreased energy and increased sleepiness', 'A', 'Per Basic Paediatric Protocols, the postdate/post-term baby is at high risk of meconium aspiration; airway/aspiration risk is the priority (ABC) nursing diagnosis over hypoglycaemia or feeding concerns.', 'BScN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is not a component of the vault of the fetal skull?', 'Occipital bone', 'Sinciput', 'Two parietal bones', 'Two frontal bones.', 'B', 'Per Myles Textbook for Midwives, the vault is formed by the occipital, two parietal and two frontal bones; the sinciput (brow) is a region of the fetal head, not a bone of the vault.', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which presentation is achieved in an extended fetal head?', 'Vertex', 'Brow', 'Mentum', 'Acromion process', 'B', 'When the fetal head is fully extended (deflexed), the brow (forehead) becomes the presenting part, giving a brow presentation. Vertex results from full flexion and mentum (face) from complete extension. Per Myles Textbook for Midwives (attitude & presentation).', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which are the storage ducts of milk in the mammary glands?', 'Alveoli', 'Lactiferous sinuses', 'Cooper’s ligaments', 'Lobules', 'B', 'Milk produced in the alveoli passes along the ducts to the lactiferous sinuses (ampullae) beneath the areola, which act as reservoirs storing milk. Alveoli produce milk; Cooper''s ligaments are support structures. Per Myles Textbook for Midwives (anatomy of the breast).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which cells are responsible for production of HCG during pregnancy?', 'Epiblast.', 'Syncytiotrophoblast', 'Hypoblast', 'Cytotrophoblast', 'B', 'Human chorionic gonadotrophin (hCG) is secreted by the syncytiotrophoblast layer of the developing placenta, maintaining the corpus luteum in early pregnancy. Per Myles Textbook for Midwives (placental physiology).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which hormone is responsible for milk production?', 'Prolactin', 'Oxytocin', 'Progesterone', 'Oestrogen', 'A', 'Prolactin from the anterior pituitary stimulates the alveoli to synthesise milk (lactogenesis). Oxytocin causes the let-down (ejection) reflex, not production. Per Myles Textbook for Midwives (physiology of lactation).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('You explain to a mother that a newborn has ''caput'' because there is a swelling on his head that:', 'Is a light pink colour and located at the base of his hairline', 'Does not cross a suture line and pits with digital pressure', 'Is firm and coloured like a reddish bruise', 'Is a diffuse oedematous swelling of the soft tissues of his scalp and crosses a suture that will resolve in 24-48hours', 'D', 'Caput succedaneum is a diffuse oedematous swelling of the scalp soft tissues that crosses suture lines and resolves within a few days, distinguishing it from cephalhaematoma which does not cross sutures. Per Myles Textbook for Midwives (birth trauma).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Radiation is the most predominate mode of heat loss for a newborn. Radiation refers to:', 'loss of heat through water evaporation from the baby', 'loss of heat through the baby shivering', 'loss of heat from the baby''s surface to surrounding colder objects', 'loss of heat to moving air or fluid around the baby', 'C', 'Radiation is heat transfer from the newborn''s body surface to nearby cooler solid objects not in direct contact (e.g. cold walls/windows). Evaporation is water loss, convection is loss to moving air, conduction is loss to objects in contact. Per Kenya Basic Paediatric Protocols / Myles (thermoregulation).', 'BScN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Daily cord care is key in the prevention of neonatal sepsis. The following is the recommended ideal antiseptic for cleaning the cord;', 'Normal saline', 'Surgical spirit', 'Methylated spirit', 'chlorohexidine', 'D', 'Chlorhexidine (4% chlorhexidine digluconate) is the WHO- and Kenya MOH-recommended antiseptic for cord care to prevent neonatal sepsis, superior to spirits and saline. Per Kenya National Newborn Care guidelines / WHO adopted in Kenya.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following is a danger sign of a neonate that the mother should always be on look out;', 'Nasal secretions', 'Shrinking of the cord', 'Refusal to breastfeed', 'Hair loss in the body.', 'C', 'Refusal/inability to breastfeed is a key IMNCI newborn danger sign requiring urgent referral. Shrinking of the cord and hair variations are normal; nasal secretions are non-specific. Per Kenya IMNCI guidelines (young infant danger signs).', 'BScN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When a newborn baby is in contact with cold surfaces, heat loss occurs by;', 'Evaporation', 'Radiation', 'Convection', 'Conduction', 'D', 'Heat loss from the baby''s body to a cold surface in direct contact (e.g. cold weighing scale or bed) occurs by conduction. Radiation is to non-contact objects, convection to moving air, evaporation from moisture. Per Kenya Basic Paediatric Protocols (thermoregulation).', 'BScN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Characteristics of a normal infant at birth include:', 'Weight 3.5kg, length 40 cm, sunken abdomen', 'Lies in an attitude of flexion, vernix caseosa, his head half his size', 'His head comprise a quarter his size, prominent abdomen.', 'Occipitofrontal circumference of 34-55 cm, lanugo, sunken abdomen.', 'B', 'A normal term newborn lies in an attitude of flexion, is covered in vernix caseosa, and the head is about one quarter to a large proportion of body length; of the options given this is the only physiologically correct description (birth weight ~3.5kg with prominent, not sunken, abdomen). Per Myles Textbook for Midwives (characteristics of the normal newborn).', 'BScN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The aims of first examination of the newborn are;', 'Assess growth, maintain clear airway, assess maturity at birth', 'Detect birth injuries, assess minor disorders, detect congenital anomalies', 'Provide care, detect infections, assess growth and development', 'Detect birth injuries, detect any congenital abnormalities, and assess maturity at term.', 'D', 'The aims of the first (immediate) newborn examination are to detect birth injuries, identify congenital abnormalities and assess maturity/wellbeing at birth. Maintaining the airway is resuscitation, not the examination''s aim. Per Myles Textbook for Midwives (examination of the newborn).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Hypoglycemia is;', 'Blood sugar level below 54mg/dl', 'Blood sugar level below 45mg/dl', 'Blood sugar level below 2.9mg/dl', 'Blood sugar level below 6.7mg/dl', 'B', 'Neonatal hypoglycaemia is commonly defined as blood glucose below 2.5 mmol/L (about 45 mg/dl); of the options this is the accepted threshold. Per Kenya Basic Paediatric Protocols (neonatal hypoglycaemia).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Jaundice on day one is often caused by;', 'Metabolic disorders', 'Physiological factors', 'Hemolysis', 'Gastrointestinal obstruction', 'C', 'Jaundice appearing within the first 24 hours (day one) is always pathological and most commonly caused by haemolysis (e.g. Rh/ABO incompatibility, G6PD deficiency). Physiological jaundice appears after 24-48 hours. Per Kenya Basic Paediatric Protocols (neonatal jaundice).', 'BScN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The common age of onset of gonococcal ophthalmic neonatorum is;', '21 - 28 days after birth', '0 - 7 days after birth', '7 - 14 days after birth', 'At 28 days of age', 'B', 'Gonococcal ophthalmia neonatorum characteristically presents early, within the first week (typically days 2-5) after birth, unlike chlamydial conjunctivitis which appears later. Per Kenya National STI/newborn guidelines.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The rooting reflex is defined as response of the baby to;', 'Being pulled upright by the wrist to a sitting position', 'Being supported upright ith his feet touching a flat surface', 'Stroking of the cheek or side of the mouth', 'Being left to drop from an angle of 45', 'C', 'The rooting reflex is elicited by stroking the newborn''s cheek or corner of the mouth, causing the baby to turn towards the stimulus and open the mouth to feed. The other options describe traction, stepping and Moro responses. Per Myles Textbook for Midwives (neonatal reflexes).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse assisted with the birth of a newborn. Which nursing action is most effective in preventing heat loss by evaporation?', 'Warming the crib pad', 'Closing the doors to the room', 'Drying the infant with a warm blanket', 'Turning on the overhead radiant warmer', 'C', 'Evaporative heat loss occurs as amniotic fluid evaporates from the skin; immediately drying the newborn with a warm blanket removes this moisture and is the most effective prevention. A radiant warmer counters radiant loss, not evaporation. Per Kenya Basic Paediatric Protocols (newborn thermal care).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse prepares to administer a phytonadione (vitamin K) injection to a newborn, which explanation should the nurse give to the mother concerning the medication?', '“Your newborn needs the medicine to develop immunity.”', '“The medicine will protect your newborn from being jaundiced.”', '“Newborns have sterile bowels, and the medicine promotes the growth of bacteria in the bowel.”', '“Newborns are deficient in vitamin K, and this injection prevents your newborn from bleeding”', 'D', 'Newborns have low vitamin K stores and sterile gut flora, so vitamin K (phytomenadione) is given to prevent vitamin K deficiency bleeding (haemorrhagic disease of the newborn). It is not an immunisation and does not prevent jaundice. Per Kenya Essential Medicines List / Basic Paediatric Protocols (newborn care).
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The treatment of choice for trichomoniasis is;', 'Ceftriaxone', 'Doxycycline', 'Metronidazole', 'Norfloxacin', 'C', 'Per Kenya National STI guidelines and EML, metronidazole (or tinidazole) is the treatment of choice for Trichomonas vaginalis. Ceftriaxone/doxycycline treat gonorrhoea/chlamydia.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Deafness that develops after speech has developed is referred to as;', 'Adventitious deafness', 'Psychogenic deafness', 'Hard of hearing', 'Congenital deafness', 'A', 'Per ENT/community health references, adventitious (acquired) deafness is hearing loss that occurs after speech/language has already developed, in contrast to congenital deafness which is present at/before birth.', 'BScN', 'Paper I', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following statement is FALSE about spermicides;', 'May cause congenital abnormalities when used several times a day.', 'May increase the risk of HIV infection if used several times a day.', 'Can be inserted ahead of time and so do not interrupt sex', 'Should not be used by women with HIV infection', 'A', 'Per Kenya FP guidelines, spermicides do NOT cause congenital abnormalities, so this statement is FALSE. Spermicides can be inserted ahead of time, and frequent use may irritate mucosa and increase HIV risk (so they are not advised for women at high HIV risk), making the other statements true.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In classification of acute respiratory infections in children, very severe symptoms include:-', 'Stridor, ear discharge, blocked nose', 'Chest indrawing, stridor, grey membrane in the throat', 'Purulent pharyngitis, ear discharge, fast breathing >70bpm', 'Cyanosis, unable to drink, respiratory rate > 70bpm', 'D', 'Per Kenya IMNCI/Basic Paediatric Protocols, very severe/severe pneumonia danger signs include central cyanosis, inability to drink and very fast breathing; option D captures these. Stridor with ear discharge or blocked nose are not classified as very severe ARI signs.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The causative agent of chancroid is:', 'Chlamydia trachomatis', 'Treponema pallidium', 'Hemophilius ducreyi', 'Ureaplasma urealyticum', 'C', 'Per Kenya STI guidelines/Brunner & Suddarth, chancroid (soft sore) is caused by Haemophilus ducreyi. Treponema pallidum causes syphilis and Chlamydia trachomatis causes LGV/chlamydia, so those distractors are wrong.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Developmental milestone achieved at 12-18 months include:', 'A child sitting unsupported, grasping actively and makes loud noises', 'A child is able to run around, says several words', 'A child is able to stand, understand a few words and tries to use them', 'A child is able to walk, grasp small objects with thumbs and fingers', 'B', 'Per Kenya paediatric developmental milestones (Basic Paediatric Protocols), by 12-18 months a toddler walks/runs and says several words. Sitting unsupported and standing with pincer grasp are earlier milestones (around 6-12 months).', 'BScN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In enterobiasis infection, the adult worm lives in the:-', 'Lungs', 'Caecum', 'Large intestines', 'Small intestines', 'B', 'Per parasitology in Kenyan nursing texts, in enterobiasis the adult Enterobius vermicularis (pinworm) lives in the caecum and appendiceal region; females migrate to the perianal area to lay eggs. Caecum is the specific site making it the best answer over ''large intestines''.', 'BScN', 'Paper I', 'Infection Prevention & Control', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Gumma lesions are characteristic of:-', 'Latent stage of syphilis', 'Primordial stage of syphilis', 'Tertiary stage of syphilis', 'Secondary stage of syphilis', 'C', 'Per Kenya STI guidelines/Brunner & Suddarth, gummas (granulomatous lesions) are characteristic of tertiary syphilis. Primary syphilis presents with a chancre and secondary with rash/condylomata lata.
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following is a lymphoma that affects children:', 'Non-hodgkin''s disease', 'Acute lymphoblastic disease', 'Acute myeloid leukemia', 'Wilm''s tumor', 'A', 'Non-Hodgkin''s lymphoma is a lymphoma of childhood; ALL is a leukemia, AML is a leukemia, and Wilm''s tumor is a renal tumor, not lymphomas (Nelson/Basic Paediatric Protocols, Kenya).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Bullous impetigo;', 'Is not contagious', 'Is commonly caused by Staphylococcus', 'Presents with painful blisters', 'Is managed using topical steroids', 'B', 'Bullous impetigo is commonly caused by Staphylococcus aureus (toxin-mediated); it is contagious, presents with fragile painless bullae, and is treated with antibiotics, not topical steroids (Basic Paediatric Protocols; Brunner & Suddarth''s).', 'BScN', 'Paper I', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The management of a child with mumps includes the following EXCEPT', 'Use of cold compresses', 'Use of aspirin to relieve pain', 'Warm salt water gargles', 'Avoiding  acidic foods', 'B', 'Aspirin is contraindicated in children with viral illness (mumps) due to Reye''s syndrome risk; cold compresses, warm salt gargles and avoiding acidic foods are appropriate, so aspirin is the EXCEPTion (Basic Paediatric Protocols; Kenya paediatric guidelines).', 'BScN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Rheumatic heart disease is caused by;', 'Streptococcus pyogenes', 'Staphylococcus aureus', 'Haemophilus influenza', 'Streptococcus pneumonia', 'A', 'Rheumatic heart disease follows rheumatic fever caused by group A beta-haemolytic Streptococcus pyogenes; the other organisms are not implicated (Brunner & Suddarth''s; Kenya clinical guidelines).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following statement is true regarding normal growth and development of a child', 'Average length of a child is 20 inches at birth and 30 inches at 1 year', 'At the age of 3 years, the average child is 6 feet tall', 'At age 4 years, the average child is 80 inches tall', 'The average annual height increase is 10 inches between age 4 years and puberty', 'A', 'Normal birth length is ~50 cm (~20 inches) and increases by ~50% by 1 year to ~75 cm (~30 inches). Per Basic Paediatric Protocols (Kenya) / standard growth norms. The other options give grossly abnormal heights.', 'BScN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following is a normal finding in pediatric respiratory assessment', 'Large head, large mandible', 'Small posteriorly-placed tongue', 'Large airways rigid thoracic cage', 'Horizontal ribs, primarily diaphragm breathers', 'D', 'Infants/young children have horizontally placed ribs and are primarily diaphragmatic (abdominal) breathers, a normal finding. Their airways are small (not large/rigid) and tongue is relatively large. Per paediatric respiratory assessment norms (Basic Paediatric Protocols).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When palpating a child''s abdomen you note hepatomegaly. You know this can be a sign of what cardiac problem?', 'Right sided heart failure', 'Left- sided heart failure', 'Rheumatic heart disease', 'Anemia', 'A', 'Right-sided heart failure causes systemic venous congestion, producing hepatomegaly and peripheral oedema. Left-sided failure causes pulmonary congestion. Per Brunner & Suddarth''s Medical-Surgical Nursing.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following should be included in the health teachings among clients receiving Valium:', 'Avoid taking CNS depressant like alcohol.', 'There are no restrictions in activities.', 'Limit fluid intake.', 'Any beverage like coffee may be taken', 'A', 'Valium (diazepam) is a CNS depressant; combining it with alcohol or other CNS depressants causes dangerous additive sedation and respiratory depression, so clients must be taught to avoid alcohol. Per Kenya EML / BNF pharmacology.
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which one of the following is an uncontrollable risk factor that has been linked to development of coronary artery disease(CAD)', 'Exercise', 'obesity', 'stress', 'heredity', 'D', 'Per Brunner & Suddarth, heredity (family history), age, gender and race are non-modifiable (uncontrollable) CAD risk factors, whereas obesity, stress and physical inactivity are modifiable.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following are risk factors for impaired gas exchange and pulmonary infection :', 'Immobility, constipation and incontinence', 'Fluid restriction, immunosuppression and decreased level of consciousness.', 'Fluid restriction, immobility and ingestion of seasoned foods', 'Incontinence, chemotherapy and anemia', 'B', 'Fluid restriction thickens secretions, immunosuppression predisposes to infection, and decreased LOC impairs airway clearance/cough — all promoting impaired gas exchange and pulmonary infection (Brunner & Suddarth respiratory nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When nursing a patient on steroids, the nurse should,', 'Observe for oedema, weigh daily, monitor blood counts', 'Maintain infection control, monitor blood sugar, maintain hydration', 'Observe for bone marrow suppression, minimise exposure to heat,encourage bed rest', 'Encourage increased fluid intake, administer anti-emetics, monitor RBC count', 'B', 'Corticosteroids cause immunosuppression (infection risk) and hyperglycaemia, and fluid balance must be maintained; per Kenya EML/BNF steroid monitoring these are the key nursing priorities. Bone marrow suppression is a cytotoxic, not steroid, effect.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The common causative organism for pharyngitis is,', 'Group B, beta hemolytic streptococcus', 'Group A, beta hemolytic streptococcus', 'Hemophilus influenza', 'Staphylococcus aureus', 'B', 'Group A beta-haemolytic streptococcus (Streptococcus pyogenes) is the classic bacterial cause of pharyngitis (Brunner & Suddarth; IMNCI sore throat guidance).', 'BScN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In pulmonary embolism (PE),', 'There is a clot formation in the pulmonary vein and or its branches', 'There is obstruction of the Pulmonary artery or one of its branches', 'Trauma, pregnancy and Valsava maneuvers are common predisposing factors', 'Old age, heart failure and intestinal obstruction clients are more prone', 'B', 'Pulmonary embolism is obstruction of the pulmonary artery or a branch, usually by a thrombus from the deep veins (Brunner & Suddarth). The clot lodges in the artery, not the pulmonary vein.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Dumping syndrome is as a result of,', 'Rapid emptying of hypertonic food from the stomach into the jejunum', 'Failure of a patient with a peptic ulcer to eat regularly', 'Chronic anemia among the elderly patients', 'Loss of the large intestine functionality following hemicolectomy', 'A', 'Dumping syndrome, common after gastric surgery, results from rapid emptying of hypertonic gastric contents into the jejunum causing fluid shifts (Brunner & Suddarth GI nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('For a patient to undergoing a kidney, ureter and bladder X-ray is important for the nurse to know that,', 'There is no special preparation required.', 'Oral fluids must be withheld the morning of the examination.', 'The patient should have a full bladder before the procedure.', 'An enema should be administered before the procedure', 'A', 'A plain KUB (kidney-ureter-bladder) X-ray requires no special preparation such as fasting, bowel prep or bladder filling (Brunner & Suddarth diagnostic procedures).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The vitamin required for normal production of RBCs is;', 'calcium', 'vitamin A', 'folic', 'vitamin K', 'C', 'Folic acid (folate), with vitamin B12, is required for normal red blood cell production/maturation; deficiency causes megaloblastic anaemia (Kenya nutrition/haematology guidance, Brunner & Suddarth).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Plain insulin has peak action of;', '8- 12hours', '2-3 hours', '12-16hours', '16-30hours', 'B', 'Plain/regular (short-acting soluble) insulin has onset ~30 min, peak action about 2-3 hours (Kenya EML/BNF insulin pharmacology).', 'BScN', 'Paper I', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Valsava maneuver can result to bradycardia. Which of the following activities will not stimulate valsalva’s maneuver?', 'Use of stool softeners', 'Enema administration', 'Gaggling while tooth brushing', 'Lifting heavy objects', 'A', 'Straining (enema, forceful gagging, heavy lifting) triggers the Valsalva manoeuvre; stool softeners prevent straining and therefore do NOT stimulate it (Brunner & Suddarth). The question asks which will NOT stimulate the manoeuvre.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the reason for the nurse in instructing the client to rotate the injection sites for insulin?', 'lipodystrophy can result and extremity painful', 'Poor rotation technique can cause superficial hemorrhaging', 'lipodystrophic areas can result, causing erratic insulin absorption rates from these', 'Injection sites can never be reused', 'C', 'Insulin injection sites are rotated to prevent lipodystrophy (lipohypertrophy/atrophy), which causes erratic, unpredictable insulin absorption (Kenya diabetes guidelines; Brunner & Suddarth).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Nurse Nyaruai is giving a health education talk to Mothers attending the MCH/FP clinic at Kapkoros health center. As a knowledgeable nurse, she must know that a mother who breastfeeds her child passes on which antibody through breast milk?', 'IgA', 'IgG', 'IgM', 'IgE', 'A', 'Secretory IgA is the predominant antibody passed to the infant in breast milk (especially colostrum), providing mucosal/gut protection (Kenya MCH/IMNCI, WHO breastfeeding guidance). IgG crosses the placenta, not chiefly milk.', 'BScN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following interventions would be helpful to a breastfeeding mother who is experiencing engorged breasts?', 'Applying ice', 'Administering bromocriptine', 'Applying a breast binder', 'Teaching how to express her breasts in a warm shower', 'D', 'For a breastfeeding mother with engorgement, warmth and expression/continued feeding relieve the fullness (Myles Textbook for Midwives). Ice, bromocriptine and binders are used to suppress lactation, not for a mother who wishes to continue breastfeeding.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('You are preparing to perform a fundal assessment on a postpartum client. The initial nursing action in performing this assessment is which of the following?', 'Ask the client to turn on her side', 'Ask the mother to urinate and empty her bladder', 'Massage the fundus gently before determining the level of the fundus.', 'Ask the client to lie flat on her back with the knees and legs flat and straight', 'B', 'The first action in fundal assessment is to have the client empty her bladder, since a full bladder displaces and elevates the fundus giving a false reading (Myles Textbook for Midwives; postpartum nursing).', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following complications is Most likely responsible for a delayed postpartum hemorrhage?', 'Cervical laceration.', 'Uterine sub involution', 'Perineal laceration', 'Clotting deficiency', 'B', 'Delayed (secondary) postpartum haemorrhage occurring after 24 hours is most often due to uterine subinvolution or retained placental fragments (Myles Textbook for Midwives). Lacerations cause early/primary PPH.', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Following a difficult labor and birth, a primiparous woman refuses to feed her baby four hours after delivery, she states that she is too tired and just wants to sleep. The nurse should:', 'Tell the woman she can rest after she feeds her baby', 'Take the baby back to the nursery, reassuring the woman that her rest is a priority at this time', 'Recognize this as a behavior of the taking-hold stage', 'Record the behavior as ineffective maternal-newborn attachment', 'B', 'In the taking-in phase after a difficult birth the mother is fatigued and focused on her own needs; the nurse supports rest and defers feeding, reassuring her (Myles Textbook for Midwives, Rubin''s maternal phases). Forcing feeding or labelling poor attachment at 4 hours is inappropriate.', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('MrsWangombe is under your care and expresses concern about the weight she gained during pregnancy and how quickly she can lose it now that the baby is born. In describing the expected pattern of weight loss, you should begin by telling her that:-', 'Lactation will inhibit weight loss since caloric intake must increase to support milk production', 'Return to pre pregnant weight is usually achieved by the end of the postpartum period', 'Fluid loss from diuresis, diaphoresis, and bleeding accounts for about a 3 pound weight loss', 'The expected weight loss immediately after birth averages about 11 to 13 pounds', 'D', 'Immediately after birth the expected weight loss (fetus, placenta, amniotic fluid, blood) averages about 11-13 pounds (Myles Textbook for Midwives). Further loss from diuresis/diaphoresis follows over the puerperium.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Signs of puerperal sepsis include', 'Pyrexia, tachycardia, whitish lochia', 'Pyrexia, tachycardia, red lochia', 'Pyrexia, tachycardia, pink lochia', 'Pyrexia, tachycardia, offensive lochia', 'D', 'Puerperal sepsis presents with pyrexia, tachycardia and offensive (foul-smelling) lochia with lower abdominal pain (Kenya maternal care guidelines; Myles Textbook for Midwives).', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Systemic changes during normal puerperium include', 'Involution of the uterus, lochia loss, blood volume returns to normal', 'Rising of the fundus, lochia loss, blood volume decreases', 'Involution of the uterus, lochia loss, blood volume increases', 'Maternal weight gain', 'A', 'Normal puerperium involves uterine involution, progressive lochia loss, and the elevated pregnancy blood volume returning to normal (Myles Textbook for Midwives). The fundus descends rather than rising.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('General nursing care during post-partal period includes assessment of the:', 'Breasts, abdomen, and fundus', 'Breasts, abdomen, and musculoskeletal system', 'Breasts, abdomen, and neurological responses', 'Breasts, abdomen and congenital abnormalities', 'A', 'Postpartum assessment (BUBBLE-HE) covers breasts, uterus/fundus and abdomen among others; assessing breasts, abdomen and fundus is standard general postpartum care (Myles Textbook for Midwives).', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('You are taking vital signs observations on a postpartum client who delivered a healthy newborn 4 hours ago. Her temperature is 100.2° F or 37.9 What is the priority nursing action?', 'Increase hydration by encouraging oral fluids.', 'Document the findings.', 'Retake the temperature in 15 minutes', 'Notify the doctor Postpartum fever is defined as a temperature of 38.7 degrees C (101.6 degrees F) or greater for the first 24 hours or greater than 38.0 degrees C (100.4 degrees F) on any two of the first 10 days postpartum.', 'A', 'A temperature of 37.9C (100.2F) within the first 24 hours postpartum is commonly due to dehydration/exertion and is not defined as puerperal fever (>=38C); the priority is to increase oral fluids and reassess (Myles Textbook for Midwives).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the best position to assess a postpartum woman’s fundus?', 'On her right side.', 'Semi-Fowler position.', 'Supine with knees slightly flexed.', 'In a chair, with feet elevated.', 'C', 'The fundus is best assessed with the woman supine and knees slightly flexed to relax the abdominal muscles, after bladder emptying (Myles Textbook for Midwives).', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The main function of oxytocin during puerperium is to stimulate:', 'Estrogen production', 'Progesterone production', 'Contraction of uterine muscle and breast tissues', 'Production of Human Placental Lactogen', 'C', 'Per Myles Textbook for Midwives, oxytocin causes uterine muscle contraction (involution) and contraction of myoepithelial cells in the breast for milk ejection during puerperium; it does not stimulate estrogen, progesterone or hPL production.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Fertilization occurs in one of the following parts of fallopian tube.', 'Infundibulum', 'Fimbrae', 'Ampulla', 'Isthmus', 'C', 'Per Myles Textbook for Midwives, fertilization normally occurs in the ampulla (widest part) of the fallopian tube; the infundibulum, fimbriae and isthmus are not the usual sites.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In the female genital tract the sperms undergo physio-biochemical modification to allow spermovum interaction. This modification is known as:', 'Capacitation', 'Transformation', 'Reaction', 'Activation', 'A', 'Per Myles Textbook for Midwives, capacitation is the physio-biochemical modification sperm undergo in the female genital tract enabling them to penetrate and fertilize the ovum.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The placenta originates from one of the following parts of the fertilized ovum', 'Inner cell mass', 'York sac', 'Trophoblast', 'Embryoblast', 'C', 'Per Myles Textbook for Midwives, the outer trophoblast (trophoblastic cells) of the blastocyst gives rise to the placenta and chorion; the inner cell mass/embryoblast forms the embryo.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following structures in fetal circulation joins the umbilical cord to the inferior vena cava', 'Ductus arteriosus', 'Foramen ovale', 'Ductus venosus', 'Hypogastric arteries', 'C', 'Per Myles Textbook for Midwives, the ductus venosus connects the umbilical vein to the inferior vena cava, allowing oxygenated blood to bypass the fetal liver.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following type of exercises should be avoided in pregnancy', 'Walking for 30 minutes', 'Sexual intercourse', 'Aerobic exercise', 'Mountain climbing', 'D', 'Per Kenya maternal health / Myles guidance, high-altitude mountain climbing and high-risk activities should be avoided in pregnancy; moderate walking, aerobic exercise and intercourse are generally safe.', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In class III cardiac disease in pregnancy, patient has:', 'No limitation of physical activity, heart murmur on general examination', 'Slight limitation of physical activity, no symptoms when at rest', 'Marked limitation of physical activity, slight exertion leads to fatigue, palpitations, dyspnea', 'Inability to carry out any physical activity without discomfort, signs of cardiac disease and heart failure even at rest', 'C', 'Per NYHA classification (Brunner & Suddarth), Class III is marked limitation of physical activity with symptoms on less-than-ordinary exertion; comfortable only at rest.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following statement is true concerning preeclampsia.', 'Oedema is considered as part of the diagnosis of preeclampsia', 'Preeclampsia is primarily hypertension during pregnancy', 'The cardinal signs of preeclampsia include oedema and headache', 'Preeclampsia is gestational hypertension plus proteinuria', 'D', 'Per Kenya maternal guidelines and Myles Textbook for Midwives, preeclampsia is defined as new-onset gestational hypertension after 20 weeks with proteinuria; oedema is no longer a diagnostic criterion.', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following sex hormone is produced during throughout the menstrual cycle', 'Follicle stimulating hormone', 'Luteinizing hormone', 'Estrogen', 'Progesterone', 'C', 'Per Myles Textbook for Midwives, estrogen is produced throughout the menstrual cycle (follicular and luteal phases), whereas progesterone predominates only after ovulation and FSH/LH peak transiently.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following hormone causes development of new blood vessels to the uterus', 'Eostrogen', 'Progesterone', 'Luteinizing hormone', 'Follicle stimulating hormone', 'A', 'Per Myles Textbook for Midwives, estrogen stimulates growth and vascularisation (development of new blood vessels) of the uterus and endometrium during the proliferative phase.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Management of nausea and vomiting among pregnant women include:-', 'Skipping meals', 'Eating small meals frequently', 'Avoiding crackers before getting up in the morning', 'Encouraging highly seasoned foods', 'B', 'Per Myles Textbook for Midwives and Kenya ANC guidance, morning sickness is managed by eating small, frequent meals, dry crackers before rising and avoiding an empty stomach; skipping meals worsens symptoms.', 'BScN', 'Paper I', 'Nursing Management & Leadership', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Ptyalism refers to:', 'Excessive nausea and vomiting in pregnancy', 'Lack of appetite', 'An abnormal craving for non-food substances of little or no nutritional value', 'Increased salivation', 'D', 'Per Myles Textbook for Midwives, ptyalism is excessive salivation, a minor disorder of pregnancy; excessive vomiting is hyperemesis and craving non-food items is pica.', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In focused antenatal care, the second dose of sulfadoxine pyrimethamine(SP) is administered at gestation of:', '16-28 weeks', '20-30 weeks', '28-34 weeks', '34-36 weeks', 'C', 'Per Kenya focused ANC / malaria in pregnancy guidelines, IPTp-SP is given from 13 weeks at least one month apart; the second dose falls around 28-34 weeks in the third trimester.', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Fetal axis pressure is a physiological change that is more significant during:', 'Early stages of labor transmitting the force of contraction to the upper pole of fetus', 'Second stage of labor when membranes are intact', 'Active and second stages of labor when membranes are ruptured', 'Second stage of labour transmitting the force of contraction to the lower pole of the uterus', 'C', 'Per Myles Textbook for Midwives, fetal axis pressure (transmission of contraction force down the fetal axis) becomes more significant during active and second stage once membranes have ruptured.', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('If the membranes rupture at cervical dilatation of 8 cm, a vaginal examination performed rule out:', 'Obstructed labour, cord prolapsed, fetal compromise', 'Cord prolapsed, cord presentation, fetal distress', 'Obstructed labour, cord prolapsed, prolonged labour', 'Maternal distress, prolonged labour, cord presentation', 'B', 'Per Myles Textbook for Midwives, when membranes rupture the immediate vaginal examination aims to exclude cord prolapse/presentation and assess for fetal distress (fetal heart rate).', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Laboratory findings that are consistent with hyperthyroidism include', 'Decreased serum triiodothyronine (T3) and thyroxine (T4) levels', 'Elevated serum thyrotropin releasing hormone (TRH) levels', 'Decreased radioactive iodine uptake', 'Increased free triiodothyronine (T3) and thyroxine (T4) levels', 'D', 'Per Brunner & Suddarth''s Medical-Surgical Nursing, hyperthyroidism is characterised by elevated free T3 and T4 with suppressed TSH and increased radioactive iodine uptake.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Substances that create colloid osmotic pressure in the capillaries include;', 'Albumin, globulin', 'Plasma, potassium', 'Globulin, sodium', 'Albumin, potassium', 'A', 'Per anatomy & physiology texts, plasma proteins albumin and globulin generate colloid (oncotic) osmotic pressure in the capillaries; electrolytes like sodium and potassium contribute to crystalloid osmotic pressure.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Discharge instructions for a client with chronic respiratory acidosis should include', 'Discussing how to plan for periods of increased activity', 'Teaching about a low protein, low carbohydrate diet', 'Demonstrating exercises to increase vital capacity', 'Encouraging participation in activities such as jogging', 'C', 'Per Brunner & Suddarth''s Medical-Surgical Nursing, clients with chronic respiratory acidosis (e.g. COPD) are taught breathing/pulmonary exercises to improve vital capacity; strenuous activity like jogging and increased activity periods are inappropriate.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The predilection of HIV for certain cells in the immune system results in', 'More T4 lymphocytes and general lymphocytopenia', 'Fewer activated B-cells and hypogammaglobulinemia', 'Increased response in cutaneous hypersensitivity', 'Susceptibility to opportunistic infection and neoplasm', 'D', 'Per Brunner & Suddarth and Kenya HIV guidelines, HIV targets CD4 (T4) helper lymphocytes causing their depletion and immunosuppression, leading to opportunistic infections and neoplasms.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The most common preventable cause of valvular heart disease is:', 'Congenital disease acquired intrauterine', 'Calcium deposits and thrombus formation', 'Marfans syndrome', 'Beta-hemolytic streptococcal infection', 'D', 'Per Brunner & Suddarth''s Medical-Surgical Nursing, rheumatic heart disease following group A beta-haemolytic streptococcal infection is the most common preventable cause of valvular heart disease.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Pelvic inflammatory diseases include:', 'Salpingitis, cervicitis, candidiasis', 'Cervicitis, endometritis, oophoritis.', 'Trichomoniasis, salpingitis, urethritis.', 'Candidiasis, toxic shock syndrome, endometritis.', 'B', 'Per Brunner & Suddarth''s Medical-Surgical Nursing, PID is ascending infection of the upper genital tract including cervicitis, endometritis, salpingitis and oophoritis; candidiasis and trichomoniasis are lower-tract/vaginal infections, so option B best lists true PID components.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Cholelithiasis is associated with:-', 'Abnormal metabolism of cholesterol and bile salts.', 'Abnormal metabolism of lipids and bile acids.', 'Chronic pancreatitis.', 'Hepatitis.', 'A', 'Per Brunner & Suddarth''s, cholesterol gallstones (the commonest type) form when bile is supersaturated with cholesterol relative to bile salts, i.e. abnormal metabolism of cholesterol and bile salts. Lipids/bile acids and pancreatitis/hepatitis are not the primary mechanism.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Glomerulonephritis usually follows:-', 'Staphylococcal infection.', 'Gonococcal infection.', 'Gonococcal infection.', 'Streptococcal infection', 'D', 'Per Brunner & Suddarth''s, acute post-streptococcal glomerulonephritis typically follows a group A beta-haemolytic streptococcal throat or skin infection. Options B and C are duplicates (gonococcal) and incorrect.', 'BScN', 'Paper I', 'Infection Prevention & Control', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The teeth that commonly get impacted are the :-', 'Molars.', 'Incisors.', 'Canine.', 'Wisdom.', 'D', 'The third molars (wisdom teeth), being the last to erupt with insufficient jaw space, are the most commonly impacted teeth (standard anatomy/dental texts).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Body mechanics usually prescribed for clients with low pain include:-', 'Bending at knee and hips, standing straight, carrying objects close to the body.', 'Bending at the waist carrying objects close to the body, standing straight.', 'Sleeping on the side carrying objects farther from the body, bending at the knees and hips.', 'Bending at the waist, sleeping on the side, standing straight.', 'A', 'Per Kozier & Erb''s Fundamentals of Nursing, correct body mechanics for low-back pain prevention involve bending at the knees and hips (not the waist), keeping the back straight, and carrying objects close to the body to reduce spinal strain.', 'BScN', 'Paper I', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When a nurse is monitoring a patient for cerebrospinal fluid (CSF) leak he/she should observe for:-', 'Halo sign.', 'Babinski reflex.', 'Iliopsoas sign.', 'Blumberg sign.', 'A', 'Per Brunner & Suddarth''s, CSF leak is detected by the halo (ring) sign, where drainage on gauze forms a clear ring around blood, and by glucose-positive fluid. Babinski, iliopsoas and Blumberg signs are unrelated neurological/abdominal signs.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The commonest cause of toxic goitre (Grave’s disease) is: -', 'Pituitary tumours', 'Benign thyroid', 'Lack of iodine in the diet', 'Immunoglobulins reaction', 'D', 'Per Brunner & Suddarth''s, Graves'' disease is an autoimmune disorder caused by thyroid-stimulating immunoglobulins (TSH-receptor antibodies). Iodine lack causes simple/endemic goitre, not toxic Graves'' goitre.', 'BScN', 'Paper I', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Parathyroid hormone maintains fluid and electrolyte balance by', 'Promoting absorption of calcium from the intestines', 'Inhibiting release of calcium from the bone', 'Increasing the excretion of phosphate ions by the kidneys', 'Acting on the renal tubules to retain water and to decrease urinary output', 'C', 'Parathyroid hormone raises serum calcium by mobilising calcium from bone, increasing intestinal (via vitamin D) and renal calcium reabsorption, and increasing renal excretion of phosphate. Of the options given, increasing phosphate excretion by the kidneys is the correct PTH action (Guyton/standard physiology).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The carcinogenic risk factors for laryngeal cancers include:', 'Tar products, mustard gas, chronic laryngitis', 'Asbestos, chronic laryngitis, voice straining', 'Voice straining, high fibre diet, tobacco', 'Asbestos, tobacco, tar products', 'D', 'Per Brunner & Suddarth''s, carcinogenic risk factors for laryngeal cancer include tobacco, alcohol, asbestos and tar/industrial exposures. A high-fibre diet (option C) is protective, not carcinogenic, so D is the fully correct set.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In Fallot’s tetralogy there is', 'Pulmonary artery stenosis, ventricular septal defect, aortic misplacement & right ventricular hypertrophy.', 'Coarctation of the aorta, patent ductus arteriosus, aortic stenosis and ventricular septal defect.', 'Ventricular hypertrophy, coarctation of the aorta, atrial septal defect and Blue babies’ syndrome', 'Atrial-ventricular hypertrophy, coarctation of the aorta, ventricular septal defect and pulmonary artery stenosis.', 'A', 'Tetralogy of Fallot classically comprises pulmonary (artery) stenosis, ventricular septal defect, overriding (misplaced) aorta and right ventricular hypertrophy (standard paediatric/anatomy texts).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The position an unconscious patient should be nursed in is:', 'Recumbent', 'Lithotomy', 'Prone', 'Semi-prone', 'D', 'Per Kozier & Erb''s, the unconscious patient is nursed in the semi-prone (recovery/lateral) position to maintain a patent airway and allow drainage of secretions, preventing aspiration.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Parklands’ formula is used to calculate', 'Total burnt surface area', 'Fluid replacement', 'Thickness of the burn', 'Hemo-concentration', 'B', 'Per Brunner & Suddarth''s / MOH burns guidelines, the Parkland formula (4 ml x weight x %TBSA) calculates the volume of IV fluid replacement required in the first 24 hours after a burn.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The body’s internal environment which is tightly controlled and kept within normal limit is:', 'Control feedback mechanism', 'Compensatory mechanism', 'Homeostasis', 'Equilibrium', 'C', 'Homeostasis is the maintenance of a relatively stable internal environment within narrow normal limits (standard physiology, Guyton).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The vascular coat of eye ball that lies between the sclera and retina is', 'Uvea', 'Iris', 'Ciliary body', 'Choroid', 'D', 'The choroid is the vascular layer of the eye lying between the sclera and the retina. The uvea is the whole vascular tunic (choroid+ciliary body+iris); the specific layer between sclera and retina is the choroid (standard anatomy).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Following thyroidectomy, the nurse suspects damage or removal of parathyroid gland when the patient develops:', 'Muscle weakness and weight loss', 'Hyperthermia and severe tachycardia', 'Hypertension and difficulty in swallowing', 'Laryngeal stridor and tingling in the hands and feet', 'D', 'Per Brunner & Suddarth''s, parathyroid damage after thyroidectomy causes hypocalcaemia manifesting as tetany: perioral/peripheral tingling (paraesthesia), carpopedal spasm and laryngeal stridor/spasm.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('increased concentration of red blood cells due to excessive production of erythropoietin is referred to as:', 'primary polycythemia', 'leukopenia', 'secondary polycythemia', 'agranulocytosis', 'C', 'Per Brunner & Suddarth''s, secondary polycythaemia is an increase in RBC mass driven by excessive erythropoietin (e.g. from hypoxia). Primary polycythaemia (vera) is a clonal marrow disorder with low/normal erythropoietin.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which cranial nerve is involved when the patient presents with facial pain, diminished corneal reflex and chewing dysfunction:', 'III', 'IV', 'V', 'VI', 'C', 'The trigeminal nerve (cranial nerve V) supplies facial sensation, the afferent limb of the corneal reflex, and the muscles of mastication; its involvement causes facial pain, diminished corneal reflex and chewing dysfunction (standard neuroanatomy).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The main long-term complication following radical mastectomy is', 'Phantom pain', 'Tingling and numbness', 'Lymphoedema', 'Paralysis', 'C', 'Per Brunner & Suddarth''s, lymphoedema of the affected arm is the main long-term complication after radical mastectomy due to removal of axillary lymph nodes impairing lymphatic drainage.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Steroid nasal sprays are used in management of sinusitis to:', 'Moisten secretions', 'Prevent nasal crusting', 'Reduce mucosal inflammation', 'Thin the nasal secretions', 'C', 'Per Kenya EML/BNF, intranasal corticosteroids act by reducing mucosal inflammation and oedema, thereby improving sinus drainage in sinusitis.', 'BScN', 'Paper I', 'Nursing Management & Leadership', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Haemophilia A results from deficiency of factor:', 'VII', 'IX', 'III', 'V', 'B', 'Haemophilia A is caused by deficiency of clotting factor VIII, and haemophilia B by factor IX; factor VIII is not among the options, so of the choices given IX is intended as the coagulation-factor deficiency answer. (Standard haematology; note factor VIII is the true answer for haemophilia A.)
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The accumulation of thick, purulent fluid within the pleural space with fibrin development is characteristic of:', 'Empyema', 'Effusion', 'Pleurisy', 'Emphysema', 'A', 'Per Brunner & Suddarth''s, empyema is the accumulation of thick, purulent fluid within the pleural space, often with fibrin and loculation. Pleural effusion is fluid without pus, pleurisy is inflammation, and emphysema is alveolar destruction.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The trophoblast cells of the developing zygote from the:-', 'Fetus and amnion', 'Placenta and fetus', 'Chorion and amnion', 'Placenta and chorion', 'D', 'Per Myles Textbook for Midwives, the trophoblast (outer cells of the blastocyst) develops into the chorion and the fetal portion of the placenta; the inner cell mass forms the fetus and amnion.', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When performing Leopold''s maneuver, the purpose of the first maneuver is to determine', 'Fetal part lying in the fundus and presentation', 'Location of fetal back and position', 'Engagement of the presenting part', 'The degree of flexion of fetal head', 'A', 'Per Myles Textbook for Midwives, the first Leopold''s manoeuvre (fundal palpation) determines which fetal pole occupies the fundus, thereby indicating the presentation/lie.', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('If Mrs. Cola’s menstrual period was on 27.7.08, her expected date of delivery will be:', '3.4.09', '4.5.09', '3.5.09', '4.4.09', 'C', 'Per Naegele''s rule (Myles), EDD = LMP - 3 months + 7 days + 1 year. From 27.7.08: -3 months = 27.4, +7 days = 3.5, +1 year = 3.5.09.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The most important benefit of vestibular stimulation in the normal newborn is improvement of', 'Sucking capability', 'Tactile sensitivity', 'Motor coordination', 'Attention span', 'C', 'Vestibular stimulation in the normal newborn primarily promotes development of motor coordination and balance through the vestibular-cerebellar system (developmental paediatric literature).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In focused antenatal care, the second dose of sulfadoxine pyrimethamine (sp) is administered at gestation of:-', '16-28 weeks(First dose)', '20-30 weeks.', '28-34 weeks. (Second dose)', '34-36 weeks.', 'C', 'Per Kenya National Malaria in Pregnancy / focused ANC guidelines, IPTp-SP is given from 16 weeks; the second dose follows about a month later, typically 28-34 weeks. The option is explicitly labelled second dose.', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The diastolic pressure is usually not affected by excitement, its increase is therefore more significant in assessment of pregnant women for pre-eclampsia. The range of change in mmHg is:-', '10-15', '15-20', '15-30', '20-30', 'C', 'Per Myles Textbook for Midwives, a diastolic rise of 15-30 mmHg (or diastolic >=90 mmHg) over baseline is significant for pre-eclampsia because diastolic pressure is little affected by excitement.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The management of placenta previa type three when the fetus has died in utero includes:-', 'Preparation of woman for emergency caesarian section.', 'Induction of labour by use of syntocinon.', 'Gentle palpation through vaginal forncles to determine whether posterior or anterior.', 'Complete bed rest and speculum examination on third day.', 'A', 'Per Myles/MOH obstetric guidelines, placenta praevia type III (major, covering the os) mandates delivery by caesarean section regardless of fetal state; vaginal delivery and syntocinon induction are contraindicated due to torrential haemorrhage risk.', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The hormonal factor responsible for uterine contractions at onset of labour are:-', 'Increase release of oxytocin progesterone from deciduas at term.', 'Formation of oxytocin and estrogen in the fetal circulation', 'Rise of oxytocin and estrogen in the fetal circulation.', 'Optimum levels of estrogen and rise of prostaglandins in maternal circulation.', 'D', 'Per Myles Textbook for Midwives, labour onset involves a fall in progesterone with dominance of oestrogen plus a rise in prostaglandins and oxytocin sensitivity that trigger coordinated uterine contractions.', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('If membranes rupture at cervical dilation of 8 centimeters, a vaginal examination performed should rule out:-', 'Obstructed labour, cord prolapse, fetal compromise.', 'Cord prolapse, cord presentation, fetal distress.', 'Obstructed labour, cord prolapse, prolonged labour.', 'Maternal distress, prolonged labour, cord presentation.', 'B', 'Per Myles/MOH intrapartum guidelines, when membranes rupture a vaginal examination is done to exclude cord prolapse and cord presentation and to check the fetal heart for distress, as the cord may be swept down with the gush of liquor.', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The partograph is an effective tool in management of women in labour, a good progress in the active phase will be:-', 'Cervical dilatation plotted progressively on alert line within 7 hours.', 'Uterine contractions increase in strength from 20-25 seconds within 8 hours.', 'Cervical dilation plotted on the action line and progressive descent.', 'Cervical dilatation plotted the right of the action line.', 'A', 'Per WHO/MOH partograph use, good progress in the active phase is dilatation at >=1 cm/hour so plotting remains on or to the left of the alert line; crossing to the action line signals poor progress.', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The anti-opioid drug used in resuscitation of the newborn is:-', 'Konakion 0.5 mg intramuscularly.', 'Dexamethasone 1-2mg Intravenously.', 'Narcan 0.1 mg/kilogram body weight intravenously', 'Naloxone 0.5 mg intravenously.', 'C', 'Per neonatal resuscitation/Kenya EML, naloxone (Narcan) is the opioid antagonist used for opioid-induced neonatal respiratory depression at 0.1 mg/kg; the weight-based dosing option is correct whereas the fixed 0.5 mg IV figure is not the neonatal standard.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Injury to the fetal scalp due to pressure by girdle of contact is known as:-', 'Cephalhematoma.', 'Pericranial hematoma.', 'Subdural oedema.', 'Caput succedaneum.', 'D', 'Per Myles Textbook for Midwives, caput succedaneum is oedematous swelling of the fetal scalp caused by pressure of the cervical girdle of contact during labour; it crosses suture lines, unlike cephalhaematoma.', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The peak action syntocinon administered to prevent postpartum hemorrhage is felt in:-', '2 ½ minutes', '2 minutes', '2 seconds', '2 ½ seconds', 'A', 'Per pharmacology of oxytocics (Myles/EML), intravenous syntocinon (oxytocin) acts within about 1 minute with peak uterine effect around 2-3 minutes; 2 1/2 minutes is the best fit among the options.', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Fetal causes of early pregnancy loss include:-', 'Structural abnormalities of the genital tract', 'Bicornulate uterus and fibroids', 'Chromosomal abnormalities of the conceptus', 'Infections such as rubella, listeria and Chlamydia', 'C', 'Per Myles Textbook for Midwives, the commonest fetal cause of early pregnancy loss (miscarriage) is chromosomal abnormality of the conceptus; uterine anomalies and infections are maternal, not fetal, causes.', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The outcome of labor is not dependent on:-', 'Effectiveness of uterine contractions', 'Maternal size', 'The “give” of the pelvic joints', 'The degree of moulding of the fetal head', 'B', 'Per Myles Textbook for Midwives, labour outcome depends on the powers (contractions), passages (pelvic joint give) and passenger (moulding); overall maternal body size is not a determinant, so it is the exception.', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('During discharge, an important advice for the breastfeeding mother is to:-', 'Routinely avoid onions, cabbage and chocolate', 'Keep her calcium intake the same as during pregnancy', 'Increase her calories over her pregnancy requirements', 'Return to her pre-pregnancy intake for proteins but not calories', 'C', 'Per maternal nutrition guidelines (Myles/Kenya MOH), lactation demands more energy than pregnancy, so the breastfeeding mother should increase her caloric intake above her pregnancy requirements; routine food avoidance is unnecessary.', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The part of the uterus in which a contraction begins is:-', 'Cornua', 'Fundus', 'Isthmus', 'The body or corpus', 'A', 'Per Myles Textbook for Midwives, uterine contractions originate at pacemakers in the cornua (near the tubal ostia) and spread downward and inward (fundal dominance).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The follicle stimulating hormone and luteinizing hormone are secreted by the:-', 'Ovaries and testes', 'Posterior pituitary', 'Anterior pituitary gland', 'Hypothalamus', 'C', 'Per human physiology (Myles/anatomy texts), FSH and LH are gonadotrophins secreted by the anterior pituitary gland under hypothalamic GnRH control.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The ectoderm differentiates to form the:-', 'Cardiovascular system', 'Peripheral nervous system', 'Respiratory tract', 'Connective tissues', 'B', 'Per embryology (Myles), the ectoderm gives rise to the nervous system (central and peripheral), skin, and sensory epithelia; cardiovascular and connective tissues derive from mesoderm and respiratory tract from endoderm.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The anteroposterior diameter of the pelvic outlet measures:-', '12CM', '13CM', '11CM', '10CM', 'B', 'Per Myles Textbook for Midwives, the anteroposterior diameter of the pelvic outlet measures about 13 cm, the largest outlet diameter.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('During pregnancy, the glomerular filtration rate', 'Only changes when pathological conditions are present', 'Is directly influenced by the woman’s posture', 'Increases significantly above pre-pregnant levels', 'Makes the most dramatic changes near birth', 'C', 'Per maternal physiology (Myles), renal plasma flow and GFR rise markedly (by ~40-50%) above pre-pregnant levels early in pregnancy due to increased cardiac output.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Signs of cardiac decompensation in a pregnant woman with cardiac disease are likely to appear at', '28-32 weeks gestation', '36-40 weeks gestation', '12-16 weeks gestation', '20-24 weeks gestation', 'A', 'Per Myles Textbook for Midwives, cardiac decompensation in pregnant women with heart disease is most likely around 28-32 weeks when blood volume and cardiac output peak.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The mechanism of labor that allows the fetal head to present itself to fit the widest anteroposterior diameter of the pelvic cavity is:-', 'Flexion', 'Internal rotation', 'Descent', 'Extension', 'B', 'Per Myles Textbook for Midwives, internal rotation brings the occiput anteriorly so the fetal head aligns its longest (anteroposterior) diameter with the widest (anteroposterior) diameter of the pelvic outlet.', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Closure of the newborns foramen ovale occurs when:-', 'Blood flows from the pulmonary artery to the aorta', 'PO2 is increased causing constriction to occur', 'The umbilical cord is severed', 'Left atrial pressure exceeds right atrial pressure', 'D', 'Per neonatal circulation physiology (Myles), after birth lung expansion lowers pulmonary resistance and increases pulmonary venous return, so left atrial pressure exceeds right atrial pressure and functionally closes the foramen ovale.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The newborn with post maturity syndrome is at high risk for cold stress due to:-', 'Absence of vernix', 'Decreased subcutaneous fat', 'Parchment like skin', 'Extended posture', 'B', 'Per neonatal care (Basic Paediatric Protocols/Myles), the postmature infant has used up subcutaneous fat and glycogen stores in utero, so reduced subcutaneous fat and brown fat predispose to cold stress and hypoglycaemia.', 'BScN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Presence of Meconium in the newborn’s lungs:-', 'Leads to respiratory alkalosis', 'Prevents air leaks', 'Traps inspired air in the alveoli', 'Prevents air from entering the airway', 'C', 'Per paediatric respiratory physiology (Basic Paediatric Protocols), meconium in the lungs causes a ball-valve obstruction that traps air distally, leading to hyperinflation and air-leak/pneumothorax with respiratory acidosis.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Symptoms of superficial thrombophlebitis include:-', 'Local redness and tenderness in a portion of the vein', 'Edema of the ankle and lower leg', 'Pain in the affected leg and foot', 'Positive Homan’s sign', 'A', 'Per Brunner & Suddarth''s Medical-Surgical Nursing, superficial thrombophlebitis presents with localized redness, warmth and tenderness along the palpable, cord-like superficial vein; oedema and positive Homan''s sign indicate deep vein thrombosis.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Persistence of moro reflex beyond the age of 6months is usually suggestive of:', 'Immaturity', 'Brain damage', 'Mental retardation', 'Brachial plexus palsy', 'B', 'Per Basic Paediatric Protocols/child development, the Moro reflex normally disappears by 3-6 months; persistence beyond 6 months suggests neurological (brain) damage or cerebral dysfunction.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Lochia serosa is composed of:', 'Decidua, vernix, leucocytes', 'Leucocytes, cervical mucus, decidua', 'Cervical mucus, cholestrin crystals, lanugo', 'Leucocytes, cervical mucus, erythrocytes', 'D', 'Per Myles Textbook for Midwives, lochia serosa (approx days 4–10) is pinkish-brown and contains leucocytes, cervical mucus, serous exudate, shreds of decidua and erythrocytes. The option listing leucocytes, cervical mucus and erythrocytes best fits; options with vernix, lanugo or cholesterin crystals are incorrect for lochia.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('During second stage of labour, the diameter that distends the vaginal orifice in face presentation is:', 'Occipito frontal', 'Submento-vertical', 'Submento-bregmatic', 'Mentovertical', 'C', 'Per Myles Textbook for Midwives, in a well-flexed (mento-anterior) face presentation the presenting diameter that distends the vulva is the submento-bregmatic (9.5 cm), analogous to the suboccipito-bregmatic in vertex. The others (occipito-frontal, submento-vertical, mento-vertical) are not the engaging/distending diameter of a face presentation delivering.', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The common age of onset for gonococcal ophthalmia neonatorum is:', 'Between 21-28 days after birth', 'Between 0-7 days after birth', 'Between 7-14 days after birth', 'At 28 days of age', 'B', 'Per Basic Paediatric Protocols and WHO, gonococcal ophthalmia neonatorum characteristically presents early, within the first week (typically day 2–5, i.e., 0–7 days) after birth, whereas chlamydial conjunctivitis appears later (5–14 days). Thus 0–7 days is correct.', 'BScN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following respiratory patterns indicate increased intracranial pressure in the brain stem?', 'Slow, irregular respirations', 'Rapid, shallow respirations’', 'Asymmetric chest excursion', 'Nasal flaring', 'A', 'Per Brunner & Suddarth, brainstem compression from raised ICP produces slow, irregular (e.g., Cheyne-Stokes, ataxic/Biot''s, or apneustic) respiratory patterns as part of Cushing''s response. Rapid shallow breathing, asymmetric excursion and nasal flaring are not the hallmark brainstem pattern of increased ICP.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse administers mannitol to the client with increased intracranial pressure. Which parameter needs close monitoring', 'Muscle relaxation', 'Intake and output', 'Widening of the pulse pressure', 'Pupil dilation', 'B', 'Per Brunner & Suddarth, mannitol is an osmotic diuretic used to reduce ICP; it causes profuse diuresis, so strict intake and output (with fluid/electrolyte and osmolality) monitoring is essential to avoid dehydration and renal compromise. Muscle relaxation, widening pulse pressure and pupil dilation are not the primary parameter tied to the drug''s diuretic action.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which activity should the nurse encourage the client to avoid when there is a risk for increased intracranial pressure (ICP)?', 'Deep breathing', 'Coughing', 'Turning', 'Passive range of motion (ROM) exercises', 'B', 'Per Brunner & Suddarth, activities that raise intrathoracic/intra-abdominal pressure (coughing, straining/Valsalva) increase ICP and should be avoided/minimized. Deep breathing, gentle turning and passive ROM are permissible; vigorous coughing is the one to avoid.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('For a client who is experiencing expressive aphasia, which nursing intervention is most helpful in promoting communication?', 'Speaking loudly', 'Using a picture board', 'Writing directions so client can read them', 'Speaking in short sentence ● (6) The nurse is assessing the motor and sensory function of an unconscious client. The nurse should use which technique to test the client’s peripheral response to pain? (A) Sternal rub (B) Nail bed pressure (C) Pressure on the orbital rim - (localizing pain) (D) Squeezing of the sternocleidomastoid muscle', 'B', 'Per Brunner & Suddarth''s Medical-Surgical Nursing, expressive (Broca''s) aphasia means the client understands but cannot produce speech; a picture/communication board lets them convey needs. Speaking loudly (A) is for hearing loss, not aphasia. (Option D text is garbled with a trailing unrelated stem, but B is the best communication aid.)
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is evaluating the neurological signs of a client in spinal shock following spinal cord injury. Which observation indicates that spinal shock persists?', 'Hyperreflexia', 'Positive reflexes', 'Flaccid paralysis', 'Reflex emptying of the bladder', 'C', 'Per Brunner & Suddarth, spinal shock is characterized by flaccid paralysis, loss of reflexes (areflexia) and loss of sensation/autonomic function below the lesion. Hyperreflexia, positive reflexes and reflex bladder emptying indicate RESOLUTION of spinal shock, so flaccid paralysis indicates it persists.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse has instructed the family of a client with stroke (brain attack) who has homonymous hemianopsia about measures to help the client overcome the deficit. Which statement suggests that the family understands the measures to use when caring for the client?', '“We need to discourage him from wearing eyeglasses.”', '“We need to place objects in his impaired field of vision.”', '“We need to approach him from the impaired field of vision.”', '“We need to remind him to turn his head to scan the lost visual field.”', 'D', 'Per Brunner & Suddarth, in homonymous hemianopsia the client loses the same half of the visual field in both eyes; teaching them to turn the head and scan toward the affected side compensates for the deficit. Initially objects/approach are placed on the intact side; discouraging eyeglasses is wrong. Head-turning/scanning shows correct understanding.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is teaching a client with myasthenia gravis about the prevention of myasthenic and cholinergic crisis. Which client activity suggests that teaching is most effective?', 'Taking medications as scheduled', 'Eating large, well-balanced meals', 'Doing muscle-strengthening exercises', 'Doing all chores early in the day while less fatigue', 'A', 'Per Brunner & Suddarth, in myasthenia gravis anticholinesterase drugs must be taken exactly on schedule to maintain therapeutic levels; late/missed doses precipitate myasthenic crisis and overdose precipitates cholinergic crisis. Large meals, strenuous exercise and doing all chores early do not reliably prevent crises; adherence to the medication schedule does.', 'BScN', 'Paper I', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client is admitted to the hospital with a diagnosis of Guillain-Barre syndrome. Which past medical history finding makes the client most at risk for this disease?', 'Meningitis or encephalitis during the last 5 years', 'Seizures or trauma to the brain within the last year', 'Back injury or trauma to the spinal cord during the last 2 years', 'Respiratory or gastrointestinal infection during the previous month', 'D', 'Per Brunner & Suddarth, Guillain-Barre syndrome is an autoimmune polyneuropathy typically preceded (1–4 weeks prior) by a viral respiratory or gastrointestinal infection (e.g., Campylobacter). Meningitis, seizures/head trauma and spinal/back injury are not the classic antecedent risk; a recent respiratory/GI infection is.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is evaluating the status of a client who had a craniotomy 3 days ago. Which assessment finding would indicate that the client is developing meningitis as a complication of surgery?', 'A negative Kernig’s sign', 'Absence of nuchal rigidity', 'A positive Brudzinski’s sign', 'A Glasgow Coma Scale score of 15', 'C', 'Per Brunner & Suddarth, meningitis produces meningeal irritation signs: nuchal rigidity and positive Kernig''s and Brudzinski''s signs. A positive Brudzinski''s sign indicates developing meningitis; a negative Kernig''s, absent nuchal rigidity and a normal GCS of 15 would suggest NO meningitis.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is positioning the female client with increased intracranial pressure. Which of the following positions would the nurse avoid?', 'Head midline', 'Head turned to the side', 'Neck in neutral position', 'Head of bed elevated 30 to 45 degrees', 'B', 'Per Brunner & Suddarth, with increased ICP the head should be kept midline and neutral with the bed elevated 30–45 degrees to promote venous drainage; turning/rotating the head to the side obstructs jugular venous outflow and raises ICP, so it is the position to AVOID.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is caring for the male client who begins to experience seizure activity while in bed. Which of the following actions by the nurse would be contraindicated?', 'Loosening restrictive clothing', 'Restraining the client’s limbs', 'Removing the pillow and raising padded side rails', 'Positioning the client to side, if possible , with the head flexed forward', 'B', 'Per Kozier & Erb''s Fundamentals and Brunner & Suddarth, during a seizure the nurse must NOT restrain the limbs (risks fractures/injury). Correct actions are loosening clothing, removing the pillow and padding side rails, and side-lying with head flexed forward; restraining limbs is contraindicated.', 'BScN', 'Paper I', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is teaching the female client with myasthenia gravis about the prevention of myasthenic and cholinergic crises. The nurse tells the client that this is most effectively done by:', 'Eating large, well-balanced meals', 'Doing muscle -strengthening exercises', 'Doing all chores early in the day while less fatigued', 'Taking medications on time to maintain therapeutic blood levels', 'D', 'Per Brunner & Suddarth, prevention of both myasthenic and cholinergic crises depends on taking anticholinesterase medication precisely on time to keep therapeutic blood levels. Large meals, muscle-strengthening exercise and doing all chores early are not effective preventive measures.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following neurotransmitters is known to be associated with sleep, mood and appetite?', 'Acetylcholine', 'Dopamine', 'Serotonin', 'GABA', 'C', 'Per standard physiology (Brunner & Suddarth / Lewis) and psychiatric nursing texts, serotonin (5-HT) regulates sleep, mood and appetite. Acetylcholine (muscle/memory), dopamine (movement/reward) and GABA (inhibition) do not fit this triad; serotonin does.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The neurons of the motor pathway control:', 'Stress reaction', 'Organs and glands', 'Involuntary muscles', 'Voluntary muscles', 'D', 'Per anatomy & physiology texts, the motor (somatic) pathway carries efferent impulses controlling voluntary (skeletal) muscles. Involuntary muscles, organs and glands are controlled by the autonomic nervous system; hence voluntary muscles is correct.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The area of the brain which is involved in the understanding of meaning is:', 'Broca’s area', 'association areas', 'Wernicke area', 'Motor speech area', 'C', 'Per neuroanatomy (Brunner & Suddarth), Wernicke''s area (posterior superior temporal lobe) is responsible for comprehension/understanding of language meaning. Broca''s/motor speech area handles speech production; general association areas integrate information, but understanding of meaning is specifically Wernicke''s area.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Parkinson’s disease , is caused by the degeneration of neurons in an area of the brain called the:', 'Substantia nigra', 'Basal ganglia', 'Cerebellum', 'Corpus callosum', 'A', 'Per Brunner & Suddarth, Parkinson''s disease results from degeneration of dopaminergic neurons in the substantia nigra, reducing dopamine. Although the basal ganglia circuit is affected, the primary site of neuronal degeneration is the substantia nigra.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The division of the nervous system which controls the involuntary muscles, organs, and glands is:', 'Somatic nervous system', 'Autonomic nervous system', 'Central nervous system', 'The motor pathway of the CNS', 'B', 'Per anatomy & physiology texts, the autonomic nervous system controls involuntary muscles, organs and glands (via sympathetic and parasympathetic divisions). The somatic system controls voluntary muscle; the CNS is the integrating centre. Hence autonomic nervous system is correct.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is teaching a class on the prevention of cerebrovascular accidents. Which of the following risk factors should the nurse identify as the most important factor contributing to a stroke?', 'Sedentary lifestyle', 'Smoking', 'Obesity', 'Hypertension', 'D', 'Per Kenya MOH NCD guidelines and Brunner & Suddarth, hypertension is the single most important MODIFIABLE risk factor for stroke (cerebrovascular accident). Smoking, obesity and sedentary lifestyle also contribute, but hypertension is the leading contributing factor.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is assessing a 37-year-old client diagnosed with multiple sclerosis. Which of the following symptoms would the nurse expect to find?', 'Flaccid muscles', 'Tremors at rest', 'Absent deep tendon reflexes', 'Vision changes', 'D', 'Per Brunner & Suddarth, multiple sclerosis classically presents with visual disturbances (optic neuritis, diplopia, blurred vision), along with spasticity, hyperreflexia and intention (not resting) tremor. Flaccid muscles, resting tremor and absent deep tendon reflexes are not typical of MS; vision changes are the expected finding.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('If a male client experienced a cerebrovascular accident (CVA) that damaged the hypothalamus, the nurse would anticipate that the client has problems with:', 'Thinking and reasoning', 'Body temperature control', 'Balance and equilibrium', 'Visual acuity', 'B', 'The hypothalamus is the principal thermoregulatory centre (also controlling hunger, thirst, and neuroendocrine function). Damage impairs body temperature control. Thinking/reasoning is cortical (frontal), balance is cerebellar, and visual acuity is occipital/optic pathway (Brunner & Suddarth''s Medical-Surgical Nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('During recovery from a cerebrovascular accident (CVA), a female client is given nothing by mouth, to help prevent aspiration. To determine when the client is ready for a liquid diet, the nurse assesses the client’s swallowing ability once each shift. This assessment evaluates', 'Cranial nerves III and V', 'Cranial nerves IX and X', 'Cranial nerves I and II', 'Cranial nerves VI and VIII', 'B', 'Swallowing (gag reflex) is mediated by the glossopharyngeal (IX) and vagus (X) nerves. Assessing swallowing ability tests these cranial nerves before advancing diet post-CVA (Brunner & Suddarth''s Medical-Surgical Nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Demyelination is defined as;', 'Loss of an axon in a neuron', 'Loss of dendrites in a neuron', 'Loss of protective sheath surrounding neurons', 'Loss of connective tissue between neurons', 'C', 'Demyelination is the loss/destruction of the myelin sheath surrounding nerve fibres (as in multiple sclerosis), slowing nerve conduction (Brunner & Suddarth''s Medical-Surgical Nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Failure of muscle coordination , including unsteady movements and staggering walk, due to disorders in the cerebellum is called?', 'Anoxia', 'Dyslexia', 'Paraplegia', 'Ataxia', 'D', 'Ataxia is impaired muscle coordination causing unsteady, staggering gait, characteristically due to cerebellar dysfunction. Anoxia is oxygen lack, dyslexia is a reading disorder, and paraplegia is lower-limb paralysis (Brunner & Suddarth''s Medical-Surgical Nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which part of the brain regulates heartbeat, breathing and other vital functions?', 'Grey matter', 'Brain stem', 'Occipital lobe', 'White matter', 'B', 'The brain stem (specifically the medulla oblongata) contains the cardiac, respiratory, and vasomotor centres regulating heartbeat, breathing and other vital functions (Brunner & Suddarth''s Medical-Surgical Nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Common complications of spinal cord injury include each of the following EXCEPT?', 'Pressure sores', 'Deep vein thrombosis', 'Diarrhoea', 'Urinary Tract infections', 'C', 'Spinal cord injury commonly causes pressure sores, DVT (from immobility), and UTIs (from neurogenic bladder/catheterisation). Constipation, not diarrhoea, results from neurogenic bowel; thus diarrhoea is the exception (Brunner & Suddarth''s Medical-Surgical Nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Broca’s area is located in the', 'Brain stem', 'Frontal lobe', 'Parietal lobe', 'Temporal lobe', 'B', 'Broca''s area (motor speech centre) lies in the inferior frontal lobe of the dominant hemisphere; damage causes expressive (non-fluent) aphasia (Brunner & Suddarth''s Medical-Surgical Nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Wernicke area is located in the', 'Brain stem', 'Parietal lobe', 'Temporal lobe', 'Frontal lobe', 'C', 'Wernicke''s area (receptive/sensory speech centre) is located in the posterior superior temporal lobe of the dominant hemisphere; damage causes receptive (fluent) aphasia (Brunner & Suddarth''s Medical-Surgical Nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The presence of ptosis suggests damage to cranial nerve:', 'IV', 'V', 'III', 'VII', 'C', 'The oculomotor nerve (III) supplies the levator palpebrae superioris, which elevates the upper eyelid; its damage causes ptosis (drooping eyelid) along with a ''down and out'' eye (Brunner & Suddarth''s Medical-Surgical Nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following function is controlled by parasympathetic system?', 'Pupil constriction', 'Acceleration of heart beat', 'Stimulation of sweat glands', 'Contraction of hair muscles', 'A', 'Parasympathetic (rest-and-digest) stimulation causes pupil constriction (miosis), slows the heart, and reduces secretions. Acceleration of heart rate, sweating, and pilo-erection are sympathetic responses (Kozier & Erb''s Fundamentals; Brunner & Suddarth''s).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which one of the following is NOT a probable sign of the second stage of labour?', 'uterine contractions', 'No cervix felt on vaginal examination', 'Rupture of membranes', 'Bulging of the perineum', 'C', 'Signs of second stage include strong uterine contractions, full dilatation (no cervix felt), and bulging perineum. Rupture of membranes can occur at any stage and is not a specific sign of second stage, so it is the exception (Myles Textbook for Midwives).', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Ms. D is admitted to the labour ward in early active labour. The priority intervention on admission of this woman would be:', 'Auscultating the fetal heart', 'Taking an obstetric history', 'Asking the client when she last ate', 'Ascertaining whether the membranes were ruptured', 'A', 'On admission in labour, assessing fetal wellbeing by auscultating the fetal heart is the priority to detect fetal compromise; history-taking and other assessments follow (Myles Textbook for Midwives; Kenya Maternal/Newborn care guidelines).', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which one of the following foetal positions is most favourable for birth?', 'Vertex presentation', 'Transverse lie', 'Frank breech presentation', 'Posterior position of the fetal head', 'A', 'Vertex (cephalic, well-flexed) presentation is the most favourable for vaginal birth. Transverse lie, frank breech, and persistent occipito-posterior positions are associated with difficult or obstructed labour (Myles Textbook for Midwives).', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In which one of the following stages is the placenta delivered?', 'Stage 1, latent phase', 'Stage 1, active phase', 'Stage2', 'Stage 3', 'D', 'The placenta is delivered during the third stage of labour, from birth of the baby to expulsion of the placenta and membranes (Myles Textbook for Midwives).', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Endogenous oxytocin is released from the:', 'anterior pituitary gland', 'cervix', 'posterior pituitary gland', 'uterus', 'C', 'Oxytocin is synthesised in the hypothalamus and released (stored) from the posterior pituitary gland; it stimulates uterine contraction and milk ejection (Myles Textbook for Midwives; physiology texts).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The midwife is caring for a woman in labour. She determines that the woman is beginning the 2nd stage of labour when which of the following signs is noted?', 'The woman begins to expel clear vaginal fluid', 'The contractions are regular', 'The membranes have ruptured', 'The cervix is dilated completely', 'D', 'The second stage of labour begins when the cervix is fully (completely) dilated at 10 cm and ends with birth of the baby. Regular contractions and ruptured membranes are not defining signs (Myles Textbook for Midwives).', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is true about congenital abnormalities?', 'It refers to defects in the body structure at birth', 'It is always occult at birth making it difficult to detect', 'Congenital abnormalities are all inherited from the family', 'It results from unknown fetal developments that are always difficult to predict', 'A', 'Congenital abnormalities are structural or functional defects present at birth. They are not always occult (many are visible), not all are inherited (many are environmental/multifactorial), and causes are often known (Myles Textbook for Midwives; Basic Paediatric Protocols).', 'BScN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When resuscitating a neonate who has neonatal asphyxia after how long should the midwife use ambubag', 'After 30 seconds of oxygen by face mask', 'When the baby remains apnoeic after 30 minutes of facemask oxygen therapy.', 'When the neonate is no longer cyanosed', 'When the neonate P02 level has increased', 'A', 'In neonatal resuscitation, if the baby is not breathing adequately after the initial steps, positive-pressure ventilation with a bag-and-mask (ambubag) is started within about 30 seconds (''the golden minute''). The 30-minute option is clearly wrong (Kenya Basic Paediatric Protocols; WHO/HBB neonatal resuscitation).', 'BScN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When should a midwife put an asphyxiated neonate on intubation and ventilation?', 'When the heart beat is more than 100 beats per minute', 'When the heart beat is less than 100 beats per minute', 'When the heart rate has improved', 'When resuscitation measures are performed without medical assistance', 'B', 'Persistent bradycardia (heart rate below 100 bpm) despite effective bag-mask ventilation indicates the need for advanced airway management (intubation and ventilation). An improving heart rate over 100 bpm signals adequate resuscitation (Kenya Basic Paediatric Protocols; neonatal resuscitation guidelines).', 'BScN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is the most appropriate feature seen in symmetric growth retarded infant?', 'Weight is depressed more than length or head circumference.', 'Fetal growth retardation probably has occurred in the last trimester of pregnancy.', 'Weight, length and head circumference are below normal and babies look like miniature normal babies.', 'It is mostly linked with cigarette smoking.', 'C', 'Symmetric (early-onset) IUGR affects weight, length and head circumference proportionately, producing a proportionately small (''miniature normal'') infant. Asymmetric IUGR (late trimester, spares head, linked to smoking) is described by the other options (Myles Textbook for Midwives; Basic Paediatric Protocols).', 'BScN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which statement is true about meconium?', 'Meconium is 1st found in the foetal ileum between the 20th and 26th weeks of gestation', 'Meconium passage is uncommon before 36 weeks but its common in pregnancies beyond 42 weeks', 'In utero passage of meconium is common because the anal sphincter tone is poor', 'All of the above', 'D', 'Meconium first forms in the fetal ileum around 20-26 weeks, its passage in utero is uncommon before 36 weeks but rises in post-term (over 42 weeks) pregnancies, and passage relates to gut maturation/hypoxia. All statements are correct, so ''All of the above'' applies (Myles Textbook for Midwives).', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is true about twin to twin transfusion syndrome?', 'The smaller twin has the greatest risk of cardiac compromise', 'The larger twin is often stuck to the uterine wall', 'Serial amnia reduction improves perinatal survival', 'Fetoscopic laser ablation of the placental vessels increases survival for both', 'D', 'Fetoscopic laser photocoagulation of the communicating placental vessels is the definitive treatment for TTTS and improves survival for both twins. The larger (recipient) twin, not the smaller donor, has cardiac compromise, and the smaller donor is the ''stuck twin''; laser ablation is superior to serial amnioreduction (Myles Textbook for Midwives; RCOG/WHO adopted guidance).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What would be the result of fail splitting a single fertilized ovum between 8 to 12 days after fertilization?', 'Conjoined twin', 'Monochorionic monoamniotic twin', 'Dichorionic diamniotic twin', 'Monochorionic diamniotic twin', 'A', 'Splitting of a single fertilized ovum after day 8-12 (late, after the amniotic sac has formed) is incomplete and results in conjoined twins. Earlier splits give diamniotic or monoamniotic monochorionic twins (Myles Textbook for Midwives).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following best describes large for gestational age?', 'Large for gestational age is weight, length, or circumference that lies above the 90th percentile for that gestational age.', 'Large for gestational age is defined as birth weight more than 2 standard deviations above the mean.', 'Large for gestational age is an indication of high prenatal growth.', 'Large for gestational age is weight of 3500g at birth despite gestational age.', 'A', 'Per standard neonatal criteria (Myles Textbook for Midwives; Basic Paediatric Protocols Kenya), LGA is defined as any growth parameter above the 90th percentile for gestational age. Option D fixes an arbitrary weight ignoring gestational age and is wrong.', 'BScN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which ONE of the following is a clinical feature clinical chorio-amnionitis?', 'Foul smelling vaginal discharge', 'Non tender uterus on palpation', 'Maternal temperature of 37.4 degrees Celsius', 'Maternal pulse of 110 beats per minute', 'D', 'Per Myles Textbook for Midwives and MOH maternal guidelines, chorioamnionitis features include maternal tachycardia (>100 bpm), fever (>38°C), foul-smelling discharge and a TENDER uterus. A pulse of 110 bpm fits; a temperature of 37.4°C is not febrile and a non-tender uterus is the opposite of the finding, so D is the valid clinical feature.', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the greatest risk of retained products of conception in the immediate post partum period?', 'Uterine atony', 'Uterine inversion', 'Uterine rupture', 'Uterine tenderness', 'A', 'Per MOH/Myles: retained products of conception prevent the uterus from contracting fully, causing uterine atony and postpartum haemorrhage, the greatest immediate risk. Inversion and rupture are not the primary consequence of retained products.', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is NOT an outcome for an occipito posterior position?', 'Brow delivery', 'Deep transverse arrest', 'Persistent occipito posterior position', 'Occipito anterior delivery', 'A', 'Per Myles Textbook for Midwives, outcomes of occipitoposterior position include long internal rotation to occipitoanterior (spontaneous delivery), persistent OP, and deep transverse arrest. Brow presentation is a separate deflexed malpresentation, not an outcome of OP, so it is the NOT answer.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When assessing the progress of labour, the midwife should assess for the 4 Ps. Which ONE of the following represents the 4 Ps?', 'Power, parity, passenger and passage', 'Passenger, power, patient and passage', 'Parity, progress, power and passenger', 'Passenger, power, progress and passage', 'D', 'Per Myles Textbook for Midwives, the factors influencing labour progress are the Powers, the Passage, the Passenger and Progress (some texts add Psyche). Option D lists passenger, power, progress and passage, the valid 4 Ps.', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is 3rd degree moulding?', 'Change of the shape of the foetal skull that occurs during labour', 'Sutures of the foetal skull are overridden, but are easily separable', 'Sutures of the foetal skull are in close contact', 'Sutures of the foetal skull are overridden and inseparable', 'D', 'Per Myles Textbook for Midwives, moulding grades: 1st = sutures meet/in close contact, 2nd = sutures overlap but reducible (easily separated), 3rd = sutures overlap and are NOT reducible (inseparable), indicating cephalopelvic disproportion. Option D is correct.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In a brow presentation, what is the engaging diameter of the foetus into the maternal pelvis?', 'Sub-mento vertical diameter', 'Occipito-frontal diameter', 'Mento-vertical diameter', 'Sub-mento bregmatic diameter', 'C', 'Per Myles Textbook for Midwives, brow presentation presents the mentovertical diameter (~13.5 cm), the largest antero-posterior diameter of the fetal skull, which usually cannot engage and leads to obstructed labour.', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which statement BEST describes a complete breech presentation?', 'Both hips are flexed and both knees are extended', 'Both hips and both knees are flexed', 'One or both hips are extended with the knees extended', 'One or both hips are extended with the knees or knee flexed', 'B', 'Per Myles Textbook for Midwives: complete (flexed) breech has both hips and both knees flexed. Frank breech = hips flexed, knees extended (option A); footling = hip(s) extended.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following are the engaging diameters in a face presentation?', 'Sub-occipitofrontal and biparietal', 'Occipito-frontal and biparietal', 'Mentovertical and biparietal', 'Sub-mentobregmatic and biparietal', 'D', 'Per Myles Textbook for Midwives, in a fully extended face presentation the engaging diameters are the submentobregmatic (~9.5 cm) antero-posteriorly and the biparietal transversely.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Thembi is primigravida at 39 weeks gestational age. She requested induction of labour because she is a student in one of the universities, in preparation for her examination. On examination:Presentation- cephalic, Fundal height- 40cm, foetal heart rate 148 beats per minute. Before induction, the obstetrician examines her and the findings are as follows: cervix-mid position; firm; station-3; length-2cm; and cervical dilatation: 1-2 cm. What is Thembi''s Bishop Score?', '2', '3', '4', '5', 'B', 'Per Myles Textbook for Midwives Bishop scoring: dilatation 1-2 cm = 1, length/effacement 2 cm (0-1 cm effaced) = 1, station -3 = 0, consistency firm = 0, position mid = 1, giving a total of 3.', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is NOT a contra-indication for a trial of scar?', 'Multiple pregnancy', 'History of sepsis following the previous caesarean section', 'Previous caesarean section for cord prolapse', 'Breech presentation', 'C', 'Per MOH/Myles VBAC criteria, a previous CS done for a non-recurrent indication such as cord prolapse is a GOOD candidate for trial of scar, so it is NOT a contraindication. Multiple pregnancy, previous sepsis, and breech are relative contraindications to trial of scar.', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which ONE of the following drugs should be used first to a non hypertensive woman presenting with post partum haemorrhage occurring due to uterine atony?', 'Syntometrine', 'Oxytocin', 'Misoprostol', 'Ergometrine', 'B', 'Per Kenya MOH/EmONC PPH guidelines, oxytocin is the first-line uterotonic for atonic PPH in any woman including hypertensives. Ergometrine and syntometrine are contraindicated in hypertension; oxytocin is the safe first choice.', 'BScN', 'Paper I', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Subtle neonatal seizure is recognized by:-', 'Sustained eye opening or fixation, drooling, sustained posturing of a limb.', 'Migrating jerks of limbs, localized clonic jerking, tonic horizontal deviation of eyes.', 'Migrating jerks of limbs, tonic horizontal deviation of eyes, lip smacking.', 'Tonic horizontal deviation of eyes, apnoeic spells, lips smacking.', 'A', 'Per Basic Paediatric Protocols (Kenya) and neonatal texts, subtle seizures manifest as eye deviation/fixation, blinking, drooling, chewing/lip-smacking, apnoea, and sustained posturing. Migrating and clonic jerking describe clonic/multifocal seizures, not subtle ones, so A best fits the subtle category.', 'BScN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Causes of primary amenorrhea include:-', 'Gonadal dysgenesis, premature ovarian failure, asherman’s syndrome.', 'Sheehan’s syndrome, gonadal dysgenesis, imperforate hymen.', 'Androgen insensitivity, gonadal dysgenesis, imperforate hymen.', 'Polycystic ovarian syndrome, sheehan’s syndrome, gonadal dysgenesis.', 'C', 'Per gynaecology texts (Myles/standard), primary amenorrhoea causes include androgen insensitivity, gonadal dysgenesis (Turner) and outflow obstruction like imperforate hymen. Asherman''s and Sheehan''s cause SECONDARY amenorrhoea, excluding options A, B and D.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following are anterior pituitary gland hormones except', 'Prolactin', 'Antidiuretic hormone', 'Follicle stimulating hormone', 'Luteinizing hormone', 'B', 'Per Kozier/anatomy & physiology, the anterior pituitary secretes prolactin, FSH, LH, GH, TSH and ACTH. ADH (vasopressin) is released by the POSTERIOR pituitary, so it is the exception.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Wernicke area is in the;', 'Occipital lobe', 'Frontal lobe', 'Parietal lobe', 'Temporal lobe', 'D', 'Per neuroanatomy (Brunner & Suddarth), Wernicke''s area (receptive/comprehension speech) lies in the posterior superior temporal lobe of the dominant hemisphere.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Cardiac output is equal to;', 'Heart rate × patients body weight', 'Venous return× Peripheral resistance', 'Peripheral resistance × stroke volume', 'Stroke volume ×heart rate', 'D', 'Per cardiovascular physiology (Brunner & Suddarth), cardiac output = stroke volume × heart rate.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Management of scaled lesion in psoriasis include;', 'Shaving the scales using a clean razor', 'Applying moisturizers to soften the scales', 'Covering the lesions with occlusive dressings to remove scales', 'Keeping the lesions dry to enhance dropping off the scales', 'B', 'Per Brunner & Suddarth dermatology, psoriatic scales are managed by emollients/moisturizers and keratolytics to soften and gently remove scales; shaving with a razor or forcibly removing scales traumatises skin and worsens lesions.', 'BScN', 'Paper I', 'Nursing Management & Leadership', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following is true regarding Hashimoto thyroiditis', 'Is an autoimmune disease, causes primary hypothyroidism', 'Is an autoimmune disease, causes primary hyperthyroidism', 'Results in goiter, causes exophthalmos', 'More common in women, there is an increase in TH levels.', 'A', 'Per Brunner & Suddarth, Hashimoto thyroiditis is an autoimmune destruction of the thyroid causing primary HYPOthyroidism. Exophthalmos and hyperthyroidism belong to Graves'' disease, excluding B and C.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Characteristics of 2nd degree burns include;', 'Waxy white dry, leathery, charred, oedema', 'Fluid-filled blisters, weeping of fluid, bright pink', 'Red to gray, may have local edema', 'severe pain, weeping of fluid, may have local edema, leathery charred', 'B', 'Per Brunner & Suddarth burn classification, second-degree (partial-thickness) burns present with fluid-filled blisters, moist weeping surface, bright pink/red colour and severe pain. Waxy white, dry, leathery and charred describe full-thickness (3rd degree) burns.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When estimating the size of burns, the palm of the patient’s hand represents body surface area of;', '3%', '1%', '4.5%', '9%', 'B', 'Per Brunner & Suddarth and burn assessment guidelines, the patient''s palm (palmar surface including fingers) represents approximately 1% of total body surface area, used to estimate scattered burns.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Malena can be caused by;', 'Small bowel obstruction, abdominal aortic aneurysm, internal hemorrhoids', 'Perforated gastric ulcers, neoplasms in the transverse colon', 'Bleeding esophageal varices, perforated gastric ulcer', 'Abdominal aortic aneurysm, splenic neoplasm, esophageal varices', 'C', 'Per Brunner & Suddarth, melaena (black tarry stool) results from UPPER GI bleeding such as bleeding oesophageal varices and perforated/bleeding gastric ulcers, where blood is digested. Lower colonic and haemorrhoidal bleeding produce fresh red blood, excluding the other options.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which sign and symptoms should a nurse expect to find in a client diagnosed with ulcerative colitis?', 'Twenty bloody stools a day', 'Chronic constipation', 'Oral temperature of 39o c', 'Hard rigid abdomen', 'A', 'Per Brunner & Suddarth, ulcerative colitis characteristically causes frequent bloody, mucoid diarrhoea (up to 10-20 stools/day). A rigid abdomen suggests peritonitis/perforation and constipation is not typical, making A the expected finding.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Early miscarriage refers to;', 'loss of pregnancy spontaneously in between 16-24 weeks', 'spontaneous loss of pregnancy from between 16-30 weeks gestation', 'spontaneous loss of pregnancy from between 0 to 16 weeks gestation', 'loss of pregnancy between 24 to 30weeks', 'C', 'Per Myles Textbook for Midwives, early miscarriage is spontaneous pregnancy loss occurring before 16 weeks (some define before 12/13 weeks); late miscarriage is 16-24 weeks. Option C best reflects early loss up to 16 weeks.', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The patient was brought to the outpatient department with a cut wound, which is the most appropriate intervention for a triage nurse;', 'Wash the site with soap and water', 'Squeeze the site to enhance bleeding', 'Apply a tourniquet proximal to the site', 'Apply a tourniquet distal to the site', 'A', 'Per MOH first-aid/wound care guidelines, initial management of a clean cut wound is to clean the site with soap and water and apply direct pressure. Squeezing to enhance bleeding or applying a tourniquet is inappropriate for a simple cut wound.', 'BScN', 'Paper I', 'Nursing Management & Leadership', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('While caring for a patient with a diagnosis of emphysema, the healthcare provider instructs the patient on positioning that will assist the patient’s ability to breathe when experiencing dyspnea. Which of the following positions will the healthcare provider instruct the patient about?', 'Lie supine with your feet on a blanket roll.', 'Sit upright and lean forward on a supportive surface', 'Sit in a recliner chair at a 120-degree angle', 'Assume a side-lying position', 'B', 'Per Brunner & Suddarth, patients with emphysema/COPD relieve dyspnoea using the orthopneic (tripod) position, sitting upright and leaning forward on a supportive surface, which improves accessory muscle use and lung expansion.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('During chest auscultation of a patient, which findings will indicate that the patient has cardiac condition and cannot be felt in a normal person', 'S1, S3 , Murmurs', 'S1, S2, Negative Murmurs,', 'S3, S4, Murmurs', 'S3, S1,S2', 'C', 'Per Brunner & Suddarth''s Med-Surg Nursing, S1 and S2 are normal heart sounds heard in healthy people; extra sounds S3 (in adults) and S4, together with murmurs, indicate cardiac pathology and are not normally audible in a healthy adult. Options containing S1/S2 are normal findings.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Nurse Lei caring for a client with a pneumothorax and who has had a chest tube inserted notes continues gentle bubbling in the suction control chamber. What action is appropriate?', 'Do nothing, because this is an expected findng', 'Immediately clamp the chest tube and notify the physician', 'Check for an air leak because the bubbling should be intermittent', 'Increase the suction pressure so that the bubbling becomes vigorous', 'A', 'Per Brunner & Suddarth, gentle continuous bubbling in the SUCTION-CONTROL chamber is expected and confirms suction is working. Continuous bubbling in the water-seal chamber would signal an air leak; clamping is contraindicated as it risks tension pneumothorax.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('You assess a client with newly diagnosed hypothyroidism as having an enlarged thyroid gland (goiter). What pathologic process causes this enlargement?', 'An excess of TH stimulates thyroid follicles', 'An increased dietary iodine intake', 'A compensatory effort to produce more TH', 'Tissue hypertrophy in response to increased TH', 'C', 'Per Brunner & Suddarth, in hypothyroidism low thyroid hormone raises TSH, which stimulates thyroid follicular hyperplasia in a compensatory attempt to produce more hormone, causing goiter. Excess TH (options A and D) is the mechanism in hyperthyroidism, not hypothyroidism.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following clients would be most at risk for the development of', 'Middle-age man who maintains normal weight', 'Young adult who is a professional basketball player', 'Middle-aged woman who is the sole caretaker of her parents', 'Woman over the age 70 who is overweight and sedentary', 'D', 'The stem is truncated but the classic at-risk profile for osteoarthritis/osteoporosis/degenerative disease is an elderly, overweight, sedentary woman (Brunner & Suddarth). The other options describe healthy or protected individuals.
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Ms. Smith complains of nausea and vomiting following her daily chemotherapy treatment. The most appropriate nursing intervention would be to;', 'Keep NPO until her daily chemotherapy is completed', 'Provide antiemetic medication 30 to 40 minutes prior to each treatment', 'Provide clear liquids until the chemotherapy is completed', 'Schedule chemotherapy administration to bed time', 'B', 'Per Brunner & Suddarth oncology nursing, chemotherapy-induced nausea/vomiting is best prevented by giving prophylactic antiemetics before treatment rather than treating symptoms after they occur; NPO or clear liquids alone do not prevent the emesis.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following clients is a greater risk for burn shock?', 'One with 90% superficial burns from a tanning bed', 'One with 10% TBSA from gasoline explosion', 'One with radiation burns following treatment for cancer', 'One with >50% TBSA from a high-voltage electric accident', 'D', 'Per Brunner & Suddarth burn nursing, extensive full-thickness/high-voltage electrical burns over >50% TBSA cause massive fluid shifts and are at greatest risk for burn (hypovolemic) shock. Superficial and small-percentage burns carry far lower shock risk.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('While providing care to an old woman with a cast on her lower arm (from below the elbow the elbow to above the fingers) you perform a neurovascular assessment. What is the possible complication?', 'Slightly edematous fingers', 'Warm, pink skin above the cast', 'Pale, cold fingers', 'Pain rating of 2 on a 1 to 10 scale', 'C', 'Per Brunner & Suddarth neurovascular (5 P''s) assessment, pale and cold fingers indicate impaired circulation/compartment compromise distal to the cast — a serious complication. Slight edema, warm pink skin and mild pain of 2/10 are expected, non-alarming findings.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Following gastrectomy, dumping syndrome occurs as a results of:-', 'Reduced gastric motility resulting from Vagus nerve stimulation', 'Removal of acid producing cells thus resulting in reduced absorption of Vit B12', 'Rapid gastric emptying of hyperosmolar fluid and substances into the duodenum', 'Damage of Vagus nerve and cardiac sphincter', 'C', 'Per Brunner & Suddarth, dumping syndrome after gastrectomy results from rapid emptying of hyperosmolar gastric contents into the jejunum/duodenum, drawing fluid into the bowel and causing vasomotor and GI symptoms. B12 malabsorption and vagal damage are separate post-gastrectomy issues.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The intracranial; hemorrhage with the worst prognosis is :-', 'Cephalohematoma', 'Epidural hemorrhage', 'Intracerebral hemorrhage', 'Subarachnoid hemorrhage', 'C', 'Per Brunner & Suddarth neuro nursing, intracerebral (intraparenchymal) hemorrhage carries the worst prognosis and highest mortality among these because it directly destroys brain tissue and causes mass effect. Cephalohematoma is benign and extradural in the newborn.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The health message given to a patient following tympanoplasty is:-', 'Drink fluids using a straw', 'Avoid blowing the nose and sneeze through the mouth', 'Administered saline water into the ear to aid healing', 'Avoid noisy places upto two weeks post operatively', 'B', 'Per Brunner & Suddarth ENT nursing, after tympanoplasty the patient must avoid nose-blowing and should sneeze with mouth open to prevent pressure transmission through the eustachian tube that could disrupt the graft. Straws/nose-blowing raise pressure; saline in the ear is contraindicated.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following indicates a normal finding on percussion of the lungs', 'Tympani over the right upper lobe', 'Resonance over the left upper lobe', 'C . Hyper resonance over the left lower lobe', 'Dullness above the left 10th intercostal space', 'B', 'Per Brunner & Suddarth respiratory assessment, resonance is the normal percussion note over healthy lung tissue. Tympany and hyperresonance are abnormal (air trapping), and dullness over lung fields is abnormal.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What are the causes of ischaemic stroke', 'Saccualar aneurysm, artery thrombosis, large artery thrombosis', 'Cardiogenic embolism, small artery thrombosis, cryptogenic', 'small artery thrombosis, cryptogenic, intracerebral hemmorage', 'Arterio-venous malformation, Cardiogenic embolism, small artery thrombosis', 'B', 'Per Brunner & Suddarth stroke classification, ischaemic stroke causes include large-artery atherosclerosis, cardiogenic/cardioembolic, small-vessel (lacunar) thrombosis and cryptogenic. Option B lists only ischaemic mechanisms, whereas the other options include haemorrhagic causes (aneurysm, intracerebral haemorrhage, AV malformation).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which one of the following is correct regarding the control of glucose levels?', 'Both insulin and glucagon are necessary to maintain high blood glucose levels.', 'Glucagon is responsible for switching off gluconeogenesis.', 'Insulin is responsible for switching on glycogenolysis.', 'Glucagon is responsible for switching on gluconeogenesis', 'D', 'Per physiology (Guyton/Brunner), glucagon raises blood glucose by switching on gluconeogenesis and glycogenolysis, while insulin lowers glucose. Insulin, not glucagon, promotes glycogen storage; the other options misassign these actions.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What type of stool can a nurse expect from a client who has a colostomy of the lower descending colon?', 'Liquid', 'Bloody', 'Black', 'Formed', 'D', 'Per Brunner & Suddarth and Kozier, a colostomy in the lower/distal descending or sigmoid colon produces formed (solid) stool because water has already been absorbed in the proximal colon. Ascending/transverse colostomies produce liquid or semi-formed stool.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Clinical features of hydatidiform mole include;', 'Positive pregnancy test of urine diluted to 1:100 after4 weeks of amenorrhea, ultrasound shows features of fetus.', 'Amenorrhea followed by vomiting, breast changes.', 'Uterus larger than dates ,chronic gonadotropin hormone in urine increase', 'Amenorrhea followed by intermittent bleeding, fetus demonstrated in x-ray.', 'C', 'Per Myles Textbook for Midwives, hydatidiform mole classically presents with a uterus larger than expected for gestational age and markedly raised hCG, plus a ''snowstorm'' ultrasound with NO fetus. Options showing a demonstrable fetus are therefore incorrect.', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The aorta divides at the level of the 4th lumbar vertebra into;', 'external &internal iliac arteries', 'superior & inferior mesenteric arteries', 'common iliac arteries', 'lumbar arteries', 'C', 'Per standard anatomy (Gray''s/Kozier), the abdominal aorta bifurcates at the level of the 4th lumbar vertebra into the right and left common iliac arteries, which subsequently divide into external and internal iliac arteries.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Corneal infections are difficult to treat due to the fact that;', 'The surface area of cornea is small', 'Causative organisms cannot be recovered', 'Corneal infections are not easily diagnosed', 'The cornea is avascular organ', 'D', 'Per Brunner & Suddarth ophthalmic nursing, the cornea is avascular, so systemic antibiotics reach it poorly and healing/defence is slower, making corneal infections difficult to treat. The other options are not the primary reason.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The most appropriate intervention for a client with a diagnosis of ineffective airway clearance is:', 'Withholding pain medications', 'Administering cough suppressants every 4-6 hours', 'Administering antibiotics as prescribed', 'Maintaining adequate hydration and providing increased humidity.', 'D', 'Per Brunner & Suddarth and Kozier, for ineffective airway clearance the priority is thinning and mobilising secretions through adequate hydration and humidification. Cough suppressants and withholding analgesia would worsen clearance.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which is a symptom of atopic dermatitis?', 'A blister on the palms of hands and soles of feet.', 'Itchy, inflamed skin.', 'Scaly patches of skin on the scalp.', 'Coin-shaped patches of irritated skin on the arms and lower legs.', 'B', 'Per dermatology/Brunner & Suddarth, atopic dermatitis (eczema) is characterised by intensely itchy, inflamed (erythematous) skin. Palmar/plantar blisters, scalp scaling and coin-shaped patches describe dyshidrotic, seborrheic and nummular dermatitis respectively.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When measuring central venous pressure (CVP) the nurse should;', 'Mark the location of the right atrium.', 'Identify the location of the left atrium.', 'Always ensure the patient lies in supine position.', 'Allow Normal saline to drip rapidly into the client for 5 min before taking CVP reading', 'A', 'Per Brunner & Suddarth critical-care nursing, the CVP zero reference (phlebostatic axis at the level of the right atrium) must be identified and marked for accurate, consistent readings. Rapid saline dripping and mandatory supine positioning are not required.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Furuncles (boils) are commonly caused by;', 'Streptococcus pyogenes', 'Clostridium tetani', 'Staphylococcus aureus', 'Bacillus aureus', 'C', 'Per standard microbiology/Brunner & Suddarth, furuncles (boils) are deep hair-follicle infections most commonly caused by Staphylococcus aureus. Streptococcus pyogenes causes impetigo/cellulitis and C. tetani causes tetanus.', 'BScN', 'Paper I', 'Infection Prevention & Control', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The immediate effects of burns on body fluids and electrolytes include ;-', 'Hypokalemia & Hyponatremia.', 'Reduced circulatory blood volume and hypernatremia.', 'Hyponatremia and Hyperkalemia.', 'Reduced urine output and hypokalemia', 'C', 'Per Brunner & Suddarth burn nursing, in the immediate emergent (fluid-shift) phase sodium is lost into the interstitium (hyponatremia) and potassium is released from damaged cells into plasma (hyperkalemia). Circulating volume and urine output also fall, but the electrolyte pattern is hyponatremia with hyperkalemia.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When suctioning a laryngeal tube;-', 'It should take about 10 seconds.', 'A clean and not asceptic technique should be used.', 'Suction is applied while inserting the catheter into the tube.', 'Suctioning should be done continuously till secretions clear. D B', 'A', 'Per Kozier and Brunner & Suddarth, tracheal/laryngeal suctioning must be brief (about 10–15 seconds) to avoid hypoxia, using STERILE technique, with suction applied only on withdrawal (not insertion) and never continuously. Thus option A is the only correct statement.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Passive range of motion exercises;', 'Are performed to prevent nosocomial infections.', 'Helps to prevent joints rigidity and contractures.', 'Is a collaborative intervention that requires a surgeon and a nurse.', 'Are repeated 5-6 times a day to enhance quick recovery. D B', 'B', 'Per Kozier & Erb''s Fundamentals, passive ROM exercises maintain joint mobility and prevent stiffness and contractures in patients unable to move independently. They do not prevent infections (A).', 'BScN', 'Paper I', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The Korotkoff sounds heard while measuring blood pressure present in the order of,', 'Tapping, Swishing, Knocking, muffling and silence', 'Swishing, Tapping, Silence, muffling and knocking', 'Knocking, Tapping, Swishing, muffling, silence', 'Silence, Tapping, Knocking, Swishing and Muffling B A', 'A', 'Per Kozier & Erb''s, the five Korotkoff phases occur in order: sharp tapping (Phase I, systolic), swishing/murmur (Phase II), knocking (Phase III), muffling (Phase IV), then silence/disappearance (Phase V, diastolic).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In sickle cell anaemia patients,', 'The structure of haemoglobin molecule is not affected.', 'Prophylactic administration of folic acid and pneumococcal vaccine is recommended', 'Administration of IV fluids & immediate blood transfusion are encouraged during sickle cell crisis situations', 'The treatment of choice includes administration of penicillins & NSAIDs C C', 'B', 'Per Kenya Basic Paediatric Protocols and Brunner & Suddarth, sickle cell patients require daily folic acid (increased erythropoiesis) and pneumococcal prophylaxis/vaccination due to functional asplenia. The Hb structure IS abnormal (A false); routine immediate transfusion in every crisis is not encouraged (C).', 'BScN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Hyperkalemia commonly occurs in the following,', 'Burns, pneumonia and congestive cardiac failure.', 'Renal failure, crush injuries and burns.', 'Digitalis toxicity, DKA and hyperthyroidism.', 'Overuse of potassium sparing diuretics, CCF and liver cirrhosis C B', 'B', 'Per Brunner & Suddarth, hyperkalemia results from impaired renal excretion (renal failure) and massive cellular potassium release in crush injuries and burns. DKA typically shows shifting but hyperthyroidism is not a classic cause (C).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The route that achieves the quickest absorption and effects of a drug is the,', 'Subcutaneous', 'Intradermal', 'Intramuscular', 'Oral D C', 'C', 'Among the given parenteral/enteral routes, intramuscular injection has the richest vascular bed, giving faster absorption than subcutaneous, intradermal, or oral. Per Brunner & Suddarth pharmacology, IM absorption is quickest of these options (IV not listed).', 'BScN', 'Paper I', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In simple mastectomy:-', 'Pectoralis major muscle and the entire breast is excised', 'Axillary lymph nodes and pectoralis major muscles are left intact', 'Underlying chest muscles and chaniin of internal mammary lymph nodes are removed', 'Entire breast and axillary lymph nodes are removed B B', 'B', 'Per Brunner & Suddarth, a simple (total) mastectomy removes the entire breast but preserves the pectoralis major muscle and axillary lymph nodes. Removing axillary nodes (D) describes modified radical mastectomy.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Reed Sternberg cell is a pathologic hallmark essential in diagnosis of:-', 'Hodgkin’s disease', 'Acute myeloid leukemia', 'Chronic lymphocytic leukemia', 'Non-hodgkin disease', 'A', 'Per Brunner & Suddarth, the Reed-Sternberg cell is the pathognomonic hallmark used to diagnose Hodgkin''s lymphoma. It is absent in non-Hodgkin lymphoma and the leukemias.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Characteristics of 1st degree burns include:-', 'Erythema and pain', 'Chilling and dry wounds', 'Healing by scaling, painless wounds', 'Black appearance, painless wounds', 'A', 'Per Brunner & Suddarth, first-degree (superficial) burns involve only the epidermis and present with erythema, pain, and no blistering (e.g., sunburn). Painless black/leathery wounds (D) indicate full-thickness burns.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In rheumatoid arthritis, inflammation of the jounts begins in the:-', 'Hip, ankle,elbow', 'Feet, wrist, toes', 'Shoulder, fingers, wrist', 'Clavicle, hands, fingers D C', 'B', 'Per Brunner & Suddarth, rheumatoid arthritis typically begins symmetrically in the small joints of the hands and feet—wrists, MCP/PIP joints, and toes—before affecting larger joints.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The main aim of escharotomy in treatment of full thickness burns is to:-', 'Improve oxygenation of the burnt tissues', 'Remove the dead tissues', 'Allow underlying viable tissues to expand', 'Reduce pain C C', 'C', 'Per Brunner & Suddarth, escharotomy incises the constricting inelastic eschar of circumferential full-thickness burns to relieve pressure, allowing underlying tissue to expand and restoring circulation/ventilation.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Risk factors of osteoporosis include:-', 'Lack of Vitamin D in diet, high estrogen levels in women', 'Too much exposure to the sun, low testosterone levels in men', 'Increase in age, late menopause', 'Excessive alcohol consumption, early menopause D', 'D', 'Per Brunner & Suddarth, osteoporosis risk factors include excessive alcohol intake and early menopause (reduced estrogen). Low—not high—estrogen and adequate vitamin D/sun are protective, making A and B incorrect.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Rhesus factor is found in the cell membrane of the:-', 'Lymphocytes', 'Granulocytes', 'Erythrocytes', 'Globulins C C', 'C', 'Per standard physiology (Brunner & Suddarth), the Rhesus (Rh) antigen is located on the cell membrane of red blood cells (erythrocytes), determining Rh-positive or Rh-negative blood type.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The hypogastric region of the abdominopelvic cavity is;', 'Inferior to the umbilical region, medial to the right iliac region', 'Lateral to the left iliac region, superior to the umbilical region', 'Medial to the right iliac region, lateral to the umbilical region', 'Superior to the umbilical region, medial to the right iliac region D A', 'A', 'Per standard anatomy, the hypogastric (suprapubic) region lies inferior to the umbilical region and medial to the right and left iliac regions in the nine-region abdominopelvic scheme.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The most appropriate nursing action when a client begins to cough and has difficulty breathing during nasogastric tube insertion is;', 'Inserting the tube quickly', 'Notifying the physician immediately', 'Removing the tube and reinserting when the respiratory distress subsides', 'Pulling the tube back a little and wait until the respiratory distress subsides D D', 'D', 'Per Kozier & Erb''s, coughing and dyspnea during NG insertion suggest the tube has entered the airway; the nurse should withdraw the tube slightly and pause until distress resolves before advancing again. Continuing to insert (A) risks tracheal placement.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The expected outcomes for a patient who has “potential for impaired gas exchange related to fluid overload” is;', 'No shortness of breath, scaphoid abdomen.', 'Chest X-ray normal, improved gas exchange.', 'Respiratory rate less than 20breaths/min, skin colour normal.', 'Heart rate less than 100 beats/min, increased urine output B D', 'C', 'Per Kozier & Erb''s, expected outcomes for impaired gas exchange are measurable normal respiratory function: respiratory rate <20/min and normal (pink) skin colour indicating adequate oxygenation. This directly reflects resolved gas-exchange impairment better than urine output (D).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('During Lumbar puncture, a needle is inserted in the space between;-', 'Fifth and sixth thoracic vertebrae.', 'Fourth and fifth thoracic vertebrae', 'Third and fourth lumbar vertebrae.', 'First and second lumbar vertebrae C C', 'C', 'Per Brunner & Suddarth, lumbar puncture is performed below the spinal cord''s end (L1-L2), typically in the L3-L4 (or L4-L5) interspace to avoid cord injury. Thoracic sites (A, B) are unsafe.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In chronic bronchitis;-', 'There is cough and sputum production for at least 3 months in 2 consecutive years.', 'There is destruction of alveoli walls due to severe infection and increased secretion.', 'There is increased ciliary function in the airway.', 'There is flow limitation and is not fully reversible', 'A', 'Per Brunner & Suddarth, chronic bronchitis is clinically defined as a productive cough present for at least 3 months in each of 2 consecutive years. Alveolar wall destruction (B) describes emphysema.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The condition in which the eyeballs are not properly aligned with each other is referred to as;', 'Astigmatism', 'Strabismus', 'Presbyopia', 'Amblyopia', 'B', 'Per standard ophthalmic nursing (Brunner & Suddarth), strabismus is misalignment of the eyes so that they do not point in the same direction. Astigmatism is refractive error, presbyopia is age-related near-vision loss, and amblyopia is ''lazy eye''.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When assessing a client with possible Cushing’s syndrome you would expect to find;', 'Hypotension', 'Thick coarse skin', 'Deposits of adipose tissue in the trunk', 'Weight loss', 'C', 'Per Brunner & Suddarth, Cushing''s syndrome (cortisol excess) causes central (truncal) obesity, moon face, and buffalo hump. It produces hypertension, thin fragile skin, and weight gain—not hypotension or weight loss.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When administering an enema;', 'The client should lie in the right lateral position.', 'The enema tube should be inserted 8 inches into the clients’ rectum.', 'The client should be advised to retain the enema for 30 minutes.', 'The nurse should position the client in left lateral position', 'D', 'Per Kozier & Erb''s, an enema is administered with the client in the left lateral (Sims'') position to follow the natural curve of the sigmoid colon. Insertion depth for adults is about 3-4 inches, not 8 (B).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The primary causes of acute otitis media are;-', 'Escherichia coli and proteus spp.', 'Streptococcus pneumoniae and Haemophilus influenzae.', 'Staphylococcus aureus and haemophilus influenzae.', 'Proteus spp. and Streptococcus pneumoniae.', 'B', 'Per Kenya Basic Paediatric Protocols and Brunner & Suddarth, the leading bacterial causes of acute otitis media are Streptococcus pneumoniae and Haemophilus influenzae (with Moraxella catarrhalis).', 'BScN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Triple therapy is indicated in treatment of;', 'Osteomyelitis.', 'Helicobacter pylori.', 'Neisseria meningitidis.', 'Oncocerca volvulus', 'B', 'Per Kenya MOH clinical guidelines and Brunner & Suddarth, triple therapy (a proton pump inhibitor plus two antibiotics such as clarithromycin and amoxicillin) is the standard regimen for eradicating Helicobacter pylori.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('during the early postoperative period after a subtotal thyroidectomy, the concern that has the priority is', 'hemorrhage', 'thyrotoxic crisis', 'airway obstruction', 'hypocalcemic tetany', 'C', 'Per Brunner & Suddarth, in the early postoperative period after thyroidectomy the priority (ABC) concern is airway obstruction from tracheal compression due to bleeding or laryngeal edema. While hemorrhage and hypocalcemia are risks, airway patency takes priority.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('immediately after esophageal surgery the priority nursing assessment concerns the client''s', 'incision', 'respiration', 'level of pain', 'nasogastric tube', 'B', 'Per Brunner & Suddarth, following esophageal surgery (thoracic approach) the priority assessment is respiratory status/airway and breathing, as the surgery affects the chest and diaphragm and impairs ventilation. Airway/breathing precede pain and NG assessment.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client presents to the clinic with a serum cholesterol of 275 mg/dL and is placed on rosuvastatin (Crestor). Which instruction should be given to the client?', 'Report muscle weakness to the physician.', 'Allow six months for the drug to take effect.', 'Take the medication with fruit juice.', 'Ask the doctor to perform a complete blood count before starting the medication.', 'A', 'Per Brunner & Suddarth pharmacology, statins such as rosuvastatin can cause myopathy/rhabdomyolysis; clients must report unexplained muscle pain or weakness promptly. Statins act within weeks, not six months (B), and are usually taken in the evening.', 'BScN', 'Paper I', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client is admitted to the hospital with hypertensive crises. Diazoxide (Hyperstat) is ordered. During administration, the nurse should:', 'Utilize an infusion pump', 'Check the blood glucose level', 'Place the client in Trendelenburg position', 'Cover the solution with foil', 'B', 'Per Brunner & Suddarth pharmacology, diazoxide is a vasodilator that also inhibits insulin release and commonly causes hyperglycemia; the nurse must monitor blood glucose during administration.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The 6-month-old client with a ventral septal defect is receiving Digitalis for regulation of his heart rate. Which finding should be reported to the doctor?', 'Blood pressure of 126/80', 'Blood glucose of 110 mg/dL', 'Heart rate of 60 bpm', 'Respiratory rate of 30 per minute', 'C', 'Per Kenya Basic Paediatric Protocols and Brunner & Suddarth, digoxin is withheld and the physician notified when the infant''s apical heart rate is below 90-100 bpm; a rate of 60 bpm signals bradycardia and possible digitalis toxicity in a 6-month-old.', 'BScN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client admitted with angina is given a prescription for nitroglycerin. The client should be instructed to:', 'Replenish his supply every 3 months', 'Take one every 15 minutes if pain occurs', 'Leave the medication in the brown bottle', 'Crush the medication and take with water', 'C', 'Per Brunner & Suddarth pharmacology, nitroglycerin is light-sensitive and must be kept in its original dark (brown) glass bottle to preserve potency. Sublingual doses are taken every 5 minutes up to three times (not 15 min), and supply should be replaced about every 6 months.', 'BScN', 'Paper I', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client is instructed regarding foods that are low in fat and cholesterol. Which diet selection is lowest in saturated fats?', 'Macaroni and cheese', 'Shrimp with rice', 'Turkey breast', 'Spaghetti', 'C', 'Per Brunner & Suddarth''s cardiac/lipid-lowering diet teaching, skinless white poultry (turkey breast) is lowest in saturated fat. Macaroni and cheese is high in dairy saturated fat, shrimp is high in cholesterol.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client is admitted with left-sided congestive heart failure. In assessing the client for edema, the nurse should check the:', 'Feet', 'Neck', 'Hands', 'Sacrum', 'D', 'Per Brunner & Suddarth''s, dependent edema collects in the sacrum in a bedbound/supine client, making it the best site to assess in hospitalized CHF patients; feet edema is checked in ambulatory clients.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is checking the client’s central venous pressure. The nurse should place the zero of the manometer at the:', 'Phlebostatic axis', 'PMI', 'Erb’s point', 'Tail of Spence', 'A', 'Per Brunner & Suddarth''s critical care nursing, the zero reference of the manometer/transducer for CVP is levelled at the phlebostatic axis (4th intercostal space, mid-anteroposterior chest) to align with the right atrium.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The physician orders lisinopril (Zestril) and furosemide (Lasix) to be administered concomitantly to the client with hypertension. The nurse should:', 'Question the order', 'Administer the medications', 'Administer separately', 'Contact the pharmacy', 'B', 'Per Kenya EML/BNF, an ACE inhibitor (lisinopril) plus a loop diuretic (furosemide) is a standard, recommended combination for hypertension/heart failure; the order is appropriate, so the nurse administers the medications.', 'BScN', 'Paper I', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The best method of evaluating the amount of peripheral edema is:', 'Weighing the client daily', 'Measuring the extremity', 'Measuring the intake and output', 'Checking for pitting', 'B', 'Per Kozier & Erb''s, measuring the circumference of the affected extremity with a tape at a marked point gives the most objective, reproducible measure of localized peripheral edema; daily weight best reflects generalized fluid, and pitting is only a graded estimate.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is caring for a client hospitalized with a facial stroke. Which diet selection would be suited to the client?', 'Roast beef sandwich, potato chips, pickle spear, iced tea', 'Split pea soup, mashed potatoes, pudding, milk', 'Tomato soup, cheese toast, Jello, coffee', 'Hamburger, baked beans, fruit cup, iced tea', 'B', 'Per Brunner & Suddarth''s stroke/dysphagia management, soft, cohesive, easily swallowed foods (soup, mashed potatoes, pudding) are safest; dry, crumbly or hard items (sandwich, chips, toast) increase aspiration risk with facial weakness.', 'BScN', 'Paper I', 'Nursing Management & Leadership', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The physician has prescribed Novolog insulin for a client with diabetes mellitus. Which statement indicates that the client knows when the peak action of the insulin occurs?', '“I will make sure I eat breakfast within 10 minutes of taking my insulin.”', '“I will need to carry candy or some form of sugar with me all the time.”', '“I will eat a snack around three o’clock each afternoon.”', '“I can save my dessert from supper for a bedtime snack.”', 'A', 'Per Kenya EML/BNF, insulin aspart (Novolog) is rapid-acting with onset ~10–20 min and peak ~1–3 h, so the client must eat within about 10–15 minutes of injecting to avoid hypoglycaemia at peak.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is teaching basic infant care to a group of first-time parents. The nurse should explain that a sponge bath is recommended for the first 2 weeks of life because:', 'New parents need time to learn how to hold the baby.', 'The umbilical cord needs time to separate.', 'Newborn skin is easily traumatized by washing.', 'The chance of chilling the baby outweighs the benefits of bathing.', 'B', 'Per Kenya Basic Paediatric Protocols/newborn care, tub bathing is delayed until the umbilical cord stump separates and heals to keep it dry and prevent infection; sponge baths are used until then.', 'BScN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The physician has prescribed Nexium (esomeprazole) for a client with erosive gastritis. The nurse should administer the medication:', '30 minutes before meals', 'With each meal', 'In a single dose at bedtime', '30 minutes after meals', 'A', 'Per Kenya EML/BNF, proton pump inhibitors such as esomeprazole are most effective taken about 30 minutes before a meal so peak drug levels coincide with meal-stimulated acid production.', 'BScN', 'Paper I', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When the nurse checks the fundus of a client on the first postpartum day, she notes that the fundus is firm, is at the level of the umbilicus, and is displaced to the right. The next action the nurse should take is to:', 'Check the client for bladder distention', 'Assess the blood pressure for hypotension', 'Determine whether an oxytocic drug was given', 'Check for the expulsion of small clots', 'A', 'Per Myles Textbook for Midwives, a firm fundus displaced to the right and above expected level indicates a full bladder; the nurse should check for bladder distention and have the client void to allow the uterus to descend and contract.', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client is seen in the clinic for treatment of migraine headaches. The drug Imitrex (sumatriptan succinate) is prescribed for the client. Which of the following in the client’s history should be reported to the doctor?', 'Diabetes', 'Prinzmetal’s angina', 'Cancer', 'Cluster headaches', 'B', 'Per Kenya EML/BNF, sumatriptan is a 5-HT1 agonist that causes vasoconstriction and is contraindicated in ischaemic/vasospastic heart disease such as Prinzmetal''s (variant) angina, so this history must be reported.', 'BScN', 'Paper I', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client with suspected meningitis is admitted to the unit. The doctor is performing an assessment to determine meningeal irritation and spinal nerve root inflammation. A positive Kernig’s sign is charted if the nurse notes:', 'Pain on flexion of the hip and knee', 'Nuchal rigidity on flexion of the neck', 'Pain when the head is turned to the left side', 'Dizziness when changing positions', 'A', 'Per Brunner & Suddarth''s neurologic assessment, a positive Kernig''s sign is pain/resistance on extending the knee when the hip and knee are flexed; nuchal rigidity on neck flexion describes Brudzinski''s sign.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client with Alzheimer’s disease is being assisted with activities of daily living when the nurse notes that the client uses her toothbrush to brush her hair. The nurse is aware that the client is exhibiting:', 'Agnosia', 'Apraxia', 'Anomia', 'Aphasia', 'B', 'Per Brunner & Suddarth''s, apraxia is the inability to carry out purposeful, learned motor tasks correctly (e.g., using a toothbrush on the hair); agnosia is failure to recognize objects, aphasia is a language deficit.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The doctor has prescribed Exelon (rivastigmine) for the client with Alzheimer’s disease. Which side effect is most often associated with this drug?', 'Urinary incontinence', 'Headaches', 'Confusion', 'Nausea', 'D', 'Per Kenya EML/BNF, rivastigmine is a cholinesterase inhibitor whose most common adverse effects are cholinergic GI effects—nausea, vomiting, anorexia; urinary incontinence is not typical (it causes cholinergic effects, not retention).', 'BScN', 'Paper I', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is assessing the deep tendon reflexes of a client with preeclampsia. Which method is used to elicit the biceps reflex?', 'The nurse places her thumb on the muscle inset in the antecubital space and taps the thumb briskly with the reflex hammer.', 'The nurse loosely suspends the client’s arm in an open hand while tapping the back of the client’s elbow.', 'The nurse instructs the client to dangle her legs as the nurse strikes the area below the patella with the blunt side of the reflex hammer.', 'The nurse instructs the client to place her arms loosely at her side as the nurse strikes the muscle insert just above the wrist.', 'A', 'Per Kozier & Erb''s/physical assessment technique, the biceps reflex is elicited by placing the thumb over the biceps tendon in the antecubital fossa and striking the thumb with the reflex hammer.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which observation in the newborn of a diabetic mother would require immediate nursing intervention?', 'Crying', 'Wakefulness', 'Jitteriness', 'Yawning', 'C', 'Per Kenya Basic Paediatric Protocols, jitteriness/tremors in the infant of a diabetic mother signals hypoglycaemia, which requires immediate assessment and treatment; crying, wakefulness and yawning are normal.', 'BScN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse caring for a client receiving intravenous magnesium sulfate must closely observe for side effects associated with drug therapy. An expected side effect of magnesium sulfate is:', 'Decreased urinary output', 'Hypersomnolence', 'Absence of knee jerk reflex', 'Decreased respiratory rate', 'B', 'Per Myles/Kenya maternal guidelines, mild sedation/drowsiness (hypersomnolence) and feeling warm are expected effects of therapeutic magnesium sulfate; loss of knee-jerk reflex, respiratory depression and oliguria are signs of toxicity, not expected effects.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client has elected to have epidural anesthesia to relieve labor pain. If the client experiences hypotension, the nurse would:', 'Place her in Trendelenburg position', 'Decrease the rate of IV infusion', 'Administer oxygen per nasal cannula', 'Increase the rate of the IV infusion', 'D', 'Per Myles Textbook for Midwives, epidural-induced hypotension is treated by increasing the IV fluid rate (fluid bolus), left-lateral positioning and oxygen; Trendelenburg is avoided as it can worsen the cephalad spread of the block.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The home health nurse is visiting an 18-year-old with osteogenesis imperfecta. Which information obtained on the visit would cause the most concern? The client:', 'Likes to play football', 'Drinks several carbonated drinks per day', 'Has two sisters with sickle cell tract', 'Is taking acetaminophen to control pain', 'A', 'Osteogenesis imperfecta causes brittle bones prone to fracture; contact sports such as football pose the greatest injury risk and cause most concern (Brunner & Suddarth''s, musculoskeletal disorders).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse working the organ transplant unit is caring for a client with a white blood cell count of 450. During evening visitation, a visitor brings a basket of fruit. What action should the nurse take?', 'Allow the client to keep the fruit', 'Place the fruit next to the bed for easy access by the client', 'Offer to wash the fruit for the client', 'Tell the family members to take the fruit home', 'D', 'A WBC of 450 indicates severe neutropenia; fresh fruit harbours bacteria/fungi and is contraindicated in neutropenic precautions, so it should be removed (Brunner & Suddarth''s, neutropenic care / IPC principles).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client admitted 2 days earlier that a lung resection accidentally pulls out the chest tube. Which action by the nurse indicates understanding of the management of chest tubes?', 'Order a chest x-ray', 'Reinsert the tube', 'Cover the insertion site with a Vaseline gauze', 'Call the doctor', 'C', 'An accidentally dislodged chest tube requires immediate application of an occlusive (Vaseline) dressing to prevent air entry and tension pneumothorax, then notify the physician (Brunner & Suddarth''s, chest drainage management).', 'BScN', 'Paper I', 'Nursing Management & Leadership', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which selection would provide the most calcium for the client who is 4 months pregnant?', 'A granola bar', 'A bran muffin', 'A cup of yogurt', 'A glass of fruit juice', 'C', 'Yogurt is a dairy product and the richest calcium source among the options, important for the increased calcium demand in pregnancy (Kozier & Erb''s Fundamentals; Kenya maternal nutrition guidelines).', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is evaluating nutritional outcomes for a with anorexia nervosa. Which data best indicates that the plan of care is effective?', 'The client selects a balanced diet from the menu.', 'The client’s hemoglobin and hematocrit improve.', 'The client’s tissue turgor improves.', 'The client gains weight.', 'D', 'In anorexia nervosa the primary nutritional goal is restoration of body weight; weight gain is the best objective indicator that the nutritional plan is effective (Brunner & Suddarth''s / mental health nursing).', 'BScN', 'Paper I', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following foods would the nurse encourage the client in sickle cell crisis to eat?', 'Peaches', 'Cottage cheese', 'Popsicle', 'Lima beans', 'C', 'Fluid intake is essential in sickle cell crisis; a popsicle provides additional fluids to support hydration and reduce sickling, making it the best choice to encourage (Brunner & Suddarth''s, sickle cell crisis hydration).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is instructing a client with iron-deficiency anemia. Which of the following meal plans would the nurse expect the client to select?', 'Roast beef, gelatin salad, green beans, and peach pie', 'Chicken salad sandwich, coleslaw, French fries, ice cream', 'Egg salad on wheat bread, carrot sticks, lettuce salad, raisin pie', 'Pork chop, creamed potatoes, corn, and coconut cake', 'C', 'Iron-rich choices include eggs, whole wheat, leafy green vegetables and raisins (dried fruit); this meal provides the most dietary iron for iron-deficiency anemia (Kenya nutrition guidelines; Brunner & Suddarth''s).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Clients with sickle cell anemia are taught to avoid activities that cause hypoxia and hypoxemia. Which of the following activities would the nurse recommend?', 'A family vacation in the Rocky Mountains', 'Chaperoning the local boys club on a snow-skiing trip', 'Traveling by airplane for business trips', 'A bus trip to the Museum of Natural History', 'D', 'Activities causing hypoxia (high altitude in the Rocky Mountains, cold snow-skiing, unpressurised/altitude air travel) must be avoided; a low-altitude bus trip is safe (Brunner & Suddarth''s, sickle cell patient education).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is conducting an admission assessment of a client with vitamin B12 deficiency. Which of the following would the nurse include in the physical assessment?', 'Palpate the spleen', 'Take the blood pressure', 'Examine the feet for petechiae', 'Examine the tongue', 'D', 'Vitamin B12 deficiency characteristically causes glossitis (a smooth, beefy-red, sore tongue); examining the tongue is the relevant physical assessment finding (Brunner & Suddarth''s, megaloblastic/pernicious anemia).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is conducting a physical assessment on a client with anemia. Which of the following clinical manifestations would be most indicative of the anemia?', 'BP 146/88', 'Respirations 28 shallow', 'Weight gain of 10 pounds in 6 months', 'Pink complexion', 'B', 'Anemia reduces oxygen-carrying capacity, causing compensatory tachypnea and dyspnea; increased shallow respirations (28) is the most indicative manifestation, while pink complexion would be inconsistent with anemia (Brunner & Suddarth''s, anemia assessment).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following would be the priority nursing diagnosis for the adult client with acute leukemia?', 'Oral mucous membrane, altered related to chemotherapy', 'Risk for injury related to thrombocytopenia', 'Fatigue related to the disease process', 'Interrupted family processes related to life-threatening illness of a family member', 'B', 'In acute leukemia, thrombocytopenia predisposes to life-threatening hemorrhage; risk for injury/bleeding is the priority (physiologic safety) nursing diagnosis (Brunner & Suddarth''s, leukemia nursing care).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The home health nurse is visiting a client with autoimmune thrombocytopenic purpura (ATP). The client''s platelet count currently is 80, It will be most important to teach the client and family about:', 'Bleeding precautions', 'Prevention of falls', 'Oxygen therapy', 'Conservation of energy', 'A', 'With a low platelet count in ATP (ITP), the priority teaching is bleeding precautions to prevent hemorrhage (Brunner & Suddarth''s, thrombocytopenia/ITP care).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client with a history of diabetes insipidus is admitted with polyuria, polydipsia, and mental confusion. The priority intervention for this client is:', 'Measure the urinary output', 'Check the vital signs', 'Encourage increased fluid intake', 'Weigh the client', 'B', 'Diabetes insipidus with polyuria and confusion risks severe dehydration and hypovolemic shock; assessing vital signs is the priority to detect fluid volume/hemodynamic instability (Brunner & Suddarth''s, diabetes insipidus).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which statement made by the nurse describes the inheritance pattern of autosomal recessive disorders?', 'An affected newborn has unaffected parents.', 'An affected newborn has one affected parent.', 'Affected parents have a one in four chance of passing on the defective gene.', 'Affected parents have unaffected children who are carriers.', 'A', 'Per genetics (Brunner & Suddarth), in autosomal recessive inheritance both unaffected parents are typically heterozygous carriers, so an affected child is born to phenotypically unaffected parents. The 1-in-4 risk refers to two carrier (not affected) parents, making that option imprecise.', 'BScN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is responsible for performing a neonatal assessment on a full-term infant. At 1 minute, the nurse would expect to find:', 'An apical pulse of 100', 'An absence of tonus', 'Cyanosis of the feet and hands', 'Jaundice of the skin and sclera', 'C', 'Per Basic Paediatric Protocols/newborn assessment, acrocyanosis (bluish hands and feet) is a normal finding at 1 minute due to peripheral circulation. Apical pulse should be 120-160, and jaundice at 1 minute is abnormal.', 'BScN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client with varicella will most likely have an order for which category of medication?', 'Antibiotics', 'Antipyretics', 'Antivirals', 'Anticoagulants', 'C', 'Per Kenya IMNCI/clinical guidelines, varicella (chickenpox) is a viral infection; antivirals such as acyclovir are indicated in severe or high-risk cases. Antibiotics treat only secondary bacterial infection.', 'BScN', 'Paper I', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following instructions should be included in the teaching for the client with rheumatoid arthritis?', 'Avoid exercise because it fatigues the joints.', 'Take prescribed anti-inflammatory medications with meals.', 'Alternate hot and cold packs to affected joints.', 'Avoid weight-bearing activity.', 'B', 'Per Brunner & Suddarth, NSAIDs/anti-inflammatory drugs for rheumatoid arthritis should be taken with meals to reduce gastric irritation. Exercise (ROM) is encouraged, not avoided, so the other options are incorrect.', 'BScN', 'Paper I', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('During the assessment of a laboring client, the nurse notes that the FHT are loudest in the upper-right quadrant. The infant is most likely in which position?', 'Right breech presentation', 'Right occipital anterior presentation', 'Left sacral anterior presentation', 'Left occipital transverse presentation', 'A', 'Per Myles, fetal heart tones heard loudest in the upper quadrant indicate the fetal back/heart is high in the uterus, consistent with a breech presentation; on the right side this is a right breech. Vertex presentations transmit FHTs in the lower quadrants.', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The primary physiological alteration in the development of asthma is:', 'Bronchiolar inflammation and dyspnea', 'Hypersecretion of abnormally viscous mucus', 'Infectious processes causing mucosal edema', 'Spasm of bronchial smooth muscle', 'D', 'Per Brunner & Suddarth respiratory pathophysiology, the primary reversible physiological alteration in asthma is bronchospasm (spasm of bronchial smooth muscle), accompanied by inflammation and mucus. Bronchospasm is the hallmark driving airway narrowing.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('To maintain Bryant''s traction, the nurse must make certain that the child''s:', 'Hips are resting on the bed, with the legs suspended at a right angle to the bed', 'Hips are slightly elevated above the bed and the legs are suspended at a right angle to the bed', 'Hips are elevated above the level of the body on a pillow and the legs are suspended parallel to the bed', 'Hips and legs are flat on the bed, with the traction positioned at the foot of the bed', 'B', 'Per paediatric orthopaedic nursing (Brunner/paeds texts), Bryant''s traction requires the hips slightly elevated off the bed so the child''s weight provides countertraction, with legs suspended vertically at a 90-degree angle to the bed. Buttocks must clear the mattress.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client has an order for a trough to be drawn on the client receiving Vancomycin. The nurse is aware that the nurse should contact the lab for them to collect the blood:', '15 minutes after the infusion', '30 minutes before the infusion', '1 hour after the infusion', '2 hours after the infusion', 'B', 'Per pharmacology/therapeutic drug monitoring (Brunner & Suddarth), a vancomycin trough is drawn immediately before (about 30 minutes prior to) the next dose to measure the lowest serum concentration. Levels drawn after infusion reflect peak, not trough.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client using a diaphragm should be instructed to:', 'Refrain from keeping the diaphragm in longer than 4 hours', 'Keep the diaphragm in a cool location', 'Have the diaphragm resized if she gains 5 pounds', 'Have the diaphragm resized if she has any surgery', 'D', 'Per Kenya Family Planning guidelines, a diaphragm must be refitted after events that change vaginal/pelvic dimensions such as pelvic surgery, childbirth, or a weight change of about 10 or more pounds. A 5-pound gain generally does not require refitting, and it must stay in at least 6 hours after intercourse.', 'BScN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is providing postpartum teaching for a mother planning to breastfeed her infant. Which of the client''s statements indicates the need for additional teaching?', '"I''m wearing a support bra."', '"I''m expressing milk from my breast."', '"I''m drinking four glasses of fluid during a 24-hour period."', '"While I''m in the shower, I''ll allow the water to run over my breasts."', 'C', 'Per Myles/postpartum lactation teaching, a breastfeeding mother needs increased fluids (about 8-10 glasses/day); only four glasses in 24 hours is inadequate and indicates a need for more teaching. Support bra, expressing milk, and letting water run over breasts are correct.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following tests should be performed before beginning a prescription of Accutane?', 'Check the calcium level', 'Perform a pregnancy test', 'Monitor apical pulse', 'Obtain a creatinine level', 'B', 'Per pharmacology (Kenya EML/BNF), isotretinoin (Accutane) is highly teratogenic, so a negative pregnancy test is mandatory before starting therapy in women of childbearing potential. Calcium and creatinine are not the primary pre-treatment screens.', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse should visit which of the following clients first?', 'The client with diabetes with a blood glucose of 95mg/dL', 'The client with hypertension being maintained on Lisinopril', 'The client with chest pain and a history of angina', 'The client with Raynaud''s disease', 'C', 'Per triage/prioritization (ABC, Brunner & Suddarth), the client with active chest pain and angina history is at risk of an evolving myocardial infarction and must be seen first. The others are stable with controlled findings.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Cataracts result in opacity of the crystalline lens. Which of the following best explains the functions of the lens?', 'The lens controls stimulation of the retina.', 'The lens orchestrates eye movement.', 'The lens focuses light rays on the retina.', 'The lens magnifies small objects.', 'C', 'The crystalline lens refracts (focuses) incoming light rays onto the retina; cataract opacity blurs this focus (Anatomy & Physiology; Brunner & Suddarth''s). Pupil/iris controls light intake and extraocular muscles control movement, not the lens.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client with color blindness will most likely have problems distinguishing which of the following colors?', 'Orange', 'Violet', 'Red', 'White', 'C', 'The most common inherited color blindness is red-green deficiency, so red is the color most likely confused (Anatomy & Physiology of vision). Violet and orange are less commonly affected and white is not a hue.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client with a pacemaker should be taught to:', 'Report ankle edema', 'Check his blood pressure daily', 'Refrain from using a microwave oven', 'Monitor his pulse rate', 'D', 'Pacemaker clients are taught to check their pulse daily and report a rate below the set threshold, which signals pacemaker malfunction (Brunner & Suddarth''s). Modern microwaves are safe, so refraining from them is unnecessary.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client with enuresis is being taught regarding bladder retraining. The nurse should advise the client to refrain from drinking after:', '1900', '1200', '1000', '0700', 'A', 'In bladder retraining for enuresis, fluids are restricted in the evening (after about 1900 hrs / 7 pm) to reduce night-time bladder filling, while daytime intake stays adequate (Kozier & Erb''s Fundamentals of Nursing). Stopping fluids at midday would cause dehydration.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following diet instructions should be given to the client with recurring urinary tract infections?', 'Increase intake of meats.', 'Avoid citrus fruits.', 'Perform pericare with hydrogen peroxide.', 'Drink a glass of cranberry juice every day.', 'D', 'Cranberry juice acidifies urine and inhibits bacterial adherence to the bladder wall, helping prevent recurrent UTIs (Brunner & Suddarth''s). Citrus need not be avoided, and hydrogen peroxide pericare is inappropriate.', 'BScN', 'Paper I', 'Infection Prevention & Control', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The physician has prescribed NPH insulin for a client with diabetes mellitus. Which statement indicates that the client knows when the peak action of the insulin occurs?', '"I will make sure I eat breakfast within 2 hours of taking my insulin."', '"I will need to carry candy or some form of sugar with me all the time."', '"I will eat a snack around three o''clock each afternoon."', '"I can save my dessert from supper for a bedtime snack."', 'C', 'NPH (intermediate-acting) insulin peaks roughly 6-12 hours after a morning dose, so a mid-afternoon snack covers the peak and prevents hypoglycemia (Brunner & Suddarth''s; Kenya EML). Eating breakfast within 2 hours describes rapid/short-acting insulin.', 'BScN', 'Paper I', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The physician has prescribed ranitidine (Zantac) for a client with erosive gastritis. The nurse should administer the medication:', '30 minutes before meals', 'With each meal', 'In a single dose at bedtime', '60 minutes after meals', 'A', 'H2 antagonists such as ranitidine are best given before meals so the drug blocks the acid secretion stimulated by eating (Brunner & Suddarth''s; Kenya EML). Single bedtime dosing does not cover mealtime acid surges as well.', 'BScN', 'Paper I', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('While assessing the postpartal client, the nurse notes that the fundus is displaced to the right. Based on this finding, the nurse should:', 'Ask the client to void', 'Assess the blood pressure for hypotension', 'Administer oxytocin', 'Check for vaginal bleeding', 'A', 'A fundus displaced to the right (and often above the umbilicus) indicates a full bladder; having the client void allows the uterus to recenter and contract, preventing atony (Myles Textbook for Midwives; Kenya MNH guidelines). Oxytocin is not first-line for a bladder-related displacement.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The physician has ordered an MRI for a client with an orthopedic ailment. An MRI should not be done if the client has:', 'The need for oxygen therapy', 'A history of claustrophobia', 'A permanent pacemaker', 'Sensory deafness', 'C', 'MRI is contraindicated with most permanent pacemakers because the strong magnetic field can disrupt or damage the device (Brunner & Suddarth''s). Claustrophobia and deafness can be accommodated and are not absolute contraindications.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is preparing to discharge a client with a long history of polio. The nurse should tell the client that:', 'Taking a hot bath will decrease stiffness and spasticity.', 'A schedule of strenuous exercise will improve muscle strength.', 'Rest periods should be scheduled throughout the day.', 'Visual disturbances can be corrected with prescription glasses.', 'C', 'Clients with polio/post-polio syndrome fatigue easily, so scheduled rest periods conserve energy and protect weakened muscles (Brunner & Suddarth''s). Strenuous exercise can worsen muscle weakness and is contraindicated.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The physician has ordered a thyroid scan to confirm the diagnosis. Before the procedure, the nurse should:', 'Assess the client for allergies', 'Bolus the client with IV fluid', 'Tell the client he will be asleep', 'Insert a urinary catheter', 'A', 'A thyroid scan uses radioactive iodine tracer, so the nurse must assess for iodine/shellfish allergy before the procedure (Brunner & Suddarth''s). Sedation, IV bolus, and catheterization are not routinely required.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The physician has ordered an injection of RhoGam for a client with blood type A negative. The nurse understands that RhoGam is given to:', 'Provide immunity against Rh isoenzymes', 'Prevent the formation of Rh antibodies', 'Eliminate circulating Rh antibodies', 'Convert the Rh factor from negative to positive', 'B', 'RhoGam (anti-D immunoglobulin) provides passive immunity that suppresses the Rh-negative mother''s active production of anti-Rh antibodies, protecting future pregnancies (Myles Textbook for Midwives; Kenya MNH guidelines). It does not convert the Rh factor or eliminate existing antibodies.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is caring for a client admitted to the emergency room after a fall. X-rays reveal that the client has several fractured bones in the foot. Which treatment should the nurse anticipate for the fractured foot?', 'Application of a short inclusive spica cast', 'Stabilization with a plaster-of-Paris cast', 'Surgery with Kirschner wire implantation', 'A gauze dressing only', 'B', 'Simple closed fractures of the foot are typically immobilized with a plaster-of-Paris cast to allow bone healing (Brunner & Suddarth''s; Kenya orthopaedic practice). A spica cast is for hip/thigh, and Kirschner wires are reserved for unstable/displaced fractures.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Following a heart transplant, a client is started on medication to prevent organ rejection. Which category of medication prevents the formation of antibodies against the new organ?', 'Antivirals', 'Antibiotics', 'Immunosuppressants', 'Analgesics', 'C', 'Immunosuppressant drugs (e.g., cyclosporine, tacrolimus) suppress the immune response and prevent antibody-mediated rejection of the transplanted heart (Brunner & Suddarth''s; Kenya EML). Antivirals and antibiotics treat infection, not rejection.', 'BScN', 'Paper I', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is preparing a client for cataract surgery. The nurse is aware that the procedure will use:', 'Mydriatics to facilitate removal', 'Miotic medications such as Timoptic', 'A laser to smooth and reshape the lens', 'Silicone oil injections into the eyeball', 'A', 'Before cataract extraction, mydriatic (dilating) drops are instilled to widen the pupil and allow access to and removal of the lens (Brunner & Suddarth''s; Kenya EML ophthalmic). Miotics constrict the pupil and would hinder surgery.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is performing an initial assessment of a newborn Caucasian male delivered at 32 weeks gestation. The nurse can expect to find the presence of:', 'Mongolian spots', 'Scrotal rugae', 'Head lag', 'Vernix caseosa', 'C', 'A preterm infant at 32 weeks has immature neck muscle tone, so marked head lag is an expected finding (Myles Textbook for Midwives; Basic Paediatric Protocols). Scrotal rugae and abundant vernix develop later, closer to term.', 'BScN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is caring for a client admitted with multiple trauma. Fractures include the pelvis, femur, and ulna. Which finding should be reported to the physician immediately?', 'Hematuria', 'Muscle spasms', 'Dizziness', 'Nausea', 'A', 'With a pelvic fracture, hematuria signals possible bladder or urethral injury and must be reported immediately (Brunner & Suddarth''s; Kenya trauma care). Muscle spasms and nausea are expected and less urgent findings.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The primary reason for rapid continuous rewarming of the area affected by frostbite is to:', 'Lessen the amount of cellular damage', 'Prevent the formation of blisters', 'Promote movement', 'Prevent pain and discomfort', 'A', 'Per Brunner & Suddarth''s Medical-Surgical Nursing, rapid continuous rewarming of frostbite in a warm water bath limits the extent of tissue and cellular destruction; the other options are secondary.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('During a home visit, a client with AIDS tells the nurse that he has been exposed to measles. Which action by the nurse is most appropriate?', 'Administer an antibiotic', 'Contact the physician for an order for immune globulin', 'Administer an antiviral', 'Tell the client that he should remain in isolation for 2 weeks', 'B', 'Per Kenya HIV/AIDS and immunocompromised care guidelines and Brunner & Suddarth''s, an immunosuppressed AIDS client exposed to measles should receive immune (immunoglobulin) prophylaxis; antibiotics and antivirals are not indicated for measles post-exposure protection.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The physician has ordered a minimal-bacteria diet for a client with neutropenia. The client should be taught to avoid eating:', 'Fruits', 'Salt', 'Pepper', 'Ketchup', 'A', 'Per oncology nursing guidance in Brunner & Suddarth''s, a neutropenic (low-bacteria) diet avoids raw/fresh fruits and vegetables which carry surface bacteria; seasonings like salt, pepper and ketchup are not the primary hazard.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is assisting the physician with removal of a central venous catheter. To facilitate removal, the nurse should instruct the client to:', 'Perform the Valsalva maneuver as the catheter is advanced', 'Turn his head to the left side and hyperextend the neck', 'Take slow, deep breaths as the catheter is removed', 'Turn his head to the right while maintaining a sniffing position', 'A', 'Per Brunner & Suddarth''s, during central venous catheter removal the client performs the Valsalva maneuver (bear down/hold breath) to raise intrathoracic pressure and prevent air embolism as the catheter is withdrawn; the stem''s wording ''advanced'' reflects the removal procedure and the Valsalva timing is the key safety action.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is providing discharge teaching for the client with leukemia. The client should be told to avoid:', 'Using oil- or cream-based soaps', 'Flossing between the teeth', 'The intake of salt', 'Using an electric razor', 'B', 'Per Brunner & Suddarth''s, leukemia clients are thrombocytopenic and neutropenic; flossing can cause gum bleeding and introduce infection, so it should be avoided. An electric razor is actually recommended to prevent cuts.', 'BScN', 'Paper I', 'Infection Prevention & Control', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is changing the ties of the client with a tracheotomy. The safest method of changing the tracheostomy ties is to:', 'Apply the new tie before removing the old one.', 'Have a helper present.', 'Hold the tracheotomy with the nondominant hand while removing the old tie.', 'Ask the doctor to suture the tracheostomy in place.', 'A', 'Per Kozier & Erb''s Fundamentals, the safest method when changing tracheostomy ties is to secure the new tie before removing the old one to prevent accidental decannulation.', 'BScN', 'Paper I', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is monitoring a client following a lung resection. The hourly output from the chest tube was 300mL. The nurse should give priority to:', 'Turning the client to the left side', 'Milking the tube to ensure patency', 'Slowing the intravenous infusion', 'Notifying the physician', 'D', 'Per Brunner & Suddarth''s, chest tube drainage exceeding 100 mL/hr (here 300 mL) suggests active hemorrhage and is a priority to report to the physician immediately; milking the tube is contraindicated.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The infant is admitted to the unit with tetralogy of fallot. The nurse would anticipate an order for which medication?', 'Digoxin', 'Epinephrine', 'Aminophylline', 'Atropine', 'A', 'Per Basic Paediatric Protocols (Kenya) and standard paediatric cardiology, digoxin is used to improve myocardial contractility and manage heart failure in congenital heart defects such as tetralogy of Fallot; epinephrine, aminophylline and atropine are not standard maintenance therapy here.', 'BScN', 'Paper I', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The toddler is admitted with a cardiac anomaly. The nurse is aware that the infant with a ventricular septal defect will:', 'Tire easily', 'Grow normally', 'Need more calories', 'Be more susceptible to viral infections', 'A', 'Per paediatric nursing references, a ventricular septal defect causes left-to-right shunting and increased pulmonary blood flow, leading to fatigue (especially with feeding), poor weight gain and increased infection risk; the classic expected finding among the options is that the child tires easily.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is monitoring a client with a history of stillborn infants. The nurse is aware that a nonstress test can be ordered for this client to:', 'Determine lung maturity', 'Measure the fetal activity', 'Show the effect of contractions on fetal heart rate', 'Measure the well-being of the fetus', 'D', 'Per Myles Textbook for Midwives, a nonstress test assesses fetal well-being through fetal heart rate accelerations with movement; while it detects fetal activity, its ordered purpose in a high-risk client is to evaluate overall fetal well-being. The contraction stress test, not NST, shows the effect of contractions.', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse has a preop order to administer Valium (diazepam) 10mg and Phenergan (promethazine) 25mg. The correct method of administering these medications is to:', 'Administer the medications together in one syringe', 'Administer the medication separately', 'Administer the Valium, wait 5 minutes, and then inject the Phenergan', 'Question the order because they cannot be given at the same time', 'A', 'Per Kenya EML/BNF and injectable drug compatibility charts, diazepam (Valium) and promethazine (Phenergan) are compatible and are commonly combined in one syringe for preoperative IM sedation.', 'BScN', 'Paper I', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client has recently returned from having a thyroidectomy. The nurse should keep which of the following at the bedside?', 'A tracheotomy set', 'A padded tongue blade', 'An endotracheal tube', 'An airway', 'A', 'Per Brunner & Suddarth''s, after thyroidectomy a tracheotomy set is kept at the bedside because laryngeal nerve damage, tracheal compression or tetany-related laryngospasm can cause airway obstruction requiring emergency tracheotomy.
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The physical manifestations of fetal alcohol syndrome include:', 'cleft lip and palette.', 'hepatomegaly, hypotonia, and microphthalmia.', 'hyperbilirubinemia, jaundice, and failure to thrive.', 'microcephaly, short philtrum, and prenatal growth retardation.', 'D', 'Fetal alcohol syndrome presents with microcephaly, characteristic facies (smooth/short philtrum, thin upper lip, short palpebral fissures), and pre- and postnatal growth retardation. The other options list features not specific to FAS. Per paediatric/midwifery references (Myles Textbook for Midwives).', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which blood gas analyses are most indicative of respiratory acidosis?', 'pH = 7.22, PC02 = 55 mm Hg, HC03 = 30 mEq/L.', 'pH = 7.28, PC02 = 45 mm Hg, HC03 = 15 mEq/L.', 'pH = 7.34, PC02 = 35 mm Hg, HC03 = 25 mEq/L.', 'pH = 7.40, PC02 = 25 mm Hg, HC03 = 30 mEq/L.', 'A', 'Respiratory acidosis = low pH with elevated PCO2. Option A shows pH 7.22 (acidotic) with PCO2 55 (elevated, the primary cause) and compensatory HCO3 rise. The other options are metabolic acidosis (B), normal (C), or respiratory alkalosis (D). Per Brunner & Suddarth''s Medical-Surgical Nursing.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The major pharmacologic action of Salbutamol is:', 'decreasing airway reactivity.', 'decreasing inflammation and airway obstruction.', 'improving the action of cilia to sweep trapped mucous upward.', 'relaxing constricted bronchial smooth muscle.', 'D', 'Salbutamol is a beta-2 agonist bronchodilator; its major action is relaxation of bronchial smooth muscle. Anti-inflammatory action describes corticosteroids, not salbutamol. Per Kenya EML/BNF pharmacology.', 'BScN', 'Paper I', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The age at which the infant can reach an object, grasp it and bring it to mouth and seems excited when see the food is', '4 mo', '5 mo', '6 mo', '7 mo (B) Secondary (C) Intermediate (D) Tertiary', 'C', 'Per Kenya Basic Paediatric Protocols/IMNCI developmental milestones, at 6 months the infant can reach for and grasp an object, bring it to the mouth (palmar grasp) and shows excitement at the sight of food, coinciding with readiness for complementary feeding. (Option D text carries an unrelated fragment.)
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Effective supplementation of folate for prevention of neural tube defect is', 'started at least 1 mo before conception, and continued through the first 2-3 mo of pregnancy', 'started at least 3 mo before conception, to be stopped after positive pregnancy', 'started after positive pregnancy test and continued through the first 2-3 mo of pregnancy.', 'started at least 1 mo before conception, to be stopped after positive pregnancy test.', 'A', 'Folic acid for neural tube defect prevention should begin at least one month before conception and continue through the first trimester (first 2-3 months); per Kenya Maternal/Newborn and MOH antenatal guidelines. Neural tube closure occurs by 28 days, so periconceptional and early-pregnancy supplementation is required.', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Expansion of the intravascular volume and increased intravascular pressure are the main causes of edema in', 'lymphatic obstruction', 'heart failure', 'protein-losing enteropathy', 'nephrotic syndrome', 'B', 'In heart failure, increased intravascular (venous/hydrostatic) volume and pressure drive fluid into interstitium causing oedema; per Brunner & Suddarth''s Medical-Surgical Nursing. Lymphatic obstruction, protein-losing enteropathy and nephrotic syndrome cause oedema mainly via reduced oncotic pressure or lymphatic blockage, not raised intravascular volume/pressure.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Increased production of CO2 occurs in all the following EXCEPT', 'fever', 'emesis', 'excess caloric intake', 'high levels of physical activity', 'B', 'Fever, excess caloric intake and high physical activity all raise metabolic rate and CO2 production; per Brunner & Suddarth acid-base physiology. Emesis (vomiting) does not increase CO2 production (it causes loss of gastric acid), so it is the EXCEPT answer.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Malignant hyperthermia is an acute hypermetabolic syndrome that is triggered by inhalational anesthetic agents and succinylcholine. Of the following, the MOST recognized clue to the risk of malignant hyperthermia is', 'rigid clenching of the masseter muscles', 'hypercarbia', 'ventricular fibrillation', 'rapid onset of fever', 'A', 'Masseter muscle rigidity (trismus) after succinylcholine is the earliest and most recognized clinical clue to malignant hyperthermia; per Brunner & Suddarth peri-operative/anesthesia nursing. Hypercarbia, arrhythmias and fever occur but appear later and are less specific as the initiating clue.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Cyanosis (unresponsive to oxygen) is a sign of poisoning with', 'atropine', 'amiodarone', 'carbon monoxide', 'vancomycin', 'C', 'Cyanosis unresponsive to oxygen indicates that haemoglobin cannot carry/release oxygen, characteristic of carbon monoxide poisoning (and methaemoglobinaemia); per Brunner & Suddarth/toxicology. Atropine, amiodarone and vancomycin do not classically cause oxygen-refractory cyanosis.', 'BScN', 'Paper I', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The MOST common reason for a sick child visit is', 'vomiting', 'altered mental status', 'respiratory distress', 'fever', 'D', 'Fever is the single most common presenting complaint for sick child visits; per Kenya IMNCI and Basic Paediatric Protocols. Vomiting, altered mental status and respiratory distress are common but less frequent than fever as the chief complaint.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Major cause of neonatal mortality in full-term newborn is', 'respiratory distress syndrome', 'necrotizing enterocolitis', 'bronchopulmonary dysplasia (BPD)', 'congenital anomalies', 'D', 'In full-term newborns, congenital anomalies are the leading cause of neonatal mortality; per Kenya newborn care/Basic Paediatric Protocols. RDS, NEC and BPD predominate in preterm rather than term infants.', 'BScN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Freedom of choice in one of the policies of the Family Planning Program. Which of the following illustrates this principle?', 'Information dissemination about the need for family planning', 'Support of research and development in family planning methods', '. Adequate information for couples regarding the different methods', 'Encouragement of couples to take family planning as a joint responsibility', 'C', 'Freedom of choice is exercised when couples are given adequate information on all available methods so they can choose freely; per Kenya National Family Planning Guidelines. General information dissemination (A), research support (B) and encouraging joint responsibility (D) do not directly embody informed free choice among methods.', 'BScN', 'Paper I', 'Research & Evidence-Based Practice', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Scotch tape swab is done to check for which intestinal parasite?', 'Ascaris', '. Pinworm', '. Hookworm', 'Schistosoma', 'B', 'The scotch (cellophane) tape test collects perianal eggs to diagnose pinworm (Enterobius vermicularis); per standard parasitology/Kenya lab practice. Ascaris, hookworm and schistosoma are diagnosed by stool or urine examination, not the tape swab.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The most frequent causes of death among clients with AIDS are opportunistic diseases. Which of the following opportunistic infections is characterized by tonsilllopharyngitis?', 'Respiratory candidiasis', '. Infectious mononucleosis', 'Cytomegalovirus disease', 'Pneumocystis carinii pneumonia', 'B', 'Infectious mononucleosis (EBV) classically presents with tonsillopharyngitis (exudative pharyngitis), fever and lymphadenopathy; per Brunner & Suddarth, EBV is a common opportunistic reactivation in immunosuppressed/AIDS patients. Candidiasis causes oral thrush/plaques, CMV causes retinitis/colitis and PCP causes pneumonia — none typified by tonsillopharyngitis.', 'BScN', 'Paper I', 'Infection Prevention & Control', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Management of a child with measles includes the administration of which of the following?', 'Gentian violet on mouth lesions', 'Antibiotic to prevent pneumonia', 'Tetracycline eye ointment for corneal opacity', 'Retinol capsule regardless of when the last dose was given', 'D', 'Per Kenya IMNCI/Basic Paediatric Protocols, every child with measles must receive Vitamin A (retinol) immediately regardless of previous dosing, to prevent complications including corneal damage and reduce mortality. Tetracycline eye ointment is for eye discharge, not corneal opacity, and antibiotics are given only for pneumonia if present.', 'BScN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The pathognomonic sign of measles is Koplik’s spot. You may see Koplik’s spot by inspecting the:', 'Nasal Mucosa', 'Buccal mucosa', 'Skin on the abdomen', 'Skin on the antecubital surface', 'B', 'Per standard paediatric/communicable disease texts, Koplik''s spots (pathognomonic of measles) are small white spots seen on the buccal mucosa opposite the molars, appearing before the rash. They are not found on the nasal mucosa or skin.', 'BScN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In a mother’s class, you discuss proper breastfeeding technique. Which of these is a sign that the baby has “lactated on” the breast property?', 'The baby takes shallow, rapid sucks', '. The mother does not feel nipple pain', 'The baby’s mouth is only partly open', 'Only the mother’s nipple is inside the baby’s mouth', 'B', 'Per Kenya MOH/WHO breastfeeding guidance, good attachment (latch) signs include the baby''s mouth wide open, more areola visible above than below, chin touching breast, slow deep sucks, and painless feeding for the mother. Shallow rapid sucks, partly-open mouth and nipple-only in mouth indicate poor attachment.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The factors that promote growth and development include:-', 'Nutrition, security, emotional support', 'Nutrition, play, emotional', 'Play, achieving status, nutrition', 'Emotional support, religion, play', 'A', 'Per child health/growth and development (Basic Paediatric Protocols; MCH), factors promoting optimal growth and development include adequate nutrition, security/safety, and emotional support (love), alongside stimulation and health care. Option A best captures these core determinants; religion is not a core requirement.', 'BScN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Complications of severe malaria include:-', 'Acute hypoglycaemia, brain damage', 'Acute hypoglycaemia, shock', 'Kidney failure, retinal damage', 'Kidney failure, joints pain', 'A', 'Per Kenya National Malaria Guidelines, complications of severe malaria include hypoglycaemia and cerebral malaria (brain damage). This pairing is the recognised complication set.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Maternal factors that may interfere with breast feeding include:-', 'Infections, prematurity, birth injuries', 'Cracked nipples, mastitis congenital abnormalities', 'Inverted nipples, prematurity, birth injuries', 'Death of a mother, cracked nipples, mastitis', 'D', 'Per Myles Textbook for Midwives, MATERNAL factors interfering with breastfeeding include death/illness of the mother, cracked nipples and mastitis. Prematurity, birth injuries and congenital abnormalities are infant (not maternal) factors.', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Molly, with suspected rheumatic fever, is admitted to the pediatric unit. When obtaining the child’s history, the nurse considers which information to be most important?', 'A fever that started 3 days ago', 'Lack of interest in food', 'A recent episode of pharyngitis', 'Vomiting for 2 days', 'C', 'Per paediatric nursing (Basic Paediatric Protocols/Brunner), rheumatic fever follows a group A streptococcal pharyngitis; a recent episode of pharyngitis is the most important historical finding linking to the diagnosis (Jones criteria supportive evidence).', 'BScN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is aware that the most common assessment finding in a child with ulcerative colitis is:', 'Intense abdominal cramps', 'Profuse diarrhea', 'Anal fissures', 'Abdominal distention', 'B', 'Per paediatric med-surg nursing, the most common presenting finding in ulcerative colitis is profuse (often bloody) diarrhea. Abdominal cramps and distention occur but diarrhea is the hallmark assessment finding.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When developing a plan of care for a male adolescent, the nurse considers the child’s psychosocial needs. During adolescence, psychosocial development focuses on:', 'Becoming industrious', 'Establishing an identity', 'Achieving intimacy', 'Developing initiative', 'B', 'Per Erikson''s developmental theory (Kozier & Erb''s), the psychosocial task of adolescence is identity vs. role confusion, i.e. establishing an identity. Industry is school age, intimacy is young adulthood, initiative is preschool.', 'BScN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When developing a plan care for a hospitalized child, nurse Mica knows that children in which age group are most likely to view illness as a punishment for misdeeds?', 'Infancy', 'Preschool age', 'School age', 'Adolescence', 'B', 'Per paediatric nursing/Piaget, preschool children (magical, egocentric preoperational thinking) most often view illness and hospitalization as punishment for their misdeeds. School-age children begin to understand cause and effect.', 'BScN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('To decrease the likelihood of bradyarrhythmias in children during endotracheal intubation, succinylcholine (Anectine) is used with which of the following agents? Epinephrine (Adrenalin) Isoproterenol (Isuprel) Atropine sulfate Lidocaine hydrochloride (Xylocaine)', 'Epinephrine (Adrenalin)', 'Isoproterenol (Isuprel)', 'Atropine sulfate', 'Lidocaine hydrochloride (Xylocaine)', 'C', 'Per paediatric pharmacology/emergency protocols, atropine sulfate is given with succinylcholine during intubation in children to block the vagally mediated bradycardia (bradyarrhythmias). Epinephrine, isoproterenol, and lidocaine do not serve this vagolytic role.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The well-child care intends to promote the physical and emotional well-being of children. The tasks of each well-child visit include all the following EXCEPT', 'disease detection', 'disease prevention', 'treatment plans', 'health promotion', 'C', 'Per well-child care (paediatric/community health), the tasks of a well-child visit are disease detection (screening), disease prevention (immunization), and health promotion. Formulating treatment plans is a sick-child task, so it is the EXCEPTION.', 'BScN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('By the age of 7 months the infant is able to do all the following EXCEPT', 'transfer object from hand to hand', 'bounces actively', 'cruises', 'grasp uses radial palm', 'C', 'Per paediatric growth and development, a 7-month-old can transfer objects hand to hand, bounce actively, and use a radial-palmar grasp, but cruising (walking while holding furniture) is not achieved until about 9-12 months, making it the EXCEPTION.', 'BScN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The neurodevelopmental function (cognition) is dependent mainly on the development of the following functions EXCEPT', 'sensory and motor', 'language', 'visual–spatial', 'cerebeller', 'D', 'Neurodevelopmental cognition depends on sensory-motor, language and visual-spatial streams (Nelson Textbook of Pediatrics). The cerebellum primarily coordinates movement/balance and is not a principal domain of cognitive assessment, making it the EXCEPT answer.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Breastfeeding has been suggested to have a possible protective effect against all the following EXCEPT', 'otitis media', 'urinary tractinfections', 'septicemia', 'skin infection', 'D', 'Breastfeeding is protective against otitis media, urinary tract infection and septicaemia through passive immunity and IgA (WHO/IMNCI; Nelson). Protection against skin infection is not an established breastfeeding benefit, making it the EXCEPT.', 'BScN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Emergency treatment in severe malnutrition includes all the following EXCEPT', 'infections', 'severe anemia', 'dehydration and shock', 'hypoglycemia', 'B', 'Immediate emergency threats in severe acute malnutrition are hypoglycaemia, hypothermia, dehydration/shock and infection (WHO 10 steps; Kenya Basic Paediatric Protocols). Severe anaemia is managed in the stabilisation phase but is not part of the initial life-threatening emergency triad, so it is the EXCEPT.', 'BScN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The aim of the rehabilitation phase in the treatment of malnutrition is to', 'repair cellular function', 'correct fluid and electrolyte imbalance', 'restore homeostasis', 'prevent death from infection', 'A', 'The rehabilitation (catch-up growth) phase aims to rebuild wasted tissues and repair cellular/metabolic function with high-energy feeds (WHO management of SAM; Kenya Basic Paediatric Protocols). Correcting fluids/electrolytes, restoring homeostasis and preventing death from infection belong to the earlier stabilisation phase.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Nonsteroidal anti-inflammatory drugs (NSAIDs) are prescribed to decrease acute and chronic inflammation associated with various rheumatic diseases; however, many adverse effects have been encountered with long term use.Of the following, the NSAID that has the highest toxicity is.', 'meloxicam', 'indomethacin', 'ibuprofen', 'naproxen', 'B', 'Among these NSAIDs indomethacin has the highest toxicity, with prominent GI, CNS and renal adverse effects (Kenya EML/BNF; Katzung Pharmacology). Ibuprofen and naproxen are comparatively safer and meloxicam is relatively COX-2 selective.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which age group has the greatest potential to demonstrate regression when they are sick?', 'Adolescent', 'Young Adult', 'Toddler', 'Infant', 'C', 'Per paediatric nursing (Kozier/Wong), the toddler has the greatest potential to regress to earlier behaviours (e.g. loss of toileting, thumb-sucking) when hospitalised or ill, due to recently acquired but fragile developmental skills.', 'BScN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The type of lochia expected 10-15 days postpartum is?', 'Rubra', 'Alba', 'Serosa', 'Clear', 'B', 'Lochia alba (whitish) is expected from about day 10 up to 2-6 weeks postpartum; rubra is days 1-3/4 and serosa days 4-10 (Myles Textbook for Midwives).', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The oral contraceptive pill has which of the following minor side effect?', 'Mild elevation of blood pressure', 'Venus thromboembolism', 'Post pill amenorrhea', 'Carcinogenicity', 'A', 'Mild elevation of blood pressure is a minor side effect of combined oral contraceptives, whereas venous thromboembolism is a serious complication; post-pill amenorrhoea and carcinogenicity are not classed as minor side effects (Kenya National Family Planning Guidelines).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('the characteristics of a classical syphilitic ulcer include', 'painful, flat lesion with edema of the surrounding area', 'painful, extensive lesions, fluid filled vesicle like blister', 'painless, flat lesion with smooth regular firm edge', 'painless, flat lesion with irregular edges and flat dirty base', 'C', 'The primary syphilitic chancre is a painless, indurated ulcer with a smooth, clean base and firm, regular raised edges; painful ragged/dirty ulcers suggest chancroid (Kenya STI guidelines, Brunner & Suddarth).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('the commonest causative organism of urinary tract infection is', 'proteus', 'streptococcus aureus', 'Escherichia coli', 'Klebsiela', 'C', 'Escherichia coli is the commonest causative organism of urinary tract infection, accounting for the majority of uncomplicated UTIs (Brunner & Suddarth, Kenya clinical guidelines).', 'BScN', 'Paper I', 'Infection Prevention & Control', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following are indicators of good nutritional status during pregnancy. Which one is not', 'Mid upper arm circumference of less then 23cm', 'Weight gain', 'Hemoglobin level of 11g per dl or more', 'Absence of clinical signs of micronutrient deficiency', 'A', 'Good nutritional status in pregnancy is indicated by adequate weight gain, Hb of 11 g/dl or more and absence of micronutrient deficiency signs; a MUAC less than 23 cm indicates malnutrition, so it is NOT an indicator of good status (Kenya maternal nutrition guidelines).', 'BScN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Lisa is a 24-year-old Para 1 who has a seizure disorder and is taking anticonvulsant medication. Which contraceptive option would the provider discourage her from using?', 'COCs', 'POPs', 'Implants', 'IUCDs', 'A', 'Enzyme-inducing anticonvulsants reduce the efficacy of combined oral contraceptives; per Kenya/WHO Medical Eligibility Criteria for Family Planning, COCs are discouraged (Category 3) with such anticonvulsants, so COCs should be avoided.', 'BScN', 'Paper I', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following falls under “DELAY” in the medical eligibility criteria?', 'Age of 18 years', 'Local skin infection', 'Depressive disorders', 'Diabetes Mellitus', 'B', 'In WHO/Kenya Medical Eligibility Criteria, the classifications are Accept, Caution, Delay and Refer; a local infection at the insertion site is a ''Delay'' condition for methods like implants/IUCDs until it resolves, whereas the others are accept/caution categories.', 'BScN', 'Paper I', 'Infection Prevention & Control', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Lactation amenorrhea method of family planning is suitable for a woman who', 'Breastfeeds exclusively, has history of delayed menstruation, has a baby of more than six months', 'Breastfeeds exclusively,has history of delayed menstruation, wants highly effective method in the first six months', 'Breastfeeds exclusively, has not resumed menstruation, has a baby of less than six months', 'Breastfeeds exclusively, has history of delayed menstruation, has a baby of less than six months A. what disease is indicative of thiamine deficiency A. Beriberi B. Pellagra C. Scurvy D. Kwashiokor', 'C', 'LAM requires all three criteria: exclusive breastfeeding, amenorrhoea (menses not resumed), and infant under 6 months. Per Kenya National Family Planning Guidelines. Option D''s stray text (Beriberi item) is disregarded.', 'BScN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Gumma lesions are the characteristics of', 'Latent stage of syphilis', 'Primordial stage of syphilis', 'Tertiary stage of syphilis', 'Secondary stage of syphilis', 'C', 'Gummata (granulomatous lesions) are the hallmark of tertiary (late) syphilis; primary shows chancre and secondary shows rash/condylomata lata. Per Kenya National STI Guidelines / Brunner & Suddarth.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The most frequent causes of death among clients with AIDS are opportunistic diseases. Which of the following opportunistic infections is characterized by tonsillopharyngitis?', 'Respiratory candidiasis', 'Infectious mononucleosis', 'Cytomegalovirus disease', 'Pneumocystis carinii pneumonia', 'B', 'Infectious mononucleosis (EBV) classically presents with tonsillopharyngitis, fever and lymphadenopathy; PCP causes pneumonia and CMV causes retinitis/colitis. Per Brunner & Suddarth / Kenya HIV guidelines.', 'BScN', 'Paper I', 'Infection Prevention & Control', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The fungal skin infection characterized by thickening and discoloration of the nails is called:-', 'Tinea versicolor', 'Tinea pedis', 'Intertrigo', 'Tinea unguium', 'D', 'Tinea unguium (onychomycosis) is the fungal nail infection causing thickening and discoloration of nails; tinea pedis affects feet and versicolor affects trunk skin. Per Brunner & Suddarth / Kenyan derm nursing.', 'BScN', 'Paper I', 'Infection Prevention & Control', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following parts of the brain is associated with multiple feelings and behaviors and is sometimes referred to as the “emotional brain”: -', 'Frontal lobe', 'Thalamus', 'Hypothalamus', 'Limbic system', 'D', 'The limbic system is termed the ''emotional brain'', governing multiple emotions and behaviours; the frontal lobe handles executive function and the thalamus is a sensory relay (neuroanatomy texts).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The main excitatory neurotransmitter in the CNS is:-', 'Cytstaete', 'Acetylecholine', 'Aspertate', 'D. Glutamate', 'D', 'Glutamate is the principal excitatory neurotransmitter of the CNS; acetylcholine and aspartate have lesser/other roles (neurophysiology texts).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is a tricyclic antidepressant:-', 'Paroxetine', 'Escitalopram', 'Venlafaxine', 'Amitriptyline', 'D', 'Amitriptyline is a classic tricyclic antidepressant, whereas paroxetine and escitalopram are SSRIs and venlafaxine is an SNRI (Kenya EML / psychopharmacology).', 'BScN', 'Paper I', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following effective nursing intervention in order to prevent occurrence of Gastroesophageal reflux?', 'Giving solid foods', 'Giving frequent small feedings', 'Giving semi-solid foods', 'Giving osterized feeding', 'B', 'Small, frequent feeds (with upright positioning) reduce gastric volume and prevent gastro-oesophageal reflux in infants (paediatric nursing). Solid/semi-solid or osterised feeds do not address the mechanism of reflux.', 'BScN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following are signs and symptoms of asthma except:', 'Fatigue', 'pinkish skin', 'Moist skin', 'Use of accessory muscles', 'B', 'In an asthma attack the child is hypoxic, so cyanosis (not pinkish skin) is expected; fatigue, diaphoresis (moist skin) and accessory muscle use are true signs (Basic Paediatric Protocols / respiratory nursing). Thus pinkish skin is the exception.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse leads an adolescent health information group, which often expands into other areas of discussion. She knows that these youths are trying to find out “who they are,” and discussion often focuses on which directions they want to take in school and life, as well as peer relationships. According to Erikson, this stage is known as:', 'identity vs. role confusion', 'adolescent rebellion.', 'career experimentation.', 'relationship testing', 'A', 'Adolescents seeking to discover ''who they are'' are in Erikson''s identity versus role confusion stage (growth & development). The other options are not Erikson stages.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is not an acyanotic heart disease?', 'Patent Ductus Arteriosus', 'Patent Ductus Arteriosus', 'Patent Ductus Arteriosus', 'Tetralogy of Fallot', 'D', 'Tetralogy of Fallot is a cyanotic (right-to-left shunt) congenital heart disease, whereas Patent Ductus Arteriosus is acyanotic; thus ToF is NOT acyanotic (paediatric cardiology). Options A-C are duplicate distractors.
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is not a sign of severe dehydration in children?', 'lethargic or unconscious', 'Skin pinch goes back readily', 'Unable to drink or drinking poorly', 'Sunken eyes', 'B', 'Per Kenya IMNCI, severe dehydration signs include lethargy/unconsciousness, inability to drink or drinking poorly, sunken eyes and a skin pinch that goes back VERY SLOWLY. A skin pinch that goes back readily is normal, so it is NOT a sign of severe dehydration.', 'BScN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('While assessing a newborn with cleft lip, the nurse would be alert that which of the following will most likely be compromised?', 'Sucking ability', 'Respiratory status', 'Locomotion', 'GI function', 'A', 'A cleft lip disrupts the infant''s ability to form a seal, so sucking ability is most likely compromised, creating feeding difficulty (paediatric/neonatal nursing). Respiratory status, locomotion and GI function are not primarily affected by an isolated cleft lip.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Patients with Idiopathic thrombocytopenic Purpura (ITP) have increased risk of bleeding. Therefore the nurse must carefully monitor:', 'WBC and bleeding time', 'Iron and ferritin level', 'PT and PTT', 'Platelet count and RBCs', 'D', 'ITP is a thrombocytopenia; the nurse monitors platelet count (and RBCs for bleeding-related anaemia) since coagulation cascade tests (PT/PTT) are typically normal in ITP (haematology nursing). Iron/ferritin and WBC are not the primary monitoring focus.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When assessing a 12 year old child with Wilm''s tumor, the nurse should keep in mind that it most important to avoid which of the following?', 'Measuring the child''s chest circumference', 'Palpating the child''s abdomen', 'Placing the child in an upright position', 'Measuring the child''s occipitofrontal circumference', 'B', 'In Wilms'' tumour, palpating the abdomen must be avoided because it may dislodge tumour cells and cause metastatic spread (paediatric oncology nursing). The other measures pose no such risk.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Craniotabes is a clinical sign of:', 'Kwashiorkor', 'Marasmus', 'Rickets', 'Scurvy', 'C', 'Craniotabes (soft, thin skull bones that indent under pressure) is a classic sign of vitamin D deficiency rickets, causing defective bone mineralization. Per Basic Paediatric Protocols (Kenya) and standard paediatrics, kwashiorkor/marasmus are protein-energy states and scurvy is vitamin C deficiency.', 'BScN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Respiratory Distress Syndrome is a disease of preterm infant which caused due to all of the following except:', 'Atelectasis of alveoli.', 'Immaturity of the respiratory center.', 'Formation of surfactant substances.', 'Hypoxia.', 'C', 'RDS of the preterm is caused by DEFICIENCY (not formation) of surfactant, leading to alveolar atelectasis, hypoxia and immature respiratory control. Since ''formation of surfactant substances'' would prevent RDS, it is the exception. Per Basic Paediatric Protocols (Kenya).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Sudden stimulus causes the arms to fly up and out is:', 'Moro', 'Gag', 'Rooting', 'Tonic neck', 'A', 'The Moro (startle) reflex is elicited by a sudden stimulus causing symmetrical abduction/extension of the arms followed by flexion. Rooting and gag involve the mouth; tonic neck is the fencing posture. Standard neonatal assessment (Kozier & Erb''s, Basic Paediatric Protocols).', 'BScN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following clinical assessments would most likely be demonstrated in severe dehydration?', 'Pale skin turgor', 'Normal skin turgor', 'Marked oliguria', 'Normal blood pressure', 'C', 'Severe dehydration produces marked oliguria/anuria from reduced renal perfusion, along with hypotension and poor (not normal) skin turgor. Per Kenya IMNCI classification of severe dehydration; ''normal'' BP and turgor are inconsistent with severe loss.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When providing postoperative care for the child with a cleft palate, the nurse should position the child in which of the following positions?', 'Supine', 'Prone', 'In an infant seat', 'lateral', 'B', 'After cleft palate repair the child is positioned prone (on the abdomen/side) to facilitate drainage of secretions and protect the suture line; supine risks aspiration. Standard paediatric surgical nursing (Brunner/Wong).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which assessment finding would the nurse expect in an infant diagnosed with pyloric stenosis?', 'Abdominal rigidity', 'Ribbon-like stools', 'Visible waves of peristalsis', 'Rectal prolapse', 'C', 'Pyloric stenosis presents with visible left-to-right gastric peristaltic waves and an olive-shaped mass with projectile vomiting. Abdominal rigidity, ribbon stools and rectal prolapse relate to other conditions. Standard paediatric med-surg.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following nursing diagnosis would the nurse identify as a priority for the infant with tracheoesophageal fistula (TEF)?', 'impaired parenting related to newborn''s illness', 'risk of injury related to increased potential for aspiration', 'ineffective nutrition: less than body requirements, related to poor sucking ability', 'ineffective breathing pattern related to a weak diaphragm', 'B', 'In TEF the priority is preventing aspiration of secretions/feeds into the lungs (airway protection), making risk of injury/aspiration the priority. Per airway-first (ABC) prioritisation; parenting and nutrition are lower priority.', 'BScN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In bacterial meningitis all the following may be observed during CSF analysis results except: a. b. c. d.', 'high cells count', 'high glucose', 'high protein', 'turbidity', 'B', 'In bacterial meningitis CSF shows high WBC (neutrophils), high protein, low (not high) glucose, and turbidity. Thus ''high glucose'' is the exception. Per Basic Paediatric Protocols / Brunner & Suddarth''s.', 'BScN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When Baby Nicole was 1 day old she has surgery for reduction of myelomeningocele. Which nursing intervention is critical during the postoperative period?', 'passive range-of-motion exercises of the lower extremities', 'suprapubic manual expression of urine', 'observation of the frequency and character of the stools', 'daily measurement of the head circumference', 'D', 'After myelomeningocele repair, hydrocephalus is a major risk, so daily head circumference measurement to detect increasing intracranial pressure is critical. Standard neuro-paediatric nursing (Wong/Brunner).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What clinical manifestations would suggest hydrocephalus in a neonate ?', 'Bulging fontanel, dilated scalp veins .', 'Closed fontanel, high-pitched cry .', 'Constant low-pitched cry, restlessness .', 'Depressed fontanel, decreased blood pressure .', 'A', 'Hydrocephalus in a neonate causes raised ICP with a bulging/tense fontanel, dilated scalp veins, enlarging head and high-pitched cry. A depressed or closed fontanel would not fit. Standard paediatric neuro assessment.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Kerning''s sign is manifestation for:', 'Wiliam''s tumor .', 'Acute Rheumatic Fever.', 'Encephalitis', 'Meningiti s', 'D', 'Kernig''s sign (resistance/pain on knee extension with hip flexed) is a sign of meningeal irritation seen in meningitis. Brunner & Suddarth''s / Basic Paediatric Protocols.', 'BScN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following heart defects usually results in hypoxemia and cyanosis ?', 'Coarctation of the aorta .', 'Atrial septal defect .', 'Patent ductus arteriosus .', 'Transposition of the great vessels .', 'D', 'Transposition of the great vessels is a cyanotic (right-to-left) defect causing hypoxemia and cyanosis. Coarctation, ASD and PDF are acyanotic (left-to-right) lesions. Standard paediatric cardiology (Wong/Brunner).', 'BScN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The best prophylactic treatment for client is to prevent further rheumatic attack:', 'Prednisone.', 'Aspirin.', 'Penicillin.', 'All of the above.', 'C', 'Secondary prophylaxis against recurrent rheumatic fever is long-term penicillin (benzathine penicillin) to prevent recurrent group A streptococcal infection. Prednisone and aspirin treat acute inflammation, not prophylaxis. Per Kenya/WHO RHD guidelines.', 'BScN', 'Paper I', 'Infection Prevention & Control', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In trachoma,', 'Pannus develop in the second stage of disease process', 'Rupture of the cornea can occur', 'The drug of choice is 1% tetracycline in early stages', 'Follicles form in the third stage of the disease process', 'C', 'Per WHO SAFE strategy adopted in Kenya, topical 1% tetracycline eye ointment (or azithromycin) is the treatment in early active trachoma. Pannus and corneal changes appear later; follicles form in the early (active) stage, not the third stage.', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following disease causes severe tenesmus;', 'Bacillary dysentery', 'Amoebic dysentery', 'Girdiasis', 'Cholera', 'A', 'Per communicable disease references, bacillary dysentery (Shigella) characteristically causes severe tenesmus with blood and mucus in stool due to rectosigmoid inflammation. Cholera causes painless watery stool without tenesmus.', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following elements of PHC were not listed in the Alma Ata Declaration', 'Education concerning prevailing health problems, basic sanitation', 'HIV/AIDS, maternal and child health', 'Treatment of common diseases, control of endemic diseases', 'Immunisation, promotion of food supply.', 'B', 'Per the 1978 Alma Ata Declaration, the original elements of PHC did NOT include HIV/AIDS (an emerging disease). The listed elements included health education, food supply/nutrition, safe water/sanitation, MCH/FP, immunisation, control of endemic diseases, treatment of common diseases, and essential drugs.', 'BScN', 'Paper II', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Sand fly is a vector for;', 'Filariasis', 'Dracunculosis', 'Leshmaniasiis', 'Yellow fever', 'C', 'Per Kenya communicable disease references, the sandfly (Phlebotomus) is the vector for leishmaniasis (kala-azar). Filariasis is spread by mosquitoes, dracunculiasis by Cyclops, yellow fever by Aedes.', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following leadership style relies on organizational policies and rules for decision making;', 'Autocratic', 'Democratic', 'Bureaucratic', 'Laissez-faire', 'C', 'Per nursing management/leadership theory (Weber), the bureaucratic leadership style relies on fixed organizational rules, policies and procedures for decision-making rather than personal judgement.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following management theorists emphasized on training and proper selection of workers;', 'Frederic Taylor', 'Max Weber', 'Henry Fayol', 'Abraham Maslow', 'A', 'Per management theory, Frederick Taylor (scientific management) emphasized scientific selection, training and development of workers to match the job. Weber = bureaucracy, Fayol = administrative principles, Maslow = needs hierarchy.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The evaluation error in performance appraisal in which the ratter assumes that if the person does well in several known areas, he or she will do well in all areas is referred to as;', 'Halo effect', 'Sun flower effect', 'Recency Effect', 'Problem distortion', 'A', 'Per nursing management (performance appraisal), the halo effect is the rating error where a rater assumes that strong performance in known areas means the person performs well in all areas, biasing the overall rating.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('School health committees are composed of the following EXCEPT;', 'Teachers, students, community health nurse', 'Teachers, community informal leaders, Parents', 'Community health nurse, Teachers, school''s supportive staff', 'Parents, teachers, community formal leaders', 'A', 'Per school health programme guidelines, the school health committee comprises teachers, parents, community leaders, health workers and supportive staff; students/pupils are not formal committee members, so this option is the EXCEPT.', 'BScN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Food borne diseases include;', 'Polio, schistosomiaisis, Girdiasis.', 'Taeniasis, milliary T.B, hepatitis A.', 'Amoebiasis, Hepatitis B, Polio', 'Polio, schistosomiasis, milliary TB.', 'B', 'Per communicable disease references, food-borne diseases include taeniasis (undercooked meat), miliary/bovine TB (unpasteurised milk/meat) and hepatitis A (faecal-oral via contaminated food/water). Schistosomiasis is water-contact, not food-borne, eliminating the other options.', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The study of population dynamics such as births, deaths and migration is referred to as;', 'Civil registration', 'Demography', 'Census', 'Epidemiology', 'B', 'Per community/public health, demography is the study of population dynamics including births, deaths, and migration. Epidemiology studies disease distribution; census is an enumeration; civil registration records vital events.', 'BScN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following factor DOES NOT affect growth of a population.', 'Migration', 'Women of reproductive age', 'Occurrence of disasters', 'Literacy levels', 'D', 'Per demography, the three direct determinants of population change/growth are births (fertility, linked to women of reproductive age), deaths (including disasters) and migration. Literacy influences these only indirectly and does NOT directly affect population growth.', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Epidemiological triad includes;', 'Agent, route of transmission, mode of transmission.', 'Host, agent, environment.', 'Vector , route of transmission, Agent', 'Host, route of transmission, environment.', 'B', 'Per epidemiology, the epidemiological triad consists of the agent, the host, and the environment; their interaction determines disease occurrence.', 'BScN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The diseases that are targeted for eradication by KEPI include;', 'Poliomyelitis, neonatal tetanus, measles', 'Neonatal tetanus, measles, chicken pox', 'Measles, yellow fever, whooping cough', 'Poliomyelitis, neonatal tetanus, diphtheria', 'A', 'Per KEPI, the diseases targeted for eradication/elimination include poliomyelitis, neonatal tetanus and measles. Chicken pox, yellow fever, whooping cough and diphtheria are not the eradication-targeted set.', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following leadership style has the least regard for organizational policies and rules ;', 'Autocratic', 'Democratic', 'Bureaucratic', 'Laissez-faire', 'D', 'Per nursing leadership theory, the laissez-faire (hands-off) style gives the least regard for organizational policies and rules, allowing group members maximum freedom with minimal leader control.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Everyone in the society is expected to bathe. This is an example of which norm?', 'A folkway', 'Mores', 'Law', 'Value', 'A', 'Per sociology as taught in NCK community/behavioural science, folkways are everyday customs of proper conduct (e.g. bathing, dressing) whose violation brings mild disapproval, unlike mores which carry strong moral weight. Bathing is a routine custom, hence a folkway.', 'BScN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Zoonotic diseases include', 'Rabies, tetanus, anthrax, trichuriasis', 'Anthrax, tetanus, rabies, plague', 'Brucellosis, rabies, anthrax, taeniasis', 'Tetanus, rabies, anthrax, brucellosis', 'C', 'Per Kenya communicable disease control, zoonoses are diseases transmitted from animals to humans; brucellosis, rabies, anthrax and taeniasis are all zoonotic. Tetanus is caused by environmental Clostridium tetani spores (not a zoonosis), so options listing tetanus are wrong.', 'BScN', 'Paper II', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The three components of a disease transmission cycle include:-', 'The environment, the transmission route, the susceptible host', 'The source, the environment, the susceptible host', 'The source, the transmission route, the susceptible host', 'The source, the vector, the transmission route', 'C', 'Per Kenya epidemiology/communicable disease control, the disease transmission cycle comprises the source (reservoir/agent), the route of transmission, and a susceptible host. The environment and vector are contributing factors, not the three core components.', 'BScN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The initial step of community diagnosis is:', 'Execution of survey', 'Planning of the survey', 'Exploration', 'Community action', 'C', 'Per Kenya community health nursing, community diagnosis begins with exploration/orientation (getting to know the community) before planning and executing the survey and taking community action. Exploration is therefore the initial step.', 'BScN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Characteristics of an effective team include:-', 'The management relationship in the organization is directive, information flows mainly downwards', 'Every member understands the objective and goals, communication is open during meetings', 'Criticism is frank and constructive, each individual strives to meet individual tasks', 'Decision making is by consensus, conflicts never arise due to the harmony', 'B', 'Per nursing management/leadership theory, effective teams share understood goals, open communication and consensus decision-making. Option B reflects these; directive downward-only flow and the claim that conflicts ''never arise'' are incorrect characteristics.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Unity of command means:-', 'The systematic reporting ranging from the ultimate authority at the top to the worker with least authority', 'One being in charge of a group that he/she can effectively supervise in terms of numbers.', 'That the employee should receive orders from one superior only.', 'Having all standards and policies in an organization addressing issues harmoniously and implicitly.', 'C', 'Per management principles (Fayol) as taught in NCK nursing management, unity of command means each employee receives instructions from only one superior. The top-to-bottom reporting chain describes the scalar chain, and effective supervisory numbers describe span of control.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Incidence rate is:-', 'The number of cases of a disease present within the population', 'Disease giving rise to unexpectedly large number of cases', 'The occurrence of new cases within a stated period', 'Transmission of disease occurring at a low rate', 'C', 'Per Kenya epidemiology/biostatistics, incidence rate measures new cases arising in a population over a defined period. Existing (all) cases describe prevalence, and unexpectedly large numbers describe an epidemic.', 'BScN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Fat soluble vitamins include:-', 'A,D,C,E', 'A,D,E,K', 'E,D,C,K', 'A,B,C,D', 'B', 'Per nutrition principles in Kenyan nursing training, the fat-soluble vitamins are A, D, E and K. Vitamins B and C are water-soluble, so options containing them are wrong.', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Common emotional health problems among the youth include:-', 'Suicidal tendency, alcoholism, drug abuse', 'Homosexuality, STI, truancy', 'Drug abuse, school drop out, promiscuity', 'Suicidal tendency, STI, school drop out', 'A', 'Per adolescent/mental health nursing, emotional health problems in youth include suicidal tendencies, alcoholism and drug/substance abuse. STIs, truancy and school drop-out are behavioural/social consequences rather than emotional health problems themselves.', 'BScN', 'Paper II', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In community diagnosis, the sampling technique where groups are randomly selected in a population that is scattered over a large geographical area is:-', 'Systematic sampling', 'Cluster sampling', 'Stratified sampling', 'Multistage sampling', 'B', 'Per Kenya research/biostatistics, cluster sampling randomly selects naturally occurring groups (clusters) when the population is spread over a large geographical area. Stratified sampling divides by strata and systematic sampling picks every nth unit.', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The process of increasing the communities ability to handle a disaster is referred to as:-', 'Preparedness', 'Response', 'Mitigation', 'Prevention', 'A', 'Per Kenya disaster management guidelines, preparedness is the process of building the community''s capacity and readiness to handle a disaster before it occurs. Mitigation reduces impact/hazard severity, while response is action taken during the event.', 'BScN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When a disease is present in a community all the time it is said to be:-', 'Epidemic', 'Endemic', 'Pandemic', 'Prevalent', 'B', 'Per Kenya epidemiology, a disease constantly present in a community/area is endemic. Epidemic is an excess of cases, pandemic is worldwide spread, and prevalence is a measure of existing cases.
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following is not associated with Vitamin B group deficiencies:', 'Angular ceilitis', 'Hematuria', 'Pellagra', 'Beriberi', 'B', 'Angular cheilitis (B2), pellagra (B3/niacin) and beriberi (B1/thiamine) are all B-group deficiency states; hematuria is unrelated to B-vitamin deficiency (Kozier Fundamentals; Kenya nutrition guidelines).', 'BScN', 'Paper II', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nutrient requirements of children are NOT influenced by:', 'Growth rate', 'Body composition', 'Composition of new growth', 'Sex of the child', 'D', 'Growth rate, body composition and composition of new growth all directly influence a child''s nutrient requirements; sex has minimal influence in early childhood and is the least relevant factor (Kenya nutrition/paediatric guidelines).', 'BScN', 'Paper II', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following is an atypical antipsychotic', 'Risperidone', 'Buspirone', 'Flulazepam', 'Fluphenazine', 'A', 'Risperidone is an atypical (second-generation) antipsychotic; buspirone is an anxiolytic, flurazepam a benzodiazepine, and fluphenazine a typical antipsychotic (Kenya EML; standard pharmacology).', 'BScN', 'Paper II', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following is NOT associated with obsessive compulsive disorder:', 'Rituals', 'Depersonalization', 'Slowness', 'Hypochondriasis', 'B', 'Rituals, slowness (obsessional slowness) and hypochondriacal preoccupations feature in OCD; depersonalization is a dissociative symptom not characteristic of OCD (standard psychiatric nursing text).', 'BScN', 'Paper II', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following is a precipitating factor of anxiety disorders', 'Childhood upbringing', 'Genetic factors', 'Problems in relationships', 'Personality', 'C', 'Precipitating factors are acute triggers; relationship problems act as an immediate precipitant, whereas childhood upbringing, genetics and personality are predisposing factors (standard psychiatric nursing text).', 'BScN', 'Paper II', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Qualitative research is interested in questions that involve:', 'Cause and effect relationships', 'Consciousness and subjectivity', 'Control and measurement', 'Generalization and prediction', 'B', 'Qualitative research explores lived experience, meaning and subjectivity; cause-effect, control/measurement and generalization/prediction are quantitative concerns (Nursing research texts; NCK research syllabus).', 'BScN', 'Paper II', 'Research & Evidence-Based Practice', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The agreement of the participant to take part in the research project after having been thoroughly briefed about the project is', 'Human dignity', 'Full disclosure', 'Self determination', 'Informed consent', 'D', 'Agreement to participate after being fully briefed is the definition of informed consent; full disclosure and self-determination are elements that support it (Research ethics; NCK research syllabus).', 'BScN', 'Paper II', 'Research & Evidence-Based Practice', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The most appropriate method of studying the characteristics of wound healing would be:', 'Questionnaire', 'Participant observation', 'Pure observation', 'Content analysis', 'C', 'Wound healing is a physical, observable process best studied by direct (pure/non-participant) observation over time; questionnaires, participant observation and content analysis are unsuitable for tracking physiological wound changes (Nursing research methods).', 'BScN', 'Paper II', 'Research & Evidence-Based Practice', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Factors to consider when selecting an instructional method do NOT include.', 'Time', 'Students characteristics', 'Teacher''s skill', 'Common practice', 'D', 'Time, student characteristics and teacher''s skill are legitimate factors in selecting an instructional method; ''common practice'' is not a valid selection criterion (Nurse education/teaching methodology).', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following type of evaluation is used for the purpose of documenting outcomes and judging value:', 'Diagnostic', 'Formative', 'Summative', 'Administrative', 'C', 'Summative evaluation documents outcomes and judges the overall value/worth at the end of a programme; formative is ongoing and diagnostic identifies difficulties (Educational evaluation; nurse-education theory).', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The process of curriculum development involves:', 'Situation analysis, Job description, Identification of students', 'Job description, Performing task analysis, Identification of trainers', 'Identification of content, Identification of students,Identification of teaching methods', 'Situation analysis, Job description, Performing task analysis', 'D', 'Curriculum development follows situation analysis, job/role description, then task analysis to derive content; the other options mix in non-sequential or extraneous steps (Curriculum development theory).', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In aversion therapy:-', 'A client is subjected to anxiety provoking stimuli in imagination', 'Noxious stimuli are used to change behavior', 'Relaxation techniques are used to correct inappropriate behavior', 'There is systematic exposure of a client to graded stimuli', 'B', 'Aversion therapy pairs an unwanted behavior with a noxious/unpleasant stimulus to reduce it; imagined anxiety stimuli and graded exposure describe systematic desensitization (behaviour therapy; psychiatric nursing).', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('There is favourable prognosis in Schizophrenia if there are:-', 'Negative symptoms with history of schizoid personality', 'Positive symptoms and older age of onset', 'Schizoid personality and early age of onset', 'Early age of onset with negative symptoms', 'B', 'Good prognostic factors in schizophrenia include predominance of positive symptoms and later age of onset; negative symptoms, early onset and schizoid premorbid personality indicate poor prognosis (standard psychiatric text).', 'BScN', 'Paper II', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('While teaching a group of patients a nurse used the term ''note carefully''. This is an example of;', 'Reinforcement', 'Set induction', 'Topic closure', 'Stimulus variation', 'D', 'Using cue words like ''note carefully'' to focus and vary attention is a stimulus-variation (focusing) technique in microteaching; set induction opens a lesson and topic closure ends it (microteaching skills).', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following is NOT an advantage of practical as a teaching method;', 'It leads to creativity', 'It saves time', 'It provides immediate feedback', 'It caters for individual differences', 'B', 'Practicals foster creativity, give immediate feedback and cater for individual differences but are time-consuming; ''saves time'' is NOT an advantage (nurse-education teaching methods).', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The correct sequence of using  teaching aids is;', 'Select, preview, plan, present, evaluate', 'Plan, select, preview present, evaluate', 'Plan, preview, select, present, evaluate', 'Select, plan , present, preview, evaluate', 'A', 'The correct sequence for using teaching aids is select, preview, plan (integrate into lesson), present, then evaluate their effectiveness (nurse-education/teaching aids theory).', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The objectives  that can be best achieved through role modeling are in;', 'Psychomotor domain', 'Cognitive domain', 'Affective domain', 'Comprehension domain', 'C', 'Role modeling shapes attitudes, values and professional behaviour, which are objectives of the affective domain; psychomotor is skills and cognitive is knowledge (Bloom''s taxonomy; nurse education).', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following characteristics differentiate  a true experiment  from a quasi-experiment include;', 'Manipulation of dependent variable, having control group, random assignment', 'Being reliable, having an experimental group, having a control group', 'Having a control group, randomization, manipulation of the independent variable', 'Having a control group, being conducted in a controlled environment, having a experiment group', 'C', 'A true experiment requires manipulation of the independent variable, a control group and random assignment; a quasi-experiment lacks randomization. Option A wrongly states manipulation of the dependent variable (Nursing research methods; NCK syllabus).', 'BScN', 'Paper II', 'Research & Evidence-Based Practice', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The middle score in a range of scores is called the;', 'Central tendency', 'Mode', 'Median', 'mean', 'C', 'The median is the middle value (score) when data are arranged in order. Per Polit & Beck / basic biostatistics used in NCK research papers, the mean is the average and mode the most frequent value.', 'BScN', 'Paper II', 'Research & Evidence-Based Practice', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following is an intervention study design:', 'Quasi experimental design', 'Evaluative study design', 'Exploratory study design', 'Descriptive study design', 'A', 'Intervention (experimental) studies manipulate an independent variable; quasi-experimental designs are intervention studies lacking full randomization. Evaluative, exploratory and descriptive designs are non-interventional. Per Polit & Beck research methods.', 'BScN', 'Paper II', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client admitted for alcohol detoxification develops increased tremors, irritability, hypertension and fever. The nurse should be alert for impending:', 'Delirium tremens', 'Korsakoff''s syndrome', 'Esophageal varices', 'Wernicke''s syndrome', 'A', 'Increasing tremors, irritability, hypertension and fever during alcohol withdrawal signal impending delirium tremens, a life-threatening emergency. Korsakoff''s/Wernicke''s are thiamine-deficiency states. Per Kozier & standard psychiatric nursing texts (NCK mental health).', 'BScN', 'Paper II', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The primary nursing intervention in working with a client with moderate stage dementia is ensuring that the client:', 'receives adequate nutrition and hydration', 'will reminisce to decrease isolation', 'remains in a safe and secure environment', 'independently performs self care', 'C', 'Safety is the priority in moderate dementia because impaired cognition and wandering pose injury risk. Nutrition/hydration and reminiscence matter but safety takes precedence; independent self-care is not realistic at this stage. Per psychiatric/geriatric nursing standards.', 'BScN', 'Paper II', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Malingering is different from somatoform disorder because the former:', 'Has evidence of an organic basis.', 'It is a deliberate effort to handle upsetting events', 'Gratification from the environment is obtained.', 'Stress is expressed through physical symptoms.', 'C', 'Malingering is the conscious, deliberate production of symptoms for external/secondary gain (environmental gratification), whereas somatoform symptoms are unconscious and not intentionally produced. Per DSM/standard psychiatric nursing texts.', 'BScN', 'Paper II', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following statement regarding the learning process is true.', 'Perception is sending the information to the brain via the special senses.', 'Acquisition refers to storing information in the memory centres either long term or short term.', 'Transfer refers to using information learnt in practice', 'Retention refers to information being recorded in the brain.', 'C', 'Transfer of learning is the application of learned information/skills in practice or new situations. Perception is receiving via senses, acquisition is initial learning, and retention is storing in memory. Per educational psychology used in NCK nursing education.', 'BScN', 'Paper II', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following is a factor to consider when selecting an instructional method.', 'Teacher''s skill', 'Examination regulations', 'Course title', 'Institution''s vision', 'A', 'Selection of an instructional method depends on factors including the teacher''s skill/competence (alongside learner, content and resources). Course title, exam regulations and institutional vision do not directly determine method choice. Per nursing education principles.', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following is a level of affective domain in learning', 'Evaluation', 'Synthesis', 'Characterizing', 'Application', 'C', 'Characterizing (by a value/value complex) is the highest level of Krathwohl''s affective domain. Evaluation, synthesis and application belong to the cognitive (Bloom''s) domain. Per educational taxonomy used in NCK nursing education.', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Cognitive theories of learning include:', 'Assimilation theory', 'Operant conditioning', 'Student centered education', 'Classical conditioning', 'A', 'Assimilation theory (Ausubel) is a cognitive theory of learning. Operant and classical conditioning are behaviourist theories, and student-centred education is an approach, not a cognitive theory. Per learning theory in nursing education.', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is included in Orem’s theory', 'Maintenance of a sufficient intake of air', 'Self-perception', 'Love and belonging', 'Physiologic needs', 'A', 'Orem''s Self-Care Deficit Theory lists universal self-care requisites including maintenance of sufficient intake of air, water and food. Love/belonging and physiologic needs belong to Maslow''s hierarchy (Kozier & Erb''s Fundamentals of Nursing).', 'BScN', 'Paper II', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('It is best to describe as a systematic, rational method of planning& providing nursing care for individuals, families, group and community.', 'assessment', 'nursing process', 'diagnosis', 'implementation', 'B', 'The nursing process is defined as a systematic, rational method of planning and providing individualized nursing care for individuals, families, groups and communities; assessment and diagnosis are only its phases (Kozier & Erb''s Fundamentals of Nursing).', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Nurse Dorothy is assessing a client for signs of postpartum depression. Which observation, if noted in the new mother, would indicate the need for further assessment related to this form of depression?', 'The mother constantly complains of tiredness and fatigue.', 'The mother is caring for the infant in a loving manner', 'The mother demonstrates an interest in the surroundings.', 'The mother looks forward to visits from the father of the newborn.', 'A', 'Persistent fatigue, along with low mood, poor bonding and loss of interest, is a warning sign warranting further assessment for postpartum depression; loving infant care and interest in surroundings are reassuring signs (Kenya mental health/MCH guidance; Myles).', 'BScN', 'Paper II', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following is caused by deficiency of zinc:-', 'Pre-eclampsia', 'Night blindness', 'Impaired immune system', 'Increased risk of spontaneous abortions', 'C', 'Per nutrition references, zinc deficiency impairs immune function and wound healing; night blindness is vitamin A deficiency, making impaired immunity the correct effect of zinc lack.', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Reverse barrier nursing is aimed at:', 'Nursing a patient in a corner bed with a sink', 'Taking precautions to protect the patient', 'Taking precautions to protect other patients', 'Nursing the patient who has a highly infectious disease', 'B', 'Per infection prevention and control principles, reverse (protective) barrier nursing protects an immunocompromised/susceptible patient from acquiring infection from the environment; standard barrier nursing protects others from an infectious patient.', 'BScN', 'Paper II', 'Infection Prevention & Control', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The Nursing council of Kenya (NCK) is established under the Nurses Act Cap.', '274', '247', '257', '254', 'C', 'The Nursing Council of Kenya was established under the Nurses Act, Cap. 257 of the Laws of Kenya, which corresponds to option C (257).', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nursing diagnosis that best describes a patient with psoriasis who has quit her job as a receptionist because she feels her appearance is disgusting to customers is:', 'Ineffective coping related to loss of skin integrity', 'Social isolation related to loss of skin integrity', 'Impaired skin integrity related to presence of lesions', 'Anxiety related to lack of knowledge of the disease process', 'B', 'Per Kozier & Erb''s nursing-diagnosis framework, quitting her job and withdrawing from customers because she feels her appearance is disgusting reflects Social isolation related to the altered skin/body image, rather than impaired coping or skin integrity as the priority problem here.', 'BScN', 'Paper II', 'Infection Prevention & Control', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The right time for diagnosing HIV infection using antibody tests among children born to HIV positive mother is at or after;', '12 months of age', '16 months off age', '18 months of age', '6 months of age', 'C', 'Per Kenya National Guidelines on HIV (EMTCT) and WHO, maternal antibodies persist in the infant, so definitive diagnosis using antibody (serological) tests is done at or after 18 months of age; before that, virological (DNA PCR) testing is used. Hence 18 months is correct.', 'BScN', 'Paper II', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Perinatal mortality refers to fetal and infants deaths including still births occurring from 28 weeks of gestation to within the first:', 'One week of life per 1000 live births', 'Two weeks of life per 1000 live births', 'Four weeks of life per 1000 live births', 'Six weeks of life per 1000 live births', 'A', 'Per WHO/Kenya MOH definitions, the perinatal period extends from 28 completed weeks of gestation to the end of the first week (7 days) of life; perinatal mortality is expressed per 1000 total births. Hence one week of life is correct.', 'BScN', 'Paper II', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The sensitivity part of culture and sensitivity test is for the purpose of,', 'Identifying the causative organism for the infection diagnosed', 'Testing the concentration of antibiotic required to cure an infection', 'Identifying the most effective antibiotics against the causative agent', 'Identifying the antibiotics that the patient is resistant to.', 'C', 'Per microbiology/IPC principles, the culture identifies the organism while the SENSITIVITY component determines which antibiotics are most effective against that isolate, guiding targeted therapy.', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client with dementia is experiencing confusion late in the afternoon and before bedtime. The nurse is aware that the client is experiencing what is known as:', 'Chronic fatigue syndrome', 'Normal aging', 'Sundowning', 'Delusions', 'C', 'Per Brunner & Suddarth''s/mental health nursing, sundowning is increased confusion and agitation in the late afternoon and evening seen in dementia.', 'BScN', 'Paper II', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client with confusion says to the nurse, “I haven’t had anything to eat all day long. When are they going to bring breakfast?” The nurse saw the client in the day room eating breakfast with other clients 30 minutes before this conversation. Which response would be best for the nurse to make?', '“You know you had breakfast 30 minutes ago.”', '“I am so sorry that they didn’t get you breakfast. I’ll report it to the charge nurse.”', '“I’ll get you some juice and toast. Would you like something else?”', '“You will have to wait a while; lunch will be here in a little while.”', 'C', 'Per mental health nursing principles for confused/dementia clients, avoid arguing with or reality-confronting the client; a supportive, non-confrontational response that meets the immediate need (offering juice and toast) is therapeutic.', 'BScN', 'Paper II', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('During the initial interview, the client reports that she has a lesion on the perineum. Further investigation reveals a small blister on the vulva that is painful to touch. The nurse is aware that the most likely source of the lesion is:', 'Syphilis', 'Herpes', 'Gonorrhea', 'Condylomata .', 'B', 'Per Kenya STI guidelines, a small painful blister/vesicle on the vulva is characteristic of genital herpes; syphilis chancre is typically painless and condylomata (HPV warts) are painless papillomas.', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client is admitted to the chemical dependence unit with an order for continuous observation. The nurse is aware that the doctor has ordered continuous observation because:', 'Hallucinogenic drugs create both stimulant and depressant effects.', 'Hallucinogenic drugs induce a state of altered perception.', 'Hallucinogenic drugs produce severe respiratory depression.', 'Hallucinogenic drugs induce rapid physical dependence.', 'B', 'Per mental health nursing (Kozier/psychiatric texts), hallucinogens cause altered perception and distorted reality that can lead to unpredictable, unsafe behavior, warranting continuous observation. They do not cause severe respiratory depression or rapid physical dependence.', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which action by the nurse indicates understanding of herpes zoster?', 'The nurse covers the lesions with a sterile dressing.', 'The nurse wears gloves when providing care.', 'The nurse administers a prescribed antibiotic.', 'The nurse administers oxygen.', 'B', 'Per infection prevention (Kenya IPC guidelines), herpes zoster lesion fluid is infectious (contact/airborne precautions), so wearing gloves during care prevents transmission. It is viral, so antibiotics are not indicated.', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is preparing to suction the client with a tracheotomy. The nurse notes a previously used bottle of normal saline on the client''s bedside table. There is no label to indicate the date or time of initial use. The nurse should:', 'Lip the bottle and use a pack of sterile 4x4 for the dressing', 'Obtain a new bottle and label it with the date and time of first use', 'Ask the ward secretary when the solution was requested', 'Label the existing bottle with the current date and time', 'B', 'Per infection prevention principles (Kenya IPC guidelines; Kozier & Erb''s Fundamentals), an opened saline bottle of unknown age/sterility must be discarded; a new bottle should be obtained and labelled with date and time of first opening to track its 24-hour usable window.', 'BScN', 'Paper II', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The physician has ordered a histoplasmosis test for the elderly client. The nurse is aware that histoplasmosis is transmitted to humans by:', 'Cats', 'Dogs', 'Turtles', 'Birds', 'D', 'Per Brunner & Suddarth''s and communicable disease references, histoplasmosis is a fungal infection acquired by inhaling spores from soil contaminated with bird or bat droppings; among the options, birds are the source.
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following is a biased sampling method:-', 'Cluster', 'Quota', 'Stratified random', 'd) Systematic', 'B', 'Quota sampling is a non-probability (biased) method because participants are selected non-randomly to fill quotas, so selection bias is introduced. Cluster, stratified random, and systematic are probability sampling methods. Per Research & Biostatistics (NCK research syllabus; Polit & Beck).', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Test-retest reliability in research involves:-', 'Two different measurements taken by different observers and then comparing them', 'Taking two sets of measurements of the same thing some time apart and comparing them', 'Recruiting participants randomly to the study project', 'Subjecting one study group to treatment and the other to placebo', 'B', 'Test-retest reliability administers the same instrument to the same subjects at two different times and correlates the results, per standard nursing research methodology. Option A describes inter-rater reliability.', 'BScN', 'Paper II', 'Research & Evidence-Based Practice', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following physical manifestations would you expect to assess in a client suffering from anorexia nervosa?', 'Tachycardia, hypertension, hyperthermia', 'Bradycardia, hypertension, hyperthermia', 'Bradycardia, hypotension, hypothermia', 'Tachycardia, hypotension, hypothermia', 'C', 'Starvation in anorexia nervosa causes hypometabolism, producing bradycardia, hypotension, and hypothermia. The other options list opposite/mixed findings. Per psychiatric nursing texts adopted in Kenyan training (Kozier; DSM-based mental health nursing).', 'BScN', 'Paper II', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Ms. T. has been diagnosed with agoraphobia. Which behavior would be most characteristic of this disorder?', 'Ms. T. experiences panic anxiety when she encounters snakes.', 'Ms. T. refuses to fly in an airplane.', 'Ms. T. will not eat in a public place.', 'Ms. T. stays in her home for fear of being in a place from which she cannot escape', 'D', 'Agoraphobia is fear of being in situations/places from which escape may be difficult, leading to housebound behavior. Fear of snakes or flying are specific phobias, and fear of eating in public is a social phobia. Per mental health nursing (DSM criteria; standard psychiatric nursing texts).', 'BScN', 'Paper II', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The physician orders sertraline (Zoloft) 50 mg bid for Margaret, a 68-year-old woman with Major Depression. After 3 days of taking the medication, Margaret says to the nurse, “I don’t think this medicine is doing any good. I don’t feel a bit better.” What is the most appropriate response by the nurse?', '“Cheer up, Margaret. You have so much to be happy about.”', '“Sometimes it takes a few weeks for the medicine to bring about an improvement in symptoms.”', '“I’ll report that to the physician, Margaret. Maybe he will order something different.”', '“Try not to dwell on your symptoms, Margaret. Why don’t you join the others down in the dayroom?”', 'B', 'SSRIs such as sertraline take 2–4 weeks for therapeutic antidepressant effect; the nurse should provide accurate information and reassurance. The other responses give false reassurance or dismiss the client. Per pharmacology (Kenya EML; psychiatric nursing).', 'BScN', 'Paper II', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Symptoms of alcohol withdrawal include:', 'euphoria, hyperactivity, and insomnia.', 'depression, suicidal ideation, and hypersomnia.', 'diaphoresis, nausea and vomiting, and tremors.', '. unsteady gait, nystagmus, and profound disorientation.', 'C', 'Alcohol withdrawal produces autonomic hyperactivity: diaphoresis, nausea/vomiting, tremors, tachycardia, and agitation. Unsteady gait/nystagmus reflect intoxication or Wernicke''s, not classic withdrawal. Per Kenya mental health/substance use nursing (psychiatric nursing texts).', 'BScN', 'Paper II', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Crises occur when an individual:', 'is exposed to a precipitating stressor', 'perceives a stressor to be threatening.', 'has no support systems.', 'experiences a stressor and perceives coping strategies to be ineffective.', 'D', 'A crisis arises when an individual faces a stressor and their usual coping mechanisms are perceived as inadequate to restore equilibrium. Exposure or perceived threat alone is insufficient without failure of coping. Per crisis intervention theory (psychiatric/mental health nursing).', 'BScN', 'Paper II', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Mr. J. is a new client on the psychiatric unit. He is 35 years old. Theoretically, in which level of psychosocial development (according to Erikson) would you place Mr. J.?', 'Intimacy vs. isolation', 'Generativity vs. self-absorption', 'Trust vs. mistrust', 'Autonomy vs. shame and doubt', 'B', 'Erikson places middle adulthood (approximately 35–65 years) in the generativity vs. stagnation/self-absorption stage. Intimacy vs. isolation is young adulthood; the others are earlier childhood stages. Per developmental theory (Kozier & Erb''s Fundamentals of Nursing).', 'BScN', 'Paper II', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The personality disorders where individuals are characteristically sensitive and suspicious include;', 'Histrionic, Borderline and Narcissistic personality disorders', 'Paranoid, Schizoid and Schizotypal personality disorders', 'Paranoid, avoidant and dependent personality disorders', 'Antisocial, Schizoid and affective personality disorders', 'B', 'Cluster A personality disorders (paranoid, schizoid, schizotypal) are characterized by odd/eccentric behavior with suspiciousness and social detachment. The other clusters are dramatic (B) or anxious (C). Per DSM/psychiatric nursing texts.', 'BScN', 'Paper II', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In drug dependence syndrome, there is:-', 'Reduced compulsion to take a substance', 'Increased anhedonia', 'Substance tolerance', 'd. Neglect of alternative pleasures', 'C', 'Dependence syndrome (ICD-10) features tolerance, a strong compulsion to use, withdrawal, and neglect of alternative pleasures. Option A (reduced compulsion) is wrong; substance tolerance is a core diagnostic feature. Per WHO ICD-10 as adopted in Kenya mental health guidelines.', 'BScN', 'Paper II', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The most persistent adverse effect of ECT is', 'Retrograde amnesia', 'Fractures', 'Seizures', 'd. Hypertension', 'A', 'The most persistent adverse effect of electroconvulsive therapy is memory impairment, particularly retrograde amnesia. Fractures and seizures are largely prevented by muscle relaxants/anesthesia. Per psychiatric nursing texts.', 'BScN', 'Paper II', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which is the primary goal of community health nursing?', 'To support and supplement the efforts of the medical profession in the promotion of health and prevention of', 'To enhance the capacity of individuals, families and communities to cope with their health needs', 'To increase the productivity of the people by providing them with services that will increase their level of health', 'To contribute to national development through promotion of family welfare, focusing particularly on mothers and children', 'B', 'The primary goal of community health nursing is to raise the health capacity/level of individuals, families, and communities so they can meet their own health needs. Options A/C/D are partial or supporting aims. Per Kenya community health nursing (NCK CHN syllabus).', 'BScN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('CHN is a community-based practice. Which best explains this statement?', 'The service is provided in the natural environment of people', 'The nurse has to conduct community diagnosis to determine nursing needs and problems', 'The service are based on the available resources within the community', 'Priority setting is based on the magnitude of the health problems identified', 'A', '"Community-based" means care is delivered where people live and work — their natural environment — rather than in an institution. The other options describe process/priority-setting, not the defining feature. Per community health nursing principles (NCK CHN syllabus).', 'BScN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Population- focused nursing practice requires which of the following processes?', 'Community organizing', 'Nursing, process', 'Community diagnosis', '. Epidemiologic process', 'C', 'Population-focused practice requires community diagnosis to identify the health needs and problems of the aggregate/population. Community organizing and the nursing process are individual/organizational tools. Per community/public health nursing (NCK CHN syllabus).', 'BScN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When the occupational health nurse employs ergonomic principles, she is performing which of her roles', 'Health care provider', 'Health educator', 'Health care coordinator', '.Environment manager', 'D', 'Applying ergonomic principles (fitting the workplace/task to the worker) is part of the occupational health nurse''s environment/hazard-management role. It is not direct care, education, or coordination. Per occupational health nursing (public health nursing texts).', 'BScN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is true of primary facilities?', 'They are usually government-run', 'Their services are provided on an out-patient basis', 'They are training facilities for health professionals', '. A community hospital is an example of this level of health facilities', 'B', 'Primary-level facilities (dispensaries/health centres) provide first-contact, mainly out-patient services. They are not defined by being government-run, training sites, or hospitals. Per Kenya health systems/KEPH.', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which is an example of the school nurse‘s health care provider function?', 'Requesting for BCG from the EPI store for school entrance immunization', 'Conducting random classroom inspection during measles epidemic', 'Taking remedial action on an accident hazard in the school playground', 'Observing places in the school where pupils spend their free times', 'A', 'Providing/organizing immunization (e.g., requesting BCG for school-entry vaccination) is a direct health-care-provider function of the school nurse. Inspection and observation are surveillance/coordination roles. Per Kenya school health/EPI (KEPI) guidelines.', 'BScN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which level of health facility is the usual point of entry of a client into the health care delivery system?', 'primary', 'Secondary', 'Intermediate', 'Tertiary', 'A', 'The primary-level facility (dispensary/health centre) is the usual point of entry into the health-care delivery system, from which clients are referred upward. Per Kenya health systems/KEPH referral structure.', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The public health nurse is the supervisor of rural health midwives. Which of the following is a supervisory function of the pubic health nurse', 'Referring cases or patients to the midwife', 'Providing technical guidance to the midwife', 'Providing nursing care to cases referred by the midwife', 'Formulating and implementing training programs for midwives', 'B', 'A supervisory function is providing technical guidance/support to the supervised midwife. Referring cases, giving direct care, and formulating training are non-supervisory or administrative tasks. Per community/public health nursing supervision principles.', 'BScN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The MOST reported type of child abuse in Kenya is', 'neglect', 'physical abuse', 'sexual abuse', 'psychological maltreatment', 'A', 'Neglect is the most commonly reported form of child abuse/maltreatment. Physical and sexual abuse are reported less frequently than neglect. Per Kenya child protection data / public health nursing.', 'BScN', 'Paper II', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Tertiary prevention is needed in which stage of the natural history of disease?', 'Pre-pathogenesis', 'pathogenesis', 'predromal', 'terminal', 'D', 'Tertiary prevention (rehabilitation, limiting disability/complications) is applied in the late/terminal stage of the natural history of disease when disease is established. Pre-pathogenesis relates to primary prevention and early pathogenesis to secondary. Per epidemiology/community health (NCK syllabus).', 'BScN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Isolation of a child with measles belongs to what level of prevention?', 'Primary', 'Community organization', 'Community study', 'Core group formation', 'A', 'Isolation of an infectious child prevents spread to susceptible contacts before they get ill; per Kenya Community Health/epidemiology principles, preventing disease occurrence in the well population is primary prevention. The other options (community organization/study/core group) are community-organizing steps, not levels of prevention.', 'BScN', 'Paper II', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In which step are plans formulated for solving community problems?', 'Mobilization', 'Community organization', 'Follow-up/extension', 'Core group formation', 'B', 'In the community organizing process, formulating plans to solve identified community problems occurs during the community organization/planning step; per Kenya Community Health Nursing texts. Mobilization is action, follow-up is later, and core group formation precedes planning.', 'BScN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which type of family-nurse contact will provide you with the best opportunity to observe family dynamics?', 'clinic consulation', 'group conferences', 'home visit', 'written communication', 'C', 'A home visit lets the nurse directly observe the family in its natural environment, giving the best opportunity to assess family dynamics and interactions; per Kenya Community Health Nursing texts. Clinic, group, and written contacts do not reveal the home environment.', 'BScN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is an advantage of a home visit?', 'It allows the nurse to provide nursing care to a greater number of people', '. It provides an opportunity to do first hand appraisal of the home situation', '. It allows sharing of experience among people with similar health problems', 'It develops the family’s initiative in providing for health needs of its members', 'B', 'The key advantage of a home visit is first-hand appraisal of the actual home and family situation; per Kenya Community Health Nursing texts. Reaching greater numbers (clinic) and sharing among peers (group) are advantages of other contact types.', 'BScN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which is CONTRARY to the principles in planning a home visit?', '. A home visit should have a purpose of objective', '. The plan should revolve around the family health .needs', 'A home visit should be conducted in the manner prescribed by the Health unit', 'Planning of continuing care should involve a responsible-family member', 'C', 'Per Kenya Community Health Nursing principles, a home visit is individualised to the family''s health needs and situation, not rigidly conducted in a manner prescribed by the health unit; A, B and D are correct principles, so C is CONTRARY.', 'BScN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is a function of epidemiology?', 'Identifying the disease condition based on manifestations presented by a client', 'Determining factors that contributed to the occurrence of pneumonia in a 3 year old', '. Determining the efficacy of the antibiotic used in the treatment of the 3 year old client with pneumonia', 'Evaluating the effectiveness of the implementation of the Integrated Management of Childhood Illness', 'B', 'Epidemiology studies the distribution and determinants (contributing factors) of disease in populations; per Kenya epidemiology/community health texts. Diagnosing an individual (A), judging drug efficacy for one client (C) and evaluating a specific program (D) are clinical/administrative, not the core epidemiologic function of identifying determinants.', 'BScN', 'Paper II', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is an epidemiologic function of the nurse during an epidemic?', 'Conducting assessment of suspected cases to detect the communicable diseases', '. Monitoring the condition of the cases affected by the communicable disease', 'Participating in the investigation to determine the source of epidemic', 'Teaching the community on preventive measures against the disease', 'C', 'The epidemiologic function of the nurse during an epidemic is participating in outbreak investigation to identify the source; per Kenya Community Health/epidemiology texts. Assessing cases, monitoring patients and health teaching are clinical/educational roles rather than the epidemiologic investigation function.', 'BScN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the legal basis of Primary Health Care approach in Kenya?', 'Alma Ata Declaration of PHC', 'Letter of Instruction', 'Presidential Decree No. 147', 'Presidential Decree 996', 'A', 'Primary Health Care is founded on the 1978 Alma-Ata Declaration, which Kenya adopted as the basis of its PHC approach; per Kenya health policy/community health texts. The presidential decrees and letter of instruction are distractors (foreign/administrative) not applicable in Kenya.', 'BScN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is a natality rate?', 'Crude birth rate', 'Neonatal mortality rate', '. Infant mortality rate', 'General fertility rate', 'A', 'Natality (birth) rates measure births in a population; crude birth rate is a natality rate; per Kenya epidemiology/biostatistics texts. Neonatal and infant mortality rates are mortality rates, and general fertility rate is a fertility (not natality) measure.', 'BScN', 'Paper II', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What numerator is used in computing general fertility rate?', 'Estimated midyear population', 'Number of registered live births', '. Number of pregnancies in the year', 'Number of females of reproductive age', 'B', 'General fertility rate uses number of live births as the numerator (denominator being women of reproductive age); per Kenya biostatistics/epidemiology texts. Midyear population and number of reproductive-age women are denominators, not the numerator.', 'BScN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which clients are considered targets for DOTS category?', 'Sputum negative cavitary cases', '. Clients returning after default', 'Relapses and failures of previous PTB treatment regimens', 'Clients diagnosed for the first time through a positive sputum exam', 'D', 'New smear-positive pulmonary TB cases (Category I) are the priority target for DOTS; per Kenya National TB Program guidelines. Smear-negative cavitary, returning-after-default, relapse and failure cases fall in other treatment categories.', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Nurse manager demonstrates passion for serving her staff rather than being served. She takes time to listen, prefers to be a teacher first before being a leader, which is characteristic of', 'Transformational leader', '. Transactional leader', '. Servant leader', 'Charismatic leader', 'C', 'A leader who prioritizes serving and listening to staff and teaches before leading exemplifies servant leadership; per nursing management/leadership theory. Transformational, transactional and charismatic styles emphasize vision, exchange, or personal magnetism rather than serving-first.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Chief Nurse Executive has charismatic leadership style. Which of the following behaviors best describes this style?', 'Possesses inspirational quality that makes followers gets attracted of him and regards him with reverence', '. Acts as he does because he expects that his behavior will yield positive results', 'Uses visioning as the core of his leadership', 'Matches his leadership style to the situation at hand', 'A', 'Charismatic leadership is defined by an inspirational personal quality that attracts followers who hold the leader in reverence; per nursing leadership theory. Expecting behavior to yield results is transactional, visioning is transformational, and matching style to situation is contingency/situational.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One leadership theory states that “leaders are born and not made,” which refers to which of the following theories?', 'trait', 'charismatic', 'great man', 'situational', 'C', 'The ''leaders are born not made'' premise defines the Great Man theory; per nursing management/leadership theory. Trait theory describes qualities, charismatic describes magnetism, and situational ties style to context.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following does NOT characterize a transactional leader?', 'Focuses on management tasks', 'Is a caretaker', '. Uses trade-offs to meet goals', 'Inspires others with vision', 'D', 'Transactional leaders focus on management tasks, act as caretakers, and use trade-offs/rewards; inspiring with vision is a transformational (not transactional) trait; per nursing leadership theory. Thus ''inspires others with vision'' does NOT characterize a transactional leader.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('the main elements of educational objective are', 'criterion, knowledge, skills', 'act, attitude, goal', 'knowledge, attitude, skills', 'perfomance, condition, standard', 'D', 'Per curriculum/instructional design theory (Mager''s behavioural objectives, NCK teaching methodology), a well-written educational (behavioural) objective has three elements: performance (behaviour), condition, and standard (criterion). This is the standard framework taught in nurse-education pedagogy.', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('formative evaluation is useful in evaluation because it', 'enable institutions to award grades, certification and licences', 'reveal students ability to apply learning at the end of the course', 'reveal the outcome of the learning at the end of the course', 'provides feedback on the strengths of the learner during the course', 'D', 'Per educational evaluation theory, formative evaluation is conducted DURING the learning process to provide ongoing feedback on learner strengths and weaknesses to improve learning. Grading/certification and end-of-course outcome assessment describe summative evaluation.', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('child neglect involves', 'physical aggression directed at a child', 'indecent exposure of the genital of a child', 'inappropriate and excessive demands on a child', 'inadequate provision of various needs of a child', 'D', 'Per child protection principles (Kenya Children Act; MOH/WHO child abuse classification), neglect is the failure/inadequate provision of a child''s basic needs (food, shelter, health, education, supervision). Physical aggression is physical abuse and indecent genital exposure is sexual abuse.', 'BScN', 'Paper II', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('under what level of measurement is marital status classified', 'nominal', 'ordinal', 'interval', 'ratio', 'A', 'Per research and biostatistics, marital status (single, married, divorced, widowed) is a categorical variable with no inherent order or numeric value, hence measured on the nominal scale. Ordinal implies ranking, interval/ratio imply numeric measurement.', 'BScN', 'Paper II', 'Research & Evidence-Based Practice', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following should be highly considered when counseling on family planning methods among HIV positive clients:', 'Drug interactions between hormonal methods and anti-tuberculosis drugs', 'The clients current stage of AIDS', 'The clients nutritional states', 'The clients economic status and source of funding', 'A', 'Per Kenya National Family Planning Guidelines, enzyme-inducing anti-TB drugs (rifampicin) reduce the efficacy of hormonal methods; TB co-infection is common in HIV, so drug interactions must be considered when counselling HIV-positive clients.', 'BScN', 'Paper II', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One characteristic of the causative organism of cholera is:-', 'A small comma motile organism found in the liver', 'A small comma-shaped motile organism found in salty water', 'A gram-negative bacillus found in contaminated food, water and milk', 'A gram-negative bacillus that spread rapidly', 'B', 'Vibrio cholerae is a small comma-shaped, motile (single flagellum) gram-negative organism that survives in salty/brackish water, per Kenya communicable disease references. This best describes its characteristic morphology.', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following is correct about clinical stage II of HIV/AIDS:-', 'Unexplained chronic diarrhea for more than 1 month', 'Oral hairy leukoplakia', 'Recurrent respiratory infections', 'Persistent generalized lymphadenopthy', 'C', 'Per WHO/Kenya HIV clinical staging, WHO Clinical Stage 2 includes recurrent upper respiratory tract infections. Chronic diarrhoea >1 month and oral hairy leukoplakia are Stage 3; persistent generalised lymphadenopathy is Stage 1.', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Implants work primarily by:-', 'Disrupting the menstrual cycle including preventing the release of eggs from the ovaries (ovulation)', 'Causing a chemical change that damages sperm and egg before they meet', 'Forming a barrier that keeps the sperms out of vagina', 'Causing the membrane of sperm cells to break killing or slowing their movement', 'A', 'Per Kenya National Family Planning Guidelines, progestin implants work primarily by suppressing ovulation (and thickening cervical mucus). Option A describes the primary ovulation-inhibiting mechanism; the others describe spermicides/barriers.', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The available methods for purifying water on an individual or domestic scale are:-', 'Super chlorination, filtration, iodine', 'Boiling, chemical disinfection, filtration', 'Filtration, rapid sand filtration, boiling', 'Storage, boiling, biological filtration', 'B', 'Per Kenya environmental/public health guidelines, domestic-scale water purification methods are boiling, chemical disinfection (chlorination/iodine) and filtration. Rapid sand filtration is a large-scale municipal method, not individual/domestic.', 'BScN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Repression as a type of defense mechanism may be defined as:-', 'Redirecting sexual aggression from a less acceptable to more acceptable behavior', 'Exclusion of unwanted thoughts from awareness', 'Making up for a personal deficit in one area', 'Substituting false reasons for real ones.', 'B', 'Per Kozier/psychiatric nursing texts, repression is the unconscious exclusion of painful or unwanted thoughts and impulses from awareness. Option A is sublimation, C is compensation, D is rationalisation.', 'BScN', 'Paper II', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Functions of education institutions include:-', 'Social integration, reduction of stress', 'Secondary socialization, cultural transmission', 'Social integration maintenance, social order', 'Innovation, humanitarianism', 'B', 'Per sociology/behavioural science references, key functions of educational institutions are secondary socialization and transmission of culture (plus innovation and social integration). Option B best captures the manifest functions of education.', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('While calculating infant mortality rate the correct formula is::-', 'IMR= Number of deaths of infants in one year x 100 Number of live births in the previous year', 'IMR = Number of deaths of infants in one year x 100 Number of live births in the same year', 'IMR = Number of deaths of infants in one year x 1000 Number of births in the same year', 'IMR = Number of deaths of infants in one year x 1000 Number of live births in the same year', 'D', 'Per epidemiology/biostatistics, Infant Mortality Rate = (deaths of infants <1 year in a year / live births in the same year) x 1000. The multiplier is 1000 and the denominator is live births in the same year.', 'BScN', 'Paper II', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Some principles of time management include:-', 'Priority setting, evaluating progress, minimal breaks', 'Time analysis, goal setting, delegation', 'Avoiding delegation, Time analysis, controlling interruptions', 'Time analysis, goal setting, minimal breaks', 'B', 'Per nursing management/leadership principles, effective time management includes time analysis, goal/priority setting and delegation. Options advocating ''avoiding delegation'' or ''minimal breaks'' are contrary to sound time management.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The four rights of delegation of duty in management are:-', 'Task, communication, time, feedback', 'Person, task, time, feedback', 'Task, time, person, communication', 'Task, person, communication, feedback', 'D', 'The classic ''rights of delegation'' in nursing management are the right task, right person (circumstance), right communication/direction and right feedback/evaluation. Option D lists these four rights.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which scale of measurement has an absolute zero?', 'Nominal', 'Ordinal', 'Interval', 'Ratio', 'D', 'Per biostatistics (research methods), the ratio scale is the only level of measurement with a true/absolute zero, allowing meaningful ratios (e.g. weight, height). Interval scales (e.g. Celsius) lack an absolute zero.', 'BScN', 'Paper II', 'Research & Evidence-Based Practice', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Whereas quantitative research tends to bring out a static picture of social life, qualitative research depicts it as', 'Symmetrical', 'Statistical', 'Processual', 'Proverbial', 'C', 'Per social research methodology, whereas quantitative research yields a static snapshot, qualitative research depicts social life as processual (unfolding as a process over time).', 'BScN', 'Paper II', 'Research & Evidence-Based Practice', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('You are asked to assess a 19-year-old woman on a medical ward who has taken an overdose of paracetamol tablets. Which of the following is not an indicator of intent:-', 'Taking precautions against discovery', 'Notifying a potential helper', 'Drinking a volume of alcohol sufficient to impair judgement', 'Leaving a suicide note', 'B', 'Per psychiatric assessment of suicidal intent, high intent is shown by precautions against discovery, disinhibiting alcohol use and leaving a suicide note. Notifying a potential helper indicates LOW intent (a wish to be found/rescued), so it is not an indicator of intent.', 'BScN', 'Paper II', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following represents a nursing intervention at the primary level of prevention', 'Teaching a class in parent effectiveness training', 'Leading a group of adolescents in drug rehabilitation', 'Referring a married couple for sex therapy', 'Leading a support group for battered women', 'A', 'Per Kenya Community Health Nursing levels of prevention, primary prevention prevents disease before it occurs through health promotion/education; teaching parent effectiveness training is health promotion, whereas rehabilitation and support groups for existing problems are secondary/tertiary prevention.', 'BScN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The most common comorbid condition in children with bipolar disorder is: -', 'Schizophrenia.', 'Substance disorders', 'Oppositional defiant disorder.', 'Attention deficit-hyperactivity disorder', 'D', 'Per standard psychiatric nursing texts (Kaplan & Sadock), ADHD is the most common comorbid condition in children with bipolar disorder, with overlapping symptoms of distractibility and hyperactivity.', 'BScN', 'Paper II', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following psychiatric disorders is MOST common among patients with bulimia nervosa:-', 'Alcohol use disorder', 'Major depressive disorder', 'Obsessive compulsive disorder', '.Panic disorder', 'B', 'Per Kaplan & Sadock''s psychiatry, major depressive disorder is the most common comorbid psychiatric disorder among patients with bulimia nervosa.', 'BScN', 'Paper II', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Clinicians tools needed to recognize early symptoms of mental disorders are called "Mental Health Action Signs".All the following are true EXCEPT', 'involvement in many fights, wanting to badly hurt others', 'not eating, throwing up, or using laxatives to make yourself lose weigh', 'feeling very sad or withdrawn for more than 2 months', 'sudden overwhelming fear for no reason', 'C', 'Per the Mental Health Action Signs framework, warning signs include severe aggression/wanting to badly hurt others, disordered eating with purging, and sudden overwhelming fear. The action sign for mood is feeling very sad or withdrawn for more than 2 WEEKS (not 2 months), so this altered option is the EXCEPTION/untrue statement.', 'BScN', 'Paper II', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('You are following a 6-year-old boy with autism, he is under structured psychosocial behavioral training program, there is frequent complains of aggression and self-injurious behavior.Of the following, the BEST medication to control his behavior is', 'methylphenidate', 'risperidone', 'escitalopram', 'amitriptyline', 'B', 'Risperidone is the FDA/WHO-approved atypical antipsychotic for irritability, aggression and self-injurious behaviour in autism (Kaplan & Sadock; standard paediatric pharmacology). Methylphenidate treats ADHD, escitalopram is an SSRI, amitriptyline a tricyclic — none is first-line for autism-related aggression.', 'BScN', 'Paper II', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Of the following, the MOST common presenting behavior in girls with attention-deficit/hyperactivity disorder (ADHD) is', 'inattentive', 'hyperactive', 'impulsive', 'disruptive', 'A', 'Girls with ADHD most commonly present with the predominantly inattentive type (daydreaming, poor focus) rather than overt hyperactivity/impulsivity, which is why they are under-diagnosed (Kaplan & Sadock; DSM-5).', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Whether a nurse’s plan of care for a community is acceptable is probably determined by which aspect of the plan?', 'It was created in coordination with community members.', 'It was financially feasible.', 'It was politically correct and feasible.', 'It was something in which the nurse really believes', 'A', 'Per Kenya Community Health Strategy and community health nursing principles, a plan of care is acceptable when developed in partnership with the community (community participation), ensuring ownership and sustainability.', 'BScN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is the most effective way of prioritizing nursing diagnoses?', 'Ensuring that the diagnoses are reimbursable by third-party payers', 'Determining the degree of community concern about the problem', 'Comparing the diagnoses with the agency’s mission statement', 'Discussing conclusions with another community health nurse', 'B', 'Per community health nursing practice, prioritising nursing diagnoses is most effectively done by gauging the community''s own perception/concern about the problem, which drives participation and effective intervention.', 'BScN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which one of the following is not included in the Elements of Primary Health Care?', 'Immunization services', 'Family planning services', 'Specialized services', 'Provision of essential drugs', 'C', 'Per WHO/Alma-Ata Primary Health Care elements as adopted in Kenya, immunization, family planning (MCH) and provision of essential drugs are core PHC elements; specialized (curative/referral) services are NOT part of the basic elements of PHC.', 'BScN', 'Paper II', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following are not necessary for a proper medical record?', 'Timely and legible entries', 'Accurate and complete entries', 'Corrections made by blacking out error', 'A logical progression of entries with reference to concurrent records and former entries', 'C', 'Per Kenya nursing documentation standards and legal record-keeping, corrections must be made by a single line through the error, dated and initialled — never by blacking out/obliterating, which is unacceptable in a proper medical record.', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Evaluation leads to all except', 'conflict', 'co-operation', '.feedback', 'critical thinking', 'A', 'Evaluation promotes feedback, co-operation and critical thinking as constructive outcomes (nursing education/management principles; Kozier & Erb). Conflict is not a legitimate aim/outcome of evaluation, making it the EXCEPT.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The ''nuclear family'' means:', 'a group of people sharing living accommodation and meals', 'a network of relatives extended within or between generations', 'the new family created when an adult leaves home and gets married', 'a two generation unit of parents and their children', 'D', 'Per sociology/community health texts, a nuclear family is a two-generation unit consisting of parents and their children, as distinct from the extended family (network of relatives across generations).', 'BScN', 'Paper II', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The term “tabula rasa” highlights the importance of in shaping behaviour.', 'genes', 'experience', 'nature', 'predestination', 'B', 'Per behavioural science, Locke''s ''tabula rasa'' (blank slate) doctrine holds that the mind at birth is empty and behaviour is shaped by experience/environment, emphasising nurture over genes and predestination.', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is not a defence mechanism?', 'projection', 'b regression', 'ingratiation', 'sublimation', 'C', 'Per psychiatric/behavioural science, projection, regression and sublimation are recognised ego defence mechanisms; ingratiation is a social-influence tactic, not a defence mechanism.', 'BScN', 'Paper II', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Students are passive in', 'Project method', 'Discovery method', 'Lecture method', 'Inquiry method', 'C', 'In the lecture method learners are passive recipients, whereas project, discovery and inquiry methods are learner-centred and active (educational methodology; nurse education principles).', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Black water fever is a special manifestation of malaria caused by;', 'P. falciparum', 'P. malariae', 'P. ovale', 'P. vivax', 'A', 'Per Kenya National Malaria Guidelines, blackwater fever (massive intravascular haemolysis with haemoglobinuria) is a severe complication associated with Plasmodium falciparum infection.', 'BScN', 'Paper II', 'Infection Prevention & Control', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Mosquitoes is/are the vector in the following disorder(s)', 'Onchocerciasis', 'Visceral leishmaniasis', 'African trypanosomiasis', 'Bancroftian filariasis', 'D', 'Per Kenya communicable disease control, mosquitoes transmit Bancroftian filariasis (Wuchereria bancrofti via Culex/Anopheles); onchocerciasis is spread by blackflies, leishmaniasis by sandflies, and trypanosomiasis by tsetse flies.', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which one is not the type of lesson plans on the basis of objectives', 'Micro lesson plan', 'Cognitive lesson plan', 'Affective lesson plan', 'Psychomotor lesson paln', 'A', 'On the basis of objectives (learning domains), lesson plans are classified as cognitive, affective and psychomotor (educational methodology). A micro lesson plan is classified by scope/duration, not by objective domain, making it the exception.', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The extent to which a community ,structure , services or geographic area is likely to be damaged or disrupted by the impact of particular hazard is termed as', 'Capacity', 'Vulnerability', 'Risk', 'Hazard assessment', 'B', 'Per disaster management/community health, vulnerability is the extent to which a community, structure, service or area is likely to be damaged or disrupted by the impact of a hazard.', 'BScN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which is not true about lesson plan', 'It is develops confidence', 'It helps in oderly delivny of contents', 'It is developed by students', 'It saves from haphazard teaching', 'C', 'A lesson plan builds teacher confidence, ensures orderly content delivery and prevents haphazard teaching, and is developed by the TEACHER, not by students (educational methodology). The statement that it is developed by students is therefore untrue.', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which stage of development is most unstable and challenging regarding the development of personal identity?', 'Adolescence', 'Toddlerhood', 'Childhood', 'Infancy', 'A', 'Per Erikson''s developmental theory, adolescence (identity vs role confusion) is the most unstable and challenging stage for the development of personal identity.', 'BScN', 'Paper II', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The continuous scrutiny of the factors determining the occurrence and dis-tribution of disease is called:', 'Opportunistic infection', 'Screening', 'Diagnosis', 'Surveillance', 'D', 'Per Kenya epidemiology/communicable disease control, surveillance is the continuous, systematic scrutiny of factors determining the occurrence and distribution of disease to guide public health action.', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The village health volunteer in the primary health care should:', 'Be a person from outside the community.', 'Be acceptable to some sections of the community', 'Have minimum formal education at least up to VIII standard', 'Should be able to spare two hours to three hours every week', 'D', 'Per primary health care/community health volunteer criteria, the village health volunteer should be from within and acceptable to the whole community and able to spare a few hours weekly; of the options given, being able to spare two to three hours each week is the valid requirement (being an outsider or acceptable to only some sections is incorrect).', 'BScN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When considering philosophy of education, John Dewey was a proponent of', 'Existentialism', 'Pragmatism', 'Idealism', 'Realism', 'B', 'John Dewey is the foremost proponent of Pragmatism (learning by doing/experience) in the philosophy of education; standard educational-foundations reference.', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The mode of intervention under secondary prevention are:', 'Health promotion (primary prevention)', 'Specific protection(primary)', 'Early diagnosis and prompt treatment', 'Rehabilitation(tertiary prevention)', 'C', 'Per Leavell & Clark levels of prevention (community health), secondary prevention consists of early diagnosis and prompt treatment; health promotion and specific protection are primary, and rehabilitation is tertiary.', 'BScN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Cognitive domain in Bloom’s Taxonomy includes all the following, except', 'Evaluation', 'Synthesis', 'Analysis', 'Criticism', 'D', 'Bloom''s cognitive domain levels are knowledge, comprehension, application, analysis, synthesis and evaluation; ''Criticism'' is not a level, making it the exception.', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Wholesome water is one which is:', 'Free from non-pathogenic agents', 'Free from harmful chemical sub-stances', 'Has color and odor', 'Usable for industrial purposes', 'B', 'Per environmental/public health, wholesome water is free from pathogenic organisms and harmful chemical substances, palatable and free from objectionable colour and odour; of the options, being free from harmful chemical substances is the defining feature.', 'BScN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Characteristics of Problem Based Learning include all, EXCEPT:', 'Learning is driven by challenging, open-ended, ill-defined and ill-structured problems.', 'Students generally work in collaborative groups.', 'The teacher is the authority', 'Teachers take on the role as "facilitators" of learning', 'C', 'In Problem-Based Learning the teacher is a facilitator, not the authority; learning is driven by ill-structured problems and collaborative group work, so ''the teacher is the authority'' is the exception.', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is not a 2-way communication?', 'Lectures', 'Group discussion', 'Panel discussion', 'Symposium', 'A', 'A traditional lecture is one-way communication (teacher to learners), whereas group/panel discussion and symposium involve exchange; standard communication/teaching-methods principle.', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The process of developing and providing planned experiences to supply information, change attitudes and influence behavior is?', 'Health promotion', 'Primary prevention', 'Communication', 'Health education', 'D', 'Health education is the planned provision of learning experiences to supply information, change attitudes and influence behaviour; health promotion is the broader umbrella including policy and environment (Kenya health promotion guidelines/WHO).', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Community health nursing is a community-based practice. Which best explains this answer?', 'The service is provided in the natural environment of people', 'The nurse has to conduct community diagnosis to determine nursing needs and problems', 'The service are based on the availability of resources within the community', 'Priority setting is based on the magnitude of the health problems identified.', 'A', 'Community-based practice means care is delivered where people live, work and play (their natural environment), not in an institution; this best explains the community-based nature of community health nursing.', 'BScN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following methods is used to remove permanent water hardness?', 'Boiling', 'Addition of sodium carbonate', 'Addition of lime', 'Chlorination', 'B', 'Permanent (non-carbonate) hardness is removed by chemical softening such as adding sodium carbonate (washing soda) or the lime-soda process; boiling removes only temporary hardness. Environmental health/water treatment reference.', 'BScN', 'Paper II', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('With regard to noise pollution, to what level of decibels, can people tolerate without substantial damage to their hearing?', '50-55dB', '60-65dB', '70-75dB', '80-85dB', 'D', 'People can generally tolerate noise up to about 80-85 dB without substantial hearing damage; sustained exposure above this level risks noise-induced hearing loss (occupational/environmental health standards).', 'BScN', 'Paper II', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is not a specific function of the school health services?', 'Determine the health status of each child.', 'Conduct a special screening programme which will disclose particular health problems.', 'Understanding the difference in the stages of growth and development.', 'Assist in maintaining the health of school personnel', 'C', 'Specific functions of school health services include determining each child''s health status, screening for problems and maintaining staff health; ''understanding the stages of growth and development'' is background knowledge, not a specific service function, so it is the exception.', 'BScN', 'Paper II', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following are examples of physical hazards?', 'Heat ,cold, vibrations, dust', 'Dust, vibrations, ionizing radiation', 'Ionizing radiation, vibrations, heat', 'Cold, asbestos, ionizing radiations', 'C', 'Physical hazards include heat, cold, noise, vibration and ionizing radiation; dust and asbestos are chemical hazards, so the option containing only physical agents (ionizing radiation, vibrations, heat) is correct (occupational health).', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The health-belief model is composed of one of the following factors:', 'Psychological factors', 'Modifying factors', 'Social factors', 'Environmental factors', 'B', 'The Health Belief Model comprises individual perceptions, modifying factors (demographic, socio-psychological cues) and likelihood of action; ''modifying factors'' is a recognised component of the model.', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Teaching breast self-examination falls under which level of disease prevention:', 'Primary', 'Secondary', 'Tertiary', 'Quaternary', 'B', 'Breast self-examination is a screening/early-detection activity, which is secondary prevention (early diagnosis of disease already possibly present); primary prevention would prevent onset (Leavell & Clark).', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The form of immunity provided by B cells through immunoglobulin; IgA, IgD, IgM is best referred to as:-', 'Cellular immunity', 'Herd immunity', 'Humoral immunity', 'Vaccine immunity', 'C', 'Immunity mediated by B cells producing immunoglobulins (IgA, IgD, IgM, IgG, IgE) is humoral (antibody-mediated) immunity; cellular immunity is T-cell mediated (immunology/microbiology).', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following vaccine is live attenuated?', 'Yellow fever', 'Rabies', 'Diphtheria', 'Influenza', 'A', 'Yellow fever vaccine is a live attenuated vaccine; rabies and influenza (injectable) are inactivated and diphtheria is a toxoid (KEPI/WHO immunization).', 'BScN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What type of acquired immunity is acquired through inoculation of an antigen?', 'Natural active immunity', 'Artificial passive immunity', 'Natural passive immunity', 'Artificial active immunity', 'D', 'Immunity acquired by inoculation (vaccination) of an antigen, prompting the host to make its own antibodies, is artificial active immunity; passive immunity involves receiving preformed antibodies. Immunology/immunization principles.', 'BScN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is not a driving force for the adoption of the electronic health record?', 'Lower health care costs', 'Improving joint commission scores', 'Fragmented clinical data across the different healthcare settings', 'Reduce incorrect diagnosis', 'B', 'Driving forces for EHR adoption include lowering costs, integrating fragmented clinical data and reducing incorrect diagnoses; improving Joint Commission accreditation scores is not a primary driving force, making it the exception (health informatics).', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Sustainable development 1 is about poverty. What is the aim of this goal?', 'Cut poverty in half by 2030', 'Reduce poverty by 75% by 2030', 'End poverty in all its forms everywhere', 'Help each nation make progress on reducing poverty', 'C', 'SDG 1 aim is ''End poverty in all its forms everywhere'' by 2030; halving or reducing by a percentage were older MDG-style targets (UN Sustainable Development Goals).', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Maternal mortality is expressed in?', 'Per 100', 'Per 1000', 'Per 10,000', 'Per 100,000', 'D', 'The maternal mortality ratio is conventionally expressed per 100,000 live births (Kenya MOH / WHO reproductive health indicators).', 'BScN', 'Paper II', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Sentinel surveillance is', 'Reporting of a disease by the health workers', 'Collection and analysis of data by a designated specialized institution', 'Correction and analyses of data by the health workers', 'Notifying of diseases by community volunteers', 'B', 'Per Kenya MOH/WHO surveillance guidelines, sentinel surveillance uses selected designated (sentinel) sites/institutions to collect and analyse data on a health event, giving high-quality data at lower cost than universal reporting.', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In the principles of primary health care, accessibility considers the following except', 'Elements of integrated services.', 'People''s awareness.', 'Transport and road network', 'Social status of community members.', 'D', 'In PHC principles, accessibility concerns physical/geographic reach (transport, road network), awareness of services and integration of services; social status relates to acceptability/equity, not accessibility, so it is the exception.', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Community oriented roles of a community health nurse include', 'Case finder, care manager, counselor', 'Direct patient care, case finder, care manager', 'Care manager, counselor, primary health care provider', 'Primary health care provider, care manager, health educator.', 'A', 'Community-oriented (population-focused) roles of the community health nurse include case finder, care manager and counselor; direct patient care is a client-oriented role, making option A the community-oriented set (community health nursing texts, NCK community health curriculum).', 'BScN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Community health action is defined as the process of', 'Gathering information on the health problems affecting the community', 'Analyzing the community health problem in order to plan for intervention', 'Providing health services to the community based on the identified problems', 'Identifying the health facilities available within the community', 'C', 'Community health action is the intervention/action step of the community health process: implementing/providing services to address problems already identified and analysed, as opposed to assessment (gathering/analysing information).', 'BScN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Factors that may affect the effectiveness of a home visit include:', 'The family feeling that they are viewed as dysfunctional, difficult to schedule visits.', 'Health workers have control over the home setting, making it difficult to schedule visits.', 'The family feeling that they are being viewed as dysfunctional, it is expensive for the client.', 'The health worker has control over the home setting, the family feeling that they are being viewed as dysfunctional', 'C', 'Genuine disadvantages of home visiting are the family feeling stigmatised/viewed as dysfunctional and the high cost (time and money); the nurse does NOT have control over the home setting, so options citing that are incorrect.', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following concepts would enable the nurse to provide holistic care for culturally diverse clients', 'Cultural conflicts', 'Ethnocentrism', 'Stereotyping', 'Cultural brokering', 'D', 'Cultural brokering (bridging/mediating between the client''s culture and the health system) supports holistic, culturally competent care; cultural conflict, ethnocentrism and stereotyping are barriers to it (transcultural nursing, Kozier Fundamentals).', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Max Weber is known for the development of which management theory?', 'Bureaucratic management', 'Scientific management', 'Humanistic management', 'Transformational leadership', 'A', 'Max Weber is credited with the bureaucratic theory of management (hierarchy, rules, division of labour); scientific management is Taylor''s, per nursing management/leadership texts.', 'BScN', 'Paper II', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Job specifications refer to:', 'Principal duties and responsibilities', 'Function elements of a position', 'Human qualities necessary to perform a job', 'Interdepartmental relationship', 'C', 'In human resource management, a job specification lists the human attributes (qualifications, skills, experience) needed to perform a job, whereas the job description lists duties and responsibilities (nursing management texts).', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following would provide quantitative information about the community?', 'observation of the target population in its community setting', 'talking with individuals within the community who know the target population well', 'data from CDCs Morbidity and Mortality Weekly Report', 'interviewing key informants', 'C', 'Quantitative data are numerical/statistical; morbidity and mortality report data are quantitative, whereas observation, talking with community members and interviewing key informants yield qualitative information (research/community assessment methods).', 'BScN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Specific, measurable actions of the desired outcome to be completed within a specific time frame is the definition of:', 'Goals', 'Objectives', 'Long term plan', 'Procedures', 'B', 'Objectives are specific, measurable, time-bound statements of desired outcomes; goals are broad and general. This matches the SMART/objective definition in nursing management and community health planning.', 'BScN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The primary purpose of providing employees with feedback during a performance appraisal is to motivate employees to _', 'apply for managerial positions', 'remove any performance deficiencies', 'revise their performance standards', 'enroll in work-related training programs', 'B', 'The primary purpose of appraisal feedback is developmental: to motivate employees to correct/remove performance deficiencies and improve performance (nursing management/leadership texts).', 'BScN', 'Paper II', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('SMART goals are best described as', 'specific, measurable, attainable, relevant, and timely', 'straight forward, meaningful, accessible, real, and tested', 'strategic, moderate, achievable, relevant, and timely', 'specific, measurable, achievable, relevant, and tested', 'A', 'SMART = Specific, Measurable, Attainable (achievable), Relevant, Timely/Time-bound; option A gives this standard expansion used in planning and management.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('which public health Act is responsible for securing and maintaining health', 'Cap 242', 'Cap 257', 'Cap 280', 'Cap 302', 'A', 'In Kenya the Public Health Act is Chapter 242 (Cap 242) of the Laws of Kenya — the principal statute for securing and maintaining public health. (Kenya Public Health Act, Cap 242.)
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('which of the following is the advantage of integration of services', 'save time and money for the nurse', 'improves immunization coverage', 'patients are integrated in the approach', 'there is high chance of cross infection between sick and health especially children', 'A', 'Integration of services allows a client to receive several services in one visit, saving time and resources for both client and provider and reducing missed opportunities; cross-infection risk is a disadvantage, not an advantage.', 'BScN', 'Paper II', 'Infection Prevention & Control', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Onchocerciasis is a vector borne disease which is transmitted by', 'Sandfly', 'black fly', 'female anopheles mosquito', 'house fly', 'B', 'Onchocerciasis (river blindness) is transmitted by the black fly (Simulium species); sandfly transmits leishmaniasis and anopheles transmits malaria (Kenya communicable disease control guidelines).', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('the stage of a natural history of disease at which secondary prevention is needed is', 'terminal', 'prodromal', 'pre-pathogenesis', 'pathogenesis', 'D', 'Secondary prevention (early diagnosis and treatment) is applied during the pathogenesis stage of the natural history of disease, early in the clinical/subclinical course; pre-pathogenesis calls for primary prevention (epidemiology).', 'BScN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('controlling is a managerial function which involves', 'contributing to a purposeful organization of work', 'reducing costs and directing efforts towards desired results', 'measuring and correcting the performances of employees', 'integration and coordination of activities', 'C', 'Controlling is the management function of measuring performance against standards and taking corrective action; organising and coordinating are separate functions (nursing management theory).', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('the activities that nurse engages in during preparatory phase of a home visit include', 'location of the house', 'clarifying sources of referral', 'recording and reporting', 'analyzing community references', 'B', 'During the preparatory/pre-visit phase of a home visit the nurse reviews the referral and clarifies its source, gathers records and plans the visit; locating the house and recording/reporting occur in later phases.', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('the occupational disease that persons working in information technology are likely to develop is', 'lead poisoning', 'radiation sickness', 'mesothelioma', 'carpal tunnel syndrome', 'D', 'Repetitive keyboard/computer work is a recognised occupational risk for carpal tunnel syndrome (repetitive strain injury); lead poisoning, radiation sickness and mesothelioma relate to other occupations (occupational health).', 'BScN', 'Paper II', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('causative organisms for yaws is', 'Tryponosoma cruzi', 'Treponema carateum', 'Treponema pallidum', 'Treponema pertenue', 'D', 'Yaws is caused by Treponema pallidum subspecies pertenue; T. pallidum (subsp. pallidum) causes venereal syphilis and T. carateum causes pinta (microbiology/communicable disease references).', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('fat soluble vitamins includes', 'A,D,C,E', 'A,D,E,K,', 'E,D,C,K', 'A,B,C,D', 'B', 'The fat-soluble vitamins are A, D, E and K (mnemonic ADEK); C and B are water-soluble. Per Kozier & Erb''s Fundamentals / nutrition texts used in Kenyan training.', 'BScN', 'Paper II', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The number of cases of Dengue fever usually increases towards the end of the rainy season. This pattern of occurrence of Dengue fever is best described as;', 'Epidemic occurrence', 'Cyclical variation', 'Sporadic occurrence', 'Secular occurrence', 'B', 'A regular, predictable rise in cases tied to a recurring season (end of rains) is a seasonal/cyclical variation, not an unpredictable epidemic or long-term secular trend. Per epidemiology (Park''s / Kenya CDC control principles).', 'BScN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('You will not give DPT 2 if the mother says that the infant had?', '.Seizures a day after DPT1', '. Fever for 3 days after DPT1', '.Abscess formation after DPT1', '. Local tenderness for 3 days after DPT1', 'A', 'Seizures/encephalopathy following a previous pertussis-containing dose is a contraindication to further DPT; fever, local tenderness and abscess are not. Per Kenya KEPI immunization guidelines.', 'BScN', 'Paper II', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Current concept of health promotion and the related activities lead to:', 'Better treatment of a problem', 'Critical awareness and life style changes', 'Adoption of prophylactic services', 'Better health services usage', 'B', 'Modern health promotion (Ottawa Charter) empowers people through critical awareness and lifestyle change rather than mere treatment or service usage. Per WHO/Kenya community health nursing.', 'BScN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Objectives of the health services include each of the following except:', 'Delivery of curative care only', 'Health promotion', 'Prevention control, or eradication of disease', 'Treatment and rehabilitation', 'A', 'Health service objectives include promotion, prevention, treatment and rehabilitation; ''curative care only'' is the exception because it excludes the other functions. Per Kenya health systems / community health.', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Loss of anatomical structure or physiological function is known as:', 'Disease', 'Disability', 'Handicap', 'Impairment', 'D', 'WHO ICIDH defines impairment as loss/abnormality of anatomical structure or physiological function; disability is activity limitation and handicap is social disadvantage. Per WHO/Kenya community health nursing.', 'BScN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When there is a cholera outbreak in a community, as a community health nurse, you have to carry out the following except', 'Notification', 'Oral rehydration therapy & tetracycline', 'Immunization of the at risk population', 'Chlorination of wells once a week', 'C', 'Cholera outbreak response is notification, ORT/antibiotics and water chlorination; mass immunization is NOT a routine first-line outbreak measure in the Kenyan CHN response, so it is the exception. Per Kenya cholera outbreak control guidelines.', 'BScN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The source of disease in transmission cycle means:', 'One who disseminates the disease agent to host', 'Disease agent multiplies and increases in number on storage', 'Storage of disease producing organisms', 'Receiver of disease agent', 'A', 'The source in the chain of transmission is the person/animal/object that disseminates the agent to a susceptible host; a reservoir merely stores it. Per epidemiology / Kenya communicable disease control.', 'BScN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Meeting basic goal of health promotion is;', 'Health', 'No illness', 'Wellness', 'Absence of diseases', 'C', 'The basic goal of health promotion is optimal wellness (positive well-being), which is broader than mere absence of disease/illness. Per WHO health promotion / Kenya community health.', 'BScN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Ottawa charter 1986 is related to:', 'Reproductive health', 'Health promotion', 'Primary Health care', 'Population development', 'B', 'The 1986 Ottawa Charter is the foundational WHO document on health promotion. Per WHO/Kenya community health nursing.', 'BScN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is not included in the eight elements of PHC?', 'Essential drugs', 'Safe drinking water and sanitation', 'Maternal and child health', 'Occupational health', 'D', 'The eight essential elements of PHC (Alma-Ata) include essential drugs, water/sanitation and MCH but NOT occupational health. Per WHO Alma-Ata / Kenya PHC.', 'BScN', 'Paper II', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Vitamin A is not related to,', 'Retinol', 'Keratocornea', 'Keratomalacia', 'Rickets', 'D', 'Vitamin A relates to retinol and to eye lesions (keratomalacia, corneal changes); rickets is a vitamin D deficiency, so it is NOT related to vitamin A. Per Kenya nutrition guidelines.', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Bitot’s spot’ is the characteristic feature of............. deficiency', 'Calcium', 'Vitamin D', 'Vitamin A', 'Vitamin C', 'C', 'Bitot''s spots (foamy conjunctival patches) are a classic sign of vitamin A deficiency/xerophthalmia. Per Kenya nutrition / IMNCI guidelines.', 'BScN', 'Paper II', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The measurement rate that is used to determine the number of new cases of a disease over an interval of time is:-', 'Incidence rate', 'Prevalence rate', 'Case fatality rate', 'Endemicities', 'A', 'Incidence measures the number of NEW cases over a defined time period; prevalence counts all existing cases. Per epidemiology / Kenya communicable disease control.', 'BScN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Water-washed diseases include:-', 'Typhoid, poliomyelitis', 'Scabies, Trachoma', 'Amoebiasis, cholera', 'Malaria, schistosomiasis', 'B', 'Water-washed diseases result from inadequate water quantity/hygiene (scabies, trachoma); typhoid/cholera/amoebiasis are water-borne and malaria/schistosomiasis are water-related. Per Kenya environmental health classification (Bradley).', 'BScN', 'Paper II', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The clinical features of onchocerciasis include:', 'Severe itching, skin nodules, dermatitis, river blindness', 'Pyrexia, septicaemia, skin pigmentation', 'River blindness, pyrexia, dermatitis', 'Septicaemia, pruritis, river blindness, hepatomegaly', 'A', 'Onchocerciasis presents with intense pruritus, subcutaneous nodules, dermatitis and ocular disease (river blindness); septicaemia/hepatomegaly are not features. Per Kenya communicable disease control.', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the sugar is least cariogenic', 'Glucose.', 'Sucrose.', 'Lactose.', 'd) Xylitol', 'D', 'Xylitol is non-fermentable by oral bacteria and is least cariogenic (indeed anti-cariogenic); glucose, sucrose and lactose are all fermentable sugars. Per nutrition/oral health references.', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Non-digestible food ingredients that stimulate the growth and activity of certain bacteria in the colon are called:-', 'Insoluble fiber', 'Probiotics', 'Prebiotics', 'd) Cellulose', 'C', 'Prebiotics are non-digestible food ingredients that selectively stimulate growth/activity of beneficial colonic bacteria; probiotics are the live organisms themselves. Per nutrition references.', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The distribution and frequency of disease in population is explained in:-', 'Cross-sectional studies', 'Ecological studies', 'Experimental studies', 'Descriptive studies Type 4 Primarily Research and Mental Health', 'D', 'Descriptive epidemiological studies describe the distribution and frequency (person, place, time) of disease in a population; analytic/experimental studies test associations. Per research & epidemiology (Paper II). Stray trailing label in the option is disregarded.', 'BScN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Ideally abstract should be about how many words: -', '50-75', '75-100', '150-175', '250-300', 'D', 'Standard research-writing conventions (used in NCK research modules) recommend a structured abstract of about 250-300 words; shorter ranges are insufficient to summarise objectives, methods, results and conclusion.', 'BScN', 'Paper II', 'Research & Evidence-Based Practice', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is nurse’s related barrier in utilization of research in nursing practices:-', 'Lack of motivation, knowledge and confidence', 'Inadequacies of nursing research methodologies', 'Lack of cooperation by physician to implement new research findings', 'Lack of quality nursing research publications', 'A', 'Nurse-related (individual) barriers to research utilisation are personal attributes: lack of motivation, knowledge and confidence to appraise/implement findings. The other options are setting- or profession-level barriers, not nurse-related (Polit & Beck, nursing research texts).', 'BScN', 'Paper II', 'Research & Evidence-Based Practice', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which level of evidence is most often placed at the top of the hierarchy of evidence for practice decisions:-', 'Meta-analysis for multiple randomized clinical trials', 'Results from a single well-controlled experimental study', 'A consensus of opinion from a group of experts on the topic', 'Case-control studies', 'A', 'In the evidence hierarchy, systematic reviews/meta-analyses of RCTs sit at the top because they synthesise the strongest experimental evidence; expert opinion and case-control studies rank lower (evidence-based practice pyramid).', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The basic research is conducted with which of the following as the aim:-', 'To make a decision', 'To develop knowledge for immediate use', 'To develop or refine theories and principles', 'To provide a solution for new problems', 'C', 'Basic (pure) research aims to generate/refine theories and principles to expand knowledge, not for immediate application; applied research seeks immediate practical solutions (nursing research methodology texts).', 'BScN', 'Paper II', 'Research & Evidence-Based Practice', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is a characteristic of qualitative research:-', 'Generalization to the population', 'Random sampling', 'Unique case orientation', 'Standardized tests and measures', 'C', 'Qualitative research is characterised by unique case orientation and in-depth, context-rich exploration; generalisation, random sampling and standardized measures are hallmarks of quantitative research (Polit & Beck).', 'BScN', 'Paper II', 'Research & Evidence-Based Practice', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following pairs contain hypotheses that are similar to each other:-', 'Simple and complex', 'Associative and causal', 'Directional and causal', 'Null and complex', 'B', 'Associative and causal hypotheses are the recognised pair classified by the type of relationship they predict between variables; the other pairings mix unrelated classification schemes (nursing research texts).', 'BScN', 'Paper II', 'Research & Evidence-Based Practice', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is not a source to develop conceptual framework:-', 'Researcher’s own experience', 'Previous research findings', 'Historical facts', 'Concepts of theories', 'C', 'Conceptual frameworks are developed from the researcher''s own experience, previous research findings and concepts/theories; isolated historical facts are not a recognised source for building a conceptual framework (research methodology texts).', 'BScN', 'Paper II', 'Research & Evidence-Based Practice', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is a research design:-', 'A way of conducting research that is not grounded in theory', 'The choice between using qualitative or quantitative methods', 'The process in which you present your research findings e.g a graph', 'A framework for every stage of the collection and analysis of data', 'D', 'A research design is the overall blueprint/framework guiding every stage of data collection and analysis; it is not merely the qualitative/quantitative choice nor how findings are presented (Polit & Beck).', 'BScN', 'Paper II', 'Research & Evidence-Based Practice', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Consider this title: ‘The Live Experience of Surviving a Tsunami’. This title would indicate which of the following types of qualitative research: -', 'Ethnographic', 'Phenomenological', 'Action', 'Historical', 'B', '''The Lived Experience of...'' signals phenomenology, which studies the lived experience/meaning of a phenomenon; ethnography studies cultures and historical research studies past events (qualitative research texts).', 'BScN', 'Paper II', 'Research & Evidence-Based Practice', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following studies would require the largest sample size:-', 'Correlational', 'Ethnography', 'Grounded theory', 'Phenomenological', 'A', 'Correlational (quantitative) studies require large samples for statistical power, whereas qualitative designs (ethnography, grounded theory, phenomenology) use small purposive samples to saturation (research methodology texts).', 'BScN', 'Paper II', 'Research & Evidence-Based Practice', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following principles is followed to determine the sample size for qualitative research: -', 'The ‘thumb rule’', 'The ‘rule of 30’', 'Data saturation', 'Power analysis', 'C', 'Sample size in qualitative research is guided by data saturation (sampling until no new themes emerge); power analysis and rules of thumb apply to quantitative designs (Polit & Beck).', 'BScN', 'Paper II', 'Research & Evidence-Based Practice', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is not one of the six major methods of data collection that are used by educational researchers:-', 'Observation', 'Questionnaires', 'Interviews', 'Checklists', 'D', 'The six major data-collection methods are tests, questionnaires, interviews, focus groups, observation and secondary/existing data; checklists are a tool used within observation, not one of the six methods (educational research texts).', 'BScN', 'Paper II', 'Research & Evidence-Based Practice', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which percent confidence interval will be the widest (i.e., the least precise) for a particular data set that includes exactly 500 cases: -', '99%', '92%', '95%', '90%', 'A', 'For a fixed sample size, a higher confidence level requires a wider interval; 99% gives the widest (least precise) confidence interval compared with 90-95% (biostatistics).', 'BScN', 'Paper II', 'Research & Evidence-Based Practice', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The literature review should occur: -', 'Near the end of the research process', 'Shortly before the analysis of the problem', 'Early in the research process', 'After research process', 'C', 'The literature review is conducted early to refine the problem, identify gaps and inform the design; it precedes data collection and analysis (research methodology texts).', 'BScN', 'Paper II', 'Research & Evidence-Based Practice', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The process of selecting a subset of population for survey is known as:-', 'Survey research', 'Representation', 'Triangulation', 'D. Sampling', 'D', 'Selecting a subset (sample) from a population for study is by definition sampling; triangulation and survey research are different concepts (Polit & Beck).', 'BScN', 'Paper II', 'Research & Evidence-Based Practice', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Ex-post facto studies are also called:-', 'Exploratory', 'Correlational', 'Longitudinal', 'D. Descriptive', 'B', 'Ex-post facto (after-the-fact) research examines existing groups without manipulation and is a form of correlational/causal-comparative research; it is non-experimental (research methodology texts).', 'BScN', 'Paper II', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which form of reasoning is the process of drawing a specific conclusion from a set of premises:-', 'Rationalism', 'Deductive reasoning', 'Inductive reasoning', 'D. Probabilistic', 'B', 'Deductive reasoning moves from general premises to a specific conclusion; inductive reasoning moves from specific observations to general conclusions (research/logic texts).', 'BScN', 'Paper II', 'Research & Evidence-Based Practice', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following cannot be considered as component of the research problem:-', 'Research study tools', 'Variables', 'Study population', 'Research setting', 'A', 'Components of a research problem include the variables, study population and research setting; the research instruments/tools are part of methodology, not a component of the problem statement itself (research methodology texts).', 'BScN', 'Paper II', 'Research & Evidence-Based Practice', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following can be used to treat extrapyramidal side effects of antipsychotic drugs except:', 'Benzhexol.', 'Amantadine', 'Propranolol.', 'D. Clozapine', 'D', 'Benzhexol (anticholinergic), amantadine and propranolol are used to treat extrapyramidal side effects; clozapine is an antipsychotic itself, not a treatment for EPSE (psychopharmacology texts).', 'BScN', 'Paper II', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The most common cause of mood congruent delusion is:', 'Obsessive-compulsive neurosis', 'Schizophrenia', 'Dementia', 'Mania', 'D', 'Mood-CONGRUENT delusions (whose content matches the prevailing mood — e.g. grandiose delusions in elevated mood) are characteristic of MOOD disorders. Among the options, mania is the mood disorder, so it is the classic cause of mood-congruent delusions; schizophrenic delusions are typically mood-incongruent (Kaplan & Sadock; standard psychiatric nursing references).', 'BScN', 'Paper II', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Psychosis is characterized by all, except:', 'Contact with reality is maintained', 'Positive symptoms are usually present', 'Impaired judgment', 'Insight is lost.', 'A', 'Psychosis is defined by LOSS of contact with reality, positive symptoms, impaired judgment and lost insight; therefore ''contact with reality is maintained'' is the exception (psychiatry texts).', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Major tranquillizers', 'Have antipsychotic effects', 'Are commonly indicated in management of manic episodes', 'Are used to prevent extra pyramidal side effects', 'They cause muscles relaxation', 'A', 'Major tranquillisers is the classic term for antipsychotics (neuroleptics), which act by dopamine blockade to produce antipsychotic effects (Brunner & Suddarth / standard psychiatric pharmacology). They in fact CAUSE extrapyramidal side effects rather than prevent them, and mood stabilisers/lithium are first-line for mania.', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Hippocrates classified mental disorders in to:', 'Major and minor mental illness', 'Psychosis and neurosis', 'Schizophrenia, mania and depression', 'Mania, melancholia and phrenitis', 'D', 'Hippocrates historically classified mental disorders into mania, melancholia and phrenitis (Kaplan & Sadock / history of psychiatry). Psychosis/neurosis and modern diagnostic categories are much later constructs.', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The belief expressed by one of your clients that an alien is creating sores on his body with a knife is classified as: -', 'Idea of reference', 'Neologism', 'Delusions', 'D. Depersonalization :', 'C', 'A fixed false belief not amenable to reason (an alien cutting sores on him) is a delusion (persecutory/somatic) per standard psychiatric nursing texts. Idea of reference and neologism describe different phenomena, and depersonalization is a self-perception disturbance.', 'BScN', 'Paper II', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The best approach for the mental health nurse to take when a client thinks his food is poisoned is to:-', 'assure the client that all food served on the hospital is safe to eat.', 'obtain an order for a tube feeding for the client.', 'provide the client with food in unopened containers.', 'tell the client that irrational thinking is detrimental to good health', 'C', 'For a paranoid client fearing poisoned food, providing sealed/unopened containers reduces suspicion and promotes nutrition without arguing with the delusion (psychiatric nursing standard). Reassuring, arguing rationality, or tube feeding do not respect the therapeutic principle of not challenging delusions directly.', 'BScN', 'Paper II', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What nursing action would be most effective in changing the behavior of a child diagnosed with attention deficit hyperactivity disorder (ADHD):-', 'Reward appropriate behavior', 'Sedate the child for acting out', 'Use aggressive punishment to control undesired behavior', 'Use lengthy time out session', 'A', 'Positive reinforcement (rewarding appropriate behaviour) is the most effective behaviour-modification strategy for ADHD (psychiatric nursing). Sedation, aggressive punishment and lengthy time-outs are ineffective and inappropriate.', 'BScN', 'Paper II', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following nursing diagnoses would be considered the priority in planning care for the autistic child:-', 'Risk for self-mutilation evidenced by banging head against wall', 'Impaired social interaction evidenced by unresponsiveness to people', 'Impaired verbal communication evidenced by absence of verbal expression', 'Disturbed personal identity evidenced by inability to differentiate self from others', 'A', 'Using Maslow/safety prioritisation, physical safety takes precedence, so risk for self-mutilation (head-banging) is the priority diagnosis for the autistic child (psychiatric nursing). Impaired interaction and communication, though characteristic, are not immediately life/safety threatening.', 'BScN', 'Paper II', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The child with conduct disorder will likely to demonstrate:-', 'Distractibility', 'Ritualistic behaviour', 'Serious violation of age related norms', 'Preference to inanimate object', 'C', 'Conduct disorder is defined by a repetitive pattern of behaviour violating the basic rights of others and major age-appropriate societal norms (DSM/psychiatric nursing). Distractibility suggests ADHD and ritualistic behaviour suggests OCD/autism.', 'BScN', 'Paper II', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('During psychiatric interview patient retains a constellation of ideas long after they have ceased to be appropriate. E.g. “where do you live?”, “London”, “How old are you”, “London. The term used to explain the condition is:-', 'Perseveration', 'Mannerisms', 'Ambivalence', 'D. Echopraxia', 'A', 'Persistent, inappropriate repetition of the same response (answering ''London'' to unrelated questions) is perseveration (psychiatric mental status examination). Mannerisms, ambivalence and echopraxia (imitating movements) describe different phenomena.', 'BScN', 'Paper II', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following nursing diagnoses would be most appropriate for a client with schizotypal personality disorder:-', 'Ineffective coping related to repetitive behaviour such as hand washing', 'Risk for self-mutilation related to social anxiety', 'Risk for violence toward others related to lack of remorse for behaviours', 'Impaired thought processes related to ideas of reference and magical thinking', 'D', 'Schizotypal personality disorder is characterised by cognitive-perceptual distortions such as ideas of reference and magical thinking, making impaired thought processes the appropriate diagnosis (psychiatric nursing). Compulsive hand-washing, self-mutilation and lack of remorse point to other disorders.', 'BScN', 'Paper II', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following nursing diagnoses would be appropriate for a client with an avoidant personality disorder:-', 'Risk for self-mutilation related to a desperate need for attention', 'Ineffective coping related to negative attitudes toward health behaviour', 'Anxiety related to fear of criticism, disapproval, and rejection', 'Risk for injury related to uncontrolled anger and hostility toward others', 'C', 'Avoidant personality disorder centres on social inhibition and hypersensitivity to criticism/rejection, so anxiety related to fear of criticism and rejection is appropriate (psychiatric nursing). Self-mutilation, poor health attitudes and uncontrolled anger fit other personality disorders.', 'BScN', 'Paper II', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Leo Kanner is known for his studies on:-', 'Autism', 'Schizophrenia', 'Bipolar disorders', 'Personality disorders', 'A', 'Leo Kanner first described early infantile autism in 1943 and is renowned for his studies on autism (history of child psychiatry).', 'BScN', 'Paper II', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is considered to be most effective and treatment of choice for phobic disorders:-', 'Behaviour therapy', 'Interpersonal psychotherapy', 'Family therapy', 'D. Psychoanalysis', 'A', 'Behaviour therapy (systematic desensitisation/exposure) is the treatment of choice for phobic disorders (psychiatric nursing / CBT evidence). Psychoanalysis, family and interpersonal therapy are less effective for specific phobias.', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is nursing education?', 'educating children about nurses', 'specific training a nurse receives to be qualified to work with patients.', 'training teachers to teach nurses', 'educating families of nurses', 'B', 'Nursing education is the specific formal training preparing a nurse to be qualified to care for patients. NCK curriculum framework / nursing education principles.', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which aim of education allows the students to develop themselves into distinct individual personality', 'Individual', 'Social', 'Vocational', 'Moral', 'A', 'The individual aim of education seeks development of the learner''s distinct/unique personality, as opposed to social, vocational or moral aims. Educational philosophy (nursing education).', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is not a characteristics of good teaching?', 'Reduces the distance between teacher and students', 'Flexible and not tied to any method', 'Incorporates cooperativeness and suggestiveness', 'Is autocratic', 'D', 'Good teaching is democratic, flexible, cooperative and reduces teacher-student distance; being autocratic is NOT a characteristic of good teaching. Principles of teaching (nursing education).', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Role-play helps to assess which domain of learning', 'Cognitive', 'Affective', 'Psychomotor', 'All of these', 'B', 'Role-play elicits attitudes, values and feelings, so it best assesses the affective domain of learning. Bloom''s taxonomy / nursing education methods.', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Educational objectives should be all except', 'Attainable', 'Realistic', 'Motivational', 'Measurabl e', 'C', 'Good educational objectives should be attainable, realistic and measurable (SMART); ''motivational'' is not a defining criterion, making it the exception. Nursing education / instructional design.', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Educational objectives according to Bloom''s taxonomy are classified into how many basic domains', 'Two', 'Three', 'Four', 'Five', 'B', 'Bloom''s taxonomy classifies objectives into three domains: cognitive, affective and psychomotor. Educational theory.', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Other name of institutional objective is', 'Behavioral objective', 'Departmental objective', 'Specific Objective', 'General objective', 'D', 'Institutional objectives are broad, overarching aims and are also termed general objectives, in contrast to specific/behavioral objectives. Curriculum development in nursing education.', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The important characteristic of assessment tool that helps us know about whether the tool measures what it is intended to measure is', 'Validity', 'Objectivity', 'Reliability', 'Practicabilit y', 'A', 'Validity is the property of an assessment tool that indicates it measures what it is intended to measure; reliability concerns consistency. Research/assessment principles (nursing education).', 'BScN', 'Paper II', 'Research & Evidence-Based Practice', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The character of feeling for others in their position is called', 'Empathy', 'Sympathy', 'Warmth', 'Reassurance', 'A', 'Empathy is understanding and feeling with others from their perspective/position, distinguished from sympathy (feeling for them). Therapeutic communication (Kozier & Erb''s).', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The purpose of taking return demonstration from students after a teaching session of demonstration of nursing procedure is to', 'Fulfill syllabus norm', 'Ensure safe Nursing practice', 'Follow institutional policy', 'Identify mistakes', 'B', 'Return demonstration verifies that the student has mastered the psychomotor skill correctly, ensuring safe nursing practice before performing it on patients. Nursing education (demonstration method).', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which one of the following is NOT a part of electronic media?', 'Radio', 'Brochure', 'Film', 'Televisio n', 'B', 'Radio, film and television are electronic media; a brochure is print media, making it the exception. Educational technology / health education media.', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is not the purpose of assessment?', 'Certification', 'Safeguarding public', 'Monitoring the program', 'Safeguarding educational institution', 'D', 'Purposes of assessment include certification, safeguarding the public, and monitoring the program; safeguarding the educational institution is not a legitimate purpose, making it the exception. Educational assessment principles.', 'BScN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In barium swallow studies:', 'Patients should not be NPO', 'High fiber diet is encouraged a day to study', 'Good for studying condition of ascending colon', 'Good for diagnosing achalasia', 'D', 'Barium swallow (esophagography) visualises the esophagus and is the classic study for achalasia, showing the dilated esophagus with distal ''bird-beak'' narrowing (Brunner & Suddarth''s Med-Surg). Patients are kept NPO before the study, so ''not NPO'' is wrong, and it studies the upper GI tract, not the ascending colon.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Esophageal varices are caused by:', 'Inflammation of the esophagus', 'Peptic ulcers', 'Hepatic hypertension', 'Hemorrhoids', 'C', 'Esophageal varices are dilated submucosal veins resulting from portal (hepatic) hypertension, most often due to cirrhosis (Brunner & Suddarth''s Med-Surg). The option ''hepatic hypertension'' best represents portal hypertension; inflammation, peptic ulcers and hemorrhoids do not cause esophageal varices.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following is the correct order of abdominal assessment:', 'Inspection, percussion, auscultation, palpation.', 'Inspection, auscultation, percussion, palpation.', 'Inspection, palpation, percussion, auscultation.', 'Inspection, auscultation, palpation, percussion.', 'B', 'Abdominal assessment follows inspection, auscultation, percussion, then palpation; auscultation precedes percussion/palpation so bowel sounds are not altered by manipulation (Kozier & Erb''s Fundamentals of Nursing).', 'KRCHN', 'Paper I', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following gastrointestinal disorder is managed best by downscaling gluten containing meals:', 'Irritable bowel syndrome', 'Diverticulum', 'Celiac disease', 'Esophageal varices.', 'C', 'Celiac disease is an immune reaction to gluten and is managed by a lifelong gluten-free diet (Brunner & Suddarth''s Med-Surg). IBS, diverticulum and esophageal varices are not gluten-driven.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Nursing intervention should be a priority in one of the following patients:', 'Patient with appendicitis with pain rating of 10/10.', 'Patient with appendicitis with sudden relief of pain.', 'Patient with peptic ulcers who need omeprazole', 'Patient with jaundice that need evaluation of liver function', 'B', 'Sudden relief of pain in appendicitis suggests perforation/rupture, a surgical emergency requiring priority intervention (Brunner & Suddarth''s Med-Surg). Severe steady pain, routine omeprazole, and elective liver-function evaluation are lower priority than a possible rupture.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The scientific study of the aging process is referred to as:', 'Ageism', 'Geriatrics', 'Gerontic', 'Gerontology', 'D', 'Gerontology is the scientific study of the aging process and older adults; geriatrics is the clinical/medical care of the elderly, and ageism is prejudice against them (Brunner & Suddarth''s Med-Surg, gerontologic nursing).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Drug dosages must be reduced in the elderly because:', 'Cardiac output is significantly reduced', 'The mucosal cells in the gastrointestinal tract are reduced', 'Drug biotransformation takes longer in an older person', 'There is a high likelihood of manifestation of toxic effects of drugs', 'D', 'Age-related decline in hepatic metabolism and renal clearance leads to drug accumulation and a high likelihood of toxicity, so doses are reduced (Brunner & Suddarth''s Med-Surg; Kenya EML pharmacology principles). This is the overarching reason encompassing slower biotransformation.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Nursing measures to deal with sensory changes in the aged include', 'Increasing lighting in the room', 'Speaking in low tones', 'Providing single and adequate calories', 'Suggesting appetite stimulants before meals', 'A', 'Aging causes visual decline; increasing (glare-free) lighting compensates for sensory changes and improves safety (Brunner & Suddarth''s Med-Surg, gerontologic nursing). Speaking in low tones worsens presbycusis; the other options address nutrition, not sensory changes.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Bone changes associated with aging frequently result from loss of:', 'Calcium', 'Magnesium', 'Vitamin A', 'Vitamin C', 'A', 'Age-related bone changes (osteoporosis/osteopenia) result from loss of bone calcium and mass (Brunner & Suddarth''s Med-Surg). Magnesium and vitamins A/C are not the primary lost element in aging bone.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the following is true about loss of muscle mass in the elderly:', 'It also known as osteopenia', 'It is solely caused by disused', 'Exercise has no impact on the process', 'It is referred to as sarcopenia.', 'D', 'Age-related loss of muscle mass and strength is termed sarcopenia; osteopenia refers to low bone mass, and exercise/resistance training does slow the process (Brunner & Suddarth''s Med-Surg).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse knows that the anterior pituitary gland is responsible for secreting all of the following except the:', 'Adrenocorticotropic hormone (ACTH).', 'Antidiuretic hormone (ADH).', 'Follicle-stimulating hormone (FSH).', 'Thyroid-stimulating hormone (TSH).', 'B', 'This is the ''except'': ADH (and oxytocin) are secreted by the posterior pituitary. The anterior pituitary secretes ACTH, FSH and TSH (Anatomy & Physiology / Brunner & Suddarth).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The major structure balancing the rapid action of the nervous system with slower hormonal action is the:', 'Hypothalamus.', 'Pineal gland.', 'Hypophysis.', 'Thyroid gland.', 'A', 'The hypothalamus links the rapid nervous system with the slower endocrine system by controlling the pituitary, balancing neural and hormonal regulation (Anatomy & Physiology / Brunner & Suddarth).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Diabetes insipidus is a disorder related to a deficiency of:', 'Growth hormone.', 'Prolactin.', 'Oxytocin.', 'Vasopressin.', 'D', 'Diabetes insipidus results from deficiency of antidiuretic hormone (vasopressin), causing polyuria and polydipsia (Brunner & Suddarth''s Med-Surg).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When thyroid hormone is administered for prolonged hypothyroidism, the nurse knows to monitor the patient for:', 'Angina.', 'Depression.', 'Mental confusion.', 'Hypoglycemia.', 'A', 'Thyroid hormone replacement increases myocardial oxygen demand; in prolonged hypothyroidism, especially with underlying CAD, it can precipitate angina, so the nurse monitors for it (Brunner & Suddarth''s Med-Surg).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The preferred medication for treating hypothyroidism is:', 'Lithium.', 'Proprandol.', 'Propylthiouracil.', 'Synthroid.', 'D', 'Synthroid (levothyroxine/T4) is the drug of choice for hypothyroidism replacement (Brunner & Suddarth''s Med-Surg; Kenya EML). Propylthiouracil and propranolol treat hyperthyroidism, and lithium is unrelated.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Patients with hyperthyroidism are characteristically:', 'Apathetic and anorexic.', 'Calm.', 'Emotionally stable.', 'Sensitive to heat.', 'D', 'Hyperthyroid patients have increased metabolism causing heat intolerance, nervousness and irritability; they are not calm, apathetic or emotionally stable (Brunner & Suddarth''s Med-Surg).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Iodine or iodide compounds are used for hyperthyroidism because they do all of the following except:', 'Decrease the basal metabolic rate.', 'Increase the vascularity of the gland.', 'Lessen the release of thyroid hormones.', 'Reduce the size of the gland.', 'B', 'This is the ''except'': iodine/iodide compounds DECREASE the size and vascularity of the thyroid gland and reduce hormone release and BMR, which is why they are given preoperatively (Brunner & Suddarth''s Med-Surg).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The objectives of pharmacotherapy for hyperthyroidism include:', 'Destroying overreactive thyroid cells.', 'Preventing thyroid hormonal synthesis.', 'Increasing the amount of thyroid tissue.', 'All of the above.', 'B', 'The objective of antithyroid pharmacotherapy (e.g., propylthiouracil, methimazole) is to inhibit thyroid hormone synthesis (Brunner & Suddarth''s Med-Surg). Destroying cells is radioiodine (not pharmacotherapy proper), and increasing thyroid tissue is opposite to the goal, so ''all of the above'' is wrong.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Signs of thyroid storm include all of the following except:', 'Bradycardia.', 'Delirium or somnolence.', 'Dyspnea and chest pain.', 'Hyperpyrexia.', 'A', 'This is the ''except'': thyroid storm causes tachycardia, hyperpyrexia, delirium/somnolence and cardiorespiratory distress; bradycardia is not a feature (Brunner & Suddarth''s Med-Surg).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Medical management for thyroid crisis includes:', 'Intravenous dextrose fluids.', 'Hypothermia measures.', 'Oxygen therapy.', 'All of the above.', 'D', 'Management of thyroid crisis includes IV dextrose/fluids for hypermetabolic demand, hypothermia (cooling) measures for hyperpyrexia, and oxygen therapy for increased metabolic demand (Brunner & Suddarth''s Med-Surg).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Pharmacotherapy for thyroid storm would not include the administration of:', 'Acetaminophen.', 'Iodine.', 'Propylthiouracil.', 'Synthetic levothyroxine.', 'D', 'Thyroid storm is treated with PTU, iodine and acetaminophen (for fever); administering synthetic levothyroxine (more thyroid hormone) would worsen the crisis and is therefore not included (Brunner & Suddarth''s Med-Surg).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The most common type of goiter is etiologically related to a deficiency of:', 'Thyrotropin.', 'Iodine.', 'Thyroxine.', 'Calcitonin.', 'B', 'Simple (endemic) goiter, the most common type, is caused by iodine deficiency (Brunner & Suddarth''s Med-Surg; addressed in Kenya via salt iodization). This is the basis of nutritional iodine supplementation.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse knows that the most common and least aggressive type of cancer is:', 'Anaplastic.', 'Follicular adenocarcinoma.', 'Medullary.', 'Papillary adenocarcinoma.', 'D', 'Papillary adenocarcinoma is the most common and least aggressive (best-prognosis) thyroid cancer; anaplastic is the most aggressive (Brunner & Suddarth''s Med-Surg).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the most important and frequently occurring complications of hyperparathyroidism is:', 'Kidney stones.', 'Pancreatitis.', 'Pathologic fractures.', 'Peptic ulcer.', 'A', 'Chronic hypercalcemia and hypercalciuria in hyperparathyroidism commonly cause renal calculi (nephrolithiasis) (Brunner & Suddarth''s Med-Surg). Pathologic fractures occur but renal stones are the most frequent complication.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The pathophysiology of hypoparathyroidism is associated with all of the following except:', 'A decrease in serum calcium.', 'An elevation of blood phosphate.', 'An increase in the renal excretion of phosphate.', 'A lowered renal excretion of calcium.', 'C', 'This is the ''except'': in hypoparathyroidism low PTH DECREASES renal phosphate excretion, causing hyperphosphatemia along with hypocalcemia and reduced renal calcium excretion (Brunner & Suddarth''s Med-Surg).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The goal of medical management for hypoparathyroidism is to:', 'Achieve a serum calcium level of 9 to 10 mg/dL.', 'Eliminate clinical symptoms.', 'Reverse the symptoms of hypocalcemia.', 'Accomplish all of the above.', 'D', 'Medical management of hypoparathyroidism aims to restore serum calcium to 9–10 mg/dL, reverse hypocalcemia and eliminate clinical symptoms (Brunner & Suddarth''s Med-Surg), so all listed goals apply.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Nursing management for a hypoparathyroid patient would not include:', 'Maintaining a quiet, subdued environment.', 'Making certain that calcium gluconate is kept at the bedside.', 'Observing the patient for signs of tetany.', 'Supplementing the diet with milk and milk products.', 'D', 'This is the ''would not include'': milk products are high in phosphorus, which is already elevated in hypoparathyroidism, so a high-calcium/low-phosphorus diet is advised, not milk supplementation. Seizure precautions, bedside calcium gluconate and tetany monitoring are appropriate (Brunner & Suddarth''s Med-Surg).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Laboratory findings suggestive of Addison''s disease include all of the following except:', 'A relative lymphocytosis.', 'Hyperkalemia and hyponatremia.', 'Hypertension.', 'Hypoglycemia.', 'C', 'Addison''s disease (adrenal insufficiency) causes HYPOtension, not hypertension, due to aldosterone/cortisol deficiency. Expected findings are hyperkalemia, hyponatremia, hypoglycemia and relative lymphocytosis; hypertension is the exception (Brunner & Suddarth''s Medical-Surgical Nursing).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Clinical manifestations of Cushing''s syndrome may be modified with a diet that is:', 'High in protein.', 'Low in carbohydrates.', 'Low in sodium.', 'All of the above.', 'D', 'Cushing''s manifestations are eased by a diet high in protein (counter catabolism), low in carbohydrates (counter hyperglycemia) and low in sodium (counter fluid retention/hypertension); all three apply (Brunner & Suddarth''s Medical-Surgical Nursing).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse needs to be aware that large-dose corticosteroid therapy is most effective when administered:', 'At 8:00 AM.', 'At 8:00 PM.', 'Between 4:00 AM and 5:00 AM.', 'Between 4:00 PM and 6:00 PM.', 'A', 'Corticosteroids are best given in the early morning (around 8:00 AM) to mimic the body''s natural diurnal cortisol peak and minimise HPA-axis suppression (Brunner & Suddarth''s Medical-Surgical Nursing; Kenya EML principles).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Nursing assessment for a patient who is receiving corticosteroid therapy includes observation for the unacceptable side effect of:', 'Glaucoma.', 'Facial mooning.', 'Potassium loss.', 'Weight gain', 'A', 'Facial mooning, potassium loss and weight gain are expected/anticipated corticosteroid effects; glaucoma (raised intraocular pressure with possible vision loss) is a serious, unacceptable adverse effect requiring monitoring (Brunner & Suddarth''s Medical-Surgical Nursing).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Traumatic injury of the following section of spine causes acute respiratory failure:', 'L1-L2', 'L3-L4', 'C5-C6', 'C7-C8', 'C', 'The phrenic nerve (diaphragm) arises from C3-C5; high cervical injury at C5-C6 impairs diaphragmatic/respiratory function causing acute respiratory failure, whereas lumbar (L1-L4) injuries spare respiration (Brunner & Suddarth''s Medical-Surgical Nursing).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Non atopic asthma is best described as:', 'Start in adulthood.', 'Associated with allergies.', 'Patient with eczema is likely not to have it.', 'Also known as intrinsic asthma.', 'D', 'Non-atopic asthma is not associated with allergy/IgE and is termed intrinsic asthma; it typically starts in adulthood but the defining description is intrinsic (non-allergic) asthma (Brunner & Suddarth''s Medical-Surgical Nursing).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Failure of bone marrow results in:', 'Pernicious anemia.', 'Aplastic anemia with fever.', 'Aplastic anemia without fever.', 'Iron deficiency anemia.', 'B', 'Bone marrow failure causes aplastic anemia; because all cell lines fail (including neutrophils), leukopenia predisposes to infection and fever, distinguishing it from the febrile-free option (Brunner & Suddarth''s Medical-Surgical Nursing).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Hyperplasia of gingiva is likely to be indicator of:', 'Ludwig angina', 'Vincent angina', 'Heart failure', 'Phenytoin therapy', 'D', 'Gingival hyperplasia is a classic adverse effect of phenytoin (anticonvulsant) therapy (Brunner & Suddarth''s Medical-Surgical Nursing; Kenya EML).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The bacteria known to cause dental caries is:', 'Streptococcus aureas', 'Streptococcus mutans', 'Group A beta hemolytic streptococcus', 'Sedenomonous aeruginosa', 'B', 'Streptococcus mutans is the principal bacterium responsible for dental caries through acid production from fermentable carbohydrates (Brunner & Suddarth''s Medical-Surgical Nursing; standard microbiology).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Contralateral shift of trachea in patient with chest complains is likely to be due to:', 'Pneumonia', 'Emphysema', 'Flail chest', 'Tension pneumothorax', 'D', 'Tension pneumothorax builds intrapleural pressure that pushes mediastinal structures and the trachea to the opposite (contralateral) side; it is a life-threatening emergency (Brunner & Suddarth''s Medical-Surgical Nursing).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Biot''s respirations are associated with:', 'Lesions on Pons.', 'Diabetic ketoacidosis.', 'Asthmatic attack.', 'Pneumonia.', 'A', 'Biot''s (ataxic) respirations, an irregular pattern of breaths with apnea, are associated with damage to the pons/medulla (Brunner & Suddarth''s Medical-Surgical Nursing). Kussmaul breathing, not Biot''s, is seen in diabetic ketoacidosis.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following is associated with thoracic aortic aneurysm only:', 'Marfan syndrome', 'Hypertension', 'Atherosclerosis', 'Smoking', 'A', 'Marfan syndrome (connective-tissue defect) is specifically linked to thoracic aortic aneurysm/dissection, whereas hypertension, atherosclerosis and smoking are shared risk factors for abdominal aneurysms too (Brunner & Suddarth''s Medical-Surgical Nursing).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In nursing assessment subjective data is data that the:', 'Patient can report on their own', 'Nurse can assess on their own', 'Nurse and doctor can confirm', 'Patient can report and the nurse can confirm', 'A', 'Subjective data is information reported by the patient (symptoms, feelings) that cannot be directly observed, whereas objective data is measurable/observable by the nurse (Kozier & Erb''s Fundamentals of Nursing).', 'KRCHN', 'Paper I', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the following procedures involves a segment of the leg being used to provide an alternative pathway for blood flow past a point of obstruction between the aorta and coronary artery:', 'Angioplasty', 'Coronary angiography', 'Heart transplant', 'Coronary bypass', 'D', 'Coronary artery bypass graft (CABG) uses a vessel such as the saphenous vein from the leg to bypass an obstruction and restore blood flow to the coronary artery (Brunner & Suddarth''s Medical-Surgical Nursing).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the following procedures involves using a small plastic balloon to open a narrowed artery:', 'Heart transplant', 'Coronary bypass', 'Angioplasty', 'Coronary angiography', 'C', 'Percutaneous transluminal (balloon) angioplasty uses a small inflatable balloon to open a narrowed artery (Brunner & Suddarth''s Medical-Surgical Nursing).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The most common symptom of myocardial infarction is:', 'Palpitations', 'Edema', 'Dyspnea', 'Chest pain', 'D', 'Chest pain (crushing, substernal, possibly radiating) is the most common presenting symptom of myocardial infarction (Brunner & Suddarth''s Medical-Surgical Nursing).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Dyspnea, fatigue, increased pulmonary artery pressure and decreased cardiac output are indicative of:', 'Right valve failure', 'Paracentisis', 'Myocardial infarction', 'Left sided heart failure', 'D', 'Dyspnea, fatigue, raised pulmonary artery pressure and reduced cardiac output reflect left-sided heart failure, where the failing left ventricle causes pulmonary congestion and low output (Brunner & Suddarth''s Medical-Surgical Nursing).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The primary reason for administration of morphine in a patient with myocardial infarction is to relieve:', 'Edema', 'Palpitations', 'Chest pain', 'Dyspnea', 'C', 'In myocardial infarction, morphine is given primarily to relieve severe ischemic chest pain (and also reduces anxiety and cardiac workload/preload) (Brunner & Suddarth''s Medical-Surgical Nursing; Kenya EML).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the following conditions results in coronary artery disease:', 'Renal failure', 'Diabetes mellitus', 'Myocardial infarction', 'Atherosclerosis', 'D', 'Atherosclerosis (plaque buildup narrowing coronary arteries) is the underlying pathological process that directly results in coronary artery disease (Brunner & Suddarth''s Medical-Surgical Nursing).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Nursing diagnoses mostly differ from medical diagnoses in that they are:', 'Primarily concerned with human response, while medical diagnoses are primarily concerned with pathology', 'Dependent upon medical diagnoses for the direction of appropriate interventions', 'Primarily concerned with caring, while medical diagnoses are primarily concerned with curing', 'Primarily concerned with psychosocial parameters, while medical diagnoses are primarily concerned with physiologic parameters.', 'A', 'A nursing diagnosis addresses the patient''s human responses to actual/potential health problems, whereas a medical diagnosis identifies the disease/pathology (Kozier & Erb''s Fundamentals of Nursing).', 'KRCHN', 'Paper I', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In the management of myocardial infarction, atherectomy is:', 'Removal of atherosclerotic plaque', 'Use of new implants', 'Ballooning of narrowed artery', 'Putting a stent to prevent collapse of artery)', 'A', 'Atherectomy is a catheter-based procedure that cuts away/removes atherosclerotic plaque from the coronary artery wall, distinct from angioplasty (ballooning) or stenting (Brunner & Suddarth''s Medical-Surgical Nursing, cardiovascular interventions).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nursing diagnosis for a patient with angina pectoris is infective tissue perfusion. The plan of care includes the patient outcome criterion of:', 'Experiencing no dyspnea on exertion', 'Reduce ischemia by increasing O2 to tissues', 'Agreeing to discontinue smoking', 'Ambulating 50 feet without experiencing dyspnea', 'D', 'An outcome criterion must be patient-centred, measurable and observable. ''Ambulating 50 feet without dyspnea'' is a specific, measurable patient outcome; the others are goals/interventions rather than measurable outcome criteria (Kozier & Erb''s Fundamentals of Nursing, nursing process).', 'KRCHN', 'Paper I', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which diagnostic test will be used to test for claudication in peripheral artery disease?', 'Doppler ultrasound', 'Treadmill', 'Arteriogram', 'Ankle brachial index', 'D', 'The ankle-brachial index (ABI) is the primary, first-line diagnostic test for peripheral artery disease/claudication, quantifying arterial insufficiency of the lower limbs (Brunner & Suddarth''s, peripheral vascular assessment).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following cardiovascular condition is more prevalent among females than males:', 'Hypertension', 'Varicose veins', 'Coronary artery disease', 'Myocardial infarction', 'B', 'Varicose veins are more prevalent in females (pregnancy, hormonal influence), whereas coronary artery disease and myocardial infarction are more common in males (Brunner & Suddarth''s, venous disorders).', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which action occurs primarily during the evaluation phase of the nursing process:', 'Decision making and judgment', 'Data collection', 'Reassessment and audit', 'Priority setting and expected outcomes.', 'C', 'The evaluation phase of the nursing process involves reassessing the patient and auditing whether outcomes were met. Data collection is assessment; priority setting/expected outcomes are planning; decision making is diagnosis (Kozier & Erb''s Fundamentals of Nursing).', 'KRCHN', 'Paper I', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Cognitive skills, key in implementation of nursing process, refers to:', 'A blend of intellectual and ''hand'' on skills', '''Hands on'' skills such as manipulating equipment', 'Problem solving, decision making, critical thinking and curative thinking', 'All activities, verbal and nonverbal, that people use when communicating directly with one another', 'C', 'Cognitive (intellectual) skills in the nursing process refer to problem solving, decision making and critical thinking. Option B describes psychomotor skills and D describes interpersonal skills (Kozier & Erb''s Fundamentals of Nursing, implementation).', 'KRCHN', 'Paper I', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Hematocrit of 60% is likely to be an indicator of:', 'Leukemia', 'Idiopathic Thrombocytopenia.', 'Non-Hodgkin Lymphoma', 'Polycythemia vera', 'D', 'A markedly elevated hematocrit (60%) indicates an increased red cell mass, characteristic of polycythemia vera. Leukemia, ITP and lymphoma do not raise the hematocrit (Brunner & Suddarth''s, hematologic disorders).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Vitamin B12 anemia is characterized by:', 'Microcytosis of RBC', 'Normal hematocrit', 'Hypochromic RBC', 'Macrocytosis of RBC', 'D', 'Vitamin B12 deficiency causes megaloblastic (macrocytic) anemia characterized by large red cells (macrocytosis) with high MCV, not microcytosis or hypochromia (Brunner & Suddarth''s, anemias).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One following oxygen delivery system has constant FiO2:', 'Nasal Prongs', 'Venturi Mask', 'Non-rebreather mask', 'Partial rebreather mask', 'B', 'The Venturi mask is a high-flow device that delivers a precise, constant FiO2 regardless of the patient''s breathing pattern; nasal prongs and rebreather masks deliver variable FiO2 (Brunner & Suddarth''s, oxygen therapy).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Patient manifesting with "hot potato voice" is likely to be suffering from:', 'Vincent angina', 'Periodontitis', 'Asthma', 'Ludwig Angina', 'D', 'A muffled ''hot potato voice'' results from the pharyngeal/submandibular swelling of Ludwig''s angina (and severe peritonsillar/deep neck infection); it is not a feature of asthma or periodontitis (Brunner & Suddarth''s, upper airway infections).', 'KRCHN', 'Paper I', 'Infection Prevention & Control', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nursing action needed for claustrophobic patient before MRI is:', 'Explain the procedure to the patient.', 'Assume patient''s concerns', 'Give paralytic drugs to the patient.', 'Tell the patient to man up.', 'A', 'For a claustrophobic patient facing MRI, the nurse should first explain the procedure to reduce anxiety and gain cooperation; assuming concerns or dismissive/inappropriate responses are non-therapeutic (Kozier & Erb''s Fundamentals of Nursing, therapeutic communication).', 'KRCHN', 'Paper I', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The best imaging study for patient with basilar artery aneurysm is:', 'Magnetic resonance imaging', 'X-Ray', 'Coronary angiography', 'Radioisotope imaging', 'A', 'MRI (with MR angiography) is the preferred non-invasive imaging for cerebral/basilar artery aneurysms; plain X-ray and coronary angiography are unsuitable for intracranial vessels (Brunner & Suddarth''s, neurologic diagnostics).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Mild intermittent asthma is best managed by:', 'Long-acting beta-adrenergic agonist (LABA)', 'Short acting beta-adrenergic agonist (SABA)', 'Long-acting muscarinic antagonist (LAMA)', 'Inhaled corticosteroids (ICS)', 'B', 'Mild intermittent asthma is managed with a short-acting beta-agonist (SABA) as reliever therapy; ICS and LABA/LAMA are for persistent asthma (GINA/WHO guidance as adopted in Kenya, Brunner & Suddarth''s).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('X-ray film of a patient shows expanded airways. This likely to be indicative of:', 'Emphysema', 'Bronchiectasis', 'Tension pneumothorax', 'Diffused pneumonia', 'A', 'Emphysema causes hyperinflation with expanded/enlarged airspaces and flattened diaphragm on chest X-ray; tension pneumothorax shows lung collapse, not expanded airways (Brunner & Suddarth''s, COPD).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Hemoptysis is defined as:', 'Blood in sputum cough.', 'Blood in GIT', 'Bad breath', 'Dry cough', 'A', 'Hemoptysis is the coughing up of blood or blood-stained sputum from the respiratory tract; blood in the GIT is hematemesis/melena (Brunner & Suddarth''s, respiratory assessment).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the following is an Intracardiac shunt', 'Ductus arteriosus', 'Ductus venosus', 'Foramen ovale', 'Ostia of aorta', 'C', 'The foramen ovale is an intracardiac shunt between the right and left atria in fetal circulation; the ductus arteriosus and ductus venosus are extracardiac shunts (Guyton/standard physiology; fetal circulation).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The immediate drainage of left intercostal veins is____________', 'Internal thoracic vein', 'Azygous vein', 'Hemiazagous vein', 'Inferior venacava', 'C', 'The left (lower) posterior intercostal veins drain immediately into the hemiazygos vein, which then crosses to the azygos vein; the right side drains to the azygos (standard anatomy, venous drainage of the thorax).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The cerebral vessels, CSF, and the cranial nerves are found within____________space.', 'Subdural', 'Epidural', 'Subarachnoid', 'Beneath Pia matter', 'C', 'The subarachnoid space contains cerebrospinal fluid (CSF), the cerebral vessels and the cranial nerves as they traverse it; the subdural and epidural spaces are potential spaces (standard neuroanatomy).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the following will reduce pulse of pressure of an individual:', 'Reduced osmolality', 'Dehydration', 'Highly hydration status', 'Low temperatures', 'B', 'Pulse pressure is stroke volume dependent; dehydration/hypovolemia reduces stroke volume and thus narrows the pulse pressure. Overhydration would widen it (Guyton physiology; Brunner & Suddarth''s, fluid balance).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Sensory neurons enter the spinal cord via:', 'Lateral horn', 'Anterior horn', 'Central canal', 'Posterior horn', 'D', 'Sensory (afferent) neurons enter the spinal cord via the dorsal (posterior) root and synapse in the posterior/dorsal horn; motor neurons exit via the anterior horn (standard neuroanatomy).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following conductive system of the heart fire action potential at higher frequency than the rest:', 'Sino Atrio Node', 'Atrioventricular Node', 'Bundle of His', 'Purkinje fibers', 'A', 'The sinoatrial (SA) node has the fastest intrinsic firing rate (~60-100/min) and thus acts as the natural pacemaker; the AV node, Bundle of His and Purkinje fibers fire at progressively lower rates (Guyton physiology; cardiac conduction).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The anterior 2/3 of tongue is innervated by cranial nerve:', '1', '3', '5', '7', 'D', 'General sensation of the anterior two-thirds of the tongue is via the lingual (V3) nerve, but taste is carried by the chorda tympani of the facial nerve (cranial nerve VII); among the options 7 (facial) is correct for taste innervation (standard neuroanatomy).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Spinal cord terminates at:', 'T12-L1', 'T11-T12', 'L1-L2', 'L4-L5', 'C', 'In adults the spinal cord terminates as the conus medullaris at the L1-L2 vertebral level; below this is the cauda equina (standard neuroanatomy).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Phrenic nerve is formed by following spinal cord plexus:', 'Cervical plexus', 'Lumber plexus', 'Thoracic nerves', 'Sacral plexus', 'A', 'The phrenic nerve arises from the cervical plexus (C3, C4, C5) and supplies the diaphragm (standard anatomy, cervical plexus).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the following is true about renal system:', 'Renal artery carries purified blood.', 'Renal vein carries oxygenated blood.', 'Renal vein carries blood with metabolic wastes.', 'It participates in erythropoiesis', 'D', 'The kidney produces erythropoietin and thus participates in erythropoiesis. The renal artery carries oxygenated (not purified) blood and the renal vein carries deoxygenated, filtered blood, making the other options false (Guyton physiology; renal function).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the following wave represent atrial depolarization:', 'P', 'Q', 'R', 'T', 'A', 'The P wave of the ECG represents atrial depolarization; the QRS represents ventricular depolarization and the T wave ventricular repolarization (Brunner & Suddarth''s, ECG interpretation).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The occipital lobe of brain:', 'Concerned with olfaction', 'Concerned with sense of test', 'Control osmolality', 'Concerned with vision.', 'D', 'The occipital lobe contains the primary visual cortex and is concerned with vision; olfaction and taste are processed elsewhere (standard neuroanatomy).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of following is a nerve formed by brachial plexus:', 'Radial nerve', 'Tibial nerve', 'Sciatic nerve', 'Pudendal nerve', 'A', 'The radial nerve is a branch of the brachial plexus supplying the upper limb; the tibial, sciatic and pudendal nerves arise from the lumbosacral plexus (standard anatomy, brachial plexus).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The fibers that pass through the internal capsule form:', 'Pyramidal tracts', 'Extrapyramidal tract', 'Rubrospinal tract', 'Cranial nerves', 'A', 'The corticospinal (pyramidal) tract fibers descend through the posterior limb of the internal capsule; the extrapyramidal and rubrospinal tracts take other routes (standard neuroanatomy, motor pathways).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following cranial nerve innervates the lateral rectus muscle of the eye:', '1', '3', '5', '6', 'D', 'The abducens nerve (cranial nerve VI) innervates the lateral rectus muscle, which abducts the eye (standard neuroanatomy, cranial nerves).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Collection of cell bodies in the central nervous system forms:', 'White matter', 'Grey matter', 'Commissures', 'Ganglion', 'B', 'Per standard neuroanatomy (Kozier & Erb''s / Brunner & Suddarth), collections of neuronal cell bodies within the CNS form grey matter, whereas myelinated axons form white matter and a cluster of cell bodies OUTSIDE the CNS is a ganglion.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Gonadal arteries branch from:', 'Internal iliac artery', 'External iliac artery', 'Abdominal aorta', 'Subclavian artery', 'C', 'Per standard anatomy (Gray''s/anatomy texts used in Kenyan training), the gonadal (testicular/ovarian) arteries arise directly from the abdominal aorta below the renal arteries, not from the iliac or subclavian vessels.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Foamy and greasy stool is a likely indicator of:', 'Secretory Diarrhea', 'Celiac disease', 'Upper GI bleeding', 'Steatorrhea', 'D', 'Per Brunner & Suddarth, foamy, greasy, bulky, foul-smelling stool that reflects fat malabsorption is by definition steatorrhea; celiac disease can cause it but the descriptive finding itself IS steatorrhea.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Esophageal varices are caused by:', 'GERD', 'Peptic ulcers', 'Cirrhosis', 'Hemorrhoids', 'C', 'Per Brunner & Suddarth, oesophageal varices result from portal hypertension, most commonly caused by hepatic cirrhosis, which raises portal venous pressure and dilates the oesophageal collateral veins.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following gastrointestinal disorder is managed best by downscaling wheat product in diet', 'Irritable bowel syndrome', 'Diverticulum', 'Celiac disease', 'Esophageal varices.', 'C', 'Per Brunner & Suddarth, celiac disease is gluten-sensitive enteropathy; management centres on a gluten-free diet, i.e. eliminating wheat, barley and rye products.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the following disorder is caused by increased tone of lower esophageal sphincter:', 'GERD', 'Achalasia', 'Hiatal hernia', 'Dumping syndrome', 'B', 'Per Brunner & Suddarth, achalasia is characterised by increased tone / failure of relaxation of the lower oesophageal sphincter, whereas GERD and hiatal hernia involve a weak/incompetent LES.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Oliguria in renal function means:', 'Urine output of < 250 mL /24 hours', 'Urine output of <1000 mL /24 hours', 'Urine output of < 2500 mL /24 hours', 'Urine output of < 500 mL /24 hours', 'D', 'Per Brunner & Suddarth and standard renal physiology, oliguria is defined as urine output less than 500 mL in 24 hours (or <0.5 mL/kg/hr); <100 mL/24 hr is anuria.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Normal Glomerular Filtration Rate (GFR) is_________ mL /min/m2  and above.', '30', '40', '50', '60', 'D', 'Per KDIGO/standard renal references used in Kenyan practice, a normal GFR is ≥60 mL/min/1.73 m2 (typically 90–120); values below 60 sustained ≥3 months indicate chronic kidney disease.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Urine specific gravity of 1.100 is indicative of:', 'Normal hydration', 'Fluid overload', 'Dehydration', 'None of the above', 'C', 'Per Brunner & Suddarth, a high urine specific gravity indicates concentrated urine seen in dehydration/fluid volume deficit (normal range ~1.005–1.030); a very high value reflects reduced water intake and haemoconcentration.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the following is inappropriate health education to a discharge patient with chronic kidney disease.', 'Use NSAID to manage mild pain.', 'Reduce red meat intake and increase carbohydrates', 'Reduce dietary intake of salt intake.', 'Reduce dietary intake of potassium.', 'A', 'Per Kenya MOH renal/CKD guidance and Brunner & Suddarth, NSAIDs are nephrotoxic and contraindicated in CKD, so advising their use is INAPPROPRIATE education; salt, potassium and protein restriction are appropriate.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Management of moderately elevated K+ in a patient with acute kidney injury involve the following:', 'Administration of KCl by slow infusion', 'Administration of spironolactone to aid elimination.', 'Administration of insulin to aid in redistribution', 'None of the above', 'C', 'Per Brunner & Suddarth and MOH emergency guidance, IV insulin (with dextrose) shifts potassium intracellularly to lower serum K+; giving KCl would worsen it and spironolactone (K-sparing) is contraindicated in hyperkalaemia/AKI.', 'KRCHN', 'Paper I', 'Nursing Management & Leadership', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Nephrotic syndrome is manifested by one of the following:', 'Proteinuria, Hypoalbuminemia, Edema, Hyperlipidemia.', 'Hyperkalemia, Hyperalbuminemia, Edema, Hypertension', 'Proteinuria, Hypoalbuminemia, Edema, Hypokalemia', 'Proteinuria, Hyperalbuminemia, Edema, Hyperlipidemia.', 'A', 'Per Brunner & Suddarth, the classic tetrad of nephrotic syndrome is massive proteinuria, hypoalbuminaemia, oedema and hyperlipidaemia.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the following is likely to cause urolithiasis', 'Hypertension', 'Diabetes insipidus', 'Hyperparathyroidism', 'Compulsive water intake', 'C', 'Per Brunner & Suddarth, hyperparathyroidism raises serum calcium and urinary calcium excretion, predisposing to calcium-containing renal stones (urolithiasis); compulsive water intake is protective.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The most common kidney stones are:', 'Calcium Phosphate salts.', 'Uric acid and Struvite', 'Calcium Oxalate', 'Amino acid Cystine', 'C', 'Per Brunner & Suddarth, calcium oxalate stones are the most common type of kidney stone (about 75–80% of cases).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Lesion of cranial nerve VII causes one of the following:', 'Ebbs palsy', 'Inability to raise neck', 'Bell''s Palsy', 'Anosmia', 'C', 'Per standard neuroanatomy (Brunner & Suddarth), the facial nerve (CN VII) supplies the muscles of facial expression; its lesion causes Bell''s palsy (unilateral facial droop). Anosmia is CN I; CN VII does not affect neck raising.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which one of the following combinations of antiparkinsonian drugs is an appropriate treatment plan?', 'Amantadine, carbidopa, and entacapone.', 'Levodopa, carbidopa, and entacapone.', 'Pramipexole, carbidopa, and entacapone.', 'Ropinirole, carbidopa, and selegiline.', 'B', 'Per Kenya EML/pharmacology texts, the standard Parkinson''s regimen combines levodopa (dopamine precursor) with carbidopa (peripheral decarboxylase inhibitor) and entacapone (COMT inhibitor); the other options pair carbidopa with drugs (amantadine, dopamine agonists) that are not levodopa and so gain no benefit from carbidopa.', 'KRCHN', 'Paper I', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Carbidopa used as antiparkinsonian drug is a:', 'Dopamine receptor agonist', 'Decarboxylase inhibitor', 'Catechol-o-methyl transferase inhibitor', 'Monoamine oxidase B inhibitor', 'B', 'Per standard pharmacology, carbidopa is a peripheral dopa-decarboxylase inhibitor that prevents peripheral conversion of levodopa, increasing CNS availability and reducing peripheral side effects.', 'KRCHN', 'Paper I', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The part of brain affected in parkinsonian disease is the:', 'Limbic system', 'Occipital lobe', 'Pyramidal tracts', 'Basal ganglia', 'D', 'Per Brunner & Suddarth, Parkinson''s disease results from degeneration of dopaminergic neurons in the substantia nigra of the basal ganglia, impairing control of voluntary movement.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the following is a rapidly progressing, ascending inflammatory demyelinating polyneuropathy of the peripheral sensory and motor nerves and nerve roots disease.', 'Myasthenia Gravis', 'Guillain-Barre Syndrome', 'Multiple Myeloma', 'Alzheimer''s disease', 'B', 'Per Brunner & Suddarth, Guillain-Barre syndrome is an acute, rapidly progressive ascending inflammatory demyelinating polyneuropathy affecting peripheral sensory and motor nerves and nerve roots.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following is a cutoff for diagnosis of increased intracranial pressure (ICP):', 'ICP of 5 mmHg', 'ICP of 10 mmHg', 'ICP of 15 mmHg', 'ICP of 20 mmHg', 'D', 'Per Brunner & Suddarth and standard neuro-critical care, normal ICP is 5–15 mmHg; a sustained ICP above 20 mmHg is the threshold defining raised intracranial pressure requiring treatment.
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When caring for a 3-day-old neonate who is receiving phototherapy to treat jaundice, the nurse in charge would expect to do which of the following?', 'Turn the neonate every 6 hours', 'Encourage the mother to discontinue breastfeeding', 'Notify the physician if the skin becomes bronze', 'Check the vital signs every 2 to 4 hours', 'D', 'During phototherapy the neonate can become hyperthermic/dehydrated, so vital signs are monitored every 2-4 hours; breastfeeding is continued and bronze skin (bronze-baby syndrome) is documented, not primarily reported. Per Basic Paediatric Protocols (Kenya) neonatal jaundice management.', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is caring for a primigravida at about 2 months and 1-week gestation. After explaining self-care measures for common discomforts of pregnancy, the nurse determines that the client understands the instructions when she says:', '“Nausea and vomiting can be reduced if I eat a few crackers before rising”', '“If I start to leak colostrum, I should cleanse my nipples with soap and water.”', '“If I have a vaginal discharge, I should wear nylon underwear.”', '“Leg cramps can be alleviated if I put an ice pack on the area.”', 'A', 'Eating dry crackers before rising is the correct self-care for morning nausea. Nipples should be washed with water only (soap dries them), cotton (not nylon) underwear is advised, and leg cramps are relieved by dorsiflexion/warmth, not ice. Per Myles Textbook for Midwives (minor disorders of pregnancy).', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse plans to instruct the postpartum client about methods to prevent breast engorgement. Which of the following measures would the nurse include in the teaching plan?', 'Feeding the neonate a maximum of 5 minutes per side on the first day', 'Wearing a supportive brassiere with nipple shields', 'Breastfeeding the neonate at frequent intervals', 'Decreasing fluid intake for the first 24 to 48 hours', 'C', 'Frequent breastfeeding empties the breasts and prevents engorgement; time-limited feeds, restricting fluids, and nipple shields do not prevent engorgement. Per Myles Textbook for Midwives / MOH breastfeeding guidelines.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When the nurse on duty accidentally bumps the bassinet, the neonate throws out its arms, hands open, and begins to cry. The nurse interprets this reaction as indicative of which of the following reflexes?', 'Startle reflex', 'Babinski reflex', 'Grasping reflex', 'Tonic neck reflex', 'A', 'Sudden jarring causing symmetrical arm abduction with open hands followed by crying is the Moro (startle) reflex. Babinski is toe fanning to sole stroking, grasp is finger curling, and tonic neck is the fencing posture. Per Kozier & Erb / Basic Paediatric Protocols (newborn assessment).', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following would the nurse most likely expect to find when assessing a pregnant client with abruption placenta?', 'Excessive vaginal bleeding', 'Rigid, board-like abdomen', 'Tetanic uterine contractions', 'Premature rupture of membranes', 'B', 'Abruptio placentae classically causes a rigid, board-like, tender abdomen from concealed retroplacental bleeding; vaginal bleeding may be minimal/concealed. Excessive painless bleeding suggests previa. Per Myles Textbook for Midwives / MOH obstetric guidelines.', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse in charge is caring for a patient who is in the first stage of labor. What is the shortest but most difficult part of this stage?', 'Active phase', 'Complete phase', 'Latent phase', 'Transitional phase', 'D', 'The transitional phase (8-10 cm) is the shortest but most intense and difficult part of the first stage of labor. Per Myles Textbook for Midwives (stages of labor).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is developing a teaching plan for a patient who is 8 weeks pregnant. The nurse should tell the patient that she can expect to feel the fetus move at which time?', 'Between 10 and 12 weeks’ gestation', 'Between 16 and 20 weeks’ gestation', 'Between 21 and 23 weeks’ gestation', 'Between 24 and 26 weeks’ gestation', 'B', 'Quickening (first felt fetal movement) typically occurs at 16-20 weeks in a primigravida. Per Myles Textbook for Midwives (presumptive signs of pregnancy).', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Normal lochial findings in the first 24 hours post-delivery include:', 'Bright red blood', 'Large clots or tissue fragments', 'A foul odor', 'The complete absence of lochia', 'A', 'Lochia rubra (bright red blood) is normal in the first 1-3 days postpartum. Large clots/tissue, foul odor, and absence of lochia are abnormal. Per Myles Textbook for Midwives (puerperium).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse in-charge is reviewing a patient’s prenatal history. Which finding indicates a genetic risk factor?', 'The patient is 25 years old', 'The patient has a child with cystic fibrosis', 'The patient was exposed to rubella at 36 weeks’ gestation', 'The patient has a history of preterm labor at 32 weeks’ gestation', 'B', 'Cystic fibrosis is an autosomal recessive inherited disorder, so a previously affected child is a genetic risk factor. Rubella exposure is teratogenic (not genetic) and preterm labor is obstetric history. Per Myles / genetics in midwifery.', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is caring for a client in labor. The external fetal monitor shows a pattern of variable decelerations in fetal heart rate. What should the nurse do first?', 'Change the client’s position', 'Prepare for an emergency cesarean section', 'Check for placenta previa', 'Administer oxygen', 'A', 'Variable decelerations indicate cord compression; the first intrauterine resuscitation step is repositioning the mother to relieve pressure, then oxygen. Cesarean is a later step if the pattern persists. Per WHO/MOH intrapartum guidelines and Myles.', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When administering magnesium sulfate to a client with preeclampsia, the nurse understands that this drug is given to:', 'Prevent seizures', 'Reduce blood pressure', 'Slow the process of labor', 'Increase diuresis', 'A', 'Magnesium sulfate is given in pre-eclampsia/eclampsia as an anticonvulsant to prevent and control seizures, not primarily to lower blood pressure. Per MOH/WHO eclampsia guidelines and Kenya EML.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is teaching care of the newborn to a childbirth preparation class and describes the need for administering antibiotic ointment into the eyes of the newborn. An expectant father asks, “What type of disease causes infections in babies that can be prevented by using this ointment?” Which response by the nurse is accurate?', 'Herpes', 'Trichomonas', 'Gonorrhea', 'Syphilis', 'C', 'Neonatal eye prophylaxis (tetracycline/erythromycin ointment) prevents ophthalmia neonatorum caused by maternal Neisseria gonorrhoeae (and chlamydia). Per MOH newborn care guidelines / Basic Paediatric Protocols.', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is counseling a couple who has sought information about conceiving. The couple asks the nurse to explain when ovulation usually occurs. Which statement by the nurse is correct?', 'Two weeks before menstruation', 'Immediately after menstruation', 'Immediately before menstruation', 'Three weeks before menstruation', 'A', 'Ovulation occurs about 14 days before the next menstrual period (mid-cycle in a 28-day cycle), driven by the fixed luteal phase length. Per Myles Textbook for Midwives (menstrual cycle physiology).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following urinary symptoms does the pregnant woman most frequently experience during the first trimester?', 'Dysuria', 'Frequency', 'Incontinence', 'Burning', 'B', 'First-trimester uterine enlargement presses on the bladder causing urinary frequency; dysuria and burning suggest infection, not normal pregnancy. Per Myles Textbook for Midwives (minor disorders).', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In which of the following areas would the nurse expect to observe chloasma?', 'Breast, areola, and nipples', 'Chest, neck, arms, and legs', 'Abdomen, breast, and thighs', 'Cheeks, forehead, and nose', 'D', 'Chloasma (melasma, the “mask of pregnancy”) is hyperpigmentation over the cheeks, forehead, and nose. Per Myles Textbook for Midwives (skin changes in pregnancy).', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Cervical softening and uterine souffle are classified as which of the following?', 'Diagnostic signs', 'Presumptive signs', 'Probable signs', 'Positive signs', 'C', 'Cervical softening (Goodell sign) and uterine souffle are objective changes detected by the examiner but not conclusive of pregnancy, so they are probable signs. Per Myles Textbook for Midwives (signs of pregnancy).', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following would the nurse identify as a presumptive sign of pregnancy?', 'Hegar sign', 'Nausea and vomiting', 'Skin pigmentation changes', 'Positive serum pregnancy test', 'B', 'Presumptive signs are subjective symptoms reported by the woman, such as nausea and vomiting. Hegar sign and pigmentation are probable, and a positive serum test/fetal detection is positive/probable. Per Myles Textbook for Midwives.', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following would be a disadvantage of breastfeeding?', 'Involution occurs more rapidly', 'The incidence of allergies increases due to maternal antibodies', 'The father may resent the infant’s demands on the mother’s body', 'There is a greater chance for error during preparation', 'C', 'A recognized disadvantage of breastfeeding is that the father may feel excluded or resent the infant''s demands on the mother. Faster involution and antibody transfer are advantages, and preparation error applies to formula. Per Myles Textbook for Midwives (breastfeeding).', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following would cause a false-positive result on a pregnancy test?', 'The test was performed less than 10 days after an abortion', 'The test was performed too early or too late in the pregnancy', 'The urine sample was stored too long at room temperature', 'A spontaneous abortion or a missed abortion is impending', 'A', 'hCG remains detectable for up to ~10 days after abortion/delivery, giving a false-positive pregnancy test. Prolonged storage or wrong timing typically cause false negatives, and impending abortion is not a false positive. Per standard laboratory/midwifery references.', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following danger signs should be reported promptly during the antepartum period?', 'Constipation', 'Breast tenderness', 'Nasal stuffiness', 'Leaking amniotic fluid', 'D', 'Per Kenya MOH/WHO focused ANC danger signs, leaking amniotic fluid (PROM) risks infection and preterm labour and must be reported; constipation, breast tenderness and nasal stuffiness are normal pregnancy discomforts.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following characteristics of contractions would the nurse expect to find in a client experiencing true labor?', 'Occurring at irregular intervals', 'Starting mainly in the abdomen', 'Gradually increasing intervals', 'Increasing intensity with walking', 'D', 'Myles Textbook for Midwives: true labour contractions are regular, begin in the back radiating to the abdomen, come at shortening intervals and intensify with activity/walking, unlike false labour which eases with walking.', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('During which of the following stages of labor would the nurse assess “crowning”?', 'First stage', 'Second stage', 'Third stage', 'Fourth stage', 'B', 'Crowning (the fetal head remaining visible at the vulva between contractions) occurs in the second stage of labour, the stage of expulsion (Myles Textbook for Midwives).', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following nursing interventions would the nurse perform during the third stage of labor?', 'Obtain a urine specimen and other laboratory tests', 'Assess uterine contractions every 30 minutes', 'Coach for effective client pushing', 'Promote parent-newborn interaction', 'D', 'The third stage runs from birth of the baby to delivery of the placenta; while awaiting placental separation the nurse promotes early parent-newborn bonding/interaction. Pushing coaching is second stage (Myles Textbook for Midwives).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following actions demonstrates the nurse’s understanding of the newborn’s thermoregulatory ability?', 'Placing the newborn under a radiant warmer', 'Suctioning with a bulb syringe', 'Obtaining an Apgar score', 'Inspecting the newborn’s umbilical cord', 'A', 'Newborns lose heat rapidly and have limited thermoregulation; placing under a radiant warmer (or skin-to-skin) prevents cold stress (Kenya Basic Paediatric Protocols / newborn care). The other actions relate to airway, scoring and cord, not thermoregulation.', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Immediately before expulsion, which of the following cardinal movements occur?', 'Descent', 'Flexion', 'Extension', 'External rotation', 'C', 'In the cardinal movements of labour, extension of the fetal head occurs as it distends the vulva and is born immediately before expulsion; external rotation (restitution) follows after the head is delivered (Myles Textbook for Midwives).', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When assessing the newborn’s heart rate, which of the following ranges would be considered normal if the newborn were sleeping?', '80 beats per minute', '100 beats per minute', '120 beats per minute', '140 beats per minute', 'B', 'Normal newborn heart rate is 120-160 bpm awake but may drop to about 100 bpm during sleep, which remains within normal limits (Kenya Basic Paediatric Protocols; newborn assessment).', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is true regarding the fontanels of the newborn?', 'The anterior is triangular shaped; the posterior is diamond-shaped', 'The posterior closes at 18 months; the anterior closes at 8 to 12 weeks', 'The anterior is large in size when compared to the posterior fontanel', 'The anterior is bulging; the posterior appears sunken', 'C', 'The anterior fontanel is diamond-shaped and larger, closing at 12-18 months; the posterior is triangular, smaller, closing by ~8-12 weeks. Option C is correct; option A reverses the shapes (Myles/newborn assessment).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following describes the Babinski reflex?', 'The newborn’s toes will hyperextend and fan apart from the dorsiflexion of the big toe when one side of the foot is stroked upward from the ball of the heel and across the ball of the foot.', 'The newborn abducts and flexes all extremities and may begin to cry when exposed to sudden movement or loud noise', 'The newborn turns the head in the direction of the stimulus, opens the mouth, and begins to suck when the cheek, lip, or corner of the mouth is touched', 'The newborn will attempt to crawl forward with both arms and legs when he is placed on his abdomen on a flat surface', 'A', 'Babinski reflex: stroking the sole causes dorsiflexion of the big toe with fanning of the toes. Option B describes Moro, C describes rooting, D describes the crawl reflex (newborn reflex assessment).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following statements best describes hyperemesis gravidarum?', 'Severe anemia leading to an electrolyte, metabolic, and nutritional imbalances in the absence of other medical problems', 'Severe nausea and vomiting leading to an electrolyte, metabolic, and nutritional imbalances in the absence of other medical problems', 'Loss of appetite and continuous vomiting that commonly results in dehydration and ultimately decreasing maternal nutrients', 'Severe nausea and diarrhea that can cause gastrointestinal irritation and possibly internal bleeding.', 'B', 'Hyperemesis gravidarum is severe, persistent nausea and vomiting in pregnancy causing dehydration, electrolyte, metabolic and nutritional imbalance without other medical cause (Myles Textbook for Midwives).', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In which of the following types of spontaneous abortions would the nurse assess dark brown vaginal discharge and a negative pregnancy test?', 'Threatened', 'Imminent', 'Missed', 'Incomplete', 'C', 'In a missed abortion the fetus dies but is retained; the woman has a dark brown discharge and, as hormone levels fall, the pregnancy test becomes negative. Threatened abortion still has a positive test (Myles Textbook for Midwives).', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is described as premature separation of a normally implanted placenta during the second half of pregnancy, usually with severe hemorrhage?', 'Placenta previa', 'Ectopic pregnancy', 'Incompetent cervix', 'Abruptio placenta', 'D', 'Abruptio placentae is premature separation of a normally implanted placenta after 20 weeks, usually with severe haemorrhage. Placenta previa is abnormal low implantation, not premature separation (Myles Textbook for Midwives).', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following best describes preterm labor?', 'Labor that begins after 20 weeks gestation and before 37 weeks gestation', 'Labor that begins after 15 weeks gestation and before 37 weeks gestation', 'Labor that begins after 24 weeks gestation and before 28 weeks gestation', 'Labor that begins after 28 weeks gestation and before 40 weeks gestation', 'A', 'Preterm labour is defined as labour occurring after 20 (viability threshold) and before 37 completed weeks of gestation (WHO/Myles Textbook for Midwives).', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following factors is the underlying cause of dystocia?', 'Nutritional', 'Mechanical', 'Environmental', 'Medical', 'B', 'Dystocia (difficult labour) arises from mechanical problems in the powers, passage or passenger (uterine dysfunction, cephalopelvic disproportion, malposition). The underlying cause is mechanical (Myles Textbook for Midwives).', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When uterine rupture occurs, which of the following would be the priority?', 'Limiting hypovolemic shock', 'Obtaining blood specimens', 'Instituting complete bed rest', 'Inserting a urinary catheter', 'A', 'Uterine rupture causes catastrophic haemorrhage; the priority is limiting/managing hypovolaemic shock (fluid resuscitation, restore circulating volume) alongside preparation for surgery (Myles Textbook for Midwives; ABC priority).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is the nurse’s initial action when umbilical cord prolapse occurs?', 'Begin monitoring maternal vital signs and FHR', 'Place the client in a knee-chest position in bed', 'Notify the physician and prepare the client for delivery', 'Apply a sterile warm saline dressing to the exposed cord', 'B', 'The immediate/first action in cord prolapse is to relieve pressure on the cord by positioning the mother knee-chest (or Trendelenburg) to prevent fetal hypoxia, before notifying and preparing for delivery (Myles Textbook for Midwives).', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following amounts of blood loss following birth marks the criterion for describing postpartum hemorrhage?', 'More than 200 ml', 'More than 300 ml', 'More than 400 ml', 'More than 500 ml', 'D', 'Postpartum haemorrhage is classically defined as blood loss exceeding 500 ml after vaginal birth (Kenya MOH maternal guidelines / WHO; Myles Textbook for Midwives).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following best reflects the frequency of reported postpartum “blues”?', 'Between 10% and 40% of all new mothers report some form of postpartum blues', 'Between 30% and 50% of all new mothers report some form of postpartum blues', 'Between 50% and 80% of all new mothers report some form of postpartum blues', 'Between 25% and 70% of all new mothers report some form of postpartum blues', 'C', 'Postpartum (baby) blues are very common, affecting roughly 50-80% of new mothers, a transient self-limiting mood disturbance in the first postnatal days (Myles Textbook for Midwives; maternal mental health).', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('For the client who is using oral contraceptives, the nurse informs the client about the need to take the pill at the same time each day to accomplish which of the following?', 'Decrease the incidence of nausea', 'Maintain hormonal levels', 'Reduce side effects', 'Prevent drug interactions', 'B', 'Taking oral contraceptives at the same time daily keeps steady hormone (estrogen/progestin) blood levels, ensuring reliable ovulation suppression and contraceptive efficacy (Kenya National Family Planning Guidelines).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When teaching a client about contraception. Which of the following would the nurse include as the most effective method for preventing sexually transmitted infections?', 'Spermicides', 'Diaphragm', 'Condoms', 'Vasectomy', 'C', 'Condoms (barrier method) are the most effective contraceptive method for preventing STIs by preventing exchange of body fluids; spermicides, diaphragm and vasectomy do not protect against STIs (Kenya National Family Planning Guidelines).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('For which of the following clients would the nurse expect that an intrauterine device would not be recommended?', 'Woman over age 35', 'Nulliparous woman', 'Promiscuous young adult', 'Postpartum client', 'C', 'An IUD is not recommended for women at high risk of STIs (multiple partners) because of the increased risk of pelvic inflammatory disease with ascending infection (Kenya National Family Planning Guidelines / WHO MEC).', 'KRCHN', 'Paper I', 'Infection Prevention & Control', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client tells the nurse that her last menstrual period started on January 14 and ended on January 20. Using Nagele’s rule, the nurse determines her EDD to be which of the following?', 'September 27', 'October 21', 'November 7', 'December 27', 'B', 'Naegele''s rule uses the first day of LMP (Jan 14): + 7 days = Jan 21, - 3 months = Oct 21. EDD is October 21 (Myles Textbook for Midwives).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse assesses the postpartum vaginal discharge (lochia) on four clients. Which of the following assessments would warrant notification of the physician?', 'A dark red discharge on a 2-day postpartum client', 'A pink to brownish discharge on a client who is 5 days postpartum', 'Almost colorless to creamy discharge on a client 2 weeks after delivery', 'A bright red discharge 5 days after delivery', 'D', 'By day 5 lochia should be serosa (pink/brown). Bright red (rubra) lochia at 5 days suggests fresh bleeding/possible haemorrhage and warrants physician notification; the other findings follow the normal lochia progression (Myles Textbook for Midwives).', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nutritional supplement given to a woman during the preconception care to prevent neural tube defect is:', 'Iron', 'Zinc', 'Folate', 'Calcium', 'C', 'Per Kenya National MNH/preconception guidelines and WHO, folic acid (folate) supplementation before and in early pregnancy prevents neural tube defects; iron/zinc/calcium do not.', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The hormone responsible for the regeneration and proliferation of the endothelium during each menstrual cycle, after menstruation has taken place is:', 'Progesterone', 'Estrogen', 'Estradiol', 'Inhibin', 'B', 'Per Myles Textbook for Midwives, estrogen from the developing follicles drives regeneration and proliferation of the endometrium during the proliferative phase after menstruation; progesterone dominates the secretory phase.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Pica is usually a sign of -------in pregnancy:', 'Anemia', 'Heart disease', 'Diabetes mellitus', 'Syphilitic infection', 'A', 'Per Myles Textbook for Midwives, pica (craving non-food substances) in pregnancy is commonly associated with iron-deficiency anaemia.', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('While evaluating urine output for a mother in shock, the midwife is concerned if the urine output is:', '< 30ml/h', '> 30ml/h', '< 150 ml/h', '> 150ml/h', 'A', 'Per Kenya MNH guidelines and Myles, urine output below 30 ml/hour indicates inadequate renal perfusion and is a concerning sign of shock/hypovolaemia.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following sign may help a midwife diagnose shoulder dystocia in labour ward?', 'The fetal head remains slightly stuck in the vagina', 'The anterior shoulder is delivered but the posterior one is stuck', 'The chin retracts and depresses the perineum', 'Traction of the head delivers the shoulder', 'C', 'Per Myles Textbook for Midwives, shoulder dystocia is recognised by the ''turtle sign''—the head delivers then retracts against the perineum (chin retracts/depresses perineum) because the anterior shoulder is impacted behind the symphysis.', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The first maneuver a nurse would choose in the management of shoulder dystocia is:', 'Zavanelli', 'Woodscrew', 'Rubin', 'McRoberts', 'D', 'Per Kenya MNH guidelines and Myles, the McRoberts manoeuvre (hyperflexion of maternal thighs) is the first-line intervention for shoulder dystocia due to its simplicity and effectiveness; Zavanelli is a last resort.', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Pressure exerted on amniotic fluid during uterine contractions is:', 'Fore water pressure', 'Hind water pressure', 'Fetal axis pressure', 'General fluid pressure', 'D', 'Per Myles Textbook for Midwives, when membranes are intact the pressure of a contraction is applied to the fluid and equally distributed throughout—this is general fluid pressure.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Immediately after the placenta is delivered, the nurse must do the following:', 'Inspect the placenta for completeness including the membranes', 'Place the placenta in a kidney dish for disposal', 'Massage the uterus and expel clots', 'Carefully examine it in the kidney dish and measure blood loss', 'A', 'Per Kenya MNH guidelines and Myles, after delivery of the placenta the midwife inspects it for completeness of cotyledons and membranes to exclude retained products, a cause of PPH.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When the fontanelles are bulging, this implies that there is :', 'A fracture of the skull', 'Increased intracranial  pressure', 'Dehydration', 'Excessive molding', 'B', 'Per Basic Paediatric Protocols (Kenya), a bulging/tense anterior fontanelle indicates raised intracranial pressure (e.g. meningitis, hydrocephalus); a sunken fontanelle indicates dehydration.', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The reflex that is elicited when the corner of the baby’s mouth is stroked and the baby turns its head and opens its mouth is:', 'Moro reflex', 'Rooting reflex', 'Sucking reflex', 'Turning reflex', 'B', 'Per Myles/Kozier, stroking the corner of the newborn''s mouth causing the head to turn and mouth to open is the rooting reflex, which aids location of the nipple.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the following is a danger sign during pueperium:', 'Watery vaginal discharge', 'Whitish with some mucus', 'Reddish with some pieces of tissue', 'Serous with some brown tinged mucus', 'C', 'Per Myles, offensive/heavy lochia with clots or tissue during puerperium suggests retained products or infection and is a danger sign; the normal progression is rubra to serosa to alba.', 'KRCHN', 'Paper I', 'Infection Prevention & Control', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The risks associated with prematurity include:', 'Asphyxia, hypothermia, cerebral haemorrhage', 'Infections, jaundice, genito-urinary malformations', 'Infections, asphyxia, malformation of the gut', 'Duodenal atresia, hypothermia, cerebral haemorrhage', 'A', 'Per Basic Paediatric Protocols (Kenya), preterm infants are prone to asphyxia, hypothermia (poor thermoregulation) and intraventricular/cerebral haemorrhage; malformations and atresias are not consequences of prematurity itself.', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The three bones that form the vault of the fetal head are:', 'Parietal, frontal, temporal', 'Frontal, lambdoidal, coronal', 'Temporal, parietal, coronal', 'Sinciput, parietal, lambdoidal', 'A', 'Per Myles Textbook for Midwives, the vault of the fetal skull is formed by the frontal, parietal (two), temporal and occipital bones; of the listed sets only ''parietal, frontal, temporal'' are true vault bones (the others list sutures).', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The diameter of the normal pelvic cavity is:', '13 cm', '12 cm', '11 cm', '10 cm', 'B', 'Per Myles Textbook for Midwives, the cavity of the true pelvis is roughly circular with diameters averaging about 12 cm; the anteroposterior and transverse diameters of the cavity are approximately 12 cm.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The four sutures of obstetric importance are:', 'Saggital, frontal, coronal, occipital', 'Coronal, temporal, saggital, frontal', 'Saggital, lambdoidal, coronal, frontal', 'Frontal, coronal, occipital, temporal', 'C', 'Per Myles Textbook for Midwives, the sutures of obstetric importance on the fetal skull are the sagittal, frontal, coronal and lambdoidal sutures.', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('During vacuum extraction procedure, the centre of the vacuum cup should be placed over which of the flexion point on the fetal head?', 'Along the sagittal suture 3 cm posterior to the anterior fontanelle', 'Over the occiput eminence', 'Along the sagittal suture 3 cm anterior to the posterior fontanelle', 'Over the posterior fontanelle', 'C', 'Per Myles/WHO obstetric vacuum guidance, the cup is centred over the flexion point on the sagittal suture about 3 cm anterior to the posterior fontanelle (about 6 cm from the anterior fontanelle) to promote flexion.', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Pathological jaundice as a result of increased haemolysis involves all the following except:', 'G6PD deficiency', 'ABO incompatibility', 'Gilbert’s syndrome', 'Bacterial septicaemia', 'C', 'Per Basic Paediatric Protocols/standard texts, Gilbert''s syndrome causes unconjugated hyperbilirubinaemia from reduced conjugation (UGT enzyme), not increased haemolysis; G6PD deficiency, ABO incompatibility and septicaemia all cause haemolytic jaundice.', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following nursing diagnosis will be of priority for a neonate undergoing phototherapy:', 'Deficient fluid volume', 'Imbalanced nutrition less than body requirements', 'Ineffective thermoregulation', 'Impaired skin integrity', 'A', 'Per Basic Paediatric Protocols and nursing care standards, phototherapy increases insensible water loss and stool water, so deficient fluid volume (risk of dehydration) is the priority; skin integrity and thermoregulation are managed but fluid loss is the leading concern.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which one of the following will be a priority nursing intervention for a neonate with Hemorrhagic disease of the newborn?', 'Administer vitamin K', 'Inform the physician', 'Preserve soiled line for estimation of blood loss', 'Observe signs of shock', 'A', 'Per Basic Paediatric Protocols (Kenya), haemorrhagic disease of the newborn results from vitamin K deficiency, so administering vitamin K is the priority intervention that treats the cause.', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The most common cause of opthalmia neonatorum is:', 'C.trachomatis', 'N.gonorrhea', 'H.simplex', 'T.pallidum', 'B', 'Per Kenya STI/newborn guidelines, Neisseria gonorrhoeae is the classic most common cause of severe ophthalmia neonatorum (purulent conjunctivitis) presenting within the first days of life; it is the reason for routine eye prophylaxis.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Sodium bicarbonate is indicated in babies with asphyxia neonatorum to:', 'Prevent metabolic acidosis', 'Reverse effects of narcotics', 'Treat hypoglycaemia', 'Treat arrhythmias', 'A', 'Per neonatal resuscitation/standard texts, sodium bicarbonate is used to correct/prevent metabolic acidosis in asphyxiated newborns; naloxone reverses narcotics, not bicarbonate.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The most appropriate treatment for hyperbilirubinemia (11.2mg/dl) in a 3 weeks old breastfeeding infant with normal growth and development is:', 'Phototherapy', 'Exchange transfusion', 'Phenobarbitone', 'Protopophyrins', 'A', 'Per Basic Paediatric Protocols (Kenya), a bilirubin of 11.2 mg/dl in a thriving 3-week breastfed infant is managed with phototherapy if treatment is required; exchange transfusion is reserved for much higher levels/haemolysis.', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('You are called to the delivery suite for a 39-week baby about to be born through thick meconium. One of following is your first step of management:', 'Intubate the baby and suction in case there is meconium below the cords', 'Dry the baby down, remove the wet wraps and give suction only if required', 'Visualize the cords with laryngoscope and only intubate if you see meconium below the cords', 'Give immediate deep oral suction', 'B', 'Per current Kenya/WHO neonatal resuscitation guidance, routine intubation and suctioning of vigorous meconium-stained babies is no longer recommended; the first step is to dry, remove wet wraps and provide initial care, suctioning only if the airway is obstructed.', 'KRCHN', 'Paper I', 'Nursing Management & Leadership', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The drug of choice for treatment of apnoeic attacks in new-borns is:', 'Caffeine citrate', 'Phenobarbitone', 'Theophylline', 'Diazepam', 'A', 'Per Kenya EML/Basic Paediatric Protocols, caffeine citrate is the drug of choice for apnoea of prematurity, being safer and more effective than theophylline.', 'KRCHN', 'Paper I', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which one of the following will be a priority nursing diagnosis for a postdate baby?', 'Risk for aspiration related to delayed swallowing reflex and meconium aspiration', 'Risk for hypoglycaemia related to decreased glycogen stores', 'Risk for infection related to prolonged exposure to the uterine environment', 'Ineffective breastfeeding related to decreased energy and increased sleepiness', 'A', 'Per Basic Paediatric Protocols, the postdate/post-term baby is at high risk of meconium aspiration; airway/aspiration risk is the priority (ABC) nursing diagnosis over hypoglycaemia or feeding concerns.', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is not a component of the vault of the fetal skull?', 'Occipital bone', 'Sinciput', 'Two parietal bones', 'Two frontal bones.', 'B', 'Per Myles Textbook for Midwives, the vault is formed by the occipital, two parietal and two frontal bones; the sinciput (brow) is a region of the fetal head, not a bone of the vault.', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which presentation is achieved in an extended fetal head?', 'Vertex', 'Brow', 'Mentum', 'Acromion process', 'B', 'When the fetal head is fully extended (deflexed), the brow (forehead) becomes the presenting part, giving a brow presentation. Vertex results from full flexion and mentum (face) from complete extension. Per Myles Textbook for Midwives (attitude & presentation).', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which are the storage ducts of milk in the mammary glands?', 'Alveoli', 'Lactiferous sinuses', 'Cooper’s ligaments', 'Lobules', 'B', 'Milk produced in the alveoli passes along the ducts to the lactiferous sinuses (ampullae) beneath the areola, which act as reservoirs storing milk. Alveoli produce milk; Cooper''s ligaments are support structures. Per Myles Textbook for Midwives (anatomy of the breast).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which cells are responsible for production of HCG during pregnancy?', 'Epiblast.', 'Syncytiotrophoblast', 'Hypoblast', 'Cytotrophoblast', 'B', 'Human chorionic gonadotrophin (hCG) is secreted by the syncytiotrophoblast layer of the developing placenta, maintaining the corpus luteum in early pregnancy. Per Myles Textbook for Midwives (placental physiology).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which hormone is responsible for milk production?', 'Prolactin', 'Oxytocin', 'Progesterone', 'Oestrogen', 'A', 'Prolactin from the anterior pituitary stimulates the alveoli to synthesise milk (lactogenesis). Oxytocin causes the let-down (ejection) reflex, not production. Per Myles Textbook for Midwives (physiology of lactation).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('You explain to a mother that a newborn has ''caput'' because there is a swelling on his head that:', 'Is a light pink colour and located at the base of his hairline', 'Does not cross a suture line and pits with digital pressure', 'Is firm and coloured like a reddish bruise', 'Is a diffuse oedematous swelling of the soft tissues of his scalp and crosses a suture that will resolve in 24-48hours', 'D', 'Caput succedaneum is a diffuse oedematous swelling of the scalp soft tissues that crosses suture lines and resolves within a few days, distinguishing it from cephalhaematoma which does not cross sutures. Per Myles Textbook for Midwives (birth trauma).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Radiation is the most predominate mode of heat loss for a newborn. Radiation refers to:', 'loss of heat through water evaporation from the baby', 'loss of heat through the baby shivering', 'loss of heat from the baby''s surface to surrounding colder objects', 'loss of heat to moving air or fluid around the baby', 'C', 'Radiation is heat transfer from the newborn''s body surface to nearby cooler solid objects not in direct contact (e.g. cold walls/windows). Evaporation is water loss, convection is loss to moving air, conduction is loss to objects in contact. Per Kenya Basic Paediatric Protocols / Myles (thermoregulation).', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Daily cord care is key in the prevention of neonatal sepsis. The following is the recommended ideal antiseptic for cleaning the cord;', 'Normal saline', 'Surgical spirit', 'Methylated spirit', 'chlorohexidine', 'D', 'Chlorhexidine (4% chlorhexidine digluconate) is the WHO- and Kenya MOH-recommended antiseptic for cord care to prevent neonatal sepsis, superior to spirits and saline. Per Kenya National Newborn Care guidelines / WHO adopted in Kenya.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following is a danger sign of a neonate that the mother should always be on look out;', 'Nasal secretions', 'Shrinking of the cord', 'Refusal to breastfeed', 'Hair loss in the body.', 'C', 'Refusal/inability to breastfeed is a key IMNCI newborn danger sign requiring urgent referral. Shrinking of the cord and hair variations are normal; nasal secretions are non-specific. Per Kenya IMNCI guidelines (young infant danger signs).', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When a newborn baby is in contact with cold surfaces, heat loss occurs by;', 'Evaporation', 'Radiation', 'Convection', 'Conduction', 'D', 'Heat loss from the baby''s body to a cold surface in direct contact (e.g. cold weighing scale or bed) occurs by conduction. Radiation is to non-contact objects, convection to moving air, evaporation from moisture. Per Kenya Basic Paediatric Protocols (thermoregulation).', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Characteristics of a normal infant at birth include:', 'Weight 3.5kg, length 40 cm, sunken abdomen', 'Lies in an attitude of flexion, vernix caseosa, his head half his size', 'His head comprise a quarter his size, prominent abdomen.', 'Occipitofrontal circumference of 34-55 cm, lanugo, sunken abdomen.', 'B', 'A normal term newborn lies in an attitude of flexion, is covered in vernix caseosa, and the head is about one quarter to a large proportion of body length; of the options given this is the only physiologically correct description (birth weight ~3.5kg with prominent, not sunken, abdomen). Per Myles Textbook for Midwives (characteristics of the normal newborn).', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The aims of first examination of the newborn are;', 'Assess growth, maintain clear airway, assess maturity at birth', 'Detect birth injuries, assess minor disorders, detect congenital anomalies', 'Provide care, detect infections, assess growth and development', 'Detect birth injuries, detect any congenital abnormalities, and assess maturity at term.', 'D', 'The aims of the first (immediate) newborn examination are to detect birth injuries, identify congenital abnormalities and assess maturity/wellbeing at birth. Maintaining the airway is resuscitation, not the examination''s aim. Per Myles Textbook for Midwives (examination of the newborn).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Hypoglycemia is;', 'Blood sugar level below 54mg/dl', 'Blood sugar level below 45mg/dl', 'Blood sugar level below 2.9mg/dl', 'Blood sugar level below 6.7mg/dl', 'B', 'Neonatal hypoglycaemia is commonly defined as blood glucose below 2.5 mmol/L (about 45 mg/dl); of the options this is the accepted threshold. Per Kenya Basic Paediatric Protocols (neonatal hypoglycaemia).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Jaundice on day one is often caused by;', 'Metabolic disorders', 'Physiological factors', 'Hemolysis', 'Gastrointestinal obstruction', 'C', 'Jaundice appearing within the first 24 hours (day one) is always pathological and most commonly caused by haemolysis (e.g. Rh/ABO incompatibility, G6PD deficiency). Physiological jaundice appears after 24-48 hours. Per Kenya Basic Paediatric Protocols (neonatal jaundice).', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The common age of onset of gonococcal ophthalmic neonatorum is;', '21 - 28 days after birth', '0 - 7 days after birth', '7 - 14 days after birth', 'At 28 days of age', 'B', 'Gonococcal ophthalmia neonatorum characteristically presents early, within the first week (typically days 2-5) after birth, unlike chlamydial conjunctivitis which appears later. Per Kenya National STI/newborn guidelines.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The rooting reflex is defined as response of the baby to;', 'Being pulled upright by the wrist to a sitting position', 'Being supported upright ith his feet touching a flat surface', 'Stroking of the cheek or side of the mouth', 'Being left to drop from an angle of 45', 'C', 'The rooting reflex is elicited by stroking the newborn''s cheek or corner of the mouth, causing the baby to turn towards the stimulus and open the mouth to feed. The other options describe traction, stepping and Moro responses. Per Myles Textbook for Midwives (neonatal reflexes).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse assisted with the birth of a newborn. Which nursing action is most effective in preventing heat loss by evaporation?', 'Warming the crib pad', 'Closing the doors to the room', 'Drying the infant with a warm blanket', 'Turning on the overhead radiant warmer', 'C', 'Evaporative heat loss occurs as amniotic fluid evaporates from the skin; immediately drying the newborn with a warm blanket removes this moisture and is the most effective prevention. A radiant warmer counters radiant loss, not evaporation. Per Kenya Basic Paediatric Protocols (newborn thermal care).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse prepares to administer a phytonadione (vitamin K) injection to a newborn, which explanation should the nurse give to the mother concerning the medication?', '“Your newborn needs the medicine to develop immunity.”', '“The medicine will protect your newborn from being jaundiced.”', '“Newborns have sterile bowels, and the medicine promotes the growth of bacteria in the bowel.”', '“Newborns are deficient in vitamin K, and this injection prevents your newborn from bleeding”', 'D', 'Newborns have low vitamin K stores and sterile gut flora, so vitamin K (phytomenadione) is given to prevent vitamin K deficiency bleeding (haemorrhagic disease of the newborn). It is not an immunisation and does not prevent jaundice. Per Kenya Essential Medicines List / Basic Paediatric Protocols (newborn care).
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The treatment of choice for trichomoniasis is;', 'Ceftriaxone', 'Doxycycline', 'Metronidazole', 'Norfloxacin', 'C', 'Per Kenya National STI guidelines and EML, metronidazole (or tinidazole) is the treatment of choice for Trichomonas vaginalis. Ceftriaxone/doxycycline treat gonorrhoea/chlamydia.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Deafness that develops after speech has developed is referred to as;', 'Adventitious deafness', 'Psychogenic deafness', 'Hard of hearing', 'Congenital deafness', 'A', 'Per ENT/community health references, adventitious (acquired) deafness is hearing loss that occurs after speech/language has already developed, in contrast to congenital deafness which is present at/before birth.', 'KRCHN', 'Paper I', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following statement is FALSE about spermicides;', 'May cause congenital abnormalities when used several times a day.', 'May increase the risk of HIV infection if used several times a day.', 'Can be inserted ahead of time and so do not interrupt sex', 'Should not be used by women with HIV infection', 'A', 'Per Kenya FP guidelines, spermicides do NOT cause congenital abnormalities, so this statement is FALSE. Spermicides can be inserted ahead of time, and frequent use may irritate mucosa and increase HIV risk (so they are not advised for women at high HIV risk), making the other statements true.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In classification of acute respiratory infections in children, very severe symptoms include:-', 'Stridor, ear discharge, blocked nose', 'Chest indrawing, stridor, grey membrane in the throat', 'Purulent pharyngitis, ear discharge, fast breathing >70bpm', 'Cyanosis, unable to drink, respiratory rate > 70bpm', 'D', 'Per Kenya IMNCI/Basic Paediatric Protocols, very severe/severe pneumonia danger signs include central cyanosis, inability to drink and very fast breathing; option D captures these. Stridor with ear discharge or blocked nose are not classified as very severe ARI signs.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The causative agent of chancroid is:', 'Chlamydia trachomatis', 'Treponema pallidium', 'Hemophilius ducreyi', 'Ureaplasma urealyticum', 'C', 'Per Kenya STI guidelines/Brunner & Suddarth, chancroid (soft sore) is caused by Haemophilus ducreyi. Treponema pallidum causes syphilis and Chlamydia trachomatis causes LGV/chlamydia, so those distractors are wrong.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Developmental milestone achieved at 12-18 months include:', 'A child sitting unsupported, grasping actively and makes loud noises', 'A child is able to run around, says several words', 'A child is able to stand, understand a few words and tries to use them', 'A child is able to walk, grasp small objects with thumbs and fingers', 'B', 'Per Kenya paediatric developmental milestones (Basic Paediatric Protocols), by 12-18 months a toddler walks/runs and says several words. Sitting unsupported and standing with pincer grasp are earlier milestones (around 6-12 months).', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In enterobiasis infection, the adult worm lives in the:-', 'Lungs', 'Caecum', 'Large intestines', 'Small intestines', 'B', 'Per parasitology in Kenyan nursing texts, in enterobiasis the adult Enterobius vermicularis (pinworm) lives in the caecum and appendiceal region; females migrate to the perianal area to lay eggs. Caecum is the specific site making it the best answer over ''large intestines''.', 'KRCHN', 'Paper I', 'Infection Prevention & Control', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Gumma lesions are characteristic of:-', 'Latent stage of syphilis', 'Primordial stage of syphilis', 'Tertiary stage of syphilis', 'Secondary stage of syphilis', 'C', 'Per Kenya STI guidelines/Brunner & Suddarth, gummas (granulomatous lesions) are characteristic of tertiary syphilis. Primary syphilis presents with a chancre and secondary with rash/condylomata lata.
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following is a lymphoma that affects children:', 'Non-hodgkin''s disease', 'Acute lymphoblastic disease', 'Acute myeloid leukemia', 'Wilm''s tumor', 'A', 'Non-Hodgkin''s lymphoma is a lymphoma of childhood; ALL is a leukemia, AML is a leukemia, and Wilm''s tumor is a renal tumor, not lymphomas (Nelson/Basic Paediatric Protocols, Kenya).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Bullous impetigo;', 'Is not contagious', 'Is commonly caused by Staphylococcus', 'Presents with painful blisters', 'Is managed using topical steroids', 'B', 'Bullous impetigo is commonly caused by Staphylococcus aureus (toxin-mediated); it is contagious, presents with fragile painless bullae, and is treated with antibiotics, not topical steroids (Basic Paediatric Protocols; Brunner & Suddarth''s).', 'KRCHN', 'Paper I', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The management of a child with mumps includes the following EXCEPT', 'Use of cold compresses', 'Use of aspirin to relieve pain', 'Warm salt water gargles', 'Avoiding  acidic foods', 'B', 'Aspirin is contraindicated in children with viral illness (mumps) due to Reye''s syndrome risk; cold compresses, warm salt gargles and avoiding acidic foods are appropriate, so aspirin is the EXCEPTion (Basic Paediatric Protocols; Kenya paediatric guidelines).', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Rheumatic heart disease is caused by;', 'Streptococcus pyogenes', 'Staphylococcus aureus', 'Haemophilus influenza', 'Streptococcus pneumonia', 'A', 'Rheumatic heart disease follows rheumatic fever caused by group A beta-haemolytic Streptococcus pyogenes; the other organisms are not implicated (Brunner & Suddarth''s; Kenya clinical guidelines).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following statement is true regarding normal growth and development of a child', 'Average length of a child is 20 inches at birth and 30 inches at 1 year', 'At the age of 3 years, the average child is 6 feet tall', 'At age 4 years, the average child is 80 inches tall', 'The average annual height increase is 10 inches between age 4 years and puberty', 'A', 'Normal birth length is ~50 cm (~20 inches) and increases by ~50% by 1 year to ~75 cm (~30 inches). Per Basic Paediatric Protocols (Kenya) / standard growth norms. The other options give grossly abnormal heights.', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following is a normal finding in pediatric respiratory assessment', 'Large head, large mandible', 'Small posteriorly-placed tongue', 'Large airways rigid thoracic cage', 'Horizontal ribs, primarily diaphragm breathers', 'D', 'Infants/young children have horizontally placed ribs and are primarily diaphragmatic (abdominal) breathers, a normal finding. Their airways are small (not large/rigid) and tongue is relatively large. Per paediatric respiratory assessment norms (Basic Paediatric Protocols).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When palpating a child''s abdomen you note hepatomegaly. You know this can be a sign of what cardiac problem?', 'Right sided heart failure', 'Left- sided heart failure', 'Rheumatic heart disease', 'Anemia', 'A', 'Right-sided heart failure causes systemic venous congestion, producing hepatomegaly and peripheral oedema. Left-sided failure causes pulmonary congestion. Per Brunner & Suddarth''s Medical-Surgical Nursing.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following should be included in the health teachings among clients receiving Valium:', 'Avoid taking CNS depressant like alcohol.', 'There are no restrictions in activities.', 'Limit fluid intake.', 'Any beverage like coffee may be taken', 'A', 'Valium (diazepam) is a CNS depressant; combining it with alcohol or other CNS depressants causes dangerous additive sedation and respiratory depression, so clients must be taught to avoid alcohol. Per Kenya EML / BNF pharmacology.
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which one of the following is an uncontrollable risk factor that has been linked to development of coronary artery disease(CAD)', 'Exercise', 'obesity', 'stress', 'heredity', 'D', 'Per Brunner & Suddarth, heredity (family history), age, gender and race are non-modifiable (uncontrollable) CAD risk factors, whereas obesity, stress and physical inactivity are modifiable.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following are risk factors for impaired gas exchange and pulmonary infection :', 'Immobility, constipation and incontinence', 'Fluid restriction, immunosuppression and decreased level of consciousness.', 'Fluid restriction, immobility and ingestion of seasoned foods', 'Incontinence, chemotherapy and anemia', 'B', 'Fluid restriction thickens secretions, immunosuppression predisposes to infection, and decreased LOC impairs airway clearance/cough — all promoting impaired gas exchange and pulmonary infection (Brunner & Suddarth respiratory nursing).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When nursing a patient on steroids, the nurse should,', 'Observe for oedema, weigh daily, monitor blood counts', 'Maintain infection control, monitor blood sugar, maintain hydration', 'Observe for bone marrow suppression, minimise exposure to heat,encourage bed rest', 'Encourage increased fluid intake, administer anti-emetics, monitor RBC count', 'B', 'Corticosteroids cause immunosuppression (infection risk) and hyperglycaemia, and fluid balance must be maintained; per Kenya EML/BNF steroid monitoring these are the key nursing priorities. Bone marrow suppression is a cytotoxic, not steroid, effect.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The common causative organism for pharyngitis is,', 'Group B, beta hemolytic streptococcus', 'Group A, beta hemolytic streptococcus', 'Hemophilus influenza', 'Staphylococcus aureus', 'B', 'Group A beta-haemolytic streptococcus (Streptococcus pyogenes) is the classic bacterial cause of pharyngitis (Brunner & Suddarth; IMNCI sore throat guidance).', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In pulmonary embolism (PE),', 'There is a clot formation in the pulmonary vein and or its branches', 'There is obstruction of the Pulmonary artery or one of its branches', 'Trauma, pregnancy and Valsava maneuvers are common predisposing factors', 'Old age, heart failure and intestinal obstruction clients are more prone', 'B', 'Pulmonary embolism is obstruction of the pulmonary artery or a branch, usually by a thrombus from the deep veins (Brunner & Suddarth). The clot lodges in the artery, not the pulmonary vein.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Dumping syndrome is as a result of,', 'Rapid emptying of hypertonic food from the stomach into the jejunum', 'Failure of a patient with a peptic ulcer to eat regularly', 'Chronic anemia among the elderly patients', 'Loss of the large intestine functionality following hemicolectomy', 'A', 'Dumping syndrome, common after gastric surgery, results from rapid emptying of hypertonic gastric contents into the jejunum causing fluid shifts (Brunner & Suddarth GI nursing).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('For a patient to undergoing a kidney, ureter and bladder X-ray is important for the nurse to know that,', 'There is no special preparation required.', 'Oral fluids must be withheld the morning of the examination.', 'The patient should have a full bladder before the procedure.', 'An enema should be administered before the procedure', 'A', 'A plain KUB (kidney-ureter-bladder) X-ray requires no special preparation such as fasting, bowel prep or bladder filling (Brunner & Suddarth diagnostic procedures).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The vitamin required for normal production of RBCs is;', 'calcium', 'vitamin A', 'folic', 'vitamin K', 'C', 'Folic acid (folate), with vitamin B12, is required for normal red blood cell production/maturation; deficiency causes megaloblastic anaemia (Kenya nutrition/haematology guidance, Brunner & Suddarth).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Plain insulin has peak action of;', '8- 12hours', '2-3 hours', '12-16hours', '16-30hours', 'B', 'Plain/regular (short-acting soluble) insulin has onset ~30 min, peak action about 2-3 hours (Kenya EML/BNF insulin pharmacology).', 'KRCHN', 'Paper I', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Valsava maneuver can result to bradycardia. Which of the following activities will not stimulate valsalva’s maneuver?', 'Use of stool softeners', 'Enema administration', 'Gaggling while tooth brushing', 'Lifting heavy objects', 'A', 'Straining (enema, forceful gagging, heavy lifting) triggers the Valsalva manoeuvre; stool softeners prevent straining and therefore do NOT stimulate it (Brunner & Suddarth). The question asks which will NOT stimulate the manoeuvre.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the reason for the nurse in instructing the client to rotate the injection sites for insulin?', 'lipodystrophy can result and extremity painful', 'Poor rotation technique can cause superficial hemorrhaging', 'lipodystrophic areas can result, causing erratic insulin absorption rates from these', 'Injection sites can never be reused', 'C', 'Insulin injection sites are rotated to prevent lipodystrophy (lipohypertrophy/atrophy), which causes erratic, unpredictable insulin absorption (Kenya diabetes guidelines; Brunner & Suddarth).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Nurse Nyaruai is giving a health education talk to Mothers attending the MCH/FP clinic at Kapkoros health center. As a knowledgeable nurse, she must know that a mother who breastfeeds her child passes on which antibody through breast milk?', 'IgA', 'IgG', 'IgM', 'IgE', 'A', 'Secretory IgA is the predominant antibody passed to the infant in breast milk (especially colostrum), providing mucosal/gut protection (Kenya MCH/IMNCI, WHO breastfeeding guidance). IgG crosses the placenta, not chiefly milk.', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following interventions would be helpful to a breastfeeding mother who is experiencing engorged breasts?', 'Applying ice', 'Administering bromocriptine', 'Applying a breast binder', 'Teaching how to express her breasts in a warm shower', 'D', 'For a breastfeeding mother with engorgement, warmth and expression/continued feeding relieve the fullness (Myles Textbook for Midwives). Ice, bromocriptine and binders are used to suppress lactation, not for a mother who wishes to continue breastfeeding.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('You are preparing to perform a fundal assessment on a postpartum client. The initial nursing action in performing this assessment is which of the following?', 'Ask the client to turn on her side', 'Ask the mother to urinate and empty her bladder', 'Massage the fundus gently before determining the level of the fundus.', 'Ask the client to lie flat on her back with the knees and legs flat and straight', 'B', 'The first action in fundal assessment is to have the client empty her bladder, since a full bladder displaces and elevates the fundus giving a false reading (Myles Textbook for Midwives; postpartum nursing).', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following complications is Most likely responsible for a delayed postpartum hemorrhage?', 'Cervical laceration.', 'Uterine sub involution', 'Perineal laceration', 'Clotting deficiency', 'B', 'Delayed (secondary) postpartum haemorrhage occurring after 24 hours is most often due to uterine subinvolution or retained placental fragments (Myles Textbook for Midwives). Lacerations cause early/primary PPH.', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Following a difficult labor and birth, a primiparous woman refuses to feed her baby four hours after delivery, she states that she is too tired and just wants to sleep. The nurse should:', 'Tell the woman she can rest after she feeds her baby', 'Take the baby back to the nursery, reassuring the woman that her rest is a priority at this time', 'Recognize this as a behavior of the taking-hold stage', 'Record the behavior as ineffective maternal-newborn attachment', 'B', 'In the taking-in phase after a difficult birth the mother is fatigued and focused on her own needs; the nurse supports rest and defers feeding, reassuring her (Myles Textbook for Midwives, Rubin''s maternal phases). Forcing feeding or labelling poor attachment at 4 hours is inappropriate.', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('MrsWangombe is under your care and expresses concern about the weight she gained during pregnancy and how quickly she can lose it now that the baby is born. In describing the expected pattern of weight loss, you should begin by telling her that:-', 'Lactation will inhibit weight loss since caloric intake must increase to support milk production', 'Return to pre pregnant weight is usually achieved by the end of the postpartum period', 'Fluid loss from diuresis, diaphoresis, and bleeding accounts for about a 3 pound weight loss', 'The expected weight loss immediately after birth averages about 11 to 13 pounds', 'D', 'Immediately after birth the expected weight loss (fetus, placenta, amniotic fluid, blood) averages about 11-13 pounds (Myles Textbook for Midwives). Further loss from diuresis/diaphoresis follows over the puerperium.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Signs of puerperal sepsis include', 'Pyrexia, tachycardia, whitish lochia', 'Pyrexia, tachycardia, red lochia', 'Pyrexia, tachycardia, pink lochia', 'Pyrexia, tachycardia, offensive lochia', 'D', 'Puerperal sepsis presents with pyrexia, tachycardia and offensive (foul-smelling) lochia with lower abdominal pain (Kenya maternal care guidelines; Myles Textbook for Midwives).', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Systemic changes during normal puerperium include', 'Involution of the uterus, lochia loss, blood volume returns to normal', 'Rising of the fundus, lochia loss, blood volume decreases', 'Involution of the uterus, lochia loss, blood volume increases', 'Maternal weight gain', 'A', 'Normal puerperium involves uterine involution, progressive lochia loss, and the elevated pregnancy blood volume returning to normal (Myles Textbook for Midwives). The fundus descends rather than rising.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('General nursing care during post-partal period includes assessment of the:', 'Breasts, abdomen, and fundus', 'Breasts, abdomen, and musculoskeletal system', 'Breasts, abdomen, and neurological responses', 'Breasts, abdomen and congenital abnormalities', 'A', 'Postpartum assessment (BUBBLE-HE) covers breasts, uterus/fundus and abdomen among others; assessing breasts, abdomen and fundus is standard general postpartum care (Myles Textbook for Midwives).', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('You are taking vital signs observations on a postpartum client who delivered a healthy newborn 4 hours ago. Her temperature is 100.2° F or 37.9 What is the priority nursing action?', 'Increase hydration by encouraging oral fluids.', 'Document the findings.', 'Retake the temperature in 15 minutes', 'Notify the doctor Postpartum fever is defined as a temperature of 38.7 degrees C (101.6 degrees F) or greater for the first 24 hours or greater than 38.0 degrees C (100.4 degrees F) on any two of the first 10 days postpartum.', 'A', 'A temperature of 37.9C (100.2F) within the first 24 hours postpartum is commonly due to dehydration/exertion and is not defined as puerperal fever (>=38C); the priority is to increase oral fluids and reassess (Myles Textbook for Midwives).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the best position to assess a postpartum woman’s fundus?', 'On her right side.', 'Semi-Fowler position.', 'Supine with knees slightly flexed.', 'In a chair, with feet elevated.', 'C', 'The fundus is best assessed with the woman supine and knees slightly flexed to relax the abdominal muscles, after bladder emptying (Myles Textbook for Midwives).', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The main function of oxytocin during puerperium is to stimulate:', 'Estrogen production', 'Progesterone production', 'Contraction of uterine muscle and breast tissues', 'Production of Human Placental Lactogen', 'C', 'Per Myles Textbook for Midwives, oxytocin causes uterine muscle contraction (involution) and contraction of myoepithelial cells in the breast for milk ejection during puerperium; it does not stimulate estrogen, progesterone or hPL production.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Fertilization occurs in one of the following parts of fallopian tube.', 'Infundibulum', 'Fimbrae', 'Ampulla', 'Isthmus', 'C', 'Per Myles Textbook for Midwives, fertilization normally occurs in the ampulla (widest part) of the fallopian tube; the infundibulum, fimbriae and isthmus are not the usual sites.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In the female genital tract the sperms undergo physio-biochemical modification to allow spermovum interaction. This modification is known as:', 'Capacitation', 'Transformation', 'Reaction', 'Activation', 'A', 'Per Myles Textbook for Midwives, capacitation is the physio-biochemical modification sperm undergo in the female genital tract enabling them to penetrate and fertilize the ovum.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The placenta originates from one of the following parts of the fertilized ovum', 'Inner cell mass', 'York sac', 'Trophoblast', 'Embryoblast', 'C', 'Per Myles Textbook for Midwives, the outer trophoblast (trophoblastic cells) of the blastocyst gives rise to the placenta and chorion; the inner cell mass/embryoblast forms the embryo.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following structures in fetal circulation joins the umbilical cord to the inferior vena cava', 'Ductus arteriosus', 'Foramen ovale', 'Ductus venosus', 'Hypogastric arteries', 'C', 'Per Myles Textbook for Midwives, the ductus venosus connects the umbilical vein to the inferior vena cava, allowing oxygenated blood to bypass the fetal liver.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following type of exercises should be avoided in pregnancy', 'Walking for 30 minutes', 'Sexual intercourse', 'Aerobic exercise', 'Mountain climbing', 'D', 'Per Kenya maternal health / Myles guidance, high-altitude mountain climbing and high-risk activities should be avoided in pregnancy; moderate walking, aerobic exercise and intercourse are generally safe.', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In class III cardiac disease in pregnancy, patient has:', 'No limitation of physical activity, heart murmur on general examination', 'Slight limitation of physical activity, no symptoms when at rest', 'Marked limitation of physical activity, slight exertion leads to fatigue, palpitations, dyspnea', 'Inability to carry out any physical activity without discomfort, signs of cardiac disease and heart failure even at rest', 'C', 'Per NYHA classification (Brunner & Suddarth), Class III is marked limitation of physical activity with symptoms on less-than-ordinary exertion; comfortable only at rest.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following statement is true concerning preeclampsia.', 'Oedema is considered as part of the diagnosis of preeclampsia', 'Preeclampsia is primarily hypertension during pregnancy', 'The cardinal signs of preeclampsia include oedema and headache', 'Preeclampsia is gestational hypertension plus proteinuria', 'D', 'Per Kenya maternal guidelines and Myles Textbook for Midwives, preeclampsia is defined as new-onset gestational hypertension after 20 weeks with proteinuria; oedema is no longer a diagnostic criterion.', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following sex hormone is produced during throughout the menstrual cycle', 'Follicle stimulating hormone', 'Luteinizing hormone', 'Estrogen', 'Progesterone', 'C', 'Per Myles Textbook for Midwives, estrogen is produced throughout the menstrual cycle (follicular and luteal phases), whereas progesterone predominates only after ovulation and FSH/LH peak transiently.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following hormone causes development of new blood vessels to the uterus', 'Eostrogen', 'Progesterone', 'Luteinizing hormone', 'Follicle stimulating hormone', 'A', 'Per Myles Textbook for Midwives, estrogen stimulates growth and vascularisation (development of new blood vessels) of the uterus and endometrium during the proliferative phase.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Management of nausea and vomiting among pregnant women include:-', 'Skipping meals', 'Eating small meals frequently', 'Avoiding crackers before getting up in the morning', 'Encouraging highly seasoned foods', 'B', 'Per Myles Textbook for Midwives and Kenya ANC guidance, morning sickness is managed by eating small, frequent meals, dry crackers before rising and avoiding an empty stomach; skipping meals worsens symptoms.', 'KRCHN', 'Paper I', 'Nursing Management & Leadership', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Ptyalism refers to:', 'Excessive nausea and vomiting in pregnancy', 'Lack of appetite', 'An abnormal craving for non-food substances of little or no nutritional value', 'Increased salivation', 'D', 'Per Myles Textbook for Midwives, ptyalism is excessive salivation, a minor disorder of pregnancy; excessive vomiting is hyperemesis and craving non-food items is pica.', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In focused antenatal care, the second dose of sulfadoxine pyrimethamine(SP) is administered at gestation of:', '16-28 weeks', '20-30 weeks', '28-34 weeks', '34-36 weeks', 'C', 'Per Kenya focused ANC / malaria in pregnancy guidelines, IPTp-SP is given from 13 weeks at least one month apart; the second dose falls around 28-34 weeks in the third trimester.', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Fetal axis pressure is a physiological change that is more significant during:', 'Early stages of labor transmitting the force of contraction to the upper pole of fetus', 'Second stage of labor when membranes are intact', 'Active and second stages of labor when membranes are ruptured', 'Second stage of labour transmitting the force of contraction to the lower pole of the uterus', 'C', 'Per Myles Textbook for Midwives, fetal axis pressure (transmission of contraction force down the fetal axis) becomes more significant during active and second stage once membranes have ruptured.', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('If the membranes rupture at cervical dilatation of 8 cm, a vaginal examination performed rule out:', 'Obstructed labour, cord prolapsed, fetal compromise', 'Cord prolapsed, cord presentation, fetal distress', 'Obstructed labour, cord prolapsed, prolonged labour', 'Maternal distress, prolonged labour, cord presentation', 'B', 'Per Myles Textbook for Midwives, when membranes rupture the immediate vaginal examination aims to exclude cord prolapse/presentation and assess for fetal distress (fetal heart rate).', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Laboratory findings that are consistent with hyperthyroidism include', 'Decreased serum triiodothyronine (T3) and thyroxine (T4) levels', 'Elevated serum thyrotropin releasing hormone (TRH) levels', 'Decreased radioactive iodine uptake', 'Increased free triiodothyronine (T3) and thyroxine (T4) levels', 'D', 'Per Brunner & Suddarth''s Medical-Surgical Nursing, hyperthyroidism is characterised by elevated free T3 and T4 with suppressed TSH and increased radioactive iodine uptake.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Substances that create colloid osmotic pressure in the capillaries include;', 'Albumin, globulin', 'Plasma, potassium', 'Globulin, sodium', 'Albumin, potassium', 'A', 'Per anatomy & physiology texts, plasma proteins albumin and globulin generate colloid (oncotic) osmotic pressure in the capillaries; electrolytes like sodium and potassium contribute to crystalloid osmotic pressure.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Discharge instructions for a client with chronic respiratory acidosis should include', 'Discussing how to plan for periods of increased activity', 'Teaching about a low protein, low carbohydrate diet', 'Demonstrating exercises to increase vital capacity', 'Encouraging participation in activities such as jogging', 'C', 'Per Brunner & Suddarth''s Medical-Surgical Nursing, clients with chronic respiratory acidosis (e.g. COPD) are taught breathing/pulmonary exercises to improve vital capacity; strenuous activity like jogging and increased activity periods are inappropriate.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The predilection of HIV for certain cells in the immune system results in', 'More T4 lymphocytes and general lymphocytopenia', 'Fewer activated B-cells and hypogammaglobulinemia', 'Increased response in cutaneous hypersensitivity', 'Susceptibility to opportunistic infection and neoplasm', 'D', 'Per Brunner & Suddarth and Kenya HIV guidelines, HIV targets CD4 (T4) helper lymphocytes causing their depletion and immunosuppression, leading to opportunistic infections and neoplasms.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The most common preventable cause of valvular heart disease is:', 'Congenital disease acquired intrauterine', 'Calcium deposits and thrombus formation', 'Marfans syndrome', 'Beta-hemolytic streptococcal infection', 'D', 'Per Brunner & Suddarth''s Medical-Surgical Nursing, rheumatic heart disease following group A beta-haemolytic streptococcal infection is the most common preventable cause of valvular heart disease.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Pelvic inflammatory diseases include:', 'Salpingitis, cervicitis, candidiasis', 'Cervicitis, endometritis, oophoritis.', 'Trichomoniasis, salpingitis, urethritis.', 'Candidiasis, toxic shock syndrome, endometritis.', 'B', 'Per Brunner & Suddarth''s Medical-Surgical Nursing, PID is ascending infection of the upper genital tract including cervicitis, endometritis, salpingitis and oophoritis; candidiasis and trichomoniasis are lower-tract/vaginal infections, so option B best lists true PID components.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Cholelithiasis is associated with:-', 'Abnormal metabolism of cholesterol and bile salts.', 'Abnormal metabolism of lipids and bile acids.', 'Chronic pancreatitis.', 'Hepatitis.', 'A', 'Per Brunner & Suddarth''s, cholesterol gallstones (the commonest type) form when bile is supersaturated with cholesterol relative to bile salts, i.e. abnormal metabolism of cholesterol and bile salts. Lipids/bile acids and pancreatitis/hepatitis are not the primary mechanism.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Glomerulonephritis usually follows:-', 'Staphylococcal infection.', 'Gonococcal infection.', 'Gonococcal infection.', 'Streptococcal infection', 'D', 'Per Brunner & Suddarth''s, acute post-streptococcal glomerulonephritis typically follows a group A beta-haemolytic streptococcal throat or skin infection. Options B and C are duplicates (gonococcal) and incorrect.', 'KRCHN', 'Paper I', 'Infection Prevention & Control', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The teeth that commonly get impacted are the :-', 'Molars.', 'Incisors.', 'Canine.', 'Wisdom.', 'D', 'The third molars (wisdom teeth), being the last to erupt with insufficient jaw space, are the most commonly impacted teeth (standard anatomy/dental texts).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Body mechanics usually prescribed for clients with low pain include:-', 'Bending at knee and hips, standing straight, carrying objects close to the body.', 'Bending at the waist carrying objects close to the body, standing straight.', 'Sleeping on the side carrying objects farther from the body, bending at the knees and hips.', 'Bending at the waist, sleeping on the side, standing straight.', 'A', 'Per Kozier & Erb''s Fundamentals of Nursing, correct body mechanics for low-back pain prevention involve bending at the knees and hips (not the waist), keeping the back straight, and carrying objects close to the body to reduce spinal strain.', 'KRCHN', 'Paper I', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When a nurse is monitoring a patient for cerebrospinal fluid (CSF) leak he/she should observe for:-', 'Halo sign.', 'Babinski reflex.', 'Iliopsoas sign.', 'Blumberg sign.', 'A', 'Per Brunner & Suddarth''s, CSF leak is detected by the halo (ring) sign, where drainage on gauze forms a clear ring around blood, and by glucose-positive fluid. Babinski, iliopsoas and Blumberg signs are unrelated neurological/abdominal signs.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The commonest cause of toxic goitre (Grave’s disease) is: -', 'Pituitary tumours', 'Benign thyroid', 'Lack of iodine in the diet', 'Immunoglobulins reaction', 'D', 'Per Brunner & Suddarth''s, Graves'' disease is an autoimmune disorder caused by thyroid-stimulating immunoglobulins (TSH-receptor antibodies). Iodine lack causes simple/endemic goitre, not toxic Graves'' goitre.', 'KRCHN', 'Paper I', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Parathyroid hormone maintains fluid and electrolyte balance by', 'Promoting absorption of calcium from the intestines', 'Inhibiting release of calcium from the bone', 'Increasing the excretion of phosphate ions by the kidneys', 'Acting on the renal tubules to retain water and to decrease urinary output', 'C', 'Parathyroid hormone raises serum calcium by mobilising calcium from bone, increasing intestinal (via vitamin D) and renal calcium reabsorption, and increasing renal excretion of phosphate. Of the options given, increasing phosphate excretion by the kidneys is the correct PTH action (Guyton/standard physiology).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The carcinogenic risk factors for laryngeal cancers include:', 'Tar products, mustard gas, chronic laryngitis', 'Asbestos, chronic laryngitis, voice straining', 'Voice straining, high fibre diet, tobacco', 'Asbestos, tobacco, tar products', 'D', 'Per Brunner & Suddarth''s, carcinogenic risk factors for laryngeal cancer include tobacco, alcohol, asbestos and tar/industrial exposures. A high-fibre diet (option C) is protective, not carcinogenic, so D is the fully correct set.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In Fallot’s tetralogy there is', 'Pulmonary artery stenosis, ventricular septal defect, aortic misplacement & right ventricular hypertrophy.', 'Coarctation of the aorta, patent ductus arteriosus, aortic stenosis and ventricular septal defect.', 'Ventricular hypertrophy, coarctation of the aorta, atrial septal defect and Blue babies’ syndrome', 'Atrial-ventricular hypertrophy, coarctation of the aorta, ventricular septal defect and pulmonary artery stenosis.', 'A', 'Tetralogy of Fallot classically comprises pulmonary (artery) stenosis, ventricular septal defect, overriding (misplaced) aorta and right ventricular hypertrophy (standard paediatric/anatomy texts).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The position an unconscious patient should be nursed in is:', 'Recumbent', 'Lithotomy', 'Prone', 'Semi-prone', 'D', 'Per Kozier & Erb''s, the unconscious patient is nursed in the semi-prone (recovery/lateral) position to maintain a patent airway and allow drainage of secretions, preventing aspiration.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Parklands’ formula is used to calculate', 'Total burnt surface area', 'Fluid replacement', 'Thickness of the burn', 'Hemo-concentration', 'B', 'Per Brunner & Suddarth''s / MOH burns guidelines, the Parkland formula (4 ml x weight x %TBSA) calculates the volume of IV fluid replacement required in the first 24 hours after a burn.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The body’s internal environment which is tightly controlled and kept within normal limit is:', 'Control feedback mechanism', 'Compensatory mechanism', 'Homeostasis', 'Equilibrium', 'C', 'Homeostasis is the maintenance of a relatively stable internal environment within narrow normal limits (standard physiology, Guyton).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The vascular coat of eye ball that lies between the sclera and retina is', 'Uvea', 'Iris', 'Ciliary body', 'Choroid', 'D', 'The choroid is the vascular layer of the eye lying between the sclera and the retina. The uvea is the whole vascular tunic (choroid+ciliary body+iris); the specific layer between sclera and retina is the choroid (standard anatomy).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Following thyroidectomy, the nurse suspects damage or removal of parathyroid gland when the patient develops:', 'Muscle weakness and weight loss', 'Hyperthermia and severe tachycardia', 'Hypertension and difficulty in swallowing', 'Laryngeal stridor and tingling in the hands and feet', 'D', 'Per Brunner & Suddarth''s, parathyroid damage after thyroidectomy causes hypocalcaemia manifesting as tetany: perioral/peripheral tingling (paraesthesia), carpopedal spasm and laryngeal stridor/spasm.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('increased concentration of red blood cells due to excessive production of erythropoietin is referred to as:', 'primary polycythemia', 'leukopenia', 'secondary polycythemia', 'agranulocytosis', 'C', 'Per Brunner & Suddarth''s, secondary polycythaemia is an increase in RBC mass driven by excessive erythropoietin (e.g. from hypoxia). Primary polycythaemia (vera) is a clonal marrow disorder with low/normal erythropoietin.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which cranial nerve is involved when the patient presents with facial pain, diminished corneal reflex and chewing dysfunction:', 'III', 'IV', 'V', 'VI', 'C', 'The trigeminal nerve (cranial nerve V) supplies facial sensation, the afferent limb of the corneal reflex, and the muscles of mastication; its involvement causes facial pain, diminished corneal reflex and chewing dysfunction (standard neuroanatomy).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The main long-term complication following radical mastectomy is', 'Phantom pain', 'Tingling and numbness', 'Lymphoedema', 'Paralysis', 'C', 'Per Brunner & Suddarth''s, lymphoedema of the affected arm is the main long-term complication after radical mastectomy due to removal of axillary lymph nodes impairing lymphatic drainage.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Steroid nasal sprays are used in management of sinusitis to:', 'Moisten secretions', 'Prevent nasal crusting', 'Reduce mucosal inflammation', 'Thin the nasal secretions', 'C', 'Per Kenya EML/BNF, intranasal corticosteroids act by reducing mucosal inflammation and oedema, thereby improving sinus drainage in sinusitis.', 'KRCHN', 'Paper I', 'Nursing Management & Leadership', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Haemophilia A results from deficiency of factor:', 'VII', 'IX', 'III', 'V', 'B', 'Haemophilia A is caused by deficiency of clotting factor VIII, and haemophilia B by factor IX; factor VIII is not among the options, so of the choices given IX is intended as the coagulation-factor deficiency answer. (Standard haematology; note factor VIII is the true answer for haemophilia A.)
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The accumulation of thick, purulent fluid within the pleural space with fibrin development is characteristic of:', 'Empyema', 'Effusion', 'Pleurisy', 'Emphysema', 'A', 'Per Brunner & Suddarth''s, empyema is the accumulation of thick, purulent fluid within the pleural space, often with fibrin and loculation. Pleural effusion is fluid without pus, pleurisy is inflammation, and emphysema is alveolar destruction.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The trophoblast cells of the developing zygote from the:-', 'Fetus and amnion', 'Placenta and fetus', 'Chorion and amnion', 'Placenta and chorion', 'D', 'Per Myles Textbook for Midwives, the trophoblast (outer cells of the blastocyst) develops into the chorion and the fetal portion of the placenta; the inner cell mass forms the fetus and amnion.', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When performing Leopold''s maneuver, the purpose of the first maneuver is to determine', 'Fetal part lying in the fundus and presentation', 'Location of fetal back and position', 'Engagement of the presenting part', 'The degree of flexion of fetal head', 'A', 'Per Myles Textbook for Midwives, the first Leopold''s manoeuvre (fundal palpation) determines which fetal pole occupies the fundus, thereby indicating the presentation/lie.', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('If Mrs. Cola’s menstrual period was on 27.7.08, her expected date of delivery will be:', '3.4.09', '4.5.09', '3.5.09', '4.4.09', 'C', 'Per Naegele''s rule (Myles), EDD = LMP - 3 months + 7 days + 1 year. From 27.7.08: -3 months = 27.4, +7 days = 3.5, +1 year = 3.5.09.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The most important benefit of vestibular stimulation in the normal newborn is improvement of', 'Sucking capability', 'Tactile sensitivity', 'Motor coordination', 'Attention span', 'C', 'Vestibular stimulation in the normal newborn primarily promotes development of motor coordination and balance through the vestibular-cerebellar system (developmental paediatric literature).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In focused antenatal care, the second dose of sulfadoxine pyrimethamine (sp) is administered at gestation of:-', '16-28 weeks(First dose)', '20-30 weeks.', '28-34 weeks. (Second dose)', '34-36 weeks.', 'C', 'Per Kenya National Malaria in Pregnancy / focused ANC guidelines, IPTp-SP is given from 16 weeks; the second dose follows about a month later, typically 28-34 weeks. The option is explicitly labelled second dose.', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The diastolic pressure is usually not affected by excitement, its increase is therefore more significant in assessment of pregnant women for pre-eclampsia. The range of change in mmHg is:-', '10-15', '15-20', '15-30', '20-30', 'C', 'Per Myles Textbook for Midwives, a diastolic rise of 15-30 mmHg (or diastolic >=90 mmHg) over baseline is significant for pre-eclampsia because diastolic pressure is little affected by excitement.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The management of placenta previa type three when the fetus has died in utero includes:-', 'Preparation of woman for emergency caesarian section.', 'Induction of labour by use of syntocinon.', 'Gentle palpation through vaginal forncles to determine whether posterior or anterior.', 'Complete bed rest and speculum examination on third day.', 'A', 'Per Myles/MOH obstetric guidelines, placenta praevia type III (major, covering the os) mandates delivery by caesarean section regardless of fetal state; vaginal delivery and syntocinon induction are contraindicated due to torrential haemorrhage risk.', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The hormonal factor responsible for uterine contractions at onset of labour are:-', 'Increase release of oxytocin progesterone from deciduas at term.', 'Formation of oxytocin and estrogen in the fetal circulation', 'Rise of oxytocin and estrogen in the fetal circulation.', 'Optimum levels of estrogen and rise of prostaglandins in maternal circulation.', 'D', 'Per Myles Textbook for Midwives, labour onset involves a fall in progesterone with dominance of oestrogen plus a rise in prostaglandins and oxytocin sensitivity that trigger coordinated uterine contractions.', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('If membranes rupture at cervical dilation of 8 centimeters, a vaginal examination performed should rule out:-', 'Obstructed labour, cord prolapse, fetal compromise.', 'Cord prolapse, cord presentation, fetal distress.', 'Obstructed labour, cord prolapse, prolonged labour.', 'Maternal distress, prolonged labour, cord presentation.', 'B', 'Per Myles/MOH intrapartum guidelines, when membranes rupture a vaginal examination is done to exclude cord prolapse and cord presentation and to check the fetal heart for distress, as the cord may be swept down with the gush of liquor.', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The partograph is an effective tool in management of women in labour, a good progress in the active phase will be:-', 'Cervical dilatation plotted progressively on alert line within 7 hours.', 'Uterine contractions increase in strength from 20-25 seconds within 8 hours.', 'Cervical dilation plotted on the action line and progressive descent.', 'Cervical dilatation plotted the right of the action line.', 'A', 'Per WHO/MOH partograph use, good progress in the active phase is dilatation at >=1 cm/hour so plotting remains on or to the left of the alert line; crossing to the action line signals poor progress.', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The anti-opioid drug used in resuscitation of the newborn is:-', 'Konakion 0.5 mg intramuscularly.', 'Dexamethasone 1-2mg Intravenously.', 'Narcan 0.1 mg/kilogram body weight intravenously', 'Naloxone 0.5 mg intravenously.', 'C', 'Per neonatal resuscitation/Kenya EML, naloxone (Narcan) is the opioid antagonist used for opioid-induced neonatal respiratory depression at 0.1 mg/kg; the weight-based dosing option is correct whereas the fixed 0.5 mg IV figure is not the neonatal standard.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Injury to the fetal scalp due to pressure by girdle of contact is known as:-', 'Cephalhematoma.', 'Pericranial hematoma.', 'Subdural oedema.', 'Caput succedaneum.', 'D', 'Per Myles Textbook for Midwives, caput succedaneum is oedematous swelling of the fetal scalp caused by pressure of the cervical girdle of contact during labour; it crosses suture lines, unlike cephalhaematoma.', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The peak action syntocinon administered to prevent postpartum hemorrhage is felt in:-', '2 ½ minutes', '2 minutes', '2 seconds', '2 ½ seconds', 'A', 'Per pharmacology of oxytocics (Myles/EML), intravenous syntocinon (oxytocin) acts within about 1 minute with peak uterine effect around 2-3 minutes; 2 1/2 minutes is the best fit among the options.', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Fetal causes of early pregnancy loss include:-', 'Structural abnormalities of the genital tract', 'Bicornulate uterus and fibroids', 'Chromosomal abnormalities of the conceptus', 'Infections such as rubella, listeria and Chlamydia', 'C', 'Per Myles Textbook for Midwives, the commonest fetal cause of early pregnancy loss (miscarriage) is chromosomal abnormality of the conceptus; uterine anomalies and infections are maternal, not fetal, causes.', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The outcome of labor is not dependent on:-', 'Effectiveness of uterine contractions', 'Maternal size', 'The “give” of the pelvic joints', 'The degree of moulding of the fetal head', 'B', 'Per Myles Textbook for Midwives, labour outcome depends on the powers (contractions), passages (pelvic joint give) and passenger (moulding); overall maternal body size is not a determinant, so it is the exception.', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('During discharge, an important advice for the breastfeeding mother is to:-', 'Routinely avoid onions, cabbage and chocolate', 'Keep her calcium intake the same as during pregnancy', 'Increase her calories over her pregnancy requirements', 'Return to her pre-pregnancy intake for proteins but not calories', 'C', 'Per maternal nutrition guidelines (Myles/Kenya MOH), lactation demands more energy than pregnancy, so the breastfeeding mother should increase her caloric intake above her pregnancy requirements; routine food avoidance is unnecessary.', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The part of the uterus in which a contraction begins is:-', 'Cornua', 'Fundus', 'Isthmus', 'The body or corpus', 'A', 'Per Myles Textbook for Midwives, uterine contractions originate at pacemakers in the cornua (near the tubal ostia) and spread downward and inward (fundal dominance).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The follicle stimulating hormone and luteinizing hormone are secreted by the:-', 'Ovaries and testes', 'Posterior pituitary', 'Anterior pituitary gland', 'Hypothalamus', 'C', 'Per human physiology (Myles/anatomy texts), FSH and LH are gonadotrophins secreted by the anterior pituitary gland under hypothalamic GnRH control.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The ectoderm differentiates to form the:-', 'Cardiovascular system', 'Peripheral nervous system', 'Respiratory tract', 'Connective tissues', 'B', 'Per embryology (Myles), the ectoderm gives rise to the nervous system (central and peripheral), skin, and sensory epithelia; cardiovascular and connective tissues derive from mesoderm and respiratory tract from endoderm.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The anteroposterior diameter of the pelvic outlet measures:-', '12CM', '13CM', '11CM', '10CM', 'B', 'Per Myles Textbook for Midwives, the anteroposterior diameter of the pelvic outlet measures about 13 cm, the largest outlet diameter.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('During pregnancy, the glomerular filtration rate', 'Only changes when pathological conditions are present', 'Is directly influenced by the woman’s posture', 'Increases significantly above pre-pregnant levels', 'Makes the most dramatic changes near birth', 'C', 'Per maternal physiology (Myles), renal plasma flow and GFR rise markedly (by ~40-50%) above pre-pregnant levels early in pregnancy due to increased cardiac output.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Signs of cardiac decompensation in a pregnant woman with cardiac disease are likely to appear at', '28-32 weeks gestation', '36-40 weeks gestation', '12-16 weeks gestation', '20-24 weeks gestation', 'A', 'Per Myles Textbook for Midwives, cardiac decompensation in pregnant women with heart disease is most likely around 28-32 weeks when blood volume and cardiac output peak.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The mechanism of labor that allows the fetal head to present itself to fit the widest anteroposterior diameter of the pelvic cavity is:-', 'Flexion', 'Internal rotation', 'Descent', 'Extension', 'B', 'Per Myles Textbook for Midwives, internal rotation brings the occiput anteriorly so the fetal head aligns its longest (anteroposterior) diameter with the widest (anteroposterior) diameter of the pelvic outlet.', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Closure of the newborns foramen ovale occurs when:-', 'Blood flows from the pulmonary artery to the aorta', 'PO2 is increased causing constriction to occur', 'The umbilical cord is severed', 'Left atrial pressure exceeds right atrial pressure', 'D', 'Per neonatal circulation physiology (Myles), after birth lung expansion lowers pulmonary resistance and increases pulmonary venous return, so left atrial pressure exceeds right atrial pressure and functionally closes the foramen ovale.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The newborn with post maturity syndrome is at high risk for cold stress due to:-', 'Absence of vernix', 'Decreased subcutaneous fat', 'Parchment like skin', 'Extended posture', 'B', 'Per neonatal care (Basic Paediatric Protocols/Myles), the postmature infant has used up subcutaneous fat and glycogen stores in utero, so reduced subcutaneous fat and brown fat predispose to cold stress and hypoglycaemia.', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Presence of Meconium in the newborn’s lungs:-', 'Leads to respiratory alkalosis', 'Prevents air leaks', 'Traps inspired air in the alveoli', 'Prevents air from entering the airway', 'C', 'Per paediatric respiratory physiology (Basic Paediatric Protocols), meconium in the lungs causes a ball-valve obstruction that traps air distally, leading to hyperinflation and air-leak/pneumothorax with respiratory acidosis.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Symptoms of superficial thrombophlebitis include:-', 'Local redness and tenderness in a portion of the vein', 'Edema of the ankle and lower leg', 'Pain in the affected leg and foot', 'Positive Homan’s sign', 'A', 'Per Brunner & Suddarth''s Medical-Surgical Nursing, superficial thrombophlebitis presents with localized redness, warmth and tenderness along the palpable, cord-like superficial vein; oedema and positive Homan''s sign indicate deep vein thrombosis.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Persistence of moro reflex beyond the age of 6months is usually suggestive of:', 'Immaturity', 'Brain damage', 'Mental retardation', 'Brachial plexus palsy', 'B', 'Per Basic Paediatric Protocols/child development, the Moro reflex normally disappears by 3-6 months; persistence beyond 6 months suggests neurological (brain) damage or cerebral dysfunction.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Lochia serosa is composed of:', 'Decidua, vernix, leucocytes', 'Leucocytes, cervical mucus, decidua', 'Cervical mucus, cholestrin crystals, lanugo', 'Leucocytes, cervical mucus, erythrocytes', 'D', 'Per Myles Textbook for Midwives, lochia serosa (approx days 4–10) is pinkish-brown and contains leucocytes, cervical mucus, serous exudate, shreds of decidua and erythrocytes. The option listing leucocytes, cervical mucus and erythrocytes best fits; options with vernix, lanugo or cholesterin crystals are incorrect for lochia.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('During second stage of labour, the diameter that distends the vaginal orifice in face presentation is:', 'Occipito frontal', 'Submento-vertical', 'Submento-bregmatic', 'Mentovertical', 'C', 'Per Myles Textbook for Midwives, in a well-flexed (mento-anterior) face presentation the presenting diameter that distends the vulva is the submento-bregmatic (9.5 cm), analogous to the suboccipito-bregmatic in vertex. The others (occipito-frontal, submento-vertical, mento-vertical) are not the engaging/distending diameter of a face presentation delivering.', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The common age of onset for gonococcal ophthalmia neonatorum is:', 'Between 21-28 days after birth', 'Between 0-7 days after birth', 'Between 7-14 days after birth', 'At 28 days of age', 'B', 'Per Basic Paediatric Protocols and WHO, gonococcal ophthalmia neonatorum characteristically presents early, within the first week (typically day 2–5, i.e., 0–7 days) after birth, whereas chlamydial conjunctivitis appears later (5–14 days). Thus 0–7 days is correct.', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following respiratory patterns indicate increased intracranial pressure in the brain stem?', 'Slow, irregular respirations', 'Rapid, shallow respirations’', 'Asymmetric chest excursion', 'Nasal flaring', 'A', 'Per Brunner & Suddarth, brainstem compression from raised ICP produces slow, irregular (e.g., Cheyne-Stokes, ataxic/Biot''s, or apneustic) respiratory patterns as part of Cushing''s response. Rapid shallow breathing, asymmetric excursion and nasal flaring are not the hallmark brainstem pattern of increased ICP.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse administers mannitol to the client with increased intracranial pressure. Which parameter needs close monitoring', 'Muscle relaxation', 'Intake and output', 'Widening of the pulse pressure', 'Pupil dilation', 'B', 'Per Brunner & Suddarth, mannitol is an osmotic diuretic used to reduce ICP; it causes profuse diuresis, so strict intake and output (with fluid/electrolyte and osmolality) monitoring is essential to avoid dehydration and renal compromise. Muscle relaxation, widening pulse pressure and pupil dilation are not the primary parameter tied to the drug''s diuretic action.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which activity should the nurse encourage the client to avoid when there is a risk for increased intracranial pressure (ICP)?', 'Deep breathing', 'Coughing', 'Turning', 'Passive range of motion (ROM) exercises', 'B', 'Per Brunner & Suddarth, activities that raise intrathoracic/intra-abdominal pressure (coughing, straining/Valsalva) increase ICP and should be avoided/minimized. Deep breathing, gentle turning and passive ROM are permissible; vigorous coughing is the one to avoid.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('For a client who is experiencing expressive aphasia, which nursing intervention is most helpful in promoting communication?', 'Speaking loudly', 'Using a picture board', 'Writing directions so client can read them', 'Speaking in short sentence ● (6) The nurse is assessing the motor and sensory function of an unconscious client. The nurse should use which technique to test the client’s peripheral response to pain? (A) Sternal rub (B) Nail bed pressure (C) Pressure on the orbital rim - (localizing pain) (D) Squeezing of the sternocleidomastoid muscle', 'B', 'Per Brunner & Suddarth''s Medical-Surgical Nursing, expressive (Broca''s) aphasia means the client understands but cannot produce speech; a picture/communication board lets them convey needs. Speaking loudly (A) is for hearing loss, not aphasia. (Option D text is garbled with a trailing unrelated stem, but B is the best communication aid.)
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is evaluating the neurological signs of a client in spinal shock following spinal cord injury. Which observation indicates that spinal shock persists?', 'Hyperreflexia', 'Positive reflexes', 'Flaccid paralysis', 'Reflex emptying of the bladder', 'C', 'Per Brunner & Suddarth, spinal shock is characterized by flaccid paralysis, loss of reflexes (areflexia) and loss of sensation/autonomic function below the lesion. Hyperreflexia, positive reflexes and reflex bladder emptying indicate RESOLUTION of spinal shock, so flaccid paralysis indicates it persists.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse has instructed the family of a client with stroke (brain attack) who has homonymous hemianopsia about measures to help the client overcome the deficit. Which statement suggests that the family understands the measures to use when caring for the client?', '“We need to discourage him from wearing eyeglasses.”', '“We need to place objects in his impaired field of vision.”', '“We need to approach him from the impaired field of vision.”', '“We need to remind him to turn his head to scan the lost visual field.”', 'D', 'Per Brunner & Suddarth, in homonymous hemianopsia the client loses the same half of the visual field in both eyes; teaching them to turn the head and scan toward the affected side compensates for the deficit. Initially objects/approach are placed on the intact side; discouraging eyeglasses is wrong. Head-turning/scanning shows correct understanding.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is teaching a client with myasthenia gravis about the prevention of myasthenic and cholinergic crisis. Which client activity suggests that teaching is most effective?', 'Taking medications as scheduled', 'Eating large, well-balanced meals', 'Doing muscle-strengthening exercises', 'Doing all chores early in the day while less fatigue', 'A', 'Per Brunner & Suddarth, in myasthenia gravis anticholinesterase drugs must be taken exactly on schedule to maintain therapeutic levels; late/missed doses precipitate myasthenic crisis and overdose precipitates cholinergic crisis. Large meals, strenuous exercise and doing all chores early do not reliably prevent crises; adherence to the medication schedule does.', 'KRCHN', 'Paper I', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client is admitted to the hospital with a diagnosis of Guillain-Barre syndrome. Which past medical history finding makes the client most at risk for this disease?', 'Meningitis or encephalitis during the last 5 years', 'Seizures or trauma to the brain within the last year', 'Back injury or trauma to the spinal cord during the last 2 years', 'Respiratory or gastrointestinal infection during the previous month', 'D', 'Per Brunner & Suddarth, Guillain-Barre syndrome is an autoimmune polyneuropathy typically preceded (1–4 weeks prior) by a viral respiratory or gastrointestinal infection (e.g., Campylobacter). Meningitis, seizures/head trauma and spinal/back injury are not the classic antecedent risk; a recent respiratory/GI infection is.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is evaluating the status of a client who had a craniotomy 3 days ago. Which assessment finding would indicate that the client is developing meningitis as a complication of surgery?', 'A negative Kernig’s sign', 'Absence of nuchal rigidity', 'A positive Brudzinski’s sign', 'A Glasgow Coma Scale score of 15', 'C', 'Per Brunner & Suddarth, meningitis produces meningeal irritation signs: nuchal rigidity and positive Kernig''s and Brudzinski''s signs. A positive Brudzinski''s sign indicates developing meningitis; a negative Kernig''s, absent nuchal rigidity and a normal GCS of 15 would suggest NO meningitis.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is positioning the female client with increased intracranial pressure. Which of the following positions would the nurse avoid?', 'Head midline', 'Head turned to the side', 'Neck in neutral position', 'Head of bed elevated 30 to 45 degrees', 'B', 'Per Brunner & Suddarth, with increased ICP the head should be kept midline and neutral with the bed elevated 30–45 degrees to promote venous drainage; turning/rotating the head to the side obstructs jugular venous outflow and raises ICP, so it is the position to AVOID.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is caring for the male client who begins to experience seizure activity while in bed. Which of the following actions by the nurse would be contraindicated?', 'Loosening restrictive clothing', 'Restraining the client’s limbs', 'Removing the pillow and raising padded side rails', 'Positioning the client to side, if possible , with the head flexed forward', 'B', 'Per Kozier & Erb''s Fundamentals and Brunner & Suddarth, during a seizure the nurse must NOT restrain the limbs (risks fractures/injury). Correct actions are loosening clothing, removing the pillow and padding side rails, and side-lying with head flexed forward; restraining limbs is contraindicated.', 'KRCHN', 'Paper I', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is teaching the female client with myasthenia gravis about the prevention of myasthenic and cholinergic crises. The nurse tells the client that this is most effectively done by:', 'Eating large, well-balanced meals', 'Doing muscle -strengthening exercises', 'Doing all chores early in the day while less fatigued', 'Taking medications on time to maintain therapeutic blood levels', 'D', 'Per Brunner & Suddarth, prevention of both myasthenic and cholinergic crises depends on taking anticholinesterase medication precisely on time to keep therapeutic blood levels. Large meals, muscle-strengthening exercise and doing all chores early are not effective preventive measures.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following neurotransmitters is known to be associated with sleep, mood and appetite?', 'Acetylcholine', 'Dopamine', 'Serotonin', 'GABA', 'C', 'Per standard physiology (Brunner & Suddarth / Lewis) and psychiatric nursing texts, serotonin (5-HT) regulates sleep, mood and appetite. Acetylcholine (muscle/memory), dopamine (movement/reward) and GABA (inhibition) do not fit this triad; serotonin does.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The neurons of the motor pathway control:', 'Stress reaction', 'Organs and glands', 'Involuntary muscles', 'Voluntary muscles', 'D', 'Per anatomy & physiology texts, the motor (somatic) pathway carries efferent impulses controlling voluntary (skeletal) muscles. Involuntary muscles, organs and glands are controlled by the autonomic nervous system; hence voluntary muscles is correct.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The area of the brain which is involved in the understanding of meaning is:', 'Broca’s area', 'association areas', 'Wernicke area', 'Motor speech area', 'C', 'Per neuroanatomy (Brunner & Suddarth), Wernicke''s area (posterior superior temporal lobe) is responsible for comprehension/understanding of language meaning. Broca''s/motor speech area handles speech production; general association areas integrate information, but understanding of meaning is specifically Wernicke''s area.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Parkinson’s disease , is caused by the degeneration of neurons in an area of the brain called the:', 'Substantia nigra', 'Basal ganglia', 'Cerebellum', 'Corpus callosum', 'A', 'Per Brunner & Suddarth, Parkinson''s disease results from degeneration of dopaminergic neurons in the substantia nigra, reducing dopamine. Although the basal ganglia circuit is affected, the primary site of neuronal degeneration is the substantia nigra.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The division of the nervous system which controls the involuntary muscles, organs, and glands is:', 'Somatic nervous system', 'Autonomic nervous system', 'Central nervous system', 'The motor pathway of the CNS', 'B', 'Per anatomy & physiology texts, the autonomic nervous system controls involuntary muscles, organs and glands (via sympathetic and parasympathetic divisions). The somatic system controls voluntary muscle; the CNS is the integrating centre. Hence autonomic nervous system is correct.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is teaching a class on the prevention of cerebrovascular accidents. Which of the following risk factors should the nurse identify as the most important factor contributing to a stroke?', 'Sedentary lifestyle', 'Smoking', 'Obesity', 'Hypertension', 'D', 'Per Kenya MOH NCD guidelines and Brunner & Suddarth, hypertension is the single most important MODIFIABLE risk factor for stroke (cerebrovascular accident). Smoking, obesity and sedentary lifestyle also contribute, but hypertension is the leading contributing factor.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is assessing a 37-year-old client diagnosed with multiple sclerosis. Which of the following symptoms would the nurse expect to find?', 'Flaccid muscles', 'Tremors at rest', 'Absent deep tendon reflexes', 'Vision changes', 'D', 'Per Brunner & Suddarth, multiple sclerosis classically presents with visual disturbances (optic neuritis, diplopia, blurred vision), along with spasticity, hyperreflexia and intention (not resting) tremor. Flaccid muscles, resting tremor and absent deep tendon reflexes are not typical of MS; vision changes are the expected finding.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('If a male client experienced a cerebrovascular accident (CVA) that damaged the hypothalamus, the nurse would anticipate that the client has problems with:', 'Thinking and reasoning', 'Body temperature control', 'Balance and equilibrium', 'Visual acuity', 'B', 'The hypothalamus is the principal thermoregulatory centre (also controlling hunger, thirst, and neuroendocrine function). Damage impairs body temperature control. Thinking/reasoning is cortical (frontal), balance is cerebellar, and visual acuity is occipital/optic pathway (Brunner & Suddarth''s Medical-Surgical Nursing).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('During recovery from a cerebrovascular accident (CVA), a female client is given nothing by mouth, to help prevent aspiration. To determine when the client is ready for a liquid diet, the nurse assesses the client’s swallowing ability once each shift. This assessment evaluates', 'Cranial nerves III and V', 'Cranial nerves IX and X', 'Cranial nerves I and II', 'Cranial nerves VI and VIII', 'B', 'Swallowing (gag reflex) is mediated by the glossopharyngeal (IX) and vagus (X) nerves. Assessing swallowing ability tests these cranial nerves before advancing diet post-CVA (Brunner & Suddarth''s Medical-Surgical Nursing).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Demyelination is defined as;', 'Loss of an axon in a neuron', 'Loss of dendrites in a neuron', 'Loss of protective sheath surrounding neurons', 'Loss of connective tissue between neurons', 'C', 'Demyelination is the loss/destruction of the myelin sheath surrounding nerve fibres (as in multiple sclerosis), slowing nerve conduction (Brunner & Suddarth''s Medical-Surgical Nursing).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Failure of muscle coordination , including unsteady movements and staggering walk, due to disorders in the cerebellum is called?', 'Anoxia', 'Dyslexia', 'Paraplegia', 'Ataxia', 'D', 'Ataxia is impaired muscle coordination causing unsteady, staggering gait, characteristically due to cerebellar dysfunction. Anoxia is oxygen lack, dyslexia is a reading disorder, and paraplegia is lower-limb paralysis (Brunner & Suddarth''s Medical-Surgical Nursing).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which part of the brain regulates heartbeat, breathing and other vital functions?', 'Grey matter', 'Brain stem', 'Occipital lobe', 'White matter', 'B', 'The brain stem (specifically the medulla oblongata) contains the cardiac, respiratory, and vasomotor centres regulating heartbeat, breathing and other vital functions (Brunner & Suddarth''s Medical-Surgical Nursing).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Common complications of spinal cord injury include each of the following EXCEPT?', 'Pressure sores', 'Deep vein thrombosis', 'Diarrhoea', 'Urinary Tract infections', 'C', 'Spinal cord injury commonly causes pressure sores, DVT (from immobility), and UTIs (from neurogenic bladder/catheterisation). Constipation, not diarrhoea, results from neurogenic bowel; thus diarrhoea is the exception (Brunner & Suddarth''s Medical-Surgical Nursing).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Broca’s area is located in the', 'Brain stem', 'Frontal lobe', 'Parietal lobe', 'Temporal lobe', 'B', 'Broca''s area (motor speech centre) lies in the inferior frontal lobe of the dominant hemisphere; damage causes expressive (non-fluent) aphasia (Brunner & Suddarth''s Medical-Surgical Nursing).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Wernicke area is located in the', 'Brain stem', 'Parietal lobe', 'Temporal lobe', 'Frontal lobe', 'C', 'Wernicke''s area (receptive/sensory speech centre) is located in the posterior superior temporal lobe of the dominant hemisphere; damage causes receptive (fluent) aphasia (Brunner & Suddarth''s Medical-Surgical Nursing).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The presence of ptosis suggests damage to cranial nerve:', 'IV', 'V', 'III', 'VII', 'C', 'The oculomotor nerve (III) supplies the levator palpebrae superioris, which elevates the upper eyelid; its damage causes ptosis (drooping eyelid) along with a ''down and out'' eye (Brunner & Suddarth''s Medical-Surgical Nursing).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following function is controlled by parasympathetic system?', 'Pupil constriction', 'Acceleration of heart beat', 'Stimulation of sweat glands', 'Contraction of hair muscles', 'A', 'Parasympathetic (rest-and-digest) stimulation causes pupil constriction (miosis), slows the heart, and reduces secretions. Acceleration of heart rate, sweating, and pilo-erection are sympathetic responses (Kozier & Erb''s Fundamentals; Brunner & Suddarth''s).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which one of the following is NOT a probable sign of the second stage of labour?', 'uterine contractions', 'No cervix felt on vaginal examination', 'Rupture of membranes', 'Bulging of the perineum', 'C', 'Signs of second stage include strong uterine contractions, full dilatation (no cervix felt), and bulging perineum. Rupture of membranes can occur at any stage and is not a specific sign of second stage, so it is the exception (Myles Textbook for Midwives).', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Ms. D is admitted to the labour ward in early active labour. The priority intervention on admission of this woman would be:', 'Auscultating the fetal heart', 'Taking an obstetric history', 'Asking the client when she last ate', 'Ascertaining whether the membranes were ruptured', 'A', 'On admission in labour, assessing fetal wellbeing by auscultating the fetal heart is the priority to detect fetal compromise; history-taking and other assessments follow (Myles Textbook for Midwives; Kenya Maternal/Newborn care guidelines).', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which one of the following foetal positions is most favourable for birth?', 'Vertex presentation', 'Transverse lie', 'Frank breech presentation', 'Posterior position of the fetal head', 'A', 'Vertex (cephalic, well-flexed) presentation is the most favourable for vaginal birth. Transverse lie, frank breech, and persistent occipito-posterior positions are associated with difficult or obstructed labour (Myles Textbook for Midwives).', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In which one of the following stages is the placenta delivered?', 'Stage 1, latent phase', 'Stage 1, active phase', 'Stage2', 'Stage 3', 'D', 'The placenta is delivered during the third stage of labour, from birth of the baby to expulsion of the placenta and membranes (Myles Textbook for Midwives).', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Endogenous oxytocin is released from the:', 'anterior pituitary gland', 'cervix', 'posterior pituitary gland', 'uterus', 'C', 'Oxytocin is synthesised in the hypothalamus and released (stored) from the posterior pituitary gland; it stimulates uterine contraction and milk ejection (Myles Textbook for Midwives; physiology texts).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The midwife is caring for a woman in labour. She determines that the woman is beginning the 2nd stage of labour when which of the following signs is noted?', 'The woman begins to expel clear vaginal fluid', 'The contractions are regular', 'The membranes have ruptured', 'The cervix is dilated completely', 'D', 'The second stage of labour begins when the cervix is fully (completely) dilated at 10 cm and ends with birth of the baby. Regular contractions and ruptured membranes are not defining signs (Myles Textbook for Midwives).', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is true about congenital abnormalities?', 'It refers to defects in the body structure at birth', 'It is always occult at birth making it difficult to detect', 'Congenital abnormalities are all inherited from the family', 'It results from unknown fetal developments that are always difficult to predict', 'A', 'Congenital abnormalities are structural or functional defects present at birth. They are not always occult (many are visible), not all are inherited (many are environmental/multifactorial), and causes are often known (Myles Textbook for Midwives; Basic Paediatric Protocols).', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When resuscitating a neonate who has neonatal asphyxia after how long should the midwife use ambubag', 'After 30 seconds of oxygen by face mask', 'When the baby remains apnoeic after 30 minutes of facemask oxygen therapy.', 'When the neonate is no longer cyanosed', 'When the neonate P02 level has increased', 'A', 'In neonatal resuscitation, if the baby is not breathing adequately after the initial steps, positive-pressure ventilation with a bag-and-mask (ambubag) is started within about 30 seconds (''the golden minute''). The 30-minute option is clearly wrong (Kenya Basic Paediatric Protocols; WHO/HBB neonatal resuscitation).', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When should a midwife put an asphyxiated neonate on intubation and ventilation?', 'When the heart beat is more than 100 beats per minute', 'When the heart beat is less than 100 beats per minute', 'When the heart rate has improved', 'When resuscitation measures are performed without medical assistance', 'B', 'Persistent bradycardia (heart rate below 100 bpm) despite effective bag-mask ventilation indicates the need for advanced airway management (intubation and ventilation). An improving heart rate over 100 bpm signals adequate resuscitation (Kenya Basic Paediatric Protocols; neonatal resuscitation guidelines).', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is the most appropriate feature seen in symmetric growth retarded infant?', 'Weight is depressed more than length or head circumference.', 'Fetal growth retardation probably has occurred in the last trimester of pregnancy.', 'Weight, length and head circumference are below normal and babies look like miniature normal babies.', 'It is mostly linked with cigarette smoking.', 'C', 'Symmetric (early-onset) IUGR affects weight, length and head circumference proportionately, producing a proportionately small (''miniature normal'') infant. Asymmetric IUGR (late trimester, spares head, linked to smoking) is described by the other options (Myles Textbook for Midwives; Basic Paediatric Protocols).', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which statement is true about meconium?', 'Meconium is 1st found in the foetal ileum between the 20th and 26th weeks of gestation', 'Meconium passage is uncommon before 36 weeks but its common in pregnancies beyond 42 weeks', 'In utero passage of meconium is common because the anal sphincter tone is poor', 'All of the above', 'D', 'Meconium first forms in the fetal ileum around 20-26 weeks, its passage in utero is uncommon before 36 weeks but rises in post-term (over 42 weeks) pregnancies, and passage relates to gut maturation/hypoxia. All statements are correct, so ''All of the above'' applies (Myles Textbook for Midwives).', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What would be the result of fail splitting a single fertilized ovum between 8 to 12 days after fertilization?', 'Conjoined twin', 'Monochorionic monoamniotic twin', 'Dichorionic diamniotic twin', 'Monochorionic diamniotic twin', 'A', 'Splitting of a single fertilized ovum after day 8-12 (late, after the amniotic sac has formed) is incomplete and results in conjoined twins. Earlier splits give diamniotic or monoamniotic monochorionic twins (Myles Textbook for Midwives).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following best describes large for gestational age?', 'Large for gestational age is weight, length, or circumference that lies above the 90th percentile for that gestational age.', 'Large for gestational age is defined as birth weight more than 2 standard deviations above the mean.', 'Large for gestational age is an indication of high prenatal growth.', 'Large for gestational age is weight of 3500g at birth despite gestational age.', 'A', 'Per standard neonatal criteria (Myles Textbook for Midwives; Basic Paediatric Protocols Kenya), LGA is defined as any growth parameter above the 90th percentile for gestational age. Option D fixes an arbitrary weight ignoring gestational age and is wrong.', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which ONE of the following is a clinical feature clinical chorio-amnionitis?', 'Foul smelling vaginal discharge', 'Non tender uterus on palpation', 'Maternal temperature of 37.4 degrees Celsius', 'Maternal pulse of 110 beats per minute', 'D', 'Per Myles Textbook for Midwives and MOH maternal guidelines, chorioamnionitis features include maternal tachycardia (>100 bpm), fever (>38°C), foul-smelling discharge and a TENDER uterus. A pulse of 110 bpm fits; a temperature of 37.4°C is not febrile and a non-tender uterus is the opposite of the finding, so D is the valid clinical feature.', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the greatest risk of retained products of conception in the immediate post partum period?', 'Uterine atony', 'Uterine inversion', 'Uterine rupture', 'Uterine tenderness', 'A', 'Per MOH/Myles: retained products of conception prevent the uterus from contracting fully, causing uterine atony and postpartum haemorrhage, the greatest immediate risk. Inversion and rupture are not the primary consequence of retained products.', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is NOT an outcome for an occipito posterior position?', 'Brow delivery', 'Deep transverse arrest', 'Persistent occipito posterior position', 'Occipito anterior delivery', 'A', 'Per Myles Textbook for Midwives, outcomes of occipitoposterior position include long internal rotation to occipitoanterior (spontaneous delivery), persistent OP, and deep transverse arrest. Brow presentation is a separate deflexed malpresentation, not an outcome of OP, so it is the NOT answer.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When assessing the progress of labour, the midwife should assess for the 4 Ps. Which ONE of the following represents the 4 Ps?', 'Power, parity, passenger and passage', 'Passenger, power, patient and passage', 'Parity, progress, power and passenger', 'Passenger, power, progress and passage', 'D', 'Per Myles Textbook for Midwives, the factors influencing labour progress are the Powers, the Passage, the Passenger and Progress (some texts add Psyche). Option D lists passenger, power, progress and passage, the valid 4 Ps.', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is 3rd degree moulding?', 'Change of the shape of the foetal skull that occurs during labour', 'Sutures of the foetal skull are overridden, but are easily separable', 'Sutures of the foetal skull are in close contact', 'Sutures of the foetal skull are overridden and inseparable', 'D', 'Per Myles Textbook for Midwives, moulding grades: 1st = sutures meet/in close contact, 2nd = sutures overlap but reducible (easily separated), 3rd = sutures overlap and are NOT reducible (inseparable), indicating cephalopelvic disproportion. Option D is correct.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In a brow presentation, what is the engaging diameter of the foetus into the maternal pelvis?', 'Sub-mento vertical diameter', 'Occipito-frontal diameter', 'Mento-vertical diameter', 'Sub-mento bregmatic diameter', 'C', 'Per Myles Textbook for Midwives, brow presentation presents the mentovertical diameter (~13.5 cm), the largest antero-posterior diameter of the fetal skull, which usually cannot engage and leads to obstructed labour.', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which statement BEST describes a complete breech presentation?', 'Both hips are flexed and both knees are extended', 'Both hips and both knees are flexed', 'One or both hips are extended with the knees extended', 'One or both hips are extended with the knees or knee flexed', 'B', 'Per Myles Textbook for Midwives: complete (flexed) breech has both hips and both knees flexed. Frank breech = hips flexed, knees extended (option A); footling = hip(s) extended.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following are the engaging diameters in a face presentation?', 'Sub-occipitofrontal and biparietal', 'Occipito-frontal and biparietal', 'Mentovertical and biparietal', 'Sub-mentobregmatic and biparietal', 'D', 'Per Myles Textbook for Midwives, in a fully extended face presentation the engaging diameters are the submentobregmatic (~9.5 cm) antero-posteriorly and the biparietal transversely.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Thembi is primigravida at 39 weeks gestational age. She requested induction of labour because she is a student in one of the universities, in preparation for her examination. On examination:Presentation- cephalic, Fundal height- 40cm, foetal heart rate 148 beats per minute. Before induction, the obstetrician examines her and the findings are as follows: cervix-mid position; firm; station-3; length-2cm; and cervical dilatation: 1-2 cm. What is Thembi''s Bishop Score?', '2', '3', '4', '5', 'B', 'Per Myles Textbook for Midwives Bishop scoring: dilatation 1-2 cm = 1, length/effacement 2 cm (0-1 cm effaced) = 1, station -3 = 0, consistency firm = 0, position mid = 1, giving a total of 3.', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is NOT a contra-indication for a trial of scar?', 'Multiple pregnancy', 'History of sepsis following the previous caesarean section', 'Previous caesarean section for cord prolapse', 'Breech presentation', 'C', 'Per MOH/Myles VBAC criteria, a previous CS done for a non-recurrent indication such as cord prolapse is a GOOD candidate for trial of scar, so it is NOT a contraindication. Multiple pregnancy, previous sepsis, and breech are relative contraindications to trial of scar.', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which ONE of the following drugs should be used first to a non hypertensive woman presenting with post partum haemorrhage occurring due to uterine atony?', 'Syntometrine', 'Oxytocin', 'Misoprostol', 'Ergometrine', 'B', 'Per Kenya MOH/EmONC PPH guidelines, oxytocin is the first-line uterotonic for atonic PPH in any woman including hypertensives. Ergometrine and syntometrine are contraindicated in hypertension; oxytocin is the safe first choice.', 'KRCHN', 'Paper I', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Subtle neonatal seizure is recognized by:-', 'Sustained eye opening or fixation, drooling, sustained posturing of a limb.', 'Migrating jerks of limbs, localized clonic jerking, tonic horizontal deviation of eyes.', 'Migrating jerks of limbs, tonic horizontal deviation of eyes, lip smacking.', 'Tonic horizontal deviation of eyes, apnoeic spells, lips smacking.', 'A', 'Per Basic Paediatric Protocols (Kenya) and neonatal texts, subtle seizures manifest as eye deviation/fixation, blinking, drooling, chewing/lip-smacking, apnoea, and sustained posturing. Migrating and clonic jerking describe clonic/multifocal seizures, not subtle ones, so A best fits the subtle category.', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Causes of primary amenorrhea include:-', 'Gonadal dysgenesis, premature ovarian failure, asherman’s syndrome.', 'Sheehan’s syndrome, gonadal dysgenesis, imperforate hymen.', 'Androgen insensitivity, gonadal dysgenesis, imperforate hymen.', 'Polycystic ovarian syndrome, sheehan’s syndrome, gonadal dysgenesis.', 'C', 'Per gynaecology texts (Myles/standard), primary amenorrhoea causes include androgen insensitivity, gonadal dysgenesis (Turner) and outflow obstruction like imperforate hymen. Asherman''s and Sheehan''s cause SECONDARY amenorrhoea, excluding options A, B and D.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following are anterior pituitary gland hormones except', 'Prolactin', 'Antidiuretic hormone', 'Follicle stimulating hormone', 'Luteinizing hormone', 'B', 'Per Kozier/anatomy & physiology, the anterior pituitary secretes prolactin, FSH, LH, GH, TSH and ACTH. ADH (vasopressin) is released by the POSTERIOR pituitary, so it is the exception.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Wernicke area is in the;', 'Occipital lobe', 'Frontal lobe', 'Parietal lobe', 'Temporal lobe', 'D', 'Per neuroanatomy (Brunner & Suddarth), Wernicke''s area (receptive/comprehension speech) lies in the posterior superior temporal lobe of the dominant hemisphere.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Cardiac output is equal to;', 'Heart rate × patients body weight', 'Venous return× Peripheral resistance', 'Peripheral resistance × stroke volume', 'Stroke volume ×heart rate', 'D', 'Per cardiovascular physiology (Brunner & Suddarth), cardiac output = stroke volume × heart rate.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Management of scaled lesion in psoriasis include;', 'Shaving the scales using a clean razor', 'Applying moisturizers to soften the scales', 'Covering the lesions with occlusive dressings to remove scales', 'Keeping the lesions dry to enhance dropping off the scales', 'B', 'Per Brunner & Suddarth dermatology, psoriatic scales are managed by emollients/moisturizers and keratolytics to soften and gently remove scales; shaving with a razor or forcibly removing scales traumatises skin and worsens lesions.', 'KRCHN', 'Paper I', 'Nursing Management & Leadership', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following is true regarding Hashimoto thyroiditis', 'Is an autoimmune disease, causes primary hypothyroidism', 'Is an autoimmune disease, causes primary hyperthyroidism', 'Results in goiter, causes exophthalmos', 'More common in women, there is an increase in TH levels.', 'A', 'Per Brunner & Suddarth, Hashimoto thyroiditis is an autoimmune destruction of the thyroid causing primary HYPOthyroidism. Exophthalmos and hyperthyroidism belong to Graves'' disease, excluding B and C.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Characteristics of 2nd degree burns include;', 'Waxy white dry, leathery, charred, oedema', 'Fluid-filled blisters, weeping of fluid, bright pink', 'Red to gray, may have local edema', 'severe pain, weeping of fluid, may have local edema, leathery charred', 'B', 'Per Brunner & Suddarth burn classification, second-degree (partial-thickness) burns present with fluid-filled blisters, moist weeping surface, bright pink/red colour and severe pain. Waxy white, dry, leathery and charred describe full-thickness (3rd degree) burns.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When estimating the size of burns, the palm of the patient’s hand represents body surface area of;', '3%', '1%', '4.5%', '9%', 'B', 'Per Brunner & Suddarth and burn assessment guidelines, the patient''s palm (palmar surface including fingers) represents approximately 1% of total body surface area, used to estimate scattered burns.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Malena can be caused by;', 'Small bowel obstruction, abdominal aortic aneurysm, internal hemorrhoids', 'Perforated gastric ulcers, neoplasms in the transverse colon', 'Bleeding esophageal varices, perforated gastric ulcer', 'Abdominal aortic aneurysm, splenic neoplasm, esophageal varices', 'C', 'Per Brunner & Suddarth, melaena (black tarry stool) results from UPPER GI bleeding such as bleeding oesophageal varices and perforated/bleeding gastric ulcers, where blood is digested. Lower colonic and haemorrhoidal bleeding produce fresh red blood, excluding the other options.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which sign and symptoms should a nurse expect to find in a client diagnosed with ulcerative colitis?', 'Twenty bloody stools a day', 'Chronic constipation', 'Oral temperature of 39o c', 'Hard rigid abdomen', 'A', 'Per Brunner & Suddarth, ulcerative colitis characteristically causes frequent bloody, mucoid diarrhoea (up to 10-20 stools/day). A rigid abdomen suggests peritonitis/perforation and constipation is not typical, making A the expected finding.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Early miscarriage refers to;', 'loss of pregnancy spontaneously in between 16-24 weeks', 'spontaneous loss of pregnancy from between 16-30 weeks gestation', 'spontaneous loss of pregnancy from between 0 to 16 weeks gestation', 'loss of pregnancy between 24 to 30weeks', 'C', 'Per Myles Textbook for Midwives, early miscarriage is spontaneous pregnancy loss occurring before 16 weeks (some define before 12/13 weeks); late miscarriage is 16-24 weeks. Option C best reflects early loss up to 16 weeks.', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The patient was brought to the outpatient department with a cut wound, which is the most appropriate intervention for a triage nurse;', 'Wash the site with soap and water', 'Squeeze the site to enhance bleeding', 'Apply a tourniquet proximal to the site', 'Apply a tourniquet distal to the site', 'A', 'Per MOH first-aid/wound care guidelines, initial management of a clean cut wound is to clean the site with soap and water and apply direct pressure. Squeezing to enhance bleeding or applying a tourniquet is inappropriate for a simple cut wound.', 'KRCHN', 'Paper I', 'Nursing Management & Leadership', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('While caring for a patient with a diagnosis of emphysema, the healthcare provider instructs the patient on positioning that will assist the patient’s ability to breathe when experiencing dyspnea. Which of the following positions will the healthcare provider instruct the patient about?', 'Lie supine with your feet on a blanket roll.', 'Sit upright and lean forward on a supportive surface', 'Sit in a recliner chair at a 120-degree angle', 'Assume a side-lying position', 'B', 'Per Brunner & Suddarth, patients with emphysema/COPD relieve dyspnoea using the orthopneic (tripod) position, sitting upright and leaning forward on a supportive surface, which improves accessory muscle use and lung expansion.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('During chest auscultation of a patient, which findings will indicate that the patient has cardiac condition and cannot be felt in a normal person', 'S1, S3 , Murmurs', 'S1, S2, Negative Murmurs,', 'S3, S4, Murmurs', 'S3, S1,S2', 'C', 'Per Brunner & Suddarth''s Med-Surg Nursing, S1 and S2 are normal heart sounds heard in healthy people; extra sounds S3 (in adults) and S4, together with murmurs, indicate cardiac pathology and are not normally audible in a healthy adult. Options containing S1/S2 are normal findings.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Nurse Lei caring for a client with a pneumothorax and who has had a chest tube inserted notes continues gentle bubbling in the suction control chamber. What action is appropriate?', 'Do nothing, because this is an expected findng', 'Immediately clamp the chest tube and notify the physician', 'Check for an air leak because the bubbling should be intermittent', 'Increase the suction pressure so that the bubbling becomes vigorous', 'A', 'Per Brunner & Suddarth, gentle continuous bubbling in the SUCTION-CONTROL chamber is expected and confirms suction is working. Continuous bubbling in the water-seal chamber would signal an air leak; clamping is contraindicated as it risks tension pneumothorax.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('You assess a client with newly diagnosed hypothyroidism as having an enlarged thyroid gland (goiter). What pathologic process causes this enlargement?', 'An excess of TH stimulates thyroid follicles', 'An increased dietary iodine intake', 'A compensatory effort to produce more TH', 'Tissue hypertrophy in response to increased TH', 'C', 'Per Brunner & Suddarth, in hypothyroidism low thyroid hormone raises TSH, which stimulates thyroid follicular hyperplasia in a compensatory attempt to produce more hormone, causing goiter. Excess TH (options A and D) is the mechanism in hyperthyroidism, not hypothyroidism.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following clients would be most at risk for the development of', 'Middle-age man who maintains normal weight', 'Young adult who is a professional basketball player', 'Middle-aged woman who is the sole caretaker of her parents', 'Woman over the age 70 who is overweight and sedentary', 'D', 'The stem is truncated but the classic at-risk profile for osteoarthritis/osteoporosis/degenerative disease is an elderly, overweight, sedentary woman (Brunner & Suddarth). The other options describe healthy or protected individuals.
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Ms. Smith complains of nausea and vomiting following her daily chemotherapy treatment. The most appropriate nursing intervention would be to;', 'Keep NPO until her daily chemotherapy is completed', 'Provide antiemetic medication 30 to 40 minutes prior to each treatment', 'Provide clear liquids until the chemotherapy is completed', 'Schedule chemotherapy administration to bed time', 'B', 'Per Brunner & Suddarth oncology nursing, chemotherapy-induced nausea/vomiting is best prevented by giving prophylactic antiemetics before treatment rather than treating symptoms after they occur; NPO or clear liquids alone do not prevent the emesis.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following clients is a greater risk for burn shock?', 'One with 90% superficial burns from a tanning bed', 'One with 10% TBSA from gasoline explosion', 'One with radiation burns following treatment for cancer', 'One with >50% TBSA from a high-voltage electric accident', 'D', 'Per Brunner & Suddarth burn nursing, extensive full-thickness/high-voltage electrical burns over >50% TBSA cause massive fluid shifts and are at greatest risk for burn (hypovolemic) shock. Superficial and small-percentage burns carry far lower shock risk.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('While providing care to an old woman with a cast on her lower arm (from below the elbow the elbow to above the fingers) you perform a neurovascular assessment. What is the possible complication?', 'Slightly edematous fingers', 'Warm, pink skin above the cast', 'Pale, cold fingers', 'Pain rating of 2 on a 1 to 10 scale', 'C', 'Per Brunner & Suddarth neurovascular (5 P''s) assessment, pale and cold fingers indicate impaired circulation/compartment compromise distal to the cast — a serious complication. Slight edema, warm pink skin and mild pain of 2/10 are expected, non-alarming findings.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Following gastrectomy, dumping syndrome occurs as a results of:-', 'Reduced gastric motility resulting from Vagus nerve stimulation', 'Removal of acid producing cells thus resulting in reduced absorption of Vit B12', 'Rapid gastric emptying of hyperosmolar fluid and substances into the duodenum', 'Damage of Vagus nerve and cardiac sphincter', 'C', 'Per Brunner & Suddarth, dumping syndrome after gastrectomy results from rapid emptying of hyperosmolar gastric contents into the jejunum/duodenum, drawing fluid into the bowel and causing vasomotor and GI symptoms. B12 malabsorption and vagal damage are separate post-gastrectomy issues.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The intracranial; hemorrhage with the worst prognosis is :-', 'Cephalohematoma', 'Epidural hemorrhage', 'Intracerebral hemorrhage', 'Subarachnoid hemorrhage', 'C', 'Per Brunner & Suddarth neuro nursing, intracerebral (intraparenchymal) hemorrhage carries the worst prognosis and highest mortality among these because it directly destroys brain tissue and causes mass effect. Cephalohematoma is benign and extradural in the newborn.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The health message given to a patient following tympanoplasty is:-', 'Drink fluids using a straw', 'Avoid blowing the nose and sneeze through the mouth', 'Administered saline water into the ear to aid healing', 'Avoid noisy places upto two weeks post operatively', 'B', 'Per Brunner & Suddarth ENT nursing, after tympanoplasty the patient must avoid nose-blowing and should sneeze with mouth open to prevent pressure transmission through the eustachian tube that could disrupt the graft. Straws/nose-blowing raise pressure; saline in the ear is contraindicated.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following indicates a normal finding on percussion of the lungs', 'Tympani over the right upper lobe', 'Resonance over the left upper lobe', 'C . Hyper resonance over the left lower lobe', 'Dullness above the left 10th intercostal space', 'B', 'Per Brunner & Suddarth respiratory assessment, resonance is the normal percussion note over healthy lung tissue. Tympany and hyperresonance are abnormal (air trapping), and dullness over lung fields is abnormal.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What are the causes of ischaemic stroke', 'Saccualar aneurysm, artery thrombosis, large artery thrombosis', 'Cardiogenic embolism, small artery thrombosis, cryptogenic', 'small artery thrombosis, cryptogenic, intracerebral hemmorage', 'Arterio-venous malformation, Cardiogenic embolism, small artery thrombosis', 'B', 'Per Brunner & Suddarth stroke classification, ischaemic stroke causes include large-artery atherosclerosis, cardiogenic/cardioembolic, small-vessel (lacunar) thrombosis and cryptogenic. Option B lists only ischaemic mechanisms, whereas the other options include haemorrhagic causes (aneurysm, intracerebral haemorrhage, AV malformation).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which one of the following is correct regarding the control of glucose levels?', 'Both insulin and glucagon are necessary to maintain high blood glucose levels.', 'Glucagon is responsible for switching off gluconeogenesis.', 'Insulin is responsible for switching on glycogenolysis.', 'Glucagon is responsible for switching on gluconeogenesis', 'D', 'Per physiology (Guyton/Brunner), glucagon raises blood glucose by switching on gluconeogenesis and glycogenolysis, while insulin lowers glucose. Insulin, not glucagon, promotes glycogen storage; the other options misassign these actions.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What type of stool can a nurse expect from a client who has a colostomy of the lower descending colon?', 'Liquid', 'Bloody', 'Black', 'Formed', 'D', 'Per Brunner & Suddarth and Kozier, a colostomy in the lower/distal descending or sigmoid colon produces formed (solid) stool because water has already been absorbed in the proximal colon. Ascending/transverse colostomies produce liquid or semi-formed stool.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Clinical features of hydatidiform mole include;', 'Positive pregnancy test of urine diluted to 1:100 after4 weeks of amenorrhea, ultrasound shows features of fetus.', 'Amenorrhea followed by vomiting, breast changes.', 'Uterus larger than dates ,chronic gonadotropin hormone in urine increase', 'Amenorrhea followed by intermittent bleeding, fetus demonstrated in x-ray.', 'C', 'Per Myles Textbook for Midwives, hydatidiform mole classically presents with a uterus larger than expected for gestational age and markedly raised hCG, plus a ''snowstorm'' ultrasound with NO fetus. Options showing a demonstrable fetus are therefore incorrect.', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The aorta divides at the level of the 4th lumbar vertebra into;', 'external &internal iliac arteries', 'superior & inferior mesenteric arteries', 'common iliac arteries', 'lumbar arteries', 'C', 'Per standard anatomy (Gray''s/Kozier), the abdominal aorta bifurcates at the level of the 4th lumbar vertebra into the right and left common iliac arteries, which subsequently divide into external and internal iliac arteries.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Corneal infections are difficult to treat due to the fact that;', 'The surface area of cornea is small', 'Causative organisms cannot be recovered', 'Corneal infections are not easily diagnosed', 'The cornea is avascular organ', 'D', 'Per Brunner & Suddarth ophthalmic nursing, the cornea is avascular, so systemic antibiotics reach it poorly and healing/defence is slower, making corneal infections difficult to treat. The other options are not the primary reason.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The most appropriate intervention for a client with a diagnosis of ineffective airway clearance is:', 'Withholding pain medications', 'Administering cough suppressants every 4-6 hours', 'Administering antibiotics as prescribed', 'Maintaining adequate hydration and providing increased humidity.', 'D', 'Per Brunner & Suddarth and Kozier, for ineffective airway clearance the priority is thinning and mobilising secretions through adequate hydration and humidification. Cough suppressants and withholding analgesia would worsen clearance.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which is a symptom of atopic dermatitis?', 'A blister on the palms of hands and soles of feet.', 'Itchy, inflamed skin.', 'Scaly patches of skin on the scalp.', 'Coin-shaped patches of irritated skin on the arms and lower legs.', 'B', 'Per dermatology/Brunner & Suddarth, atopic dermatitis (eczema) is characterised by intensely itchy, inflamed (erythematous) skin. Palmar/plantar blisters, scalp scaling and coin-shaped patches describe dyshidrotic, seborrheic and nummular dermatitis respectively.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Furuncles (boils) are commonly caused by;', 'Streptococcus pyogenes', 'Clostridium tetani', 'Staphylococcus aureus', 'Bacillus aureus', 'C', 'Per standard microbiology/Brunner & Suddarth, furuncles (boils) are deep hair-follicle infections most commonly caused by Staphylococcus aureus. Streptococcus pyogenes causes impetigo/cellulitis and C. tetani causes tetanus.', 'KRCHN', 'Paper I', 'Infection Prevention & Control', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The immediate effects of burns on body fluids and electrolytes include ;-', 'Hypokalemia & Hyponatremia.', 'Reduced circulatory blood volume and hypernatremia.', 'Hyponatremia and Hyperkalemia.', 'Reduced urine output and hypokalemia', 'C', 'Per Brunner & Suddarth burn nursing, in the immediate emergent (fluid-shift) phase sodium is lost into the interstitium (hyponatremia) and potassium is released from damaged cells into plasma (hyperkalemia). Circulating volume and urine output also fall, but the electrolyte pattern is hyponatremia with hyperkalemia.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When suctioning a laryngeal tube;-', 'It should take about 10 seconds.', 'A clean and not asceptic technique should be used.', 'Suction is applied while inserting the catheter into the tube.', 'Suctioning should be done continuously till secretions clear. D B', 'A', 'Per Kozier and Brunner & Suddarth, tracheal/laryngeal suctioning must be brief (about 10–15 seconds) to avoid hypoxia, using STERILE technique, with suction applied only on withdrawal (not insertion) and never continuously. Thus option A is the only correct statement.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Passive range of motion exercises;', 'Are performed to prevent nosocomial infections.', 'Helps to prevent joints rigidity and contractures.', 'Is a collaborative intervention that requires a surgeon and a nurse.', 'Are repeated 5-6 times a day to enhance quick recovery. D B', 'B', 'Per Kozier & Erb''s Fundamentals, passive ROM exercises maintain joint mobility and prevent stiffness and contractures in patients unable to move independently. They do not prevent infections (A).', 'KRCHN', 'Paper I', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The Korotkoff sounds heard while measuring blood pressure present in the order of,', 'Tapping, Swishing, Knocking, muffling and silence', 'Swishing, Tapping, Silence, muffling and knocking', 'Knocking, Tapping, Swishing, muffling, silence', 'Silence, Tapping, Knocking, Swishing and Muffling B A', 'A', 'Per Kozier & Erb''s, the five Korotkoff phases occur in order: sharp tapping (Phase I, systolic), swishing/murmur (Phase II), knocking (Phase III), muffling (Phase IV), then silence/disappearance (Phase V, diastolic).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In sickle cell anaemia patients,', 'The structure of haemoglobin molecule is not affected.', 'Prophylactic administration of folic acid and pneumococcal vaccine is recommended', 'Administration of IV fluids & immediate blood transfusion are encouraged during sickle cell crisis situations', 'The treatment of choice includes administration of penicillins & NSAIDs C C', 'B', 'Per Kenya Basic Paediatric Protocols and Brunner & Suddarth, sickle cell patients require daily folic acid (increased erythropoiesis) and pneumococcal prophylaxis/vaccination due to functional asplenia. The Hb structure IS abnormal (A false); routine immediate transfusion in every crisis is not encouraged (C).', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Hyperkalemia commonly occurs in the following,', 'Burns, pneumonia and congestive cardiac failure.', 'Renal failure, crush injuries and burns.', 'Digitalis toxicity, DKA and hyperthyroidism.', 'Overuse of potassium sparing diuretics, CCF and liver cirrhosis C B', 'B', 'Per Brunner & Suddarth, hyperkalemia results from impaired renal excretion (renal failure) and massive cellular potassium release in crush injuries and burns. DKA typically shows shifting but hyperthyroidism is not a classic cause (C).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The route that achieves the quickest absorption and effects of a drug is the,', 'Subcutaneous', 'Intradermal', 'Intramuscular', 'Oral D C', 'C', 'Among the given parenteral/enteral routes, intramuscular injection has the richest vascular bed, giving faster absorption than subcutaneous, intradermal, or oral. Per Brunner & Suddarth pharmacology, IM absorption is quickest of these options (IV not listed).', 'KRCHN', 'Paper I', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In simple mastectomy:-', 'Pectoralis major muscle and the entire breast is excised', 'Axillary lymph nodes and pectoralis major muscles are left intact', 'Underlying chest muscles and chaniin of internal mammary lymph nodes are removed', 'Entire breast and axillary lymph nodes are removed B B', 'B', 'Per Brunner & Suddarth, a simple (total) mastectomy removes the entire breast but preserves the pectoralis major muscle and axillary lymph nodes. Removing axillary nodes (D) describes modified radical mastectomy.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Reed Sternberg cell is a pathologic hallmark essential in diagnosis of:-', 'Hodgkin’s disease', 'Acute myeloid leukemia', 'Chronic lymphocytic leukemia', 'Non-hodgkin disease', 'A', 'Per Brunner & Suddarth, the Reed-Sternberg cell is the pathognomonic hallmark used to diagnose Hodgkin''s lymphoma. It is absent in non-Hodgkin lymphoma and the leukemias.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Characteristics of 1st degree burns include:-', 'Erythema and pain', 'Chilling and dry wounds', 'Healing by scaling, painless wounds', 'Black appearance, painless wounds', 'A', 'Per Brunner & Suddarth, first-degree (superficial) burns involve only the epidermis and present with erythema, pain, and no blistering (e.g., sunburn). Painless black/leathery wounds (D) indicate full-thickness burns.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In rheumatoid arthritis, inflammation of the jounts begins in the:-', 'Hip, ankle,elbow', 'Feet, wrist, toes', 'Shoulder, fingers, wrist', 'Clavicle, hands, fingers D C', 'B', 'Per Brunner & Suddarth, rheumatoid arthritis typically begins symmetrically in the small joints of the hands and feet—wrists, MCP/PIP joints, and toes—before affecting larger joints.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The main aim of escharotomy in treatment of full thickness burns is to:-', 'Improve oxygenation of the burnt tissues', 'Remove the dead tissues', 'Allow underlying viable tissues to expand', 'Reduce pain C C', 'C', 'Per Brunner & Suddarth, escharotomy incises the constricting inelastic eschar of circumferential full-thickness burns to relieve pressure, allowing underlying tissue to expand and restoring circulation/ventilation.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Risk factors of osteoporosis include:-', 'Lack of Vitamin D in diet, high estrogen levels in women', 'Too much exposure to the sun, low testosterone levels in men', 'Increase in age, late menopause', 'Excessive alcohol consumption, early menopause D', 'D', 'Per Brunner & Suddarth, osteoporosis risk factors include excessive alcohol intake and early menopause (reduced estrogen). Low—not high—estrogen and adequate vitamin D/sun are protective, making A and B incorrect.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Rhesus factor is found in the cell membrane of the:-', 'Lymphocytes', 'Granulocytes', 'Erythrocytes', 'Globulins C C', 'C', 'Per standard physiology (Brunner & Suddarth), the Rhesus (Rh) antigen is located on the cell membrane of red blood cells (erythrocytes), determining Rh-positive or Rh-negative blood type.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The hypogastric region of the abdominopelvic cavity is;', 'Inferior to the umbilical region, medial to the right iliac region', 'Lateral to the left iliac region, superior to the umbilical region', 'Medial to the right iliac region, lateral to the umbilical region', 'Superior to the umbilical region, medial to the right iliac region D A', 'A', 'Per standard anatomy, the hypogastric (suprapubic) region lies inferior to the umbilical region and medial to the right and left iliac regions in the nine-region abdominopelvic scheme.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The most appropriate nursing action when a client begins to cough and has difficulty breathing during nasogastric tube insertion is;', 'Inserting the tube quickly', 'Notifying the physician immediately', 'Removing the tube and reinserting when the respiratory distress subsides', 'Pulling the tube back a little and wait until the respiratory distress subsides D D', 'D', 'Per Kozier & Erb''s, coughing and dyspnea during NG insertion suggest the tube has entered the airway; the nurse should withdraw the tube slightly and pause until distress resolves before advancing again. Continuing to insert (A) risks tracheal placement.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The expected outcomes for a patient who has “potential for impaired gas exchange related to fluid overload” is;', 'No shortness of breath, scaphoid abdomen.', 'Chest X-ray normal, improved gas exchange.', 'Respiratory rate less than 20breaths/min, skin colour normal.', 'Heart rate less than 100 beats/min, increased urine output B D', 'C', 'Per Kozier & Erb''s, expected outcomes for impaired gas exchange are measurable normal respiratory function: respiratory rate <20/min and normal (pink) skin colour indicating adequate oxygenation. This directly reflects resolved gas-exchange impairment better than urine output (D).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('During Lumbar puncture, a needle is inserted in the space between;-', 'Fifth and sixth thoracic vertebrae.', 'Fourth and fifth thoracic vertebrae', 'Third and fourth lumbar vertebrae.', 'First and second lumbar vertebrae C C', 'C', 'Per Brunner & Suddarth, lumbar puncture is performed below the spinal cord''s end (L1-L2), typically in the L3-L4 (or L4-L5) interspace to avoid cord injury. Thoracic sites (A, B) are unsafe.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In chronic bronchitis;-', 'There is cough and sputum production for at least 3 months in 2 consecutive years.', 'There is destruction of alveoli walls due to severe infection and increased secretion.', 'There is increased ciliary function in the airway.', 'There is flow limitation and is not fully reversible', 'A', 'Per Brunner & Suddarth, chronic bronchitis is clinically defined as a productive cough present for at least 3 months in each of 2 consecutive years. Alveolar wall destruction (B) describes emphysema.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The condition in which the eyeballs are not properly aligned with each other is referred to as;', 'Astigmatism', 'Strabismus', 'Presbyopia', 'Amblyopia', 'B', 'Per standard ophthalmic nursing (Brunner & Suddarth), strabismus is misalignment of the eyes so that they do not point in the same direction. Astigmatism is refractive error, presbyopia is age-related near-vision loss, and amblyopia is ''lazy eye''.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When assessing a client with possible Cushing’s syndrome you would expect to find;', 'Hypotension', 'Thick coarse skin', 'Deposits of adipose tissue in the trunk', 'Weight loss', 'C', 'Per Brunner & Suddarth, Cushing''s syndrome (cortisol excess) causes central (truncal) obesity, moon face, and buffalo hump. It produces hypertension, thin fragile skin, and weight gain—not hypotension or weight loss.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When administering an enema;', 'The client should lie in the right lateral position.', 'The enema tube should be inserted 8 inches into the clients’ rectum.', 'The client should be advised to retain the enema for 30 minutes.', 'The nurse should position the client in left lateral position', 'D', 'Per Kozier & Erb''s, an enema is administered with the client in the left lateral (Sims'') position to follow the natural curve of the sigmoid colon. Insertion depth for adults is about 3-4 inches, not 8 (B).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The primary causes of acute otitis media are;-', 'Escherichia coli and proteus spp.', 'Streptococcus pneumoniae and Haemophilus influenzae.', 'Staphylococcus aureus and haemophilus influenzae.', 'Proteus spp. and Streptococcus pneumoniae.', 'B', 'Per Kenya Basic Paediatric Protocols and Brunner & Suddarth, the leading bacterial causes of acute otitis media are Streptococcus pneumoniae and Haemophilus influenzae (with Moraxella catarrhalis).', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Triple therapy is indicated in treatment of;', 'Osteomyelitis.', 'Helicobacter pylori.', 'Neisseria meningitidis.', 'Oncocerca volvulus', 'B', 'Per Kenya MOH clinical guidelines and Brunner & Suddarth, triple therapy (a proton pump inhibitor plus two antibiotics such as clarithromycin and amoxicillin) is the standard regimen for eradicating Helicobacter pylori.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('during the early postoperative period after a subtotal thyroidectomy, the concern that has the priority is', 'hemorrhage', 'thyrotoxic crisis', 'airway obstruction', 'hypocalcemic tetany', 'C', 'Per Brunner & Suddarth, in the early postoperative period after thyroidectomy the priority (ABC) concern is airway obstruction from tracheal compression due to bleeding or laryngeal edema. While hemorrhage and hypocalcemia are risks, airway patency takes priority.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('immediately after esophageal surgery the priority nursing assessment concerns the client''s', 'incision', 'respiration', 'level of pain', 'nasogastric tube', 'B', 'Per Brunner & Suddarth, following esophageal surgery (thoracic approach) the priority assessment is respiratory status/airway and breathing, as the surgery affects the chest and diaphragm and impairs ventilation. Airway/breathing precede pain and NG assessment.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client presents to the clinic with a serum cholesterol of 275 mg/dL and is placed on rosuvastatin (Crestor). Which instruction should be given to the client?', 'Report muscle weakness to the physician.', 'Allow six months for the drug to take effect.', 'Take the medication with fruit juice.', 'Ask the doctor to perform a complete blood count before starting the medication.', 'A', 'Per Brunner & Suddarth pharmacology, statins such as rosuvastatin can cause myopathy/rhabdomyolysis; clients must report unexplained muscle pain or weakness promptly. Statins act within weeks, not six months (B), and are usually taken in the evening.', 'KRCHN', 'Paper I', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client is admitted to the hospital with hypertensive crises. Diazoxide (Hyperstat) is ordered. During administration, the nurse should:', 'Utilize an infusion pump', 'Check the blood glucose level', 'Place the client in Trendelenburg position', 'Cover the solution with foil', 'B', 'Per Brunner & Suddarth pharmacology, diazoxide is a vasodilator that also inhibits insulin release and commonly causes hyperglycemia; the nurse must monitor blood glucose during administration.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The 6-month-old client with a ventral septal defect is receiving Digitalis for regulation of his heart rate. Which finding should be reported to the doctor?', 'Blood pressure of 126/80', 'Blood glucose of 110 mg/dL', 'Heart rate of 60 bpm', 'Respiratory rate of 30 per minute', 'C', 'Per Kenya Basic Paediatric Protocols and Brunner & Suddarth, digoxin is withheld and the physician notified when the infant''s apical heart rate is below 90-100 bpm; a rate of 60 bpm signals bradycardia and possible digitalis toxicity in a 6-month-old.', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client admitted with angina is given a prescription for nitroglycerin. The client should be instructed to:', 'Replenish his supply every 3 months', 'Take one every 15 minutes if pain occurs', 'Leave the medication in the brown bottle', 'Crush the medication and take with water', 'C', 'Per Brunner & Suddarth pharmacology, nitroglycerin is light-sensitive and must be kept in its original dark (brown) glass bottle to preserve potency. Sublingual doses are taken every 5 minutes up to three times (not 15 min), and supply should be replaced about every 6 months.', 'KRCHN', 'Paper I', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client is instructed regarding foods that are low in fat and cholesterol. Which diet selection is lowest in saturated fats?', 'Macaroni and cheese', 'Shrimp with rice', 'Turkey breast', 'Spaghetti', 'C', 'Per Brunner & Suddarth''s cardiac/lipid-lowering diet teaching, skinless white poultry (turkey breast) is lowest in saturated fat. Macaroni and cheese is high in dairy saturated fat, shrimp is high in cholesterol.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client is admitted with left-sided congestive heart failure. In assessing the client for edema, the nurse should check the:', 'Feet', 'Neck', 'Hands', 'Sacrum', 'D', 'Per Brunner & Suddarth''s, dependent edema collects in the sacrum in a bedbound/supine client, making it the best site to assess in hospitalized CHF patients; feet edema is checked in ambulatory clients.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is checking the client’s central venous pressure. The nurse should place the zero of the manometer at the:', 'Phlebostatic axis', 'PMI', 'Erb’s point', 'Tail of Spence', 'A', 'Per Brunner & Suddarth''s critical care nursing, the zero reference of the manometer/transducer for CVP is levelled at the phlebostatic axis (4th intercostal space, mid-anteroposterior chest) to align with the right atrium.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The physician orders lisinopril (Zestril) and furosemide (Lasix) to be administered concomitantly to the client with hypertension. The nurse should:', 'Question the order', 'Administer the medications', 'Administer separately', 'Contact the pharmacy', 'B', 'Per Kenya EML/BNF, an ACE inhibitor (lisinopril) plus a loop diuretic (furosemide) is a standard, recommended combination for hypertension/heart failure; the order is appropriate, so the nurse administers the medications.', 'KRCHN', 'Paper I', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The best method of evaluating the amount of peripheral edema is:', 'Weighing the client daily', 'Measuring the extremity', 'Measuring the intake and output', 'Checking for pitting', 'B', 'Per Kozier & Erb''s, measuring the circumference of the affected extremity with a tape at a marked point gives the most objective, reproducible measure of localized peripheral edema; daily weight best reflects generalized fluid, and pitting is only a graded estimate.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is caring for a client hospitalized with a facial stroke. Which diet selection would be suited to the client?', 'Roast beef sandwich, potato chips, pickle spear, iced tea', 'Split pea soup, mashed potatoes, pudding, milk', 'Tomato soup, cheese toast, Jello, coffee', 'Hamburger, baked beans, fruit cup, iced tea', 'B', 'Per Brunner & Suddarth''s stroke/dysphagia management, soft, cohesive, easily swallowed foods (soup, mashed potatoes, pudding) are safest; dry, crumbly or hard items (sandwich, chips, toast) increase aspiration risk with facial weakness.', 'KRCHN', 'Paper I', 'Nursing Management & Leadership', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The physician has prescribed Novolog insulin for a client with diabetes mellitus. Which statement indicates that the client knows when the peak action of the insulin occurs?', '“I will make sure I eat breakfast within 10 minutes of taking my insulin.”', '“I will need to carry candy or some form of sugar with me all the time.”', '“I will eat a snack around three o’clock each afternoon.”', '“I can save my dessert from supper for a bedtime snack.”', 'A', 'Per Kenya EML/BNF, insulin aspart (Novolog) is rapid-acting with onset ~10–20 min and peak ~1–3 h, so the client must eat within about 10–15 minutes of injecting to avoid hypoglycaemia at peak.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is teaching basic infant care to a group of first-time parents. The nurse should explain that a sponge bath is recommended for the first 2 weeks of life because:', 'New parents need time to learn how to hold the baby.', 'The umbilical cord needs time to separate.', 'Newborn skin is easily traumatized by washing.', 'The chance of chilling the baby outweighs the benefits of bathing.', 'B', 'Per Kenya Basic Paediatric Protocols/newborn care, tub bathing is delayed until the umbilical cord stump separates and heals to keep it dry and prevent infection; sponge baths are used until then.', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The physician has prescribed Nexium (esomeprazole) for a client with erosive gastritis. The nurse should administer the medication:', '30 minutes before meals', 'With each meal', 'In a single dose at bedtime', '30 minutes after meals', 'A', 'Per Kenya EML/BNF, proton pump inhibitors such as esomeprazole are most effective taken about 30 minutes before a meal so peak drug levels coincide with meal-stimulated acid production.', 'KRCHN', 'Paper I', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When the nurse checks the fundus of a client on the first postpartum day, she notes that the fundus is firm, is at the level of the umbilicus, and is displaced to the right. The next action the nurse should take is to:', 'Check the client for bladder distention', 'Assess the blood pressure for hypotension', 'Determine whether an oxytocic drug was given', 'Check for the expulsion of small clots', 'A', 'Per Myles Textbook for Midwives, a firm fundus displaced to the right and above expected level indicates a full bladder; the nurse should check for bladder distention and have the client void to allow the uterus to descend and contract.', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client is seen in the clinic for treatment of migraine headaches. The drug Imitrex (sumatriptan succinate) is prescribed for the client. Which of the following in the client’s history should be reported to the doctor?', 'Diabetes', 'Prinzmetal’s angina', 'Cancer', 'Cluster headaches', 'B', 'Per Kenya EML/BNF, sumatriptan is a 5-HT1 agonist that causes vasoconstriction and is contraindicated in ischaemic/vasospastic heart disease such as Prinzmetal''s (variant) angina, so this history must be reported.', 'KRCHN', 'Paper I', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client with suspected meningitis is admitted to the unit. The doctor is performing an assessment to determine meningeal irritation and spinal nerve root inflammation. A positive Kernig’s sign is charted if the nurse notes:', 'Pain on flexion of the hip and knee', 'Nuchal rigidity on flexion of the neck', 'Pain when the head is turned to the left side', 'Dizziness when changing positions', 'A', 'Per Brunner & Suddarth''s neurologic assessment, a positive Kernig''s sign is pain/resistance on extending the knee when the hip and knee are flexed; nuchal rigidity on neck flexion describes Brudzinski''s sign.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client with Alzheimer’s disease is being assisted with activities of daily living when the nurse notes that the client uses her toothbrush to brush her hair. The nurse is aware that the client is exhibiting:', 'Agnosia', 'Apraxia', 'Anomia', 'Aphasia', 'B', 'Per Brunner & Suddarth''s, apraxia is the inability to carry out purposeful, learned motor tasks correctly (e.g., using a toothbrush on the hair); agnosia is failure to recognize objects, aphasia is a language deficit.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The doctor has prescribed Exelon (rivastigmine) for the client with Alzheimer’s disease. Which side effect is most often associated with this drug?', 'Urinary incontinence', 'Headaches', 'Confusion', 'Nausea', 'D', 'Per Kenya EML/BNF, rivastigmine is a cholinesterase inhibitor whose most common adverse effects are cholinergic GI effects—nausea, vomiting, anorexia; urinary incontinence is not typical (it causes cholinergic effects, not retention).', 'KRCHN', 'Paper I', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is assessing the deep tendon reflexes of a client with preeclampsia. Which method is used to elicit the biceps reflex?', 'The nurse places her thumb on the muscle inset in the antecubital space and taps the thumb briskly with the reflex hammer.', 'The nurse loosely suspends the client’s arm in an open hand while tapping the back of the client’s elbow.', 'The nurse instructs the client to dangle her legs as the nurse strikes the area below the patella with the blunt side of the reflex hammer.', 'The nurse instructs the client to place her arms loosely at her side as the nurse strikes the muscle insert just above the wrist.', 'A', 'Per Kozier & Erb''s/physical assessment technique, the biceps reflex is elicited by placing the thumb over the biceps tendon in the antecubital fossa and striking the thumb with the reflex hammer.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which observation in the newborn of a diabetic mother would require immediate nursing intervention?', 'Crying', 'Wakefulness', 'Jitteriness', 'Yawning', 'C', 'Per Kenya Basic Paediatric Protocols, jitteriness/tremors in the infant of a diabetic mother signals hypoglycaemia, which requires immediate assessment and treatment; crying, wakefulness and yawning are normal.', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse caring for a client receiving intravenous magnesium sulfate must closely observe for side effects associated with drug therapy. An expected side effect of magnesium sulfate is:', 'Decreased urinary output', 'Hypersomnolence', 'Absence of knee jerk reflex', 'Decreased respiratory rate', 'B', 'Per Myles/Kenya maternal guidelines, mild sedation/drowsiness (hypersomnolence) and feeling warm are expected effects of therapeutic magnesium sulfate; loss of knee-jerk reflex, respiratory depression and oliguria are signs of toxicity, not expected effects.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client has elected to have epidural anesthesia to relieve labor pain. If the client experiences hypotension, the nurse would:', 'Place her in Trendelenburg position', 'Decrease the rate of IV infusion', 'Administer oxygen per nasal cannula', 'Increase the rate of the IV infusion', 'D', 'Per Myles Textbook for Midwives, epidural-induced hypotension is treated by increasing the IV fluid rate (fluid bolus), left-lateral positioning and oxygen; Trendelenburg is avoided as it can worsen the cephalad spread of the block.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The home health nurse is visiting an 18-year-old with osteogenesis imperfecta. Which information obtained on the visit would cause the most concern? The client:', 'Likes to play football', 'Drinks several carbonated drinks per day', 'Has two sisters with sickle cell tract', 'Is taking acetaminophen to control pain', 'A', 'Osteogenesis imperfecta causes brittle bones prone to fracture; contact sports such as football pose the greatest injury risk and cause most concern (Brunner & Suddarth''s, musculoskeletal disorders).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse working the organ transplant unit is caring for a client with a white blood cell count of 450. During evening visitation, a visitor brings a basket of fruit. What action should the nurse take?', 'Allow the client to keep the fruit', 'Place the fruit next to the bed for easy access by the client', 'Offer to wash the fruit for the client', 'Tell the family members to take the fruit home', 'D', 'A WBC of 450 indicates severe neutropenia; fresh fruit harbours bacteria/fungi and is contraindicated in neutropenic precautions, so it should be removed (Brunner & Suddarth''s, neutropenic care / IPC principles).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client admitted 2 days earlier that a lung resection accidentally pulls out the chest tube. Which action by the nurse indicates understanding of the management of chest tubes?', 'Order a chest x-ray', 'Reinsert the tube', 'Cover the insertion site with a Vaseline gauze', 'Call the doctor', 'C', 'An accidentally dislodged chest tube requires immediate application of an occlusive (Vaseline) dressing to prevent air entry and tension pneumothorax, then notify the physician (Brunner & Suddarth''s, chest drainage management).', 'KRCHN', 'Paper I', 'Nursing Management & Leadership', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which selection would provide the most calcium for the client who is 4 months pregnant?', 'A granola bar', 'A bran muffin', 'A cup of yogurt', 'A glass of fruit juice', 'C', 'Yogurt is a dairy product and the richest calcium source among the options, important for the increased calcium demand in pregnancy (Kozier & Erb''s Fundamentals; Kenya maternal nutrition guidelines).', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is evaluating nutritional outcomes for a with anorexia nervosa. Which data best indicates that the plan of care is effective?', 'The client selects a balanced diet from the menu.', 'The client’s hemoglobin and hematocrit improve.', 'The client’s tissue turgor improves.', 'The client gains weight.', 'D', 'In anorexia nervosa the primary nutritional goal is restoration of body weight; weight gain is the best objective indicator that the nutritional plan is effective (Brunner & Suddarth''s / mental health nursing).', 'KRCHN', 'Paper I', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following foods would the nurse encourage the client in sickle cell crisis to eat?', 'Peaches', 'Cottage cheese', 'Popsicle', 'Lima beans', 'C', 'Fluid intake is essential in sickle cell crisis; a popsicle provides additional fluids to support hydration and reduce sickling, making it the best choice to encourage (Brunner & Suddarth''s, sickle cell crisis hydration).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is instructing a client with iron-deficiency anemia. Which of the following meal plans would the nurse expect the client to select?', 'Roast beef, gelatin salad, green beans, and peach pie', 'Chicken salad sandwich, coleslaw, French fries, ice cream', 'Egg salad on wheat bread, carrot sticks, lettuce salad, raisin pie', 'Pork chop, creamed potatoes, corn, and coconut cake', 'C', 'Iron-rich choices include eggs, whole wheat, leafy green vegetables and raisins (dried fruit); this meal provides the most dietary iron for iron-deficiency anemia (Kenya nutrition guidelines; Brunner & Suddarth''s).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Clients with sickle cell anemia are taught to avoid activities that cause hypoxia and hypoxemia. Which of the following activities would the nurse recommend?', 'A family vacation in the Rocky Mountains', 'Chaperoning the local boys club on a snow-skiing trip', 'Traveling by airplane for business trips', 'A bus trip to the Museum of Natural History', 'D', 'Activities causing hypoxia (high altitude in the Rocky Mountains, cold snow-skiing, unpressurised/altitude air travel) must be avoided; a low-altitude bus trip is safe (Brunner & Suddarth''s, sickle cell patient education).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is conducting an admission assessment of a client with vitamin B12 deficiency. Which of the following would the nurse include in the physical assessment?', 'Palpate the spleen', 'Take the blood pressure', 'Examine the feet for petechiae', 'Examine the tongue', 'D', 'Vitamin B12 deficiency characteristically causes glossitis (a smooth, beefy-red, sore tongue); examining the tongue is the relevant physical assessment finding (Brunner & Suddarth''s, megaloblastic/pernicious anemia).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is conducting a physical assessment on a client with anemia. Which of the following clinical manifestations would be most indicative of the anemia?', 'BP 146/88', 'Respirations 28 shallow', 'Weight gain of 10 pounds in 6 months', 'Pink complexion', 'B', 'Anemia reduces oxygen-carrying capacity, causing compensatory tachypnea and dyspnea; increased shallow respirations (28) is the most indicative manifestation, while pink complexion would be inconsistent with anemia (Brunner & Suddarth''s, anemia assessment).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following would be the priority nursing diagnosis for the adult client with acute leukemia?', 'Oral mucous membrane, altered related to chemotherapy', 'Risk for injury related to thrombocytopenia', 'Fatigue related to the disease process', 'Interrupted family processes related to life-threatening illness of a family member', 'B', 'In acute leukemia, thrombocytopenia predisposes to life-threatening hemorrhage; risk for injury/bleeding is the priority (physiologic safety) nursing diagnosis (Brunner & Suddarth''s, leukemia nursing care).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The home health nurse is visiting a client with autoimmune thrombocytopenic purpura (ATP). The client''s platelet count currently is 80, It will be most important to teach the client and family about:', 'Bleeding precautions', 'Prevention of falls', 'Oxygen therapy', 'Conservation of energy', 'A', 'With a low platelet count in ATP (ITP), the priority teaching is bleeding precautions to prevent hemorrhage (Brunner & Suddarth''s, thrombocytopenia/ITP care).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client with a history of diabetes insipidus is admitted with polyuria, polydipsia, and mental confusion. The priority intervention for this client is:', 'Measure the urinary output', 'Check the vital signs', 'Encourage increased fluid intake', 'Weigh the client', 'B', 'Diabetes insipidus with polyuria and confusion risks severe dehydration and hypovolemic shock; assessing vital signs is the priority to detect fluid volume/hemodynamic instability (Brunner & Suddarth''s, diabetes insipidus).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which statement made by the nurse describes the inheritance pattern of autosomal recessive disorders?', 'An affected newborn has unaffected parents.', 'An affected newborn has one affected parent.', 'Affected parents have a one in four chance of passing on the defective gene.', 'Affected parents have unaffected children who are carriers.', 'A', 'Per genetics (Brunner & Suddarth), in autosomal recessive inheritance both unaffected parents are typically heterozygous carriers, so an affected child is born to phenotypically unaffected parents. The 1-in-4 risk refers to two carrier (not affected) parents, making that option imprecise.', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is responsible for performing a neonatal assessment on a full-term infant. At 1 minute, the nurse would expect to find:', 'An apical pulse of 100', 'An absence of tonus', 'Cyanosis of the feet and hands', 'Jaundice of the skin and sclera', 'C', 'Per Basic Paediatric Protocols/newborn assessment, acrocyanosis (bluish hands and feet) is a normal finding at 1 minute due to peripheral circulation. Apical pulse should be 120-160, and jaundice at 1 minute is abnormal.', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client with varicella will most likely have an order for which category of medication?', 'Antibiotics', 'Antipyretics', 'Antivirals', 'Anticoagulants', 'C', 'Per Kenya IMNCI/clinical guidelines, varicella (chickenpox) is a viral infection; antivirals such as acyclovir are indicated in severe or high-risk cases. Antibiotics treat only secondary bacterial infection.', 'KRCHN', 'Paper I', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following instructions should be included in the teaching for the client with rheumatoid arthritis?', 'Avoid exercise because it fatigues the joints.', 'Take prescribed anti-inflammatory medications with meals.', 'Alternate hot and cold packs to affected joints.', 'Avoid weight-bearing activity.', 'B', 'Per Brunner & Suddarth, NSAIDs/anti-inflammatory drugs for rheumatoid arthritis should be taken with meals to reduce gastric irritation. Exercise (ROM) is encouraged, not avoided, so the other options are incorrect.', 'KRCHN', 'Paper I', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('During the assessment of a laboring client, the nurse notes that the FHT are loudest in the upper-right quadrant. The infant is most likely in which position?', 'Right breech presentation', 'Right occipital anterior presentation', 'Left sacral anterior presentation', 'Left occipital transverse presentation', 'A', 'Per Myles, fetal heart tones heard loudest in the upper quadrant indicate the fetal back/heart is high in the uterus, consistent with a breech presentation; on the right side this is a right breech. Vertex presentations transmit FHTs in the lower quadrants.', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The primary physiological alteration in the development of asthma is:', 'Bronchiolar inflammation and dyspnea', 'Hypersecretion of abnormally viscous mucus', 'Infectious processes causing mucosal edema', 'Spasm of bronchial smooth muscle', 'D', 'Per Brunner & Suddarth respiratory pathophysiology, the primary reversible physiological alteration in asthma is bronchospasm (spasm of bronchial smooth muscle), accompanied by inflammation and mucus. Bronchospasm is the hallmark driving airway narrowing.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('To maintain Bryant''s traction, the nurse must make certain that the child''s:', 'Hips are resting on the bed, with the legs suspended at a right angle to the bed', 'Hips are slightly elevated above the bed and the legs are suspended at a right angle to the bed', 'Hips are elevated above the level of the body on a pillow and the legs are suspended parallel to the bed', 'Hips and legs are flat on the bed, with the traction positioned at the foot of the bed', 'B', 'Per paediatric orthopaedic nursing (Brunner/paeds texts), Bryant''s traction requires the hips slightly elevated off the bed so the child''s weight provides countertraction, with legs suspended vertically at a 90-degree angle to the bed. Buttocks must clear the mattress.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client has an order for a trough to be drawn on the client receiving Vancomycin. The nurse is aware that the nurse should contact the lab for them to collect the blood:', '15 minutes after the infusion', '30 minutes before the infusion', '1 hour after the infusion', '2 hours after the infusion', 'B', 'Per pharmacology/therapeutic drug monitoring (Brunner & Suddarth), a vancomycin trough is drawn immediately before (about 30 minutes prior to) the next dose to measure the lowest serum concentration. Levels drawn after infusion reflect peak, not trough.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client using a diaphragm should be instructed to:', 'Refrain from keeping the diaphragm in longer than 4 hours', 'Keep the diaphragm in a cool location', 'Have the diaphragm resized if she gains 5 pounds', 'Have the diaphragm resized if she has any surgery', 'D', 'Per Kenya Family Planning guidelines, a diaphragm must be refitted after events that change vaginal/pelvic dimensions such as pelvic surgery, childbirth, or a weight change of about 10 or more pounds. A 5-pound gain generally does not require refitting, and it must stay in at least 6 hours after intercourse.', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is providing postpartum teaching for a mother planning to breastfeed her infant. Which of the client''s statements indicates the need for additional teaching?', '"I''m wearing a support bra."', '"I''m expressing milk from my breast."', '"I''m drinking four glasses of fluid during a 24-hour period."', '"While I''m in the shower, I''ll allow the water to run over my breasts."', 'C', 'Per Myles/postpartum lactation teaching, a breastfeeding mother needs increased fluids (about 8-10 glasses/day); only four glasses in 24 hours is inadequate and indicates a need for more teaching. Support bra, expressing milk, and letting water run over breasts are correct.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following tests should be performed before beginning a prescription of Accutane?', 'Check the calcium level', 'Perform a pregnancy test', 'Monitor apical pulse', 'Obtain a creatinine level', 'B', 'Per pharmacology (Kenya EML/BNF), isotretinoin (Accutane) is highly teratogenic, so a negative pregnancy test is mandatory before starting therapy in women of childbearing potential. Calcium and creatinine are not the primary pre-treatment screens.', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse should visit which of the following clients first?', 'The client with diabetes with a blood glucose of 95mg/dL', 'The client with hypertension being maintained on Lisinopril', 'The client with chest pain and a history of angina', 'The client with Raynaud''s disease', 'C', 'Per triage/prioritization (ABC, Brunner & Suddarth), the client with active chest pain and angina history is at risk of an evolving myocardial infarction and must be seen first. The others are stable with controlled findings.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Cataracts result in opacity of the crystalline lens. Which of the following best explains the functions of the lens?', 'The lens controls stimulation of the retina.', 'The lens orchestrates eye movement.', 'The lens focuses light rays on the retina.', 'The lens magnifies small objects.', 'C', 'The crystalline lens refracts (focuses) incoming light rays onto the retina; cataract opacity blurs this focus (Anatomy & Physiology; Brunner & Suddarth''s). Pupil/iris controls light intake and extraocular muscles control movement, not the lens.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client with color blindness will most likely have problems distinguishing which of the following colors?', 'Orange', 'Violet', 'Red', 'White', 'C', 'The most common inherited color blindness is red-green deficiency, so red is the color most likely confused (Anatomy & Physiology of vision). Violet and orange are less commonly affected and white is not a hue.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client with a pacemaker should be taught to:', 'Report ankle edema', 'Check his blood pressure daily', 'Refrain from using a microwave oven', 'Monitor his pulse rate', 'D', 'Pacemaker clients are taught to check their pulse daily and report a rate below the set threshold, which signals pacemaker malfunction (Brunner & Suddarth''s). Modern microwaves are safe, so refraining from them is unnecessary.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client with enuresis is being taught regarding bladder retraining. The nurse should advise the client to refrain from drinking after:', '1900', '1200', '1000', '0700', 'A', 'In bladder retraining for enuresis, fluids are restricted in the evening (after about 1900 hrs / 7 pm) to reduce night-time bladder filling, while daytime intake stays adequate (Kozier & Erb''s Fundamentals of Nursing). Stopping fluids at midday would cause dehydration.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following diet instructions should be given to the client with recurring urinary tract infections?', 'Increase intake of meats.', 'Avoid citrus fruits.', 'Perform pericare with hydrogen peroxide.', 'Drink a glass of cranberry juice every day.', 'D', 'Cranberry juice acidifies urine and inhibits bacterial adherence to the bladder wall, helping prevent recurrent UTIs (Brunner & Suddarth''s). Citrus need not be avoided, and hydrogen peroxide pericare is inappropriate.', 'KRCHN', 'Paper I', 'Infection Prevention & Control', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The physician has prescribed NPH insulin for a client with diabetes mellitus. Which statement indicates that the client knows when the peak action of the insulin occurs?', '"I will make sure I eat breakfast within 2 hours of taking my insulin."', '"I will need to carry candy or some form of sugar with me all the time."', '"I will eat a snack around three o''clock each afternoon."', '"I can save my dessert from supper for a bedtime snack."', 'C', 'NPH (intermediate-acting) insulin peaks roughly 6-12 hours after a morning dose, so a mid-afternoon snack covers the peak and prevents hypoglycemia (Brunner & Suddarth''s; Kenya EML). Eating breakfast within 2 hours describes rapid/short-acting insulin.', 'KRCHN', 'Paper I', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The physician has prescribed ranitidine (Zantac) for a client with erosive gastritis. The nurse should administer the medication:', '30 minutes before meals', 'With each meal', 'In a single dose at bedtime', '60 minutes after meals', 'A', 'H2 antagonists such as ranitidine are best given before meals so the drug blocks the acid secretion stimulated by eating (Brunner & Suddarth''s; Kenya EML). Single bedtime dosing does not cover mealtime acid surges as well.', 'KRCHN', 'Paper I', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('While assessing the postpartal client, the nurse notes that the fundus is displaced to the right. Based on this finding, the nurse should:', 'Ask the client to void', 'Assess the blood pressure for hypotension', 'Administer oxytocin', 'Check for vaginal bleeding', 'A', 'A fundus displaced to the right (and often above the umbilicus) indicates a full bladder; having the client void allows the uterus to recenter and contract, preventing atony (Myles Textbook for Midwives; Kenya MNH guidelines). Oxytocin is not first-line for a bladder-related displacement.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The physician has ordered an MRI for a client with an orthopedic ailment. An MRI should not be done if the client has:', 'The need for oxygen therapy', 'A history of claustrophobia', 'A permanent pacemaker', 'Sensory deafness', 'C', 'MRI is contraindicated with most permanent pacemakers because the strong magnetic field can disrupt or damage the device (Brunner & Suddarth''s). Claustrophobia and deafness can be accommodated and are not absolute contraindications.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is preparing to discharge a client with a long history of polio. The nurse should tell the client that:', 'Taking a hot bath will decrease stiffness and spasticity.', 'A schedule of strenuous exercise will improve muscle strength.', 'Rest periods should be scheduled throughout the day.', 'Visual disturbances can be corrected with prescription glasses.', 'C', 'Clients with polio/post-polio syndrome fatigue easily, so scheduled rest periods conserve energy and protect weakened muscles (Brunner & Suddarth''s). Strenuous exercise can worsen muscle weakness and is contraindicated.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The physician has ordered a thyroid scan to confirm the diagnosis. Before the procedure, the nurse should:', 'Assess the client for allergies', 'Bolus the client with IV fluid', 'Tell the client he will be asleep', 'Insert a urinary catheter', 'A', 'A thyroid scan uses radioactive iodine tracer, so the nurse must assess for iodine/shellfish allergy before the procedure (Brunner & Suddarth''s). Sedation, IV bolus, and catheterization are not routinely required.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The physician has ordered an injection of RhoGam for a client with blood type A negative. The nurse understands that RhoGam is given to:', 'Provide immunity against Rh isoenzymes', 'Prevent the formation of Rh antibodies', 'Eliminate circulating Rh antibodies', 'Convert the Rh factor from negative to positive', 'B', 'RhoGam (anti-D immunoglobulin) provides passive immunity that suppresses the Rh-negative mother''s active production of anti-Rh antibodies, protecting future pregnancies (Myles Textbook for Midwives; Kenya MNH guidelines). It does not convert the Rh factor or eliminate existing antibodies.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is caring for a client admitted to the emergency room after a fall. X-rays reveal that the client has several fractured bones in the foot. Which treatment should the nurse anticipate for the fractured foot?', 'Application of a short inclusive spica cast', 'Stabilization with a plaster-of-Paris cast', 'Surgery with Kirschner wire implantation', 'A gauze dressing only', 'B', 'Simple closed fractures of the foot are typically immobilized with a plaster-of-Paris cast to allow bone healing (Brunner & Suddarth''s; Kenya orthopaedic practice). A spica cast is for hip/thigh, and Kirschner wires are reserved for unstable/displaced fractures.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Following a heart transplant, a client is started on medication to prevent organ rejection. Which category of medication prevents the formation of antibodies against the new organ?', 'Antivirals', 'Antibiotics', 'Immunosuppressants', 'Analgesics', 'C', 'Immunosuppressant drugs (e.g., cyclosporine, tacrolimus) suppress the immune response and prevent antibody-mediated rejection of the transplanted heart (Brunner & Suddarth''s; Kenya EML). Antivirals and antibiotics treat infection, not rejection.', 'KRCHN', 'Paper I', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is preparing a client for cataract surgery. The nurse is aware that the procedure will use:', 'Mydriatics to facilitate removal', 'Miotic medications such as Timoptic', 'A laser to smooth and reshape the lens', 'Silicone oil injections into the eyeball', 'A', 'Before cataract extraction, mydriatic (dilating) drops are instilled to widen the pupil and allow access to and removal of the lens (Brunner & Suddarth''s; Kenya EML ophthalmic). Miotics constrict the pupil and would hinder surgery.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is performing an initial assessment of a newborn Caucasian male delivered at 32 weeks gestation. The nurse can expect to find the presence of:', 'Mongolian spots', 'Scrotal rugae', 'Head lag', 'Vernix caseosa', 'C', 'A preterm infant at 32 weeks has immature neck muscle tone, so marked head lag is an expected finding (Myles Textbook for Midwives; Basic Paediatric Protocols). Scrotal rugae and abundant vernix develop later, closer to term.', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is caring for a client admitted with multiple trauma. Fractures include the pelvis, femur, and ulna. Which finding should be reported to the physician immediately?', 'Hematuria', 'Muscle spasms', 'Dizziness', 'Nausea', 'A', 'With a pelvic fracture, hematuria signals possible bladder or urethral injury and must be reported immediately (Brunner & Suddarth''s; Kenya trauma care). Muscle spasms and nausea are expected and less urgent findings.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The primary reason for rapid continuous rewarming of the area affected by frostbite is to:', 'Lessen the amount of cellular damage', 'Prevent the formation of blisters', 'Promote movement', 'Prevent pain and discomfort', 'A', 'Per Brunner & Suddarth''s Medical-Surgical Nursing, rapid continuous rewarming of frostbite in a warm water bath limits the extent of tissue and cellular destruction; the other options are secondary.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('During a home visit, a client with AIDS tells the nurse that he has been exposed to measles. Which action by the nurse is most appropriate?', 'Administer an antibiotic', 'Contact the physician for an order for immune globulin', 'Administer an antiviral', 'Tell the client that he should remain in isolation for 2 weeks', 'B', 'Per Kenya HIV/AIDS and immunocompromised care guidelines and Brunner & Suddarth''s, an immunosuppressed AIDS client exposed to measles should receive immune (immunoglobulin) prophylaxis; antibiotics and antivirals are not indicated for measles post-exposure protection.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The physician has ordered a minimal-bacteria diet for a client with neutropenia. The client should be taught to avoid eating:', 'Fruits', 'Salt', 'Pepper', 'Ketchup', 'A', 'Per oncology nursing guidance in Brunner & Suddarth''s, a neutropenic (low-bacteria) diet avoids raw/fresh fruits and vegetables which carry surface bacteria; seasonings like salt, pepper and ketchup are not the primary hazard.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is assisting the physician with removal of a central venous catheter. To facilitate removal, the nurse should instruct the client to:', 'Perform the Valsalva maneuver as the catheter is advanced', 'Turn his head to the left side and hyperextend the neck', 'Take slow, deep breaths as the catheter is removed', 'Turn his head to the right while maintaining a sniffing position', 'A', 'Per Brunner & Suddarth''s, during central venous catheter removal the client performs the Valsalva maneuver (bear down/hold breath) to raise intrathoracic pressure and prevent air embolism as the catheter is withdrawn; the stem''s wording ''advanced'' reflects the removal procedure and the Valsalva timing is the key safety action.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is providing discharge teaching for the client with leukemia. The client should be told to avoid:', 'Using oil- or cream-based soaps', 'Flossing between the teeth', 'The intake of salt', 'Using an electric razor', 'B', 'Per Brunner & Suddarth''s, leukemia clients are thrombocytopenic and neutropenic; flossing can cause gum bleeding and introduce infection, so it should be avoided. An electric razor is actually recommended to prevent cuts.', 'KRCHN', 'Paper I', 'Infection Prevention & Control', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is changing the ties of the client with a tracheotomy. The safest method of changing the tracheostomy ties is to:', 'Apply the new tie before removing the old one.', 'Have a helper present.', 'Hold the tracheotomy with the nondominant hand while removing the old tie.', 'Ask the doctor to suture the tracheostomy in place.', 'A', 'Per Kozier & Erb''s Fundamentals, the safest method when changing tracheostomy ties is to secure the new tie before removing the old one to prevent accidental decannulation.', 'KRCHN', 'Paper I', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is monitoring a client following a lung resection. The hourly output from the chest tube was 300mL. The nurse should give priority to:', 'Turning the client to the left side', 'Milking the tube to ensure patency', 'Slowing the intravenous infusion', 'Notifying the physician', 'D', 'Per Brunner & Suddarth''s, chest tube drainage exceeding 100 mL/hr (here 300 mL) suggests active hemorrhage and is a priority to report to the physician immediately; milking the tube is contraindicated.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The infant is admitted to the unit with tetralogy of fallot. The nurse would anticipate an order for which medication?', 'Digoxin', 'Epinephrine', 'Aminophylline', 'Atropine', 'A', 'Per Basic Paediatric Protocols (Kenya) and standard paediatric cardiology, digoxin is used to improve myocardial contractility and manage heart failure in congenital heart defects such as tetralogy of Fallot; epinephrine, aminophylline and atropine are not standard maintenance therapy here.', 'KRCHN', 'Paper I', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The toddler is admitted with a cardiac anomaly. The nurse is aware that the infant with a ventricular septal defect will:', 'Tire easily', 'Grow normally', 'Need more calories', 'Be more susceptible to viral infections', 'A', 'Per paediatric nursing references, a ventricular septal defect causes left-to-right shunting and increased pulmonary blood flow, leading to fatigue (especially with feeding), poor weight gain and increased infection risk; the classic expected finding among the options is that the child tires easily.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is monitoring a client with a history of stillborn infants. The nurse is aware that a nonstress test can be ordered for this client to:', 'Determine lung maturity', 'Measure the fetal activity', 'Show the effect of contractions on fetal heart rate', 'Measure the well-being of the fetus', 'D', 'Per Myles Textbook for Midwives, a nonstress test assesses fetal well-being through fetal heart rate accelerations with movement; while it detects fetal activity, its ordered purpose in a high-risk client is to evaluate overall fetal well-being. The contraction stress test, not NST, shows the effect of contractions.', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse has a preop order to administer Valium (diazepam) 10mg and Phenergan (promethazine) 25mg. The correct method of administering these medications is to:', 'Administer the medications together in one syringe', 'Administer the medication separately', 'Administer the Valium, wait 5 minutes, and then inject the Phenergan', 'Question the order because they cannot be given at the same time', 'A', 'Per Kenya EML/BNF and injectable drug compatibility charts, diazepam (Valium) and promethazine (Phenergan) are compatible and are commonly combined in one syringe for preoperative IM sedation.', 'KRCHN', 'Paper I', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client has recently returned from having a thyroidectomy. The nurse should keep which of the following at the bedside?', 'A tracheotomy set', 'A padded tongue blade', 'An endotracheal tube', 'An airway', 'A', 'Per Brunner & Suddarth''s, after thyroidectomy a tracheotomy set is kept at the bedside because laryngeal nerve damage, tracheal compression or tetany-related laryngospasm can cause airway obstruction requiring emergency tracheotomy.
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The physical manifestations of fetal alcohol syndrome include:', 'cleft lip and palette.', 'hepatomegaly, hypotonia, and microphthalmia.', 'hyperbilirubinemia, jaundice, and failure to thrive.', 'microcephaly, short philtrum, and prenatal growth retardation.', 'D', 'Fetal alcohol syndrome presents with microcephaly, characteristic facies (smooth/short philtrum, thin upper lip, short palpebral fissures), and pre- and postnatal growth retardation. The other options list features not specific to FAS. Per paediatric/midwifery references (Myles Textbook for Midwives).', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which blood gas analyses are most indicative of respiratory acidosis?', 'pH = 7.22, PC02 = 55 mm Hg, HC03 = 30 mEq/L.', 'pH = 7.28, PC02 = 45 mm Hg, HC03 = 15 mEq/L.', 'pH = 7.34, PC02 = 35 mm Hg, HC03 = 25 mEq/L.', 'pH = 7.40, PC02 = 25 mm Hg, HC03 = 30 mEq/L.', 'A', 'Respiratory acidosis = low pH with elevated PCO2. Option A shows pH 7.22 (acidotic) with PCO2 55 (elevated, the primary cause) and compensatory HCO3 rise. The other options are metabolic acidosis (B), normal (C), or respiratory alkalosis (D). Per Brunner & Suddarth''s Medical-Surgical Nursing.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The major pharmacologic action of Salbutamol is:', 'decreasing airway reactivity.', 'decreasing inflammation and airway obstruction.', 'improving the action of cilia to sweep trapped mucous upward.', 'relaxing constricted bronchial smooth muscle.', 'D', 'Salbutamol is a beta-2 agonist bronchodilator; its major action is relaxation of bronchial smooth muscle. Anti-inflammatory action describes corticosteroids, not salbutamol. Per Kenya EML/BNF pharmacology.', 'KRCHN', 'Paper I', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The age at which the infant can reach an object, grasp it and bring it to mouth and seems excited when see the food is', '4 mo', '5 mo', '6 mo', '7 mo (B) Secondary (C) Intermediate (D) Tertiary', 'C', 'Per Kenya Basic Paediatric Protocols/IMNCI developmental milestones, at 6 months the infant can reach for and grasp an object, bring it to the mouth (palmar grasp) and shows excitement at the sight of food, coinciding with readiness for complementary feeding. (Option D text carries an unrelated fragment.)
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Effective supplementation of folate for prevention of neural tube defect is', 'started at least 1 mo before conception, and continued through the first 2-3 mo of pregnancy', 'started at least 3 mo before conception, to be stopped after positive pregnancy', 'started after positive pregnancy test and continued through the first 2-3 mo of pregnancy.', 'started at least 1 mo before conception, to be stopped after positive pregnancy test.', 'A', 'Folic acid for neural tube defect prevention should begin at least one month before conception and continue through the first trimester (first 2-3 months); per Kenya Maternal/Newborn and MOH antenatal guidelines. Neural tube closure occurs by 28 days, so periconceptional and early-pregnancy supplementation is required.', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Expansion of the intravascular volume and increased intravascular pressure are the main causes of edema in', 'lymphatic obstruction', 'heart failure', 'protein-losing enteropathy', 'nephrotic syndrome', 'B', 'In heart failure, increased intravascular (venous/hydrostatic) volume and pressure drive fluid into interstitium causing oedema; per Brunner & Suddarth''s Medical-Surgical Nursing. Lymphatic obstruction, protein-losing enteropathy and nephrotic syndrome cause oedema mainly via reduced oncotic pressure or lymphatic blockage, not raised intravascular volume/pressure.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Increased production of CO2 occurs in all the following EXCEPT', 'fever', 'emesis', 'excess caloric intake', 'high levels of physical activity', 'B', 'Fever, excess caloric intake and high physical activity all raise metabolic rate and CO2 production; per Brunner & Suddarth acid-base physiology. Emesis (vomiting) does not increase CO2 production (it causes loss of gastric acid), so it is the EXCEPT answer.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Malignant hyperthermia is an acute hypermetabolic syndrome that is triggered by inhalational anesthetic agents and succinylcholine. Of the following, the MOST recognized clue to the risk of malignant hyperthermia is', 'rigid clenching of the masseter muscles', 'hypercarbia', 'ventricular fibrillation', 'rapid onset of fever', 'A', 'Masseter muscle rigidity (trismus) after succinylcholine is the earliest and most recognized clinical clue to malignant hyperthermia; per Brunner & Suddarth peri-operative/anesthesia nursing. Hypercarbia, arrhythmias and fever occur but appear later and are less specific as the initiating clue.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Cyanosis (unresponsive to oxygen) is a sign of poisoning with', 'atropine', 'amiodarone', 'carbon monoxide', 'vancomycin', 'C', 'Cyanosis unresponsive to oxygen indicates that haemoglobin cannot carry/release oxygen, characteristic of carbon monoxide poisoning (and methaemoglobinaemia); per Brunner & Suddarth/toxicology. Atropine, amiodarone and vancomycin do not classically cause oxygen-refractory cyanosis.', 'KRCHN', 'Paper I', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The MOST common reason for a sick child visit is', 'vomiting', 'altered mental status', 'respiratory distress', 'fever', 'D', 'Fever is the single most common presenting complaint for sick child visits; per Kenya IMNCI and Basic Paediatric Protocols. Vomiting, altered mental status and respiratory distress are common but less frequent than fever as the chief complaint.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Major cause of neonatal mortality in full-term newborn is', 'respiratory distress syndrome', 'necrotizing enterocolitis', 'bronchopulmonary dysplasia (BPD)', 'congenital anomalies', 'D', 'In full-term newborns, congenital anomalies are the leading cause of neonatal mortality; per Kenya newborn care/Basic Paediatric Protocols. RDS, NEC and BPD predominate in preterm rather than term infants.', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Freedom of choice in one of the policies of the Family Planning Program. Which of the following illustrates this principle?', 'Information dissemination about the need for family planning', 'Support of research and development in family planning methods', '. Adequate information for couples regarding the different methods', 'Encouragement of couples to take family planning as a joint responsibility', 'C', 'Freedom of choice is exercised when couples are given adequate information on all available methods so they can choose freely; per Kenya National Family Planning Guidelines. General information dissemination (A), research support (B) and encouraging joint responsibility (D) do not directly embody informed free choice among methods.', 'KRCHN', 'Paper I', 'Research & Evidence-Based Practice', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Scotch tape swab is done to check for which intestinal parasite?', 'Ascaris', '. Pinworm', '. Hookworm', 'Schistosoma', 'B', 'The scotch (cellophane) tape test collects perianal eggs to diagnose pinworm (Enterobius vermicularis); per standard parasitology/Kenya lab practice. Ascaris, hookworm and schistosoma are diagnosed by stool or urine examination, not the tape swab.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The most frequent causes of death among clients with AIDS are opportunistic diseases. Which of the following opportunistic infections is characterized by tonsilllopharyngitis?', 'Respiratory candidiasis', '. Infectious mononucleosis', 'Cytomegalovirus disease', 'Pneumocystis carinii pneumonia', 'B', 'Infectious mononucleosis (EBV) classically presents with tonsillopharyngitis (exudative pharyngitis), fever and lymphadenopathy; per Brunner & Suddarth, EBV is a common opportunistic reactivation in immunosuppressed/AIDS patients. Candidiasis causes oral thrush/plaques, CMV causes retinitis/colitis and PCP causes pneumonia — none typified by tonsillopharyngitis.', 'KRCHN', 'Paper I', 'Infection Prevention & Control', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Management of a child with measles includes the administration of which of the following?', 'Gentian violet on mouth lesions', 'Antibiotic to prevent pneumonia', 'Tetracycline eye ointment for corneal opacity', 'Retinol capsule regardless of when the last dose was given', 'D', 'Per Kenya IMNCI/Basic Paediatric Protocols, every child with measles must receive Vitamin A (retinol) immediately regardless of previous dosing, to prevent complications including corneal damage and reduce mortality. Tetracycline eye ointment is for eye discharge, not corneal opacity, and antibiotics are given only for pneumonia if present.', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The pathognomonic sign of measles is Koplik’s spot. You may see Koplik’s spot by inspecting the:', 'Nasal Mucosa', 'Buccal mucosa', 'Skin on the abdomen', 'Skin on the antecubital surface', 'B', 'Per standard paediatric/communicable disease texts, Koplik''s spots (pathognomonic of measles) are small white spots seen on the buccal mucosa opposite the molars, appearing before the rash. They are not found on the nasal mucosa or skin.', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In a mother’s class, you discuss proper breastfeeding technique. Which of these is a sign that the baby has “lactated on” the breast property?', 'The baby takes shallow, rapid sucks', '. The mother does not feel nipple pain', 'The baby’s mouth is only partly open', 'Only the mother’s nipple is inside the baby’s mouth', 'B', 'Per Kenya MOH/WHO breastfeeding guidance, good attachment (latch) signs include the baby''s mouth wide open, more areola visible above than below, chin touching breast, slow deep sucks, and painless feeding for the mother. Shallow rapid sucks, partly-open mouth and nipple-only in mouth indicate poor attachment.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The factors that promote growth and development include:-', 'Nutrition, security, emotional support', 'Nutrition, play, emotional', 'Play, achieving status, nutrition', 'Emotional support, religion, play', 'A', 'Per child health/growth and development (Basic Paediatric Protocols; MCH), factors promoting optimal growth and development include adequate nutrition, security/safety, and emotional support (love), alongside stimulation and health care. Option A best captures these core determinants; religion is not a core requirement.', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Complications of severe malaria include:-', 'Acute hypoglycaemia, brain damage', 'Acute hypoglycaemia, shock', 'Kidney failure, retinal damage', 'Kidney failure, joints pain', 'A', 'Per Kenya National Malaria Guidelines, complications of severe malaria include hypoglycaemia and cerebral malaria (brain damage). This pairing is the recognised complication set.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Maternal factors that may interfere with breast feeding include:-', 'Infections, prematurity, birth injuries', 'Cracked nipples, mastitis congenital abnormalities', 'Inverted nipples, prematurity, birth injuries', 'Death of a mother, cracked nipples, mastitis', 'D', 'Per Myles Textbook for Midwives, MATERNAL factors interfering with breastfeeding include death/illness of the mother, cracked nipples and mastitis. Prematurity, birth injuries and congenital abnormalities are infant (not maternal) factors.', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Molly, with suspected rheumatic fever, is admitted to the pediatric unit. When obtaining the child’s history, the nurse considers which information to be most important?', 'A fever that started 3 days ago', 'Lack of interest in food', 'A recent episode of pharyngitis', 'Vomiting for 2 days', 'C', 'Per paediatric nursing (Basic Paediatric Protocols/Brunner), rheumatic fever follows a group A streptococcal pharyngitis; a recent episode of pharyngitis is the most important historical finding linking to the diagnosis (Jones criteria supportive evidence).', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is aware that the most common assessment finding in a child with ulcerative colitis is:', 'Intense abdominal cramps', 'Profuse diarrhea', 'Anal fissures', 'Abdominal distention', 'B', 'Per paediatric med-surg nursing, the most common presenting finding in ulcerative colitis is profuse (often bloody) diarrhea. Abdominal cramps and distention occur but diarrhea is the hallmark assessment finding.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When developing a plan of care for a male adolescent, the nurse considers the child’s psychosocial needs. During adolescence, psychosocial development focuses on:', 'Becoming industrious', 'Establishing an identity', 'Achieving intimacy', 'Developing initiative', 'B', 'Per Erikson''s developmental theory (Kozier & Erb''s), the psychosocial task of adolescence is identity vs. role confusion, i.e. establishing an identity. Industry is school age, intimacy is young adulthood, initiative is preschool.', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When developing a plan care for a hospitalized child, nurse Mica knows that children in which age group are most likely to view illness as a punishment for misdeeds?', 'Infancy', 'Preschool age', 'School age', 'Adolescence', 'B', 'Per paediatric nursing/Piaget, preschool children (magical, egocentric preoperational thinking) most often view illness and hospitalization as punishment for their misdeeds. School-age children begin to understand cause and effect.', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('To decrease the likelihood of bradyarrhythmias in children during endotracheal intubation, succinylcholine (Anectine) is used with which of the following agents? Epinephrine (Adrenalin) Isoproterenol (Isuprel) Atropine sulfate Lidocaine hydrochloride (Xylocaine)', 'Epinephrine (Adrenalin)', 'Isoproterenol (Isuprel)', 'Atropine sulfate', 'Lidocaine hydrochloride (Xylocaine)', 'C', 'Per paediatric pharmacology/emergency protocols, atropine sulfate is given with succinylcholine during intubation in children to block the vagally mediated bradycardia (bradyarrhythmias). Epinephrine, isoproterenol, and lidocaine do not serve this vagolytic role.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The well-child care intends to promote the physical and emotional well-being of children. The tasks of each well-child visit include all the following EXCEPT', 'disease detection', 'disease prevention', 'treatment plans', 'health promotion', 'C', 'Per well-child care (paediatric/community health), the tasks of a well-child visit are disease detection (screening), disease prevention (immunization), and health promotion. Formulating treatment plans is a sick-child task, so it is the EXCEPTION.', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('By the age of 7 months the infant is able to do all the following EXCEPT', 'transfer object from hand to hand', 'bounces actively', 'cruises', 'grasp uses radial palm', 'C', 'Per paediatric growth and development, a 7-month-old can transfer objects hand to hand, bounce actively, and use a radial-palmar grasp, but cruising (walking while holding furniture) is not achieved until about 9-12 months, making it the EXCEPTION.', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The neurodevelopmental function (cognition) is dependent mainly on the development of the following functions EXCEPT', 'sensory and motor', 'language', 'visual–spatial', 'cerebeller', 'D', 'Neurodevelopmental cognition depends on sensory-motor, language and visual-spatial streams (Nelson Textbook of Pediatrics). The cerebellum primarily coordinates movement/balance and is not a principal domain of cognitive assessment, making it the EXCEPT answer.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Breastfeeding has been suggested to have a possible protective effect against all the following EXCEPT', 'otitis media', 'urinary tractinfections', 'septicemia', 'skin infection', 'D', 'Breastfeeding is protective against otitis media, urinary tract infection and septicaemia through passive immunity and IgA (WHO/IMNCI; Nelson). Protection against skin infection is not an established breastfeeding benefit, making it the EXCEPT.', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Emergency treatment in severe malnutrition includes all the following EXCEPT', 'infections', 'severe anemia', 'dehydration and shock', 'hypoglycemia', 'B', 'Immediate emergency threats in severe acute malnutrition are hypoglycaemia, hypothermia, dehydration/shock and infection (WHO 10 steps; Kenya Basic Paediatric Protocols). Severe anaemia is managed in the stabilisation phase but is not part of the initial life-threatening emergency triad, so it is the EXCEPT.', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The aim of the rehabilitation phase in the treatment of malnutrition is to', 'repair cellular function', 'correct fluid and electrolyte imbalance', 'restore homeostasis', 'prevent death from infection', 'A', 'The rehabilitation (catch-up growth) phase aims to rebuild wasted tissues and repair cellular/metabolic function with high-energy feeds (WHO management of SAM; Kenya Basic Paediatric Protocols). Correcting fluids/electrolytes, restoring homeostasis and preventing death from infection belong to the earlier stabilisation phase.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Nonsteroidal anti-inflammatory drugs (NSAIDs) are prescribed to decrease acute and chronic inflammation associated with various rheumatic diseases; however, many adverse effects have been encountered with long term use.Of the following, the NSAID that has the highest toxicity is.', 'meloxicam', 'indomethacin', 'ibuprofen', 'naproxen', 'B', 'Among these NSAIDs indomethacin has the highest toxicity, with prominent GI, CNS and renal adverse effects (Kenya EML/BNF; Katzung Pharmacology). Ibuprofen and naproxen are comparatively safer and meloxicam is relatively COX-2 selective.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which age group has the greatest potential to demonstrate regression when they are sick?', 'Adolescent', 'Young Adult', 'Toddler', 'Infant', 'C', 'Per paediatric nursing (Kozier/Wong), the toddler has the greatest potential to regress to earlier behaviours (e.g. loss of toileting, thumb-sucking) when hospitalised or ill, due to recently acquired but fragile developmental skills.', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The type of lochia expected 10-15 days postpartum is?', 'Rubra', 'Alba', 'Serosa', 'Clear', 'B', 'Lochia alba (whitish) is expected from about day 10 up to 2-6 weeks postpartum; rubra is days 1-3/4 and serosa days 4-10 (Myles Textbook for Midwives).', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The oral contraceptive pill has which of the following minor side effect?', 'Mild elevation of blood pressure', 'Venus thromboembolism', 'Post pill amenorrhea', 'Carcinogenicity', 'A', 'Mild elevation of blood pressure is a minor side effect of combined oral contraceptives, whereas venous thromboembolism is a serious complication; post-pill amenorrhoea and carcinogenicity are not classed as minor side effects (Kenya National Family Planning Guidelines).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('the characteristics of a classical syphilitic ulcer include', 'painful, flat lesion with edema of the surrounding area', 'painful, extensive lesions, fluid filled vesicle like blister', 'painless, flat lesion with smooth regular firm edge', 'painless, flat lesion with irregular edges and flat dirty base', 'C', 'The primary syphilitic chancre is a painless, indurated ulcer with a smooth, clean base and firm, regular raised edges; painful ragged/dirty ulcers suggest chancroid (Kenya STI guidelines, Brunner & Suddarth).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('the commonest causative organism of urinary tract infection is', 'proteus', 'streptococcus aureus', 'Escherichia coli', 'Klebsiela', 'C', 'Escherichia coli is the commonest causative organism of urinary tract infection, accounting for the majority of uncomplicated UTIs (Brunner & Suddarth, Kenya clinical guidelines).', 'KRCHN', 'Paper I', 'Infection Prevention & Control', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following are indicators of good nutritional status during pregnancy. Which one is not', 'Mid upper arm circumference of less then 23cm', 'Weight gain', 'Hemoglobin level of 11g per dl or more', 'Absence of clinical signs of micronutrient deficiency', 'A', 'Good nutritional status in pregnancy is indicated by adequate weight gain, Hb of 11 g/dl or more and absence of micronutrient deficiency signs; a MUAC less than 23 cm indicates malnutrition, so it is NOT an indicator of good status (Kenya maternal nutrition guidelines).', 'KRCHN', 'Paper I', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Lisa is a 24-year-old Para 1 who has a seizure disorder and is taking anticonvulsant medication. Which contraceptive option would the provider discourage her from using?', 'COCs', 'POPs', 'Implants', 'IUCDs', 'A', 'Enzyme-inducing anticonvulsants reduce the efficacy of combined oral contraceptives; per Kenya/WHO Medical Eligibility Criteria for Family Planning, COCs are discouraged (Category 3) with such anticonvulsants, so COCs should be avoided.', 'KRCHN', 'Paper I', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following falls under “DELAY” in the medical eligibility criteria?', 'Age of 18 years', 'Local skin infection', 'Depressive disorders', 'Diabetes Mellitus', 'B', 'In WHO/Kenya Medical Eligibility Criteria, the classifications are Accept, Caution, Delay and Refer; a local infection at the insertion site is a ''Delay'' condition for methods like implants/IUCDs until it resolves, whereas the others are accept/caution categories.', 'KRCHN', 'Paper I', 'Infection Prevention & Control', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Lactation amenorrhea method of family planning is suitable for a woman who', 'Breastfeeds exclusively, has history of delayed menstruation, has a baby of more than six months', 'Breastfeeds exclusively,has history of delayed menstruation, wants highly effective method in the first six months', 'Breastfeeds exclusively, has not resumed menstruation, has a baby of less than six months', 'Breastfeeds exclusively, has history of delayed menstruation, has a baby of less than six months A. what disease is indicative of thiamine deficiency A. Beriberi B. Pellagra C. Scurvy D. Kwashiokor', 'C', 'LAM requires all three criteria: exclusive breastfeeding, amenorrhoea (menses not resumed), and infant under 6 months. Per Kenya National Family Planning Guidelines. Option D''s stray text (Beriberi item) is disregarded.', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Gumma lesions are the characteristics of', 'Latent stage of syphilis', 'Primordial stage of syphilis', 'Tertiary stage of syphilis', 'Secondary stage of syphilis', 'C', 'Gummata (granulomatous lesions) are the hallmark of tertiary (late) syphilis; primary shows chancre and secondary shows rash/condylomata lata. Per Kenya National STI Guidelines / Brunner & Suddarth.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The most frequent causes of death among clients with AIDS are opportunistic diseases. Which of the following opportunistic infections is characterized by tonsillopharyngitis?', 'Respiratory candidiasis', 'Infectious mononucleosis', 'Cytomegalovirus disease', 'Pneumocystis carinii pneumonia', 'B', 'Infectious mononucleosis (EBV) classically presents with tonsillopharyngitis, fever and lymphadenopathy; PCP causes pneumonia and CMV causes retinitis/colitis. Per Brunner & Suddarth / Kenya HIV guidelines.', 'KRCHN', 'Paper I', 'Infection Prevention & Control', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The fungal skin infection characterized by thickening and discoloration of the nails is called:-', 'Tinea versicolor', 'Tinea pedis', 'Intertrigo', 'Tinea unguium', 'D', 'Tinea unguium (onychomycosis) is the fungal nail infection causing thickening and discoloration of nails; tinea pedis affects feet and versicolor affects trunk skin. Per Brunner & Suddarth / Kenyan derm nursing.', 'KRCHN', 'Paper I', 'Infection Prevention & Control', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following parts of the brain is associated with multiple feelings and behaviors and is sometimes referred to as the “emotional brain”: -', 'Frontal lobe', 'Thalamus', 'Hypothalamus', 'Limbic system', 'D', 'The limbic system is termed the ''emotional brain'', governing multiple emotions and behaviours; the frontal lobe handles executive function and the thalamus is a sensory relay (neuroanatomy texts).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is a tricyclic antidepressant:-', 'Paroxetine', 'Escitalopram', 'Venlafaxine', 'Amitriptyline', 'D', 'Amitriptyline is a classic tricyclic antidepressant, whereas paroxetine and escitalopram are SSRIs and venlafaxine is an SNRI (Kenya EML / psychopharmacology).', 'KRCHN', 'Paper I', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following effective nursing intervention in order to prevent occurrence of Gastroesophageal reflux?', 'Giving solid foods', 'Giving frequent small feedings', 'Giving semi-solid foods', 'Giving osterized feeding', 'B', 'Small, frequent feeds (with upright positioning) reduce gastric volume and prevent gastro-oesophageal reflux in infants (paediatric nursing). Solid/semi-solid or osterised feeds do not address the mechanism of reflux.', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following are signs and symptoms of asthma except:', 'Fatigue', 'pinkish skin', 'Moist skin', 'Use of accessory muscles', 'B', 'In an asthma attack the child is hypoxic, so cyanosis (not pinkish skin) is expected; fatigue, diaphoresis (moist skin) and accessory muscle use are true signs (Basic Paediatric Protocols / respiratory nursing). Thus pinkish skin is the exception.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse leads an adolescent health information group, which often expands into other areas of discussion. She knows that these youths are trying to find out “who they are,” and discussion often focuses on which directions they want to take in school and life, as well as peer relationships. According to Erikson, this stage is known as:', 'identity vs. role confusion', 'adolescent rebellion.', 'career experimentation.', 'relationship testing', 'A', 'Adolescents seeking to discover ''who they are'' are in Erikson''s identity versus role confusion stage (growth & development). The other options are not Erikson stages.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is not an acyanotic heart disease?', 'Patent Ductus Arteriosus', 'Patent Ductus Arteriosus', 'Patent Ductus Arteriosus', 'Tetralogy of Fallot', 'D', 'Tetralogy of Fallot is a cyanotic (right-to-left shunt) congenital heart disease, whereas Patent Ductus Arteriosus is acyanotic; thus ToF is NOT acyanotic (paediatric cardiology). Options A-C are duplicate distractors.
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is not a sign of severe dehydration in children?', 'lethargic or unconscious', 'Skin pinch goes back readily', 'Unable to drink or drinking poorly', 'Sunken eyes', 'B', 'Per Kenya IMNCI, severe dehydration signs include lethargy/unconsciousness, inability to drink or drinking poorly, sunken eyes and a skin pinch that goes back VERY SLOWLY. A skin pinch that goes back readily is normal, so it is NOT a sign of severe dehydration.', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('While assessing a newborn with cleft lip, the nurse would be alert that which of the following will most likely be compromised?', 'Sucking ability', 'Respiratory status', 'Locomotion', 'GI function', 'A', 'A cleft lip disrupts the infant''s ability to form a seal, so sucking ability is most likely compromised, creating feeding difficulty (paediatric/neonatal nursing). Respiratory status, locomotion and GI function are not primarily affected by an isolated cleft lip.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Patients with Idiopathic thrombocytopenic Purpura (ITP) have increased risk of bleeding. Therefore the nurse must carefully monitor:', 'WBC and bleeding time', 'Iron and ferritin level', 'PT and PTT', 'Platelet count and RBCs', 'D', 'ITP is a thrombocytopenia; the nurse monitors platelet count (and RBCs for bleeding-related anaemia) since coagulation cascade tests (PT/PTT) are typically normal in ITP (haematology nursing). Iron/ferritin and WBC are not the primary monitoring focus.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When assessing a 12 year old child with Wilm''s tumor, the nurse should keep in mind that it most important to avoid which of the following?', 'Measuring the child''s chest circumference', 'Palpating the child''s abdomen', 'Placing the child in an upright position', 'Measuring the child''s occipitofrontal circumference', 'B', 'In Wilms'' tumour, palpating the abdomen must be avoided because it may dislodge tumour cells and cause metastatic spread (paediatric oncology nursing). The other measures pose no such risk.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Craniotabes is a clinical sign of:', 'Kwashiorkor', 'Marasmus', 'Rickets', 'Scurvy', 'C', 'Craniotabes (soft, thin skull bones that indent under pressure) is a classic sign of vitamin D deficiency rickets, causing defective bone mineralization. Per Basic Paediatric Protocols (Kenya) and standard paediatrics, kwashiorkor/marasmus are protein-energy states and scurvy is vitamin C deficiency.', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Respiratory Distress Syndrome is a disease of preterm infant which caused due to all of the following except:', 'Atelectasis of alveoli.', 'Immaturity of the respiratory center.', 'Formation of surfactant substances.', 'Hypoxia.', 'C', 'RDS of the preterm is caused by DEFICIENCY (not formation) of surfactant, leading to alveolar atelectasis, hypoxia and immature respiratory control. Since ''formation of surfactant substances'' would prevent RDS, it is the exception. Per Basic Paediatric Protocols (Kenya).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Sudden stimulus causes the arms to fly up and out is:', 'Moro', 'Gag', 'Rooting', 'Tonic neck', 'A', 'The Moro (startle) reflex is elicited by a sudden stimulus causing symmetrical abduction/extension of the arms followed by flexion. Rooting and gag involve the mouth; tonic neck is the fencing posture. Standard neonatal assessment (Kozier & Erb''s, Basic Paediatric Protocols).', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following clinical assessments would most likely be demonstrated in severe dehydration?', 'Pale skin turgor', 'Normal skin turgor', 'Marked oliguria', 'Normal blood pressure', 'C', 'Severe dehydration produces marked oliguria/anuria from reduced renal perfusion, along with hypotension and poor (not normal) skin turgor. Per Kenya IMNCI classification of severe dehydration; ''normal'' BP and turgor are inconsistent with severe loss.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When providing postoperative care for the child with a cleft palate, the nurse should position the child in which of the following positions?', 'Supine', 'Prone', 'In an infant seat', 'lateral', 'B', 'After cleft palate repair the child is positioned prone (on the abdomen/side) to facilitate drainage of secretions and protect the suture line; supine risks aspiration. Standard paediatric surgical nursing (Brunner/Wong).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which assessment finding would the nurse expect in an infant diagnosed with pyloric stenosis?', 'Abdominal rigidity', 'Ribbon-like stools', 'Visible waves of peristalsis', 'Rectal prolapse', 'C', 'Pyloric stenosis presents with visible left-to-right gastric peristaltic waves and an olive-shaped mass with projectile vomiting. Abdominal rigidity, ribbon stools and rectal prolapse relate to other conditions. Standard paediatric med-surg.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following nursing diagnosis would the nurse identify as a priority for the infant with tracheoesophageal fistula (TEF)?', 'impaired parenting related to newborn''s illness', 'risk of injury related to increased potential for aspiration', 'ineffective nutrition: less than body requirements, related to poor sucking ability', 'ineffective breathing pattern related to a weak diaphragm', 'B', 'In TEF the priority is preventing aspiration of secretions/feeds into the lungs (airway protection), making risk of injury/aspiration the priority. Per airway-first (ABC) prioritisation; parenting and nutrition are lower priority.', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In bacterial meningitis all the following may be observed during CSF analysis results except: a. b. c. d.', 'high cells count', 'high glucose', 'high protein', 'turbidity', 'B', 'In bacterial meningitis CSF shows high WBC (neutrophils), high protein, low (not high) glucose, and turbidity. Thus ''high glucose'' is the exception. Per Basic Paediatric Protocols / Brunner & Suddarth''s.', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When Baby Nicole was 1 day old she has surgery for reduction of myelomeningocele. Which nursing intervention is critical during the postoperative period?', 'passive range-of-motion exercises of the lower extremities', 'suprapubic manual expression of urine', 'observation of the frequency and character of the stools', 'daily measurement of the head circumference', 'D', 'After myelomeningocele repair, hydrocephalus is a major risk, so daily head circumference measurement to detect increasing intracranial pressure is critical. Standard neuro-paediatric nursing (Wong/Brunner).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What clinical manifestations would suggest hydrocephalus in a neonate ?', 'Bulging fontanel, dilated scalp veins .', 'Closed fontanel, high-pitched cry .', 'Constant low-pitched cry, restlessness .', 'Depressed fontanel, decreased blood pressure .', 'A', 'Hydrocephalus in a neonate causes raised ICP with a bulging/tense fontanel, dilated scalp veins, enlarging head and high-pitched cry. A depressed or closed fontanel would not fit. Standard paediatric neuro assessment.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Kerning''s sign is manifestation for:', 'Wiliam''s tumor .', 'Acute Rheumatic Fever.', 'Encephalitis', 'Meningiti s', 'D', 'Kernig''s sign (resistance/pain on knee extension with hip flexed) is a sign of meningeal irritation seen in meningitis. Brunner & Suddarth''s / Basic Paediatric Protocols.', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following heart defects usually results in hypoxemia and cyanosis ?', 'Coarctation of the aorta .', 'Atrial septal defect .', 'Patent ductus arteriosus .', 'Transposition of the great vessels .', 'D', 'Transposition of the great vessels is a cyanotic (right-to-left) defect causing hypoxemia and cyanosis. Coarctation, ASD and PDF are acyanotic (left-to-right) lesions. Standard paediatric cardiology (Wong/Brunner).', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The best prophylactic treatment for client is to prevent further rheumatic attack:', 'Prednisone.', 'Aspirin.', 'Penicillin.', 'All of the above.', 'C', 'Secondary prophylaxis against recurrent rheumatic fever is long-term penicillin (benzathine penicillin) to prevent recurrent group A streptococcal infection. Prednisone and aspirin treat acute inflammation, not prophylaxis. Per Kenya/WHO RHD guidelines.', 'KRCHN', 'Paper I', 'Infection Prevention & Control', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In trachoma,', 'Pannus develop in the second stage of disease process', 'Rupture of the cornea can occur', 'The drug of choice is 1% tetracycline in early stages', 'Follicles form in the third stage of the disease process', 'C', 'Per WHO SAFE strategy adopted in Kenya, topical 1% tetracycline eye ointment (or azithromycin) is the treatment in early active trachoma. Pannus and corneal changes appear later; follicles form in the early (active) stage, not the third stage.', 'KRCHN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following disease causes severe tenesmus;', 'Bacillary dysentery', 'Amoebic dysentery', 'Girdiasis', 'Cholera', 'A', 'Per communicable disease references, bacillary dysentery (Shigella) characteristically causes severe tenesmus with blood and mucus in stool due to rectosigmoid inflammation. Cholera causes painless watery stool without tenesmus.', 'KRCHN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following elements of PHC were not listed in the Alma Ata Declaration', 'Education concerning prevailing health problems, basic sanitation', 'HIV/AIDS, maternal and child health', 'Treatment of common diseases, control of endemic diseases', 'Immunisation, promotion of food supply.', 'B', 'Per the 1978 Alma Ata Declaration, the original elements of PHC did NOT include HIV/AIDS (an emerging disease). The listed elements included health education, food supply/nutrition, safe water/sanitation, MCH/FP, immunisation, control of endemic diseases, treatment of common diseases, and essential drugs.', 'KRCHN', 'Paper II', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Sand fly is a vector for;', 'Filariasis', 'Dracunculosis', 'Leshmaniasiis', 'Yellow fever', 'C', 'Per Kenya communicable disease references, the sandfly (Phlebotomus) is the vector for leishmaniasis (kala-azar). Filariasis is spread by mosquitoes, dracunculiasis by Cyclops, yellow fever by Aedes.', 'KRCHN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following leadership style relies on organizational policies and rules for decision making;', 'Autocratic', 'Democratic', 'Bureaucratic', 'Laissez-faire', 'C', 'Per nursing management/leadership theory (Weber), the bureaucratic leadership style relies on fixed organizational rules, policies and procedures for decision-making rather than personal judgement.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('School health committees are composed of the following EXCEPT;', 'Teachers, students, community health nurse', 'Teachers, community informal leaders, Parents', 'Community health nurse, Teachers, school''s supportive staff', 'Parents, teachers, community formal leaders', 'A', 'Per school health programme guidelines, the school health committee comprises teachers, parents, community leaders, health workers and supportive staff; students/pupils are not formal committee members, so this option is the EXCEPT.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Food borne diseases include;', 'Polio, schistosomiaisis, Girdiasis.', 'Taeniasis, milliary T.B, hepatitis A.', 'Amoebiasis, Hepatitis B, Polio', 'Polio, schistosomiasis, milliary TB.', 'B', 'Per communicable disease references, food-borne diseases include taeniasis (undercooked meat), miliary/bovine TB (unpasteurised milk/meat) and hepatitis A (faecal-oral via contaminated food/water). Schistosomiasis is water-contact, not food-borne, eliminating the other options.', 'KRCHN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The study of population dynamics such as births, deaths and migration is referred to as;', 'Civil registration', 'Demography', 'Census', 'Epidemiology', 'B', 'Per community/public health, demography is the study of population dynamics including births, deaths, and migration. Epidemiology studies disease distribution; census is an enumeration; civil registration records vital events.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following factor DOES NOT affect growth of a population.', 'Migration', 'Women of reproductive age', 'Occurrence of disasters', 'Literacy levels', 'D', 'Per demography, the three direct determinants of population change/growth are births (fertility, linked to women of reproductive age), deaths (including disasters) and migration. Literacy influences these only indirectly and does NOT directly affect population growth.', 'KRCHN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Epidemiological triad includes;', 'Agent, route of transmission, mode of transmission.', 'Host, agent, environment.', 'Vector , route of transmission, Agent', 'Host, route of transmission, environment.', 'B', 'Per epidemiology, the epidemiological triad consists of the agent, the host, and the environment; their interaction determines disease occurrence.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The diseases that are targeted for eradication by KEPI include;', 'Poliomyelitis, neonatal tetanus, measles', 'Neonatal tetanus, measles, chicken pox', 'Measles, yellow fever, whooping cough', 'Poliomyelitis, neonatal tetanus, diphtheria', 'A', 'Per KEPI, the diseases targeted for eradication/elimination include poliomyelitis, neonatal tetanus and measles. Chicken pox, yellow fever, whooping cough and diphtheria are not the eradication-targeted set.', 'KRCHN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following leadership style has the least regard for organizational policies and rules ;', 'Autocratic', 'Democratic', 'Bureaucratic', 'Laissez-faire', 'D', 'Per nursing leadership theory, the laissez-faire (hands-off) style gives the least regard for organizational policies and rules, allowing group members maximum freedom with minimal leader control.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Everyone in the society is expected to bathe. This is an example of which norm?', 'A folkway', 'Mores', 'Law', 'Value', 'A', 'Per sociology as taught in NCK community/behavioural science, folkways are everyday customs of proper conduct (e.g. bathing, dressing) whose violation brings mild disapproval, unlike mores which carry strong moral weight. Bathing is a routine custom, hence a folkway.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Zoonotic diseases include', 'Rabies, tetanus, anthrax, trichuriasis', 'Anthrax, tetanus, rabies, plague', 'Brucellosis, rabies, anthrax, taeniasis', 'Tetanus, rabies, anthrax, brucellosis', 'C', 'Per Kenya communicable disease control, zoonoses are diseases transmitted from animals to humans; brucellosis, rabies, anthrax and taeniasis are all zoonotic. Tetanus is caused by environmental Clostridium tetani spores (not a zoonosis), so options listing tetanus are wrong.', 'KRCHN', 'Paper II', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The three components of a disease transmission cycle include:-', 'The environment, the transmission route, the susceptible host', 'The source, the environment, the susceptible host', 'The source, the transmission route, the susceptible host', 'The source, the vector, the transmission route', 'C', 'Per Kenya epidemiology/communicable disease control, the disease transmission cycle comprises the source (reservoir/agent), the route of transmission, and a susceptible host. The environment and vector are contributing factors, not the three core components.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The initial step of community diagnosis is:', 'Execution of survey', 'Planning of the survey', 'Exploration', 'Community action', 'C', 'Per Kenya community health nursing, community diagnosis begins with exploration/orientation (getting to know the community) before planning and executing the survey and taking community action. Exploration is therefore the initial step.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Characteristics of an effective team include:-', 'The management relationship in the organization is directive, information flows mainly downwards', 'Every member understands the objective and goals, communication is open during meetings', 'Criticism is frank and constructive, each individual strives to meet individual tasks', 'Decision making is by consensus, conflicts never arise due to the harmony', 'B', 'Per nursing management/leadership theory, effective teams share understood goals, open communication and consensus decision-making. Option B reflects these; directive downward-only flow and the claim that conflicts ''never arise'' are incorrect characteristics.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Incidence rate is:-', 'The number of cases of a disease present within the population', 'Disease giving rise to unexpectedly large number of cases', 'The occurrence of new cases within a stated period', 'Transmission of disease occurring at a low rate', 'C', 'Per Kenya epidemiology/biostatistics, incidence rate measures new cases arising in a population over a defined period. Existing (all) cases describe prevalence, and unexpectedly large numbers describe an epidemic.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Fat soluble vitamins include:-', 'A,D,C,E', 'A,D,E,K', 'E,D,C,K', 'A,B,C,D', 'B', 'Per nutrition principles in Kenyan nursing training, the fat-soluble vitamins are A, D, E and K. Vitamins B and C are water-soluble, so options containing them are wrong.', 'KRCHN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Common emotional health problems among the youth include:-', 'Suicidal tendency, alcoholism, drug abuse', 'Homosexuality, STI, truancy', 'Drug abuse, school drop out, promiscuity', 'Suicidal tendency, STI, school drop out', 'A', 'Per adolescent/mental health nursing, emotional health problems in youth include suicidal tendencies, alcoholism and drug/substance abuse. STIs, truancy and school drop-out are behavioural/social consequences rather than emotional health problems themselves.', 'KRCHN', 'Paper II', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The process of increasing the communities ability to handle a disaster is referred to as:-', 'Preparedness', 'Response', 'Mitigation', 'Prevention', 'A', 'Per Kenya disaster management guidelines, preparedness is the process of building the community''s capacity and readiness to handle a disaster before it occurs. Mitigation reduces impact/hazard severity, while response is action taken during the event.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When a disease is present in a community all the time it is said to be:-', 'Epidemic', 'Endemic', 'Pandemic', 'Prevalent', 'B', 'Per Kenya epidemiology, a disease constantly present in a community/area is endemic. Epidemic is an excess of cases, pandemic is worldwide spread, and prevalence is a measure of existing cases.
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following is not associated with Vitamin B group deficiencies:', 'Angular ceilitis', 'Hematuria', 'Pellagra', 'Beriberi', 'B', 'Angular cheilitis (B2), pellagra (B3/niacin) and beriberi (B1/thiamine) are all B-group deficiency states; hematuria is unrelated to B-vitamin deficiency (Kozier Fundamentals; Kenya nutrition guidelines).', 'KRCHN', 'Paper II', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nutrient requirements of children are NOT influenced by:', 'Growth rate', 'Body composition', 'Composition of new growth', 'Sex of the child', 'D', 'Growth rate, body composition and composition of new growth all directly influence a child''s nutrient requirements; sex has minimal influence in early childhood and is the least relevant factor (Kenya nutrition/paediatric guidelines).', 'KRCHN', 'Paper II', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following is an atypical antipsychotic', 'Risperidone', 'Buspirone', 'Flulazepam', 'Fluphenazine', 'A', 'Risperidone is an atypical (second-generation) antipsychotic; buspirone is an anxiolytic, flurazepam a benzodiazepine, and fluphenazine a typical antipsychotic (Kenya EML; standard pharmacology).', 'KRCHN', 'Paper II', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following is NOT associated with obsessive compulsive disorder:', 'Rituals', 'Depersonalization', 'Slowness', 'Hypochondriasis', 'B', 'Rituals, slowness (obsessional slowness) and hypochondriacal preoccupations feature in OCD; depersonalization is a dissociative symptom not characteristic of OCD (standard psychiatric nursing text).', 'KRCHN', 'Paper II', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following is a precipitating factor of anxiety disorders', 'Childhood upbringing', 'Genetic factors', 'Problems in relationships', 'Personality', 'C', 'Precipitating factors are acute triggers; relationship problems act as an immediate precipitant, whereas childhood upbringing, genetics and personality are predisposing factors (standard psychiatric nursing text).', 'KRCHN', 'Paper II', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The agreement of the participant to take part in the research project after having been thoroughly briefed about the project is', 'Human dignity', 'Full disclosure', 'Self determination', 'Informed consent', 'D', 'Agreement to participate after being fully briefed is the definition of informed consent; full disclosure and self-determination are elements that support it (Research ethics; NCK research syllabus).', 'KRCHN', 'Paper II', 'Research & Evidence-Based Practice', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In aversion therapy:-', 'A client is subjected to anxiety provoking stimuli in imagination', 'Noxious stimuli are used to change behavior', 'Relaxation techniques are used to correct inappropriate behavior', 'There is systematic exposure of a client to graded stimuli', 'B', 'Aversion therapy pairs an unwanted behavior with a noxious/unpleasant stimulus to reduce it; imagined anxiety stimuli and graded exposure describe systematic desensitization (behaviour therapy; psychiatric nursing).', 'KRCHN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('There is favourable prognosis in Schizophrenia if there are:-', 'Negative symptoms with history of schizoid personality', 'Positive symptoms and older age of onset', 'Schizoid personality and early age of onset', 'Early age of onset with negative symptoms', 'B', 'Good prognostic factors in schizophrenia include predominance of positive symptoms and later age of onset; negative symptoms, early onset and schizoid premorbid personality indicate poor prognosis (standard psychiatric text).', 'KRCHN', 'Paper II', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The middle score in a range of scores is called the;', 'Central tendency', 'Mode', 'Median', 'mean', 'C', 'The median is the middle value (score) when data are arranged in order. Per Polit & Beck / basic biostatistics used in NCK research papers, the mean is the average and mode the most frequent value.', 'KRCHN', 'Paper II', 'Research & Evidence-Based Practice', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client admitted for alcohol detoxification develops increased tremors, irritability, hypertension and fever. The nurse should be alert for impending:', 'Delirium tremens', 'Korsakoff''s syndrome', 'Esophageal varices', 'Wernicke''s syndrome', 'A', 'Increasing tremors, irritability, hypertension and fever during alcohol withdrawal signal impending delirium tremens, a life-threatening emergency. Korsakoff''s/Wernicke''s are thiamine-deficiency states. Per Kozier & standard psychiatric nursing texts (NCK mental health).', 'KRCHN', 'Paper II', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The primary nursing intervention in working with a client with moderate stage dementia is ensuring that the client:', 'receives adequate nutrition and hydration', 'will reminisce to decrease isolation', 'remains in a safe and secure environment', 'independently performs self care', 'C', 'Safety is the priority in moderate dementia because impaired cognition and wandering pose injury risk. Nutrition/hydration and reminiscence matter but safety takes precedence; independent self-care is not realistic at this stage. Per psychiatric/geriatric nursing standards.', 'KRCHN', 'Paper II', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Malingering is different from somatoform disorder because the former:', 'Has evidence of an organic basis.', 'It is a deliberate effort to handle upsetting events', 'Gratification from the environment is obtained.', 'Stress is expressed through physical symptoms.', 'C', 'Malingering is the conscious, deliberate production of symptoms for external/secondary gain (environmental gratification), whereas somatoform symptoms are unconscious and not intentionally produced. Per DSM/standard psychiatric nursing texts.
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is included in Orem’s theory', 'Maintenance of a sufficient intake of air', 'Self-perception', 'Love and belonging', 'Physiologic needs', 'A', 'Orem''s Self-Care Deficit Theory lists universal self-care requisites including maintenance of sufficient intake of air, water and food. Love/belonging and physiologic needs belong to Maslow''s hierarchy (Kozier & Erb''s Fundamentals of Nursing).', 'KRCHN', 'Paper II', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('It is best to describe as a systematic, rational method of planning& providing nursing care for individuals, families, group and community.', 'assessment', 'nursing process', 'diagnosis', 'implementation', 'B', 'The nursing process is defined as a systematic, rational method of planning and providing individualized nursing care for individuals, families, groups and communities; assessment and diagnosis are only its phases (Kozier & Erb''s Fundamentals of Nursing).', 'KRCHN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Nurse Dorothy is assessing a client for signs of postpartum depression. Which observation, if noted in the new mother, would indicate the need for further assessment related to this form of depression?', 'The mother constantly complains of tiredness and fatigue.', 'The mother is caring for the infant in a loving manner', 'The mother demonstrates an interest in the surroundings.', 'The mother looks forward to visits from the father of the newborn.', 'A', 'Persistent fatigue, along with low mood, poor bonding and loss of interest, is a warning sign warranting further assessment for postpartum depression; loving infant care and interest in surroundings are reassuring signs (Kenya mental health/MCH guidance; Myles).', 'KRCHN', 'Paper II', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following is caused by deficiency of zinc:-', 'Pre-eclampsia', 'Night blindness', 'Impaired immune system', 'Increased risk of spontaneous abortions', 'C', 'Per nutrition references, zinc deficiency impairs immune function and wound healing; night blindness is vitamin A deficiency, making impaired immunity the correct effect of zinc lack.', 'KRCHN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Reverse barrier nursing is aimed at:', 'Nursing a patient in a corner bed with a sink', 'Taking precautions to protect the patient', 'Taking precautions to protect other patients', 'Nursing the patient who has a highly infectious disease', 'B', 'Per infection prevention and control principles, reverse (protective) barrier nursing protects an immunocompromised/susceptible patient from acquiring infection from the environment; standard barrier nursing protects others from an infectious patient.', 'KRCHN', 'Paper II', 'Infection Prevention & Control', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The Nursing council of Kenya (NCK) is established under the Nurses Act Cap.', '274', '247', '257', '254', 'C', 'The Nursing Council of Kenya was established under the Nurses Act, Cap. 257 of the Laws of Kenya, which corresponds to option C (257).', 'KRCHN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nursing diagnosis that best describes a patient with psoriasis who has quit her job as a receptionist because she feels her appearance is disgusting to customers is:', 'Ineffective coping related to loss of skin integrity', 'Social isolation related to loss of skin integrity', 'Impaired skin integrity related to presence of lesions', 'Anxiety related to lack of knowledge of the disease process', 'B', 'Per Kozier & Erb''s nursing-diagnosis framework, quitting her job and withdrawing from customers because she feels her appearance is disgusting reflects Social isolation related to the altered skin/body image, rather than impaired coping or skin integrity as the priority problem here.', 'KRCHN', 'Paper II', 'Infection Prevention & Control', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The right time for diagnosing HIV infection using antibody tests among children born to HIV positive mother is at or after;', '12 months of age', '16 months off age', '18 months of age', '6 months of age', 'C', 'Per Kenya National Guidelines on HIV (EMTCT) and WHO, maternal antibodies persist in the infant, so definitive diagnosis using antibody (serological) tests is done at or after 18 months of age; before that, virological (DNA PCR) testing is used. Hence 18 months is correct.', 'KRCHN', 'Paper II', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Perinatal mortality refers to fetal and infants deaths including still births occurring from 28 weeks of gestation to within the first:', 'One week of life per 1000 live births', 'Two weeks of life per 1000 live births', 'Four weeks of life per 1000 live births', 'Six weeks of life per 1000 live births', 'A', 'Per WHO/Kenya MOH definitions, the perinatal period extends from 28 completed weeks of gestation to the end of the first week (7 days) of life; perinatal mortality is expressed per 1000 total births. Hence one week of life is correct.', 'KRCHN', 'Paper II', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The sensitivity part of culture and sensitivity test is for the purpose of,', 'Identifying the causative organism for the infection diagnosed', 'Testing the concentration of antibiotic required to cure an infection', 'Identifying the most effective antibiotics against the causative agent', 'Identifying the antibiotics that the patient is resistant to.', 'C', 'Per microbiology/IPC principles, the culture identifies the organism while the SENSITIVITY component determines which antibiotics are most effective against that isolate, guiding targeted therapy.', 'KRCHN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client with dementia is experiencing confusion late in the afternoon and before bedtime. The nurse is aware that the client is experiencing what is known as:', 'Chronic fatigue syndrome', 'Normal aging', 'Sundowning', 'Delusions', 'C', 'Per Brunner & Suddarth''s/mental health nursing, sundowning is increased confusion and agitation in the late afternoon and evening seen in dementia.', 'KRCHN', 'Paper II', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client with confusion says to the nurse, “I haven’t had anything to eat all day long. When are they going to bring breakfast?” The nurse saw the client in the day room eating breakfast with other clients 30 minutes before this conversation. Which response would be best for the nurse to make?', '“You know you had breakfast 30 minutes ago.”', '“I am so sorry that they didn’t get you breakfast. I’ll report it to the charge nurse.”', '“I’ll get you some juice and toast. Would you like something else?”', '“You will have to wait a while; lunch will be here in a little while.”', 'C', 'Per mental health nursing principles for confused/dementia clients, avoid arguing with or reality-confronting the client; a supportive, non-confrontational response that meets the immediate need (offering juice and toast) is therapeutic.', 'KRCHN', 'Paper II', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('During the initial interview, the client reports that she has a lesion on the perineum. Further investigation reveals a small blister on the vulva that is painful to touch. The nurse is aware that the most likely source of the lesion is:', 'Syphilis', 'Herpes', 'Gonorrhea', 'Condylomata .', 'B', 'Per Kenya STI guidelines, a small painful blister/vesicle on the vulva is characteristic of genital herpes; syphilis chancre is typically painless and condylomata (HPV warts) are painless papillomas.', 'KRCHN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client is admitted to the chemical dependence unit with an order for continuous observation. The nurse is aware that the doctor has ordered continuous observation because:', 'Hallucinogenic drugs create both stimulant and depressant effects.', 'Hallucinogenic drugs induce a state of altered perception.', 'Hallucinogenic drugs produce severe respiratory depression.', 'Hallucinogenic drugs induce rapid physical dependence.', 'B', 'Per mental health nursing (Kozier/psychiatric texts), hallucinogens cause altered perception and distorted reality that can lead to unpredictable, unsafe behavior, warranting continuous observation. They do not cause severe respiratory depression or rapid physical dependence.', 'KRCHN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which action by the nurse indicates understanding of herpes zoster?', 'The nurse covers the lesions with a sterile dressing.', 'The nurse wears gloves when providing care.', 'The nurse administers a prescribed antibiotic.', 'The nurse administers oxygen.', 'B', 'Per infection prevention (Kenya IPC guidelines), herpes zoster lesion fluid is infectious (contact/airborne precautions), so wearing gloves during care prevents transmission. It is viral, so antibiotics are not indicated.', 'KRCHN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is preparing to suction the client with a tracheotomy. The nurse notes a previously used bottle of normal saline on the client''s bedside table. There is no label to indicate the date or time of initial use. The nurse should:', 'Lip the bottle and use a pack of sterile 4x4 for the dressing', 'Obtain a new bottle and label it with the date and time of first use', 'Ask the ward secretary when the solution was requested', 'Label the existing bottle with the current date and time', 'B', 'Per infection prevention principles (Kenya IPC guidelines; Kozier & Erb''s Fundamentals), an opened saline bottle of unknown age/sterility must be discarded; a new bottle should be obtained and labelled with date and time of first opening to track its 24-hour usable window.', 'KRCHN', 'Paper II', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The physician has ordered a histoplasmosis test for the elderly client. The nurse is aware that histoplasmosis is transmitted to humans by:', 'Cats', 'Dogs', 'Turtles', 'Birds', 'D', 'Per Brunner & Suddarth''s and communicable disease references, histoplasmosis is a fungal infection acquired by inhaling spores from soil contaminated with bird or bat droppings; among the options, birds are the source.
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following physical manifestations would you expect to assess in a client suffering from anorexia nervosa?', 'Tachycardia, hypertension, hyperthermia', 'Bradycardia, hypertension, hyperthermia', 'Bradycardia, hypotension, hypothermia', 'Tachycardia, hypotension, hypothermia', 'C', 'Starvation in anorexia nervosa causes hypometabolism, producing bradycardia, hypotension, and hypothermia. The other options list opposite/mixed findings. Per psychiatric nursing texts adopted in Kenyan training (Kozier; DSM-based mental health nursing).', 'KRCHN', 'Paper II', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Ms. T. has been diagnosed with agoraphobia. Which behavior would be most characteristic of this disorder?', 'Ms. T. experiences panic anxiety when she encounters snakes.', 'Ms. T. refuses to fly in an airplane.', 'Ms. T. will not eat in a public place.', 'Ms. T. stays in her home for fear of being in a place from which she cannot escape', 'D', 'Agoraphobia is fear of being in situations/places from which escape may be difficult, leading to housebound behavior. Fear of snakes or flying are specific phobias, and fear of eating in public is a social phobia. Per mental health nursing (DSM criteria; standard psychiatric nursing texts).', 'KRCHN', 'Paper II', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The physician orders sertraline (Zoloft) 50 mg bid for Margaret, a 68-year-old woman with Major Depression. After 3 days of taking the medication, Margaret says to the nurse, “I don’t think this medicine is doing any good. I don’t feel a bit better.” What is the most appropriate response by the nurse?', '“Cheer up, Margaret. You have so much to be happy about.”', '“Sometimes it takes a few weeks for the medicine to bring about an improvement in symptoms.”', '“I’ll report that to the physician, Margaret. Maybe he will order something different.”', '“Try not to dwell on your symptoms, Margaret. Why don’t you join the others down in the dayroom?”', 'B', 'SSRIs such as sertraline take 2–4 weeks for therapeutic antidepressant effect; the nurse should provide accurate information and reassurance. The other responses give false reassurance or dismiss the client. Per pharmacology (Kenya EML; psychiatric nursing).', 'KRCHN', 'Paper II', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Symptoms of alcohol withdrawal include:', 'euphoria, hyperactivity, and insomnia.', 'depression, suicidal ideation, and hypersomnia.', 'diaphoresis, nausea and vomiting, and tremors.', '. unsteady gait, nystagmus, and profound disorientation.', 'C', 'Alcohol withdrawal produces autonomic hyperactivity: diaphoresis, nausea/vomiting, tremors, tachycardia, and agitation. Unsteady gait/nystagmus reflect intoxication or Wernicke''s, not classic withdrawal. Per Kenya mental health/substance use nursing (psychiatric nursing texts).', 'KRCHN', 'Paper II', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Crises occur when an individual:', 'is exposed to a precipitating stressor', 'perceives a stressor to be threatening.', 'has no support systems.', 'experiences a stressor and perceives coping strategies to be ineffective.', 'D', 'A crisis arises when an individual faces a stressor and their usual coping mechanisms are perceived as inadequate to restore equilibrium. Exposure or perceived threat alone is insufficient without failure of coping. Per crisis intervention theory (psychiatric/mental health nursing).', 'KRCHN', 'Paper II', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Mr. J. is a new client on the psychiatric unit. He is 35 years old. Theoretically, in which level of psychosocial development (according to Erikson) would you place Mr. J.?', 'Intimacy vs. isolation', 'Generativity vs. self-absorption', 'Trust vs. mistrust', 'Autonomy vs. shame and doubt', 'B', 'Erikson places middle adulthood (approximately 35–65 years) in the generativity vs. stagnation/self-absorption stage. Intimacy vs. isolation is young adulthood; the others are earlier childhood stages. Per developmental theory (Kozier & Erb''s Fundamentals of Nursing).', 'KRCHN', 'Paper II', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The personality disorders where individuals are characteristically sensitive and suspicious include;', 'Histrionic, Borderline and Narcissistic personality disorders', 'Paranoid, Schizoid and Schizotypal personality disorders', 'Paranoid, avoidant and dependent personality disorders', 'Antisocial, Schizoid and affective personality disorders', 'B', 'Cluster A personality disorders (paranoid, schizoid, schizotypal) are characterized by odd/eccentric behavior with suspiciousness and social detachment. The other clusters are dramatic (B) or anxious (C). Per DSM/psychiatric nursing texts.', 'KRCHN', 'Paper II', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In drug dependence syndrome, there is:-', 'Reduced compulsion to take a substance', 'Increased anhedonia', 'Substance tolerance', 'd. Neglect of alternative pleasures', 'C', 'Dependence syndrome (ICD-10) features tolerance, a strong compulsion to use, withdrawal, and neglect of alternative pleasures. Option A (reduced compulsion) is wrong; substance tolerance is a core diagnostic feature. Per WHO ICD-10 as adopted in Kenya mental health guidelines.', 'KRCHN', 'Paper II', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The most persistent adverse effect of ECT is', 'Retrograde amnesia', 'Fractures', 'Seizures', 'd. Hypertension', 'A', 'The most persistent adverse effect of electroconvulsive therapy is memory impairment, particularly retrograde amnesia. Fractures and seizures are largely prevented by muscle relaxants/anesthesia. Per psychiatric nursing texts.', 'KRCHN', 'Paper II', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which is the primary goal of community health nursing?', 'To support and supplement the efforts of the medical profession in the promotion of health and prevention of', 'To enhance the capacity of individuals, families and communities to cope with their health needs', 'To increase the productivity of the people by providing them with services that will increase their level of health', 'To contribute to national development through promotion of family welfare, focusing particularly on mothers and children', 'B', 'The primary goal of community health nursing is to raise the health capacity/level of individuals, families, and communities so they can meet their own health needs. Options A/C/D are partial or supporting aims. Per Kenya community health nursing (NCK CHN syllabus).', 'KRCHN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('CHN is a community-based practice. Which best explains this statement?', 'The service is provided in the natural environment of people', 'The nurse has to conduct community diagnosis to determine nursing needs and problems', 'The service are based on the available resources within the community', 'Priority setting is based on the magnitude of the health problems identified', 'A', '"Community-based" means care is delivered where people live and work — their natural environment — rather than in an institution. The other options describe process/priority-setting, not the defining feature. Per community health nursing principles (NCK CHN syllabus).', 'KRCHN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Population- focused nursing practice requires which of the following processes?', 'Community organizing', 'Nursing, process', 'Community diagnosis', '. Epidemiologic process', 'C', 'Population-focused practice requires community diagnosis to identify the health needs and problems of the aggregate/population. Community organizing and the nursing process are individual/organizational tools. Per community/public health nursing (NCK CHN syllabus).', 'KRCHN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When the occupational health nurse employs ergonomic principles, she is performing which of her roles', 'Health care provider', 'Health educator', 'Health care coordinator', '.Environment manager', 'D', 'Applying ergonomic principles (fitting the workplace/task to the worker) is part of the occupational health nurse''s environment/hazard-management role. It is not direct care, education, or coordination. Per occupational health nursing (public health nursing texts).', 'KRCHN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is true of primary facilities?', 'They are usually government-run', 'Their services are provided on an out-patient basis', 'They are training facilities for health professionals', '. A community hospital is an example of this level of health facilities', 'B', 'Primary-level facilities (dispensaries/health centres) provide first-contact, mainly out-patient services. They are not defined by being government-run, training sites, or hospitals. Per Kenya health systems/KEPH.', 'KRCHN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which is an example of the school nurse‘s health care provider function?', 'Requesting for BCG from the EPI store for school entrance immunization', 'Conducting random classroom inspection during measles epidemic', 'Taking remedial action on an accident hazard in the school playground', 'Observing places in the school where pupils spend their free times', 'A', 'Providing/organizing immunization (e.g., requesting BCG for school-entry vaccination) is a direct health-care-provider function of the school nurse. Inspection and observation are surveillance/coordination roles. Per Kenya school health/EPI (KEPI) guidelines.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which level of health facility is the usual point of entry of a client into the health care delivery system?', 'primary', 'Secondary', 'Intermediate', 'Tertiary', 'A', 'The primary-level facility (dispensary/health centre) is the usual point of entry into the health-care delivery system, from which clients are referred upward. Per Kenya health systems/KEPH referral structure.', 'KRCHN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The public health nurse is the supervisor of rural health midwives. Which of the following is a supervisory function of the pubic health nurse', 'Referring cases or patients to the midwife', 'Providing technical guidance to the midwife', 'Providing nursing care to cases referred by the midwife', 'Formulating and implementing training programs for midwives', 'B', 'A supervisory function is providing technical guidance/support to the supervised midwife. Referring cases, giving direct care, and formulating training are non-supervisory or administrative tasks. Per community/public health nursing supervision principles.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The MOST reported type of child abuse in Kenya is', 'neglect', 'physical abuse', 'sexual abuse', 'psychological maltreatment', 'A', 'Neglect is the most commonly reported form of child abuse/maltreatment. Physical and sexual abuse are reported less frequently than neglect. Per Kenya child protection data / public health nursing.', 'KRCHN', 'Paper II', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Tertiary prevention is needed in which stage of the natural history of disease?', 'Pre-pathogenesis', 'pathogenesis', 'predromal', 'terminal', 'D', 'Tertiary prevention (rehabilitation, limiting disability/complications) is applied in the late/terminal stage of the natural history of disease when disease is established. Pre-pathogenesis relates to primary prevention and early pathogenesis to secondary. Per epidemiology/community health (NCK syllabus).', 'KRCHN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Isolation of a child with measles belongs to what level of prevention?', 'Primary', 'Community organization', 'Community study', 'Core group formation', 'A', 'Isolation of an infectious child prevents spread to susceptible contacts before they get ill; per Kenya Community Health/epidemiology principles, preventing disease occurrence in the well population is primary prevention. The other options (community organization/study/core group) are community-organizing steps, not levels of prevention.', 'KRCHN', 'Paper II', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In which step are plans formulated for solving community problems?', 'Mobilization', 'Community organization', 'Follow-up/extension', 'Core group formation', 'B', 'In the community organizing process, formulating plans to solve identified community problems occurs during the community organization/planning step; per Kenya Community Health Nursing texts. Mobilization is action, follow-up is later, and core group formation precedes planning.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which type of family-nurse contact will provide you with the best opportunity to observe family dynamics?', 'clinic consulation', 'group conferences', 'home visit', 'written communication', 'C', 'A home visit lets the nurse directly observe the family in its natural environment, giving the best opportunity to assess family dynamics and interactions; per Kenya Community Health Nursing texts. Clinic, group, and written contacts do not reveal the home environment.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is an advantage of a home visit?', 'It allows the nurse to provide nursing care to a greater number of people', '. It provides an opportunity to do first hand appraisal of the home situation', '. It allows sharing of experience among people with similar health problems', 'It develops the family’s initiative in providing for health needs of its members', 'B', 'The key advantage of a home visit is first-hand appraisal of the actual home and family situation; per Kenya Community Health Nursing texts. Reaching greater numbers (clinic) and sharing among peers (group) are advantages of other contact types.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which is CONTRARY to the principles in planning a home visit?', '. A home visit should have a purpose of objective', '. The plan should revolve around the family health .needs', 'A home visit should be conducted in the manner prescribed by the Health unit', 'Planning of continuing care should involve a responsible-family member', 'C', 'Per Kenya Community Health Nursing principles, a home visit is individualised to the family''s health needs and situation, not rigidly conducted in a manner prescribed by the health unit; A, B and D are correct principles, so C is CONTRARY.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is a function of epidemiology?', 'Identifying the disease condition based on manifestations presented by a client', 'Determining factors that contributed to the occurrence of pneumonia in a 3 year old', '. Determining the efficacy of the antibiotic used in the treatment of the 3 year old client with pneumonia', 'Evaluating the effectiveness of the implementation of the Integrated Management of Childhood Illness', 'B', 'Epidemiology studies the distribution and determinants (contributing factors) of disease in populations; per Kenya epidemiology/community health texts. Diagnosing an individual (A), judging drug efficacy for one client (C) and evaluating a specific program (D) are clinical/administrative, not the core epidemiologic function of identifying determinants.', 'KRCHN', 'Paper II', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is an epidemiologic function of the nurse during an epidemic?', 'Conducting assessment of suspected cases to detect the communicable diseases', '. Monitoring the condition of the cases affected by the communicable disease', 'Participating in the investigation to determine the source of epidemic', 'Teaching the community on preventive measures against the disease', 'C', 'The epidemiologic function of the nurse during an epidemic is participating in outbreak investigation to identify the source; per Kenya Community Health/epidemiology texts. Assessing cases, monitoring patients and health teaching are clinical/educational roles rather than the epidemiologic investigation function.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the legal basis of Primary Health Care approach in Kenya?', 'Alma Ata Declaration of PHC', 'Letter of Instruction', 'Presidential Decree No. 147', 'Presidential Decree 996', 'A', 'Primary Health Care is founded on the 1978 Alma-Ata Declaration, which Kenya adopted as the basis of its PHC approach; per Kenya health policy/community health texts. The presidential decrees and letter of instruction are distractors (foreign/administrative) not applicable in Kenya.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is a natality rate?', 'Crude birth rate', 'Neonatal mortality rate', '. Infant mortality rate', 'General fertility rate', 'A', 'Natality (birth) rates measure births in a population; crude birth rate is a natality rate; per Kenya epidemiology/biostatistics texts. Neonatal and infant mortality rates are mortality rates, and general fertility rate is a fertility (not natality) measure.', 'KRCHN', 'Paper II', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What numerator is used in computing general fertility rate?', 'Estimated midyear population', 'Number of registered live births', '. Number of pregnancies in the year', 'Number of females of reproductive age', 'B', 'General fertility rate uses number of live births as the numerator (denominator being women of reproductive age); per Kenya biostatistics/epidemiology texts. Midyear population and number of reproductive-age women are denominators, not the numerator.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which clients are considered targets for DOTS category?', 'Sputum negative cavitary cases', '. Clients returning after default', 'Relapses and failures of previous PTB treatment regimens', 'Clients diagnosed for the first time through a positive sputum exam', 'D', 'New smear-positive pulmonary TB cases (Category I) are the priority target for DOTS; per Kenya National TB Program guidelines. Smear-negative cavitary, returning-after-default, relapse and failure cases fall in other treatment categories.', 'KRCHN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('child neglect involves', 'physical aggression directed at a child', 'indecent exposure of the genital of a child', 'inappropriate and excessive demands on a child', 'inadequate provision of various needs of a child', 'D', 'Per child protection principles (Kenya Children Act; MOH/WHO child abuse classification), neglect is the failure/inadequate provision of a child''s basic needs (food, shelter, health, education, supervision). Physical aggression is physical abuse and indecent genital exposure is sexual abuse.', 'KRCHN', 'Paper II', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following should be highly considered when counseling on family planning methods among HIV positive clients:', 'Drug interactions between hormonal methods and anti-tuberculosis drugs', 'The clients current stage of AIDS', 'The clients nutritional states', 'The clients economic status and source of funding', 'A', 'Per Kenya National Family Planning Guidelines, enzyme-inducing anti-TB drugs (rifampicin) reduce the efficacy of hormonal methods; TB co-infection is common in HIV, so drug interactions must be considered when counselling HIV-positive clients.', 'KRCHN', 'Paper II', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One characteristic of the causative organism of cholera is:-', 'A small comma motile organism found in the liver', 'A small comma-shaped motile organism found in salty water', 'A gram-negative bacillus found in contaminated food, water and milk', 'A gram-negative bacillus that spread rapidly', 'B', 'Vibrio cholerae is a small comma-shaped, motile (single flagellum) gram-negative organism that survives in salty/brackish water, per Kenya communicable disease references. This best describes its characteristic morphology.', 'KRCHN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following is correct about clinical stage II of HIV/AIDS:-', 'Unexplained chronic diarrhea for more than 1 month', 'Oral hairy leukoplakia', 'Recurrent respiratory infections', 'Persistent generalized lymphadenopthy', 'C', 'Per WHO/Kenya HIV clinical staging, WHO Clinical Stage 2 includes recurrent upper respiratory tract infections. Chronic diarrhoea >1 month and oral hairy leukoplakia are Stage 3; persistent generalised lymphadenopathy is Stage 1.', 'KRCHN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Implants work primarily by:-', 'Disrupting the menstrual cycle including preventing the release of eggs from the ovaries (ovulation)', 'Causing a chemical change that damages sperm and egg before they meet', 'Forming a barrier that keeps the sperms out of vagina', 'Causing the membrane of sperm cells to break killing or slowing their movement', 'A', 'Per Kenya National Family Planning Guidelines, progestin implants work primarily by suppressing ovulation (and thickening cervical mucus). Option A describes the primary ovulation-inhibiting mechanism; the others describe spermicides/barriers.', 'KRCHN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The available methods for purifying water on an individual or domestic scale are:-', 'Super chlorination, filtration, iodine', 'Boiling, chemical disinfection, filtration', 'Filtration, rapid sand filtration, boiling', 'Storage, boiling, biological filtration', 'B', 'Per Kenya environmental/public health guidelines, domestic-scale water purification methods are boiling, chemical disinfection (chlorination/iodine) and filtration. Rapid sand filtration is a large-scale municipal method, not individual/domestic.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Repression as a type of defense mechanism may be defined as:-', 'Redirecting sexual aggression from a less acceptable to more acceptable behavior', 'Exclusion of unwanted thoughts from awareness', 'Making up for a personal deficit in one area', 'Substituting false reasons for real ones.', 'B', 'Per Kozier/psychiatric nursing texts, repression is the unconscious exclusion of painful or unwanted thoughts and impulses from awareness. Option A is sublimation, C is compensation, D is rationalisation.', 'KRCHN', 'Paper II', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('While calculating infant mortality rate the correct formula is::-', 'IMR= Number of deaths of infants in one year x 100 Number of live births in the previous year', 'IMR = Number of deaths of infants in one year x 100 Number of live births in the same year', 'IMR = Number of deaths of infants in one year x 1000 Number of births in the same year', 'IMR = Number of deaths of infants in one year x 1000 Number of live births in the same year', 'D', 'Per epidemiology/biostatistics, Infant Mortality Rate = (deaths of infants <1 year in a year / live births in the same year) x 1000. The multiplier is 1000 and the denominator is live births in the same year.', 'KRCHN', 'Paper II', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('You are asked to assess a 19-year-old woman on a medical ward who has taken an overdose of paracetamol tablets. Which of the following is not an indicator of intent:-', 'Taking precautions against discovery', 'Notifying a potential helper', 'Drinking a volume of alcohol sufficient to impair judgement', 'Leaving a suicide note', 'B', 'Per psychiatric assessment of suicidal intent, high intent is shown by precautions against discovery, disinhibiting alcohol use and leaving a suicide note. Notifying a potential helper indicates LOW intent (a wish to be found/rescued), so it is not an indicator of intent.', 'KRCHN', 'Paper II', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following represents a nursing intervention at the primary level of prevention', 'Teaching a class in parent effectiveness training', 'Leading a group of adolescents in drug rehabilitation', 'Referring a married couple for sex therapy', 'Leading a support group for battered women', 'A', 'Per Kenya Community Health Nursing levels of prevention, primary prevention prevents disease before it occurs through health promotion/education; teaching parent effectiveness training is health promotion, whereas rehabilitation and support groups for existing problems are secondary/tertiary prevention.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The most common comorbid condition in children with bipolar disorder is: -', 'Schizophrenia.', 'Substance disorders', 'Oppositional defiant disorder.', 'Attention deficit-hyperactivity disorder', 'D', 'Per standard psychiatric nursing texts (Kaplan & Sadock), ADHD is the most common comorbid condition in children with bipolar disorder, with overlapping symptoms of distractibility and hyperactivity.', 'KRCHN', 'Paper II', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following psychiatric disorders is MOST common among patients with bulimia nervosa:-', 'Alcohol use disorder', 'Major depressive disorder', 'Obsessive compulsive disorder', '.Panic disorder', 'B', 'Per Kaplan & Sadock''s psychiatry, major depressive disorder is the most common comorbid psychiatric disorder among patients with bulimia nervosa.', 'KRCHN', 'Paper II', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Clinicians tools needed to recognize early symptoms of mental disorders are called "Mental Health Action Signs".All the following are true EXCEPT', 'involvement in many fights, wanting to badly hurt others', 'not eating, throwing up, or using laxatives to make yourself lose weigh', 'feeling very sad or withdrawn for more than 2 months', 'sudden overwhelming fear for no reason', 'C', 'Per the Mental Health Action Signs framework, warning signs include severe aggression/wanting to badly hurt others, disordered eating with purging, and sudden overwhelming fear. The action sign for mood is feeling very sad or withdrawn for more than 2 WEEKS (not 2 months), so this altered option is the EXCEPTION/untrue statement.', 'KRCHN', 'Paper II', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('You are following a 6-year-old boy with autism, he is under structured psychosocial behavioral training program, there is frequent complains of aggression and self-injurious behavior.Of the following, the BEST medication to control his behavior is', 'methylphenidate', 'risperidone', 'escitalopram', 'amitriptyline', 'B', 'Risperidone is the FDA/WHO-approved atypical antipsychotic for irritability, aggression and self-injurious behaviour in autism (Kaplan & Sadock; standard paediatric pharmacology). Methylphenidate treats ADHD, escitalopram is an SSRI, amitriptyline a tricyclic — none is first-line for autism-related aggression.', 'KRCHN', 'Paper II', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Of the following, the MOST common presenting behavior in girls with attention-deficit/hyperactivity disorder (ADHD) is', 'inattentive', 'hyperactive', 'impulsive', 'disruptive', 'A', 'Girls with ADHD most commonly present with the predominantly inattentive type (daydreaming, poor focus) rather than overt hyperactivity/impulsivity, which is why they are under-diagnosed (Kaplan & Sadock; DSM-5).', 'KRCHN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Whether a nurse’s plan of care for a community is acceptable is probably determined by which aspect of the plan?', 'It was created in coordination with community members.', 'It was financially feasible.', 'It was politically correct and feasible.', 'It was something in which the nurse really believes', 'A', 'Per Kenya Community Health Strategy and community health nursing principles, a plan of care is acceptable when developed in partnership with the community (community participation), ensuring ownership and sustainability.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is the most effective way of prioritizing nursing diagnoses?', 'Ensuring that the diagnoses are reimbursable by third-party payers', 'Determining the degree of community concern about the problem', 'Comparing the diagnoses with the agency’s mission statement', 'Discussing conclusions with another community health nurse', 'B', 'Per community health nursing practice, prioritising nursing diagnoses is most effectively done by gauging the community''s own perception/concern about the problem, which drives participation and effective intervention.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which one of the following is not included in the Elements of Primary Health Care?', 'Immunization services', 'Family planning services', 'Specialized services', 'Provision of essential drugs', 'C', 'Per WHO/Alma-Ata Primary Health Care elements as adopted in Kenya, immunization, family planning (MCH) and provision of essential drugs are core PHC elements; specialized (curative/referral) services are NOT part of the basic elements of PHC.', 'KRCHN', 'Paper II', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following are not necessary for a proper medical record?', 'Timely and legible entries', 'Accurate and complete entries', 'Corrections made by blacking out error', 'A logical progression of entries with reference to concurrent records and former entries', 'C', 'Per Kenya nursing documentation standards and legal record-keeping, corrections must be made by a single line through the error, dated and initialled — never by blacking out/obliterating, which is unacceptable in a proper medical record.', 'KRCHN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Evaluation leads to all except', 'conflict', 'co-operation', '.feedback', 'critical thinking', 'A', 'Evaluation promotes feedback, co-operation and critical thinking as constructive outcomes (nursing education/management principles; Kozier & Erb). Conflict is not a legitimate aim/outcome of evaluation, making it the EXCEPT.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The ''nuclear family'' means:', 'a group of people sharing living accommodation and meals', 'a network of relatives extended within or between generations', 'the new family created when an adult leaves home and gets married', 'a two generation unit of parents and their children', 'D', 'Per sociology/community health texts, a nuclear family is a two-generation unit consisting of parents and their children, as distinct from the extended family (network of relatives across generations).', 'KRCHN', 'Paper II', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The term “tabula rasa” highlights the importance of in shaping behaviour.', 'genes', 'experience', 'nature', 'predestination', 'B', 'Per behavioural science, Locke''s ''tabula rasa'' (blank slate) doctrine holds that the mind at birth is empty and behaviour is shaped by experience/environment, emphasising nurture over genes and predestination.', 'KRCHN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is not a defence mechanism?', 'projection', 'b regression', 'ingratiation', 'sublimation', 'C', 'Per psychiatric/behavioural science, projection, regression and sublimation are recognised ego defence mechanisms; ingratiation is a social-influence tactic, not a defence mechanism.', 'KRCHN', 'Paper II', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Students are passive in', 'Project method', 'Discovery method', 'Lecture method', 'Inquiry method', 'C', 'In the lecture method learners are passive recipients, whereas project, discovery and inquiry methods are learner-centred and active (educational methodology; nurse education principles).', 'KRCHN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Black water fever is a special manifestation of malaria caused by;', 'P. falciparum', 'P. malariae', 'P. ovale', 'P. vivax', 'A', 'Per Kenya National Malaria Guidelines, blackwater fever (massive intravascular haemolysis with haemoglobinuria) is a severe complication associated with Plasmodium falciparum infection.', 'KRCHN', 'Paper II', 'Infection Prevention & Control', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Mosquitoes is/are the vector in the following disorder(s)', 'Onchocerciasis', 'Visceral leishmaniasis', 'African trypanosomiasis', 'Bancroftian filariasis', 'D', 'Per Kenya communicable disease control, mosquitoes transmit Bancroftian filariasis (Wuchereria bancrofti via Culex/Anopheles); onchocerciasis is spread by blackflies, leishmaniasis by sandflies, and trypanosomiasis by tsetse flies.', 'KRCHN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which one is not the type of lesson plans on the basis of objectives', 'Micro lesson plan', 'Cognitive lesson plan', 'Affective lesson plan', 'Psychomotor lesson paln', 'A', 'On the basis of objectives (learning domains), lesson plans are classified as cognitive, affective and psychomotor (educational methodology). A micro lesson plan is classified by scope/duration, not by objective domain, making it the exception.', 'KRCHN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The extent to which a community ,structure , services or geographic area is likely to be damaged or disrupted by the impact of particular hazard is termed as', 'Capacity', 'Vulnerability', 'Risk', 'Hazard assessment', 'B', 'Per disaster management/community health, vulnerability is the extent to which a community, structure, service or area is likely to be damaged or disrupted by the impact of a hazard.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which is not true about lesson plan', 'It is develops confidence', 'It helps in oderly delivny of contents', 'It is developed by students', 'It saves from haphazard teaching', 'C', 'A lesson plan builds teacher confidence, ensures orderly content delivery and prevents haphazard teaching, and is developed by the TEACHER, not by students (educational methodology). The statement that it is developed by students is therefore untrue.', 'KRCHN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which stage of development is most unstable and challenging regarding the development of personal identity?', 'Adolescence', 'Toddlerhood', 'Childhood', 'Infancy', 'A', 'Per Erikson''s developmental theory, adolescence (identity vs role confusion) is the most unstable and challenging stage for the development of personal identity.', 'KRCHN', 'Paper II', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The continuous scrutiny of the factors determining the occurrence and dis-tribution of disease is called:', 'Opportunistic infection', 'Screening', 'Diagnosis', 'Surveillance', 'D', 'Per Kenya epidemiology/communicable disease control, surveillance is the continuous, systematic scrutiny of factors determining the occurrence and distribution of disease to guide public health action.', 'KRCHN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The village health volunteer in the primary health care should:', 'Be a person from outside the community.', 'Be acceptable to some sections of the community', 'Have minimum formal education at least up to VIII standard', 'Should be able to spare two hours to three hours every week', 'D', 'Per primary health care/community health volunteer criteria, the village health volunteer should be from within and acceptable to the whole community and able to spare a few hours weekly; of the options given, being able to spare two to three hours each week is the valid requirement (being an outsider or acceptable to only some sections is incorrect).', 'KRCHN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When considering philosophy of education, John Dewey was a proponent of', 'Existentialism', 'Pragmatism', 'Idealism', 'Realism', 'B', 'John Dewey is the foremost proponent of Pragmatism (learning by doing/experience) in the philosophy of education; standard educational-foundations reference.', 'KRCHN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The mode of intervention under secondary prevention are:', 'Health promotion (primary prevention)', 'Specific protection(primary)', 'Early diagnosis and prompt treatment', 'Rehabilitation(tertiary prevention)', 'C', 'Per Leavell & Clark levels of prevention (community health), secondary prevention consists of early diagnosis and prompt treatment; health promotion and specific protection are primary, and rehabilitation is tertiary.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Cognitive domain in Bloom’s Taxonomy includes all the following, except', 'Evaluation', 'Synthesis', 'Analysis', 'Criticism', 'D', 'Bloom''s cognitive domain levels are knowledge, comprehension, application, analysis, synthesis and evaluation; ''Criticism'' is not a level, making it the exception.', 'KRCHN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Wholesome water is one which is:', 'Free from non-pathogenic agents', 'Free from harmful chemical sub-stances', 'Has color and odor', 'Usable for industrial purposes', 'B', 'Per environmental/public health, wholesome water is free from pathogenic organisms and harmful chemical substances, palatable and free from objectionable colour and odour; of the options, being free from harmful chemical substances is the defining feature.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Characteristics of Problem Based Learning include all, EXCEPT:', 'Learning is driven by challenging, open-ended, ill-defined and ill-structured problems.', 'Students generally work in collaborative groups.', 'The teacher is the authority', 'Teachers take on the role as "facilitators" of learning', 'C', 'In Problem-Based Learning the teacher is a facilitator, not the authority; learning is driven by ill-structured problems and collaborative group work, so ''the teacher is the authority'' is the exception.', 'KRCHN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is not a 2-way communication?', 'Lectures', 'Group discussion', 'Panel discussion', 'Symposium', 'A', 'A traditional lecture is one-way communication (teacher to learners), whereas group/panel discussion and symposium involve exchange; standard communication/teaching-methods principle.', 'KRCHN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The process of developing and providing planned experiences to supply information, change attitudes and influence behavior is?', 'Health promotion', 'Primary prevention', 'Communication', 'Health education', 'D', 'Health education is the planned provision of learning experiences to supply information, change attitudes and influence behaviour; health promotion is the broader umbrella including policy and environment (Kenya health promotion guidelines/WHO).', 'KRCHN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Community health nursing is a community-based practice. Which best explains this answer?', 'The service is provided in the natural environment of people', 'The nurse has to conduct community diagnosis to determine nursing needs and problems', 'The service are based on the availability of resources within the community', 'Priority setting is based on the magnitude of the health problems identified.', 'A', 'Community-based practice means care is delivered where people live, work and play (their natural environment), not in an institution; this best explains the community-based nature of community health nursing.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following methods is used to remove permanent water hardness?', 'Boiling', 'Addition of sodium carbonate', 'Addition of lime', 'Chlorination', 'B', 'Permanent (non-carbonate) hardness is removed by chemical softening such as adding sodium carbonate (washing soda) or the lime-soda process; boiling removes only temporary hardness. Environmental health/water treatment reference.', 'KRCHN', 'Paper II', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('With regard to noise pollution, to what level of decibels, can people tolerate without substantial damage to their hearing?', '50-55dB', '60-65dB', '70-75dB', '80-85dB', 'D', 'People can generally tolerate noise up to about 80-85 dB without substantial hearing damage; sustained exposure above this level risks noise-induced hearing loss (occupational/environmental health standards).', 'KRCHN', 'Paper II', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is not a specific function of the school health services?', 'Determine the health status of each child.', 'Conduct a special screening programme which will disclose particular health problems.', 'Understanding the difference in the stages of growth and development.', 'Assist in maintaining the health of school personnel', 'C', 'Specific functions of school health services include determining each child''s health status, screening for problems and maintaining staff health; ''understanding the stages of growth and development'' is background knowledge, not a specific service function, so it is the exception.', 'KRCHN', 'Paper II', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following are examples of physical hazards?', 'Heat ,cold, vibrations, dust', 'Dust, vibrations, ionizing radiation', 'Ionizing radiation, vibrations, heat', 'Cold, asbestos, ionizing radiations', 'C', 'Physical hazards include heat, cold, noise, vibration and ionizing radiation; dust and asbestos are chemical hazards, so the option containing only physical agents (ionizing radiation, vibrations, heat) is correct (occupational health).', 'KRCHN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The health-belief model is composed of one of the following factors:', 'Psychological factors', 'Modifying factors', 'Social factors', 'Environmental factors', 'B', 'The Health Belief Model comprises individual perceptions, modifying factors (demographic, socio-psychological cues) and likelihood of action; ''modifying factors'' is a recognised component of the model.', 'KRCHN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Teaching breast self-examination falls under which level of disease prevention:', 'Primary', 'Secondary', 'Tertiary', 'Quaternary', 'B', 'Breast self-examination is a screening/early-detection activity, which is secondary prevention (early diagnosis of disease already possibly present); primary prevention would prevent onset (Leavell & Clark).', 'KRCHN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The form of immunity provided by B cells through immunoglobulin; IgA, IgD, IgM is best referred to as:-', 'Cellular immunity', 'Herd immunity', 'Humoral immunity', 'Vaccine immunity', 'C', 'Immunity mediated by B cells producing immunoglobulins (IgA, IgD, IgM, IgG, IgE) is humoral (antibody-mediated) immunity; cellular immunity is T-cell mediated (immunology/microbiology).', 'KRCHN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following vaccine is live attenuated?', 'Yellow fever', 'Rabies', 'Diphtheria', 'Influenza', 'A', 'Yellow fever vaccine is a live attenuated vaccine; rabies and influenza (injectable) are inactivated and diphtheria is a toxoid (KEPI/WHO immunization).', 'KRCHN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What type of acquired immunity is acquired through inoculation of an antigen?', 'Natural active immunity', 'Artificial passive immunity', 'Natural passive immunity', 'Artificial active immunity', 'D', 'Immunity acquired by inoculation (vaccination) of an antigen, prompting the host to make its own antibodies, is artificial active immunity; passive immunity involves receiving preformed antibodies. Immunology/immunization principles.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Sustainable development 1 is about poverty. What is the aim of this goal?', 'Cut poverty in half by 2030', 'Reduce poverty by 75% by 2030', 'End poverty in all its forms everywhere', 'Help each nation make progress on reducing poverty', 'C', 'SDG 1 aim is ''End poverty in all its forms everywhere'' by 2030; halving or reducing by a percentage were older MDG-style targets (UN Sustainable Development Goals).', 'KRCHN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Maternal mortality is expressed in?', 'Per 100', 'Per 1000', 'Per 10,000', 'Per 100,000', 'D', 'The maternal mortality ratio is conventionally expressed per 100,000 live births (Kenya MOH / WHO reproductive health indicators).', 'KRCHN', 'Paper II', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Sentinel surveillance is', 'Reporting of a disease by the health workers', 'Collection and analysis of data by a designated specialized institution', 'Correction and analyses of data by the health workers', 'Notifying of diseases by community volunteers', 'B', 'Per Kenya MOH/WHO surveillance guidelines, sentinel surveillance uses selected designated (sentinel) sites/institutions to collect and analyse data on a health event, giving high-quality data at lower cost than universal reporting.', 'KRCHN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In the principles of primary health care, accessibility considers the following except', 'Elements of integrated services.', 'People''s awareness.', 'Transport and road network', 'Social status of community members.', 'D', 'In PHC principles, accessibility concerns physical/geographic reach (transport, road network), awareness of services and integration of services; social status relates to acceptability/equity, not accessibility, so it is the exception.', 'KRCHN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Community oriented roles of a community health nurse include', 'Case finder, care manager, counselor', 'Direct patient care, case finder, care manager', 'Care manager, counselor, primary health care provider', 'Primary health care provider, care manager, health educator.', 'A', 'Community-oriented (population-focused) roles of the community health nurse include case finder, care manager and counselor; direct patient care is a client-oriented role, making option A the community-oriented set (community health nursing texts, NCK community health curriculum).', 'KRCHN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Community health action is defined as the process of', 'Gathering information on the health problems affecting the community', 'Analyzing the community health problem in order to plan for intervention', 'Providing health services to the community based on the identified problems', 'Identifying the health facilities available within the community', 'C', 'Community health action is the intervention/action step of the community health process: implementing/providing services to address problems already identified and analysed, as opposed to assessment (gathering/analysing information).', 'KRCHN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Factors that may affect the effectiveness of a home visit include:', 'The family feeling that they are viewed as dysfunctional, difficult to schedule visits.', 'Health workers have control over the home setting, making it difficult to schedule visits.', 'The family feeling that they are being viewed as dysfunctional, it is expensive for the client.', 'The health worker has control over the home setting, the family feeling that they are being viewed as dysfunctional', 'C', 'Genuine disadvantages of home visiting are the family feeling stigmatised/viewed as dysfunctional and the high cost (time and money); the nurse does NOT have control over the home setting, so options citing that are incorrect.', 'KRCHN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following concepts would enable the nurse to provide holistic care for culturally diverse clients', 'Cultural conflicts', 'Ethnocentrism', 'Stereotyping', 'Cultural brokering', 'D', 'Cultural brokering (bridging/mediating between the client''s culture and the health system) supports holistic, culturally competent care; cultural conflict, ethnocentrism and stereotyping are barriers to it (transcultural nursing, Kozier Fundamentals).', 'KRCHN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Max Weber is known for the development of which management theory?', 'Bureaucratic management', 'Scientific management', 'Humanistic management', 'Transformational leadership', 'A', 'Max Weber is credited with the bureaucratic theory of management (hierarchy, rules, division of labour); scientific management is Taylor''s, per nursing management/leadership texts.', 'KRCHN', 'Paper II', 'Midwifery', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Job specifications refer to:', 'Principal duties and responsibilities', 'Function elements of a position', 'Human qualities necessary to perform a job', 'Interdepartmental relationship', 'C', 'In human resource management, a job specification lists the human attributes (qualifications, skills, experience) needed to perform a job, whereas the job description lists duties and responsibilities (nursing management texts).', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following would provide quantitative information about the community?', 'observation of the target population in its community setting', 'talking with individuals within the community who know the target population well', 'data from CDCs Morbidity and Mortality Weekly Report', 'interviewing key informants', 'C', 'Quantitative data are numerical/statistical; morbidity and mortality report data are quantitative, whereas observation, talking with community members and interviewing key informants yield qualitative information (research/community assessment methods).', 'KRCHN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Specific, measurable actions of the desired outcome to be completed within a specific time frame is the definition of:', 'Goals', 'Objectives', 'Long term plan', 'Procedures', 'B', 'Objectives are specific, measurable, time-bound statements of desired outcomes; goals are broad and general. This matches the SMART/objective definition in nursing management and community health planning.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The primary purpose of providing employees with feedback during a performance appraisal is to motivate employees to _', 'apply for managerial positions', 'remove any performance deficiencies', 'revise their performance standards', 'enroll in work-related training programs', 'B', 'The primary purpose of appraisal feedback is developmental: to motivate employees to correct/remove performance deficiencies and improve performance (nursing management/leadership texts).', 'KRCHN', 'Paper II', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('SMART goals are best described as', 'specific, measurable, attainable, relevant, and timely', 'straight forward, meaningful, accessible, real, and tested', 'strategic, moderate, achievable, relevant, and timely', 'specific, measurable, achievable, relevant, and tested', 'A', 'SMART = Specific, Measurable, Attainable (achievable), Relevant, Timely/Time-bound; option A gives this standard expansion used in planning and management.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('which public health Act is responsible for securing and maintaining health', 'Cap 242', 'Cap 257', 'Cap 280', 'Cap 302', 'A', 'In Kenya the Public Health Act is Chapter 242 (Cap 242) of the Laws of Kenya — the principal statute for securing and maintaining public health. (Kenya Public Health Act, Cap 242.)
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('which of the following is the advantage of integration of services', 'save time and money for the nurse', 'improves immunization coverage', 'patients are integrated in the approach', 'there is high chance of cross infection between sick and health especially children', 'A', 'Integration of services allows a client to receive several services in one visit, saving time and resources for both client and provider and reducing missed opportunities; cross-infection risk is a disadvantage, not an advantage.', 'KRCHN', 'Paper II', 'Infection Prevention & Control', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Onchocerciasis is a vector borne disease which is transmitted by', 'Sandfly', 'black fly', 'female anopheles mosquito', 'house fly', 'B', 'Onchocerciasis (river blindness) is transmitted by the black fly (Simulium species); sandfly transmits leishmaniasis and anopheles transmits malaria (Kenya communicable disease control guidelines).', 'KRCHN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('the stage of a natural history of disease at which secondary prevention is needed is', 'terminal', 'prodromal', 'pre-pathogenesis', 'pathogenesis', 'D', 'Secondary prevention (early diagnosis and treatment) is applied during the pathogenesis stage of the natural history of disease, early in the clinical/subclinical course; pre-pathogenesis calls for primary prevention (epidemiology).', 'KRCHN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('controlling is a managerial function which involves', 'contributing to a purposeful organization of work', 'reducing costs and directing efforts towards desired results', 'measuring and correcting the performances of employees', 'integration and coordination of activities', 'C', 'Controlling is the management function of measuring performance against standards and taking corrective action; organising and coordinating are separate functions (nursing management theory).', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('the activities that nurse engages in during preparatory phase of a home visit include', 'location of the house', 'clarifying sources of referral', 'recording and reporting', 'analyzing community references', 'B', 'During the preparatory/pre-visit phase of a home visit the nurse reviews the referral and clarifies its source, gathers records and plans the visit; locating the house and recording/reporting occur in later phases.', 'KRCHN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('the occupational disease that persons working in information technology are likely to develop is', 'lead poisoning', 'radiation sickness', 'mesothelioma', 'carpal tunnel syndrome', 'D', 'Repetitive keyboard/computer work is a recognised occupational risk for carpal tunnel syndrome (repetitive strain injury); lead poisoning, radiation sickness and mesothelioma relate to other occupations (occupational health).', 'KRCHN', 'Paper II', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('causative organisms for yaws is', 'Tryponosoma cruzi', 'Treponema carateum', 'Treponema pallidum', 'Treponema pertenue', 'D', 'Yaws is caused by Treponema pallidum subspecies pertenue; T. pallidum (subsp. pallidum) causes venereal syphilis and T. carateum causes pinta (microbiology/communicable disease references).', 'KRCHN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('fat soluble vitamins includes', 'A,D,C,E', 'A,D,E,K,', 'E,D,C,K', 'A,B,C,D', 'B', 'The fat-soluble vitamins are A, D, E and K (mnemonic ADEK); C and B are water-soluble. Per Kozier & Erb''s Fundamentals / nutrition texts used in Kenyan training.', 'KRCHN', 'Paper II', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The number of cases of Dengue fever usually increases towards the end of the rainy season. This pattern of occurrence of Dengue fever is best described as;', 'Epidemic occurrence', 'Cyclical variation', 'Sporadic occurrence', 'Secular occurrence', 'B', 'A regular, predictable rise in cases tied to a recurring season (end of rains) is a seasonal/cyclical variation, not an unpredictable epidemic or long-term secular trend. Per epidemiology (Park''s / Kenya CDC control principles).', 'KRCHN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('You will not give DPT 2 if the mother says that the infant had?', '.Seizures a day after DPT1', '. Fever for 3 days after DPT1', '.Abscess formation after DPT1', '. Local tenderness for 3 days after DPT1', 'A', 'Seizures/encephalopathy following a previous pertussis-containing dose is a contraindication to further DPT; fever, local tenderness and abscess are not. Per Kenya KEPI immunization guidelines.', 'KRCHN', 'Paper II', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Current concept of health promotion and the related activities lead to:', 'Better treatment of a problem', 'Critical awareness and life style changes', 'Adoption of prophylactic services', 'Better health services usage', 'B', 'Modern health promotion (Ottawa Charter) empowers people through critical awareness and lifestyle change rather than mere treatment or service usage. Per WHO/Kenya community health nursing.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Objectives of the health services include each of the following except:', 'Delivery of curative care only', 'Health promotion', 'Prevention control, or eradication of disease', 'Treatment and rehabilitation', 'A', 'Health service objectives include promotion, prevention, treatment and rehabilitation; ''curative care only'' is the exception because it excludes the other functions. Per Kenya health systems / community health.', 'KRCHN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Loss of anatomical structure or physiological function is known as:', 'Disease', 'Disability', 'Handicap', 'Impairment', 'D', 'WHO ICIDH defines impairment as loss/abnormality of anatomical structure or physiological function; disability is activity limitation and handicap is social disadvantage. Per WHO/Kenya community health nursing.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When there is a cholera outbreak in a community, as a community health nurse, you have to carry out the following except', 'Notification', 'Oral rehydration therapy & tetracycline', 'Immunization of the at risk population', 'Chlorination of wells once a week', 'C', 'Cholera outbreak response is notification, ORT/antibiotics and water chlorination; mass immunization is NOT a routine first-line outbreak measure in the Kenyan CHN response, so it is the exception. Per Kenya cholera outbreak control guidelines.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The source of disease in transmission cycle means:', 'One who disseminates the disease agent to host', 'Disease agent multiplies and increases in number on storage', 'Storage of disease producing organisms', 'Receiver of disease agent', 'A', 'The source in the chain of transmission is the person/animal/object that disseminates the agent to a susceptible host; a reservoir merely stores it. Per epidemiology / Kenya communicable disease control.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Meeting basic goal of health promotion is;', 'Health', 'No illness', 'Wellness', 'Absence of diseases', 'C', 'The basic goal of health promotion is optimal wellness (positive well-being), which is broader than mere absence of disease/illness. Per WHO health promotion / Kenya community health.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Ottawa charter 1986 is related to:', 'Reproductive health', 'Health promotion', 'Primary Health care', 'Population development', 'B', 'The 1986 Ottawa Charter is the foundational WHO document on health promotion. Per WHO/Kenya community health nursing.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is not included in the eight elements of PHC?', 'Essential drugs', 'Safe drinking water and sanitation', 'Maternal and child health', 'Occupational health', 'D', 'The eight essential elements of PHC (Alma-Ata) include essential drugs, water/sanitation and MCH but NOT occupational health. Per WHO Alma-Ata / Kenya PHC.', 'KRCHN', 'Paper II', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Vitamin A is not related to,', 'Retinol', 'Keratocornea', 'Keratomalacia', 'Rickets', 'D', 'Vitamin A relates to retinol and to eye lesions (keratomalacia, corneal changes); rickets is a vitamin D deficiency, so it is NOT related to vitamin A. Per Kenya nutrition guidelines.', 'KRCHN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Bitot’s spot’ is the characteristic feature of............. deficiency', 'Calcium', 'Vitamin D', 'Vitamin A', 'Vitamin C', 'C', 'Bitot''s spots (foamy conjunctival patches) are a classic sign of vitamin A deficiency/xerophthalmia. Per Kenya nutrition / IMNCI guidelines.', 'KRCHN', 'Paper II', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The measurement rate that is used to determine the number of new cases of a disease over an interval of time is:-', 'Incidence rate', 'Prevalence rate', 'Case fatality rate', 'Endemicities', 'A', 'Incidence measures the number of NEW cases over a defined time period; prevalence counts all existing cases. Per epidemiology / Kenya communicable disease control.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Water-washed diseases include:-', 'Typhoid, poliomyelitis', 'Scabies, Trachoma', 'Amoebiasis, cholera', 'Malaria, schistosomiasis', 'B', 'Water-washed diseases result from inadequate water quantity/hygiene (scabies, trachoma); typhoid/cholera/amoebiasis are water-borne and malaria/schistosomiasis are water-related. Per Kenya environmental health classification (Bradley).', 'KRCHN', 'Paper II', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The clinical features of onchocerciasis include:', 'Severe itching, skin nodules, dermatitis, river blindness', 'Pyrexia, septicaemia, skin pigmentation', 'River blindness, pyrexia, dermatitis', 'Septicaemia, pruritis, river blindness, hepatomegaly', 'A', 'Onchocerciasis presents with intense pruritus, subcutaneous nodules, dermatitis and ocular disease (river blindness); septicaemia/hepatomegaly are not features. Per Kenya communicable disease control.', 'KRCHN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the sugar is least cariogenic', 'Glucose.', 'Sucrose.', 'Lactose.', 'd) Xylitol', 'D', 'Xylitol is non-fermentable by oral bacteria and is least cariogenic (indeed anti-cariogenic); glucose, sucrose and lactose are all fermentable sugars. Per nutrition/oral health references.', 'KRCHN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Non-digestible food ingredients that stimulate the growth and activity of certain bacteria in the colon are called:-', 'Insoluble fiber', 'Probiotics', 'Prebiotics', 'd) Cellulose', 'C', 'Prebiotics are non-digestible food ingredients that selectively stimulate growth/activity of beneficial colonic bacteria; probiotics are the live organisms themselves. Per nutrition references.', 'KRCHN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following can be used to treat extrapyramidal side effects of antipsychotic drugs except:', 'Benzhexol.', 'Amantadine', 'Propranolol.', 'D. Clozapine', 'D', 'Benzhexol (anticholinergic), amantadine and propranolol are used to treat extrapyramidal side effects; clozapine is an antipsychotic itself, not a treatment for EPSE (psychopharmacology texts).', 'KRCHN', 'Paper II', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Psychosis is characterized by all, except:', 'Contact with reality is maintained', 'Positive symptoms are usually present', 'Impaired judgment', 'Insight is lost.', 'A', 'Psychosis is defined by LOSS of contact with reality, positive symptoms, impaired judgment and lost insight; therefore ''contact with reality is maintained'' is the exception (psychiatry texts).', 'KRCHN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Major tranquillizers', 'Have antipsychotic effects', 'Are commonly indicated in management of manic episodes', 'Are used to prevent extra pyramidal side effects', 'They cause muscles relaxation', 'A', 'Major tranquillisers is the classic term for antipsychotics (neuroleptics), which act by dopamine blockade to produce antipsychotic effects (Brunner & Suddarth / standard psychiatric pharmacology). They in fact CAUSE extrapyramidal side effects rather than prevent them, and mood stabilisers/lithium are first-line for mania.', 'KRCHN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Hippocrates classified mental disorders in to:', 'Major and minor mental illness', 'Psychosis and neurosis', 'Schizophrenia, mania and depression', 'Mania, melancholia and phrenitis', 'D', 'Hippocrates historically classified mental disorders into mania, melancholia and phrenitis (Kaplan & Sadock / history of psychiatry). Psychosis/neurosis and modern diagnostic categories are much later constructs.', 'KRCHN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The belief expressed by one of your clients that an alien is creating sores on his body with a knife is classified as: -', 'Idea of reference', 'Neologism', 'Delusions', 'D. Depersonalization :', 'C', 'A fixed false belief not amenable to reason (an alien cutting sores on him) is a delusion (persecutory/somatic) per standard psychiatric nursing texts. Idea of reference and neologism describe different phenomena, and depersonalization is a self-perception disturbance.', 'KRCHN', 'Paper II', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The best approach for the mental health nurse to take when a client thinks his food is poisoned is to:-', 'assure the client that all food served on the hospital is safe to eat.', 'obtain an order for a tube feeding for the client.', 'provide the client with food in unopened containers.', 'tell the client that irrational thinking is detrimental to good health', 'C', 'For a paranoid client fearing poisoned food, providing sealed/unopened containers reduces suspicion and promotes nutrition without arguing with the delusion (psychiatric nursing standard). Reassuring, arguing rationality, or tube feeding do not respect the therapeutic principle of not challenging delusions directly.', 'KRCHN', 'Paper II', 'Pharmacology', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What nursing action would be most effective in changing the behavior of a child diagnosed with attention deficit hyperactivity disorder (ADHD):-', 'Reward appropriate behavior', 'Sedate the child for acting out', 'Use aggressive punishment to control undesired behavior', 'Use lengthy time out session', 'A', 'Positive reinforcement (rewarding appropriate behaviour) is the most effective behaviour-modification strategy for ADHD (psychiatric nursing). Sedation, aggressive punishment and lengthy time-outs are ineffective and inappropriate.', 'KRCHN', 'Paper II', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following nursing diagnoses would be considered the priority in planning care for the autistic child:-', 'Risk for self-mutilation evidenced by banging head against wall', 'Impaired social interaction evidenced by unresponsiveness to people', 'Impaired verbal communication evidenced by absence of verbal expression', 'Disturbed personal identity evidenced by inability to differentiate self from others', 'A', 'Using Maslow/safety prioritisation, physical safety takes precedence, so risk for self-mutilation (head-banging) is the priority diagnosis for the autistic child (psychiatric nursing). Impaired interaction and communication, though characteristic, are not immediately life/safety threatening.', 'KRCHN', 'Paper II', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The child with conduct disorder will likely to demonstrate:-', 'Distractibility', 'Ritualistic behaviour', 'Serious violation of age related norms', 'Preference to inanimate object', 'C', 'Conduct disorder is defined by a repetitive pattern of behaviour violating the basic rights of others and major age-appropriate societal norms (DSM/psychiatric nursing). Distractibility suggests ADHD and ritualistic behaviour suggests OCD/autism.', 'KRCHN', 'Paper II', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('During psychiatric interview patient retains a constellation of ideas long after they have ceased to be appropriate. E.g. “where do you live?”, “London”, “How old are you”, “London. The term used to explain the condition is:-', 'Perseveration', 'Mannerisms', 'Ambivalence', 'D. Echopraxia', 'A', 'Persistent, inappropriate repetition of the same response (answering ''London'' to unrelated questions) is perseveration (psychiatric mental status examination). Mannerisms, ambivalence and echopraxia (imitating movements) describe different phenomena.', 'KRCHN', 'Paper II', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following nursing diagnoses would be most appropriate for a client with schizotypal personality disorder:-', 'Ineffective coping related to repetitive behaviour such as hand washing', 'Risk for self-mutilation related to social anxiety', 'Risk for violence toward others related to lack of remorse for behaviours', 'Impaired thought processes related to ideas of reference and magical thinking', 'D', 'Schizotypal personality disorder is characterised by cognitive-perceptual distortions such as ideas of reference and magical thinking, making impaired thought processes the appropriate diagnosis (psychiatric nursing). Compulsive hand-washing, self-mutilation and lack of remorse point to other disorders.', 'KRCHN', 'Paper II', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following nursing diagnoses would be appropriate for a client with an avoidant personality disorder:-', 'Risk for self-mutilation related to a desperate need for attention', 'Ineffective coping related to negative attitudes toward health behaviour', 'Anxiety related to fear of criticism, disapproval, and rejection', 'Risk for injury related to uncontrolled anger and hostility toward others', 'C', 'Avoidant personality disorder centres on social inhibition and hypersensitivity to criticism/rejection, so anxiety related to fear of criticism and rejection is appropriate (psychiatric nursing). Self-mutilation, poor health attitudes and uncontrolled anger fit other personality disorders.', 'KRCHN', 'Paper II', 'Mental Health Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Leo Kanner is known for his studies on:-', 'Autism', 'Schizophrenia', 'Bipolar disorders', 'Personality disorders', 'A', 'Leo Kanner first described early infantile autism in 1943 and is renowned for his studies on autism (history of child psychiatry).', 'KRCHN', 'Paper II', 'Paediatric Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is considered to be most effective and treatment of choice for phobic disorders:-', 'Behaviour therapy', 'Interpersonal psychotherapy', 'Family therapy', 'D. Psychoanalysis', 'A', 'Behaviour therapy (systematic desensitisation/exposure) is the treatment of choice for phobic disorders (psychiatric nursing / CBT evidence). Psychoanalysis, family and interpersonal therapy are less effective for specific phobias.', 'KRCHN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is nursing education?', 'educating children about nurses', 'specific training a nurse receives to be qualified to work with patients.', 'training teachers to teach nurses', 'educating families of nurses', 'B', 'Nursing education is the specific formal training preparing a nurse to be qualified to care for patients. NCK curriculum framework / nursing education principles.', 'KRCHN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The character of feeling for others in their position is called', 'Empathy', 'Sympathy', 'Warmth', 'Reassurance', 'A', 'Empathy is understanding and feeling with others from their perspective/position, distinguished from sympathy (feeling for them). Therapeutic communication (Kozier & Erb''s).', 'KRCHN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The purpose of taking return demonstration from students after a teaching session of demonstration of nursing procedure is to', 'Fulfill syllabus norm', 'Ensure safe Nursing practice', 'Follow institutional policy', 'Identify mistakes', 'B', 'Return demonstration verifies that the student has mastered the psychomotor skill correctly, ensuring safe nursing practice before performing it on patients. Nursing education (demonstration method).', 'KRCHN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which one of the following is NOT a part of electronic media?', 'Radio', 'Brochure', 'Film', 'Televisio n', 'B', 'Radio, film and television are electronic media; a brochure is print media, making it the exception. Educational technology / health education media.', 'KRCHN', 'Paper II', 'Medical-Surgical Nursing', 'General', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
